function TicketRecurrenciaById({
  ticketId,
  token,
  canEdit,
  onRefresh,
}: {
  ticketId: number;
  token: string;
  canEdit: boolean;
  onRefresh?: () => void;
}) {
  const [ticket, setTicket] = useState<Ticket | null>(null);
  useEffect(() => {
    tapi(`/${ticketId}`, token).then(setTicket).catch(() => setTicket(null));
  }, [ticketId, token]);
  if (!ticket) return null;
  return (
    <TicketRecurrenciaSection
      ticket={ticket}
      token={token}
      canEdit={canEdit}
      onTicket={(t) => {
        setTicket(t);
        onRefresh?.();
      }}
    />
  );
}

function TicketRecurrenciaSection({
  ticket,
  token,
  onTicket,
  canEdit,
}: {
  ticket: Ticket;
  token: string;
  onTicket: (t: Ticket) => void;
  canEdit: boolean;
}) {
  const [freq, setFreq] = useState(ticket.frecuencia || "");
  const [saving, setSaving] = useState(false);
  const [renewing, setRenewing] = useState(false);

  useEffect(() => {
    setFreq(ticket.frecuencia || "");
  }, [ticket.id, ticket.frecuencia]);

  async function saveFreq() {
    setSaving(true);
    try {
      const updated = await tapi(`/${ticket.id}`, token, {
        method: "PUT",
        body: JSON.stringify({ frecuencia: freq || null }),
      });
      onTicket(updated);
    } catch (e: unknown) {
      alert(e instanceof Error ? e.message : "Error al guardar");
    } finally {
      setSaving(false);
    }
  }

  async function renovar() {
    if (!confirm(`¿Renovar el ticket ${ticket.numero}?\n\nSe desmarcarán los pasos y quedará listo para un nuevo ciclo.`)) return;
    setRenewing(true);
    try {
      const updated = await tapi(`/${ticket.id}/renovar`, token, { method: "POST" });
      onTicket(updated);
    } catch (e: unknown) {
      alert(e instanceof Error ? e.message : "Error al renovar");
    } finally {
      setRenewing(false);
    }
  }

  return (
    <div className="rounded-xl border-2 border-accent/20 bg-accent/50 p-4 space-y-3 dark:border-accent">
      <p className="text-xs font-bold uppercase tracking-wide text-accent">
        ♻️ Recurrencia del ticket
      </p>
      {canEdit ? (
        <div className="flex flex-wrap items-end gap-2">
          <div className="min-w-[12rem] flex-1">
            <SelectFrecuencia value={freq} onChange={setFreq} />
          </div>
          <button
            type="button"
            disabled={saving || freq === (ticket.frecuencia || "")}
            onClick={saveFreq}
            className="rounded-paper border-2 border-accent/50 px-3 py-1.5 text-xs font-bold text-accent hover:bg-accent/50 hover:text-white transition disabled:opacity-50"
          >
            {saving ? "..." : "Guardar"}
          </button>
        </div>
      ) : (
        <p className="text-sm text-ink">
          {ticket.frecuencia ? (FRECUENCIA_LABEL[ticket.frecuencia] ?? ticket.frecuencia) : "Sin repetición"}
        </p>
      )}
      {ticket.frecuencia && ticket.proxima_renovacion && ticket.estado === "resuelto" && (
        <p className="text-xs font-semibold text-accent">
          ⏰ Próxima renovación automática: {fmtFecha(ticket.proxima_renovacion)}
        </p>
      )}
      {canEdit && ticket.estado === "resuelto" && (
        <button
          type="button"
          disabled={renewing}
          onClick={renovar}
          className="rounded-paper border-2 border-accent/40 px-3 py-1.5 text-xs font-bold text-accent hover:bg-accent/50 hover:border-accent/50 hover:text-white transition disabled:opacity-50"
        >
          {renewing ? "Renovando..." : "♻️ Renovar ticket"}
        </button>
      )}
    </div>
  );
}

function fmtFecha(iso: string | null | undefined): string {
  if (!iso) return "";
  const d = new Date(iso.replace(" ", "T") + "Z");
  return d.toLocaleDateString("es-CO", { day: "2-digit", month: "short", year: "numeric" });
}

