  onEtapaTitulo: (i: number, v: string) => void;
  onEtapaDesc: (i: number, v: string) => void;
  onAsignacion: (orden: number, userId: string) => void;
  onEtapaPasos: (i: number, pasos: PasoDraft[]) => void;
  onEtapaFrecuencia: (i: number, v: string) => void;
