// ── Acciones View ─────────────────────────────────────────────────────────────

const PRIORIDAD_COLOR: Record<string, string> = {
  urgente: "bg-red-500 text-white",
  alta: "bg-accent/40 text-white",
  media: "bg-accent/40 text-gray-900",
  baja: "bg-gray-300 text-gray-700",
};

/**
 * AudioContext desbloqueado por gesto del usuario.
 * En Android Chrome, el AudioContext debe crearse/resumirse durante un toque
 * para que pueda reproducir audio posterior sin gesto (como las alarmas a los 5 min).
 */
let _unlockedCtx: AudioContext | null = null;

function unlockAudioContext() {
  if (_unlockedCtx && _unlockedCtx.state !== "closed") return;
  try {
    _unlockedCtx = new AudioContext();
    // Reproducir buffer vacío de 1 muestra para desbloquear el contexto
    const buf = _unlockedCtx.createBuffer(1, 1, 22050);
    const src = _unlockedCtx.createBufferSource();
    src.buffer = buf;
    src.connect(_unlockedCtx.destination);
    src.start(0);
  } catch { _unlockedCtx = null; }
}

/** Reproduce un recordatorio de voz corto. Primero intenta el TTS del servidor;
 *  si no responde en 1.5 s, usa SpeechSynthesis del navegador (funciona offline/Android).
 *  El AudioContext debe estar desbloqueado previamente por gesto del usuario. */
function urlBase64ToUint8Array(base64String: string): Uint8Array {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = window.atob(base64);
  return new Uint8Array([...raw].map((c) => c.charCodeAt(0)));
}

// parseUtcTs importado desde ./Cronometro

// ── Caché de audio de alarma ──────────────────────────────────────────────────
// El audio TTS se genera una sola vez y se reutiliza en todas las alarmas del día.
// Evita latencia de ~5 s de Voicebox en cada disparo.
let _alarmCache: { buffer: ArrayBuffer; type: string } | null = null;
let _alarmCacheExpiry = 0;

async function _playBlobBuffer(buffer: ArrayBuffer, type: string): Promise<void> {
  const blob = new Blob([buffer], { type });
  const url = URL.createObjectURL(blob);
  const audio = new Audio(url);
  audio.volume = 1;
  return new Promise((resolve, reject) => {
    audio.onended = () => { URL.revokeObjectURL(url); resolve(); };
    audio.onerror = () => { URL.revokeObjectURL(url); reject(new Error("playback error")); };
    audio.play().catch(reject);
  });
}

const HUGO_VOICEBOX_PROFILE = "3762e0ae-ae88-4f5e-8d77-af4f8eb7cc23";

/** TTS con la voz de Hugo García (Voicebox). apiToken = CHAT_API_TOKEN o JWT de tickets. */
async function hablarHugoTts(apiToken: string, texto: string): Promise<boolean> {
  if (!texto.trim() || !apiToken) return false;

  const payload = JSON.stringify({
    texto: texto.trim(),
    motor: "voicebox",
    voicebox_engine: "qwen3",
    voicebox_profile: HUGO_VOICEBOX_PROFILE,
    language: "Spanish",
  });

  // Dos intentos: el backend ya reintenta internamente, pero un error de red
  // transitorio (conexión cerrada, gateway timeout) merece un segundo intento.
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const res = await fetch("/api/voz/sintetizar", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiToken}` },
        body: payload,
      });
      if (!res.ok) {
        // El backend ya agotó sus reintentos internos y devolvió error.
        // No usar voz del navegador — simplemente fallar.
        if (attempt === 0) { await new Promise(r => setTimeout(r, 2000)); continue; }
        return false;
      }
      const ct = res.headers.get("content-type") || "audio/wav";
      if (ct.includes("json")) {
        if (attempt === 0) { await new Promise(r => setTimeout(r, 2000)); continue; }
        return false;
      }
      const buffer = await res.arrayBuffer();
      const type = ct.includes("mpeg") ? "audio/mpeg" : "audio/wav";
      await _playBlobBuffer(buffer, type);
      return true;
    } catch {
      if (attempt === 0) { await new Promise(r => setTimeout(r, 2000)); }
    }
  }
  // Si ambos intentos fallan: no usar voz del navegador, solo fallar silenciosamente.
  return false;
}

/** Reproduce alerta de voz para recordatorios vencidos usando la voz de Hugo García. */
async function playRecordatorioAlerta(apiToken: string, count: number): Promise<void> {
  const texto = count === 1
    ? "Hola, veci. Tiene un recordatorio pendiente para hoy."
    : `Hola, veci. Tiene ${count} recordatorios pendientes para hoy.`;
  await hablarHugoTts(apiToken, texto);
}

/** Genera y cachea el audio de alarma. Llámalo al activar la alarma para pre-calentar. */
async function warmAlarmCache(apiToken: string): Promise<boolean> {
  if (_alarmCache && Date.now() < _alarmCacheExpiry) return true;
  try {
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), 12_000);
    const res = await fetch("/api/voz/sintetizar", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiToken}` },
      body: JSON.stringify({
        texto: "Pilas, veci: tiene una tarea en proceso.",
        motor: "voicebox",
        voicebox_engine: "qwen3",
        voicebox_profile: "3762e0ae-ae88-4f5e-8d77-af4f8eb7cc23",
        language: "Spanish",
      }),
      signal: ctrl.signal,
    });
    clearTimeout(tid);
    if (!res.ok) return false;
    const buffer = await res.arrayBuffer();
    const type = res.headers.get("content-type") || "audio/wav";
    _alarmCache = { buffer, type };
    _alarmCacheExpiry = Date.now() + 12 * 60 * 60 * 1000; // caché 12 horas
    return true;
  } catch { return false; }
}

/** Devuelve true si la hora local cae en horario de descanso (22:00–07:00). */
function esHorarioSilencio(): boolean {
  const hora = new Date().getHours();
  return hora >= 22 || hora < 7;
}

async function playAlarmAudio(apiToken?: string) {
  // Intento 1: audio cacheado (generado previamente, sin latencia)
  if (_alarmCache && Date.now() < _alarmCacheExpiry) {
    try { await _playBlobBuffer(_alarmCache.buffer, _alarmCache.type); return; } catch {}
  }

  // Intento 2: generar TTS y cachear (primera vez o caché expirada)
  if (apiToken) {
    try {
      if (await warmAlarmCache(apiToken) && _alarmCache) {
        await _playBlobBuffer(_alarmCache.buffer, _alarmCache.type);
        return;
      }
    } catch {}
  }

  // Intento 3: SpeechSynthesis del navegador (sin servidor, Android Chrome lo soporta)
  if ("speechSynthesis" in window) {
    window.speechSynthesis.cancel();
    const utt = new SpeechSynthesisUtterance("Pilas, veci: tiene una tarea en proceso.");
    utt.lang = "es-CO"; utt.rate = 0.92; utt.volume = 1;
    window.speechSynthesis.speak(utt);
    return;
  }

  // Fallback: chime Web Audio API
  try {
    const ctx = _unlockedCtx ?? new AudioContext();
    const now = ctx.currentTime;
    [[0, 880], [0.32, 1100], [0.64, 660]].forEach(([delay, freq]) => {
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      osc.type = "sine"; osc.frequency.value = freq;
      gain.gain.setValueAtTime(0, now + delay);
      gain.gain.linearRampToValueAtTime(0.3, now + delay + 0.06);
      gain.gain.exponentialRampToValueAtTime(0.001, now + delay + 0.4);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(now + delay); osc.stop(now + delay + 0.42);
    });
    setTimeout(() => ctx.close().catch(() => {}), 2500);
  } catch { /* AudioContext no disponible */ }
}

async function playSolicitudAudio(nombre: string, apiToken?: string): Promise<void> {
  const texto = `Veci, tiene una solicitud de parte de ${nombre}.`;
  if (apiToken) {
    try {
      const ctrl = new AbortController();
      const tid = setTimeout(() => ctrl.abort(), 12_000);
      const res = await fetch("/api/voz/sintetizar", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiToken}` },
        body: JSON.stringify({
          texto,
          motor: "voicebox",
          voicebox_engine: "qwen3",
          voicebox_profile: "3762e0ae-ae88-4f5e-8d77-af4f8eb7cc23",
          language: "Spanish",
        }),
        signal: ctrl.signal,
      });
      clearTimeout(tid);
      if (!res.ok) throw new Error("tts error");
      const buffer = await res.arrayBuffer();
      const type = res.headers.get("content-type") || "audio/wav";
      await _playBlobBuffer(buffer, type);
      return;
    } catch { /* fallback */ }
  }
  if ("speechSynthesis" in window) {
    window.speechSynthesis.cancel();
    const utt = new SpeechSynthesisUtterance(texto);
    utt.lang = "es-CO"; utt.rate = 0.92; utt.volume = 1;
    window.speechSynthesis.speak(utt);
  }
}

// Persists timer start time across React remounts (ticket moves between column groups).
const _timerStore = new Map<number, number>();

/** IDs de acciones cuyo detail debe abrir el modo paso-a-paso automáticamente. */
const _autoStartPasoAPaso = new Set<number>();

function esTarjetaSoloCompras(ticket: Ticket, user?: TicketsUser): boolean {
  return esSolicitudCompraDelegada(ticket) || (
    !!user && uidEq(ticket.asignado_a, user.id)
    && (ticket.titulo || "").trim().toLowerCase().startsWith("compras:")
  );
}

function AccionCardAvisoCompras({ ticket }: { ticket: Ticket }) {
  return (
    <div className="rounded-xl border border-accent/50 bg-accent/50  p-3 space-y-2">
      <p className="text-sm font-bold text-ink">🛒 {ticket.titulo}</p>
      <p className="text-xs text-muted font-mono">{ticket.numero}</p>
      <p className="text-xs text-muted">
        Esta tarea es solo la lista de compras. Ábrela en <strong className="text-ink">Solicitudes</strong>.
      </p>
    </div>
  );
}

function AccionCard(props: {
  ticket: Ticket; token: string;
  user?: TicketsUser;
  onSelect: (id: number) => void;
  onChanged: () => void;
  onContinuar?: (ticket: Ticket) => void;
  isAdmin?: boolean;
  readOnly?: boolean;
}) {
  if (esTarjetaSoloCompras(props.ticket, props.user)) {
    return <AccionCardAvisoCompras ticket={props.ticket} />;
  }
  return <AccionCardOperativa {...props} />;
}

function AccionCardOperativa({
  ticket, token, onSelect, onChanged, onContinuar, isAdmin, readOnly,
}: {
  ticket: Ticket; token: string;
  onSelect: (id: number) => void;
  onChanged: () => void;
  onContinuar?: (ticket: Ticket) => void;
  isAdmin?: boolean;
  readOnly?: boolean;
}) {
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [corridaId, setCorridaId] = useState<number | null>(ticket.corrida?.id ?? null);
  const [corridaActiva, setCorridaActiva] = useState(ticket.corrida?.estado === "activa");

  // segBase = solo segundos acumulados de segmentos anteriores (sin incluir la corrida activa)
  const [segBase, setSegBase] = useState<number>(
    ticket.corrida?.segundos_acumulados ?? ticket.segundos_trabajo ?? 0
  );
  const [segLive, setSegLive] = useState(0);

  // inicioRef: marca de tiempo (ms) desde cuando corre el tramo actual.
  // null = detenido. No-null = corriendo. El intervalo solo mira este ref.
  // Inicializado desde el servidor si la corrida ya estaba activa al montar.
  const inicioRef = useRef<number | null>(
    _timerStore.get(ticket.id) ??
    (ticket.corrida?.estado === "activa"
      ? (ticket.corrida.reanudada_en || ticket.corrida.iniciada_en
        ? parseUtcTs(ticket.corrida.reanudada_en || ticket.corrida.iniciada_en!)
        : null)
      : null)
  );
  const [resolucionInfo, setResolucionInfo] = useState<{ duracion: number; horario: string } | null>(null);

  // Limpiar segLive cuando corridaActiva cambia a false (para display)
  useEffect(() => {
    if (!corridaActiva) setSegLive(0);
  }, [corridaActiva]);

  // Intervalo PERMANENTE montado UNA SOLA VEZ.
  // Solo comprueba inicioRef.current — asignado SINCRÓNICAMENTE en iniciarPausar
  // antes de cualquier await, así nunca hay race condition con React batching.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => {
    const iv = setInterval(() => {
      if (inicioRef.current == null) return;
      const s = Math.floor((Date.now() - inicioRef.current) / 1000);
      setSegLive((p) => (p === s ? p : s));
    }, 250);
    return () => clearInterval(iv);
  }, []);

  const segDisplay = segBase + segLive;

  async function iniciarPausar() {
    if (busy) return;
    setBusy(true);
    try {
      const nuevoEstado = ticket.estado === "en_proceso" ? "pendiente" : "en_proceso";
      if (nuevoEstado === "en_proceso") {
        // ── ARRANCAR TIMER INMEDIATAMENTE (antes del round-trip al servidor) ──
        // El intervalo permanente ya está corriendo; solo necesita inicioRef != null.
        const t0 = Date.now();
        inicioRef.current = t0;
        _timerStore.set(ticket.id, t0);
        setCorridaActiva(true);
        setSegLive(0);

        // Registrar la corrida en servidor (sin bloquear la UI)
        try {
          const data: Ticket = await tapi(`/${ticket.id}/corridas/iniciar`, token, {
            method: "POST", body: JSON.stringify({ segundos_previos: segBase }),
          });
          if (data.corrida) {
            setCorridaId(data.corrida.id);
            setSegBase(data.corrida.segundos_acumulados ?? 0);
            // Si el servidor reporta un inicio anterior al click local, sincronizar
            if (data.corrida.iniciada_en || data.corrida.reanudada_en) {
              const srvTs = parseUtcTs(data.corrida.reanudada_en || data.corrida.iniciada_en);
              if (srvTs < t0 && t0 - srvTs < 30_000) { inicioRef.current = srvTs; _timerStore.set(ticket.id, srvTs); }
            }
          }
        } catch { /* timer ya corriendo desde t0 */ }

        try {
          await tapi(`/${ticket.id}/estado`, token, {
            method: "PUT", body: JSON.stringify({ estado: "en_proceso" }),
          });
        } catch {}
      } else {
        // ── PAUSAR: capturar segLive ANTES de resetear ──
        const segTotal = segBase + segLive;
        setCorridaActiva(false);   // corridaActivaRef se sincroniza en useEffect
        inicioRef.current = null;  // detiene el intervalo permanente
        _timerStore.delete(ticket.id);

        if (corridaId) {
          try {
            const data: Ticket = await tapi(`/corridas/${corridaId}/pausar`, token, { method: "POST" });
            setSegBase(data.corrida?.segundos_acumulados ?? segTotal);
          } catch { setSegBase(segTotal); }
        } else {
          setSegBase(segTotal);
        }

        try {
          await tapi(`/${ticket.id}/estado`, token, {
            method: "PUT", body: JSON.stringify({ estado: "pendiente" }),
          });
        } catch {}
      }
      onChanged();
      // Tickets operativos (no acciones): modo paso a paso MeLi al iniciar
      if (
        ticket.tipo !== "accion"
        && nuevoEstado === "en_proceso"
        && (ticket.pasos_total ?? 0) > 0
      ) {
        _autoStartPasoAPaso.add(ticket.id);
        onSelect(ticket.id);
      }
    } catch { /* ignore */ }
    finally { setBusy(false); }
  }

  async function resolver() {
    if (busy) return;
    if (!confirm(`¿Marcar "${ticket.titulo}" como terminada?\n\nEsta acción no se puede deshacer.`)) return;
    setBusy(true);
    try {
      if (corridaId) {
        try { await tapi(`/corridas/${corridaId}/finalizar`, token, { method: "POST" }); } catch {}
      }
      await tapi(`/${ticket.id}/estado`, token, { method: "PUT", body: JSON.stringify({ estado: "resuelto" }) });
      const duracion = segDisplay;
      const horario = new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" });
      setResolucionInfo({ duracion, horario });
      setCorridaActiva(false);
      inicioRef.current = null;
      _timerStore.delete(ticket.id);
      setSegLive(0);
      setTimeout(() => onChanged(), 2200);
    } catch { /* ignore */ }
    finally { setBusy(false); }
  }

  async function cancelar() {
    if (busy) return;
    if (!confirm(`¿Cancelar la acción "${ticket.titulo}"?\n\nSe marcará como cancelada y quedará en el historial.`)) return;
    setBusy(true);
    try {
      if (corridaId) {
        try { await tapi(`/corridas/${corridaId}/pausar`, token, { method: "POST" }); } catch {}
      }
      await tapi(`/${ticket.id}/estado`, token, { method: "PUT", body: JSON.stringify({ estado: "rechazado", motivo: "Acción cancelada por el responsable" }) });
      inicioRef.current = null;
      _timerStore.delete(ticket.id);
      onChanged();
    } catch { /* ignore */ }
    finally { setBusy(false); }
  }

  async function eliminar() {
    if (busy) return;
    setBusy(true);
    try {
      await tapi(`/${ticket.id}`, token, { method: "DELETE" });
      onChanged();
    } catch { /* ignore */ }
    finally { setBusy(false); setConfirmDelete(false); }
  }

  const resuelta = ticket.estado === "resuelto" || ticket.estado === "rechazado";
  const enProceso = ticket.estado === "en_proceso";

  return (
    <div
      className={`flex flex-col gap-2 rounded-xl border border-border bg-surface p-3 shadow-sm transition-opacity ${resuelta ? "opacity-60" : ""}`}
    >
      <div className="flex items-start gap-2">
        <div className="min-w-0 flex-1">
          <span className="text-sm font-medium text-ink">{ticket.titulo}</span>
          {ticket.descripcion && ticket.descripcion !== ticket.titulo && (
            <p className="mt-0.5 text-xs text-muted line-clamp-2">{ticket.descripcion}</p>
          )}
        </div>
        <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${PRIORIDAD_COLOR[ticket.prioridad ?? "media"] ?? "bg-gray-200 text-gray-700"}`}>
          {ticket.prioridad ?? "media"}
        </span>
        {isAdmin && !confirmDelete && (
          <button
            type="button"
            title="Eliminar acción"
            onClick={() => setConfirmDelete(true)}
            className="shrink-0 rounded p-0.5 text-muted hover:text-red-600 transition-colors"
          >
            <Icon name="trash" size={13} />
          </button>
        )}
        {isAdmin && confirmDelete && (
          <div className="flex items-center gap-1">
            <button
              type="button"
              disabled={busy}
              onClick={eliminar}
              className="rounded bg-red-600 px-1.5 py-0.5 text-[10px] font-bold text-white hover:bg-red-700"
            >
              Sí
            </button>
            <button
              type="button"
              onClick={() => setConfirmDelete(false)}
              className="rounded bg-surface-hover px-1.5 py-0.5 text-[10px] font-bold text-muted hover:text-ink"
            >
              No
            </button>
          </div>
        )}
      </div>

      <div className="flex items-center gap-2 text-xs text-muted">
        <Icon name="user" size={12} />
        <span>{ticket.asignado_a_nombre ?? "Sin asignar"}</span>
        <span className="ml-auto rounded-full border border-border px-2 py-0.5 text-[10px]">
          {ESTADO_LABEL[ticket.estado] ?? ticket.estado}
        </span>
      </div>

      {/* Cronómetro live */}
      {!resuelta && (enProceso || segBase > 0 || corridaActiva) && (
        <div className={`flex items-center gap-2 rounded-lg px-2 py-1 text-xs font-mono ${
          corridaActiva ? "bg-accent/10 text-accent" : "bg-surface-hover text-muted"
        }`}>
          <span>{fmtTiempo(segDisplay)}</span>
          {corridaActiva && <span className="h-1.5 w-1.5 rounded-full bg-accent animate-pulse" />}
          {!corridaActiva && segBase > 0 && <span className="text-[10px]">en pausa</span>}
        </div>
      )}

      {/* Resumen al completar */}
      {resolucionInfo && (
        <div className="rounded-lg border border-accent/30 bg-accent/5  px-2 py-1.5 text-xs text-accent">
          ✓ Completada a las <strong>{resolucionInfo.horario}</strong> · {fmtTiempo(resolucionInfo.duracion)} de trabajo
        </div>
      )}

      {!resuelta && !resolucionInfo && !readOnly && (
        <div className="flex flex-col gap-2 pt-1">
          {onContinuar && (
            <button
              type="button"
              disabled={busy}
              onClick={() => onContinuar(ticket)}
              className="flex w-full items-center justify-center gap-1.5 rounded-xl bg-accent px-3 py-3 text-sm font-extrabold text-white min-h-[44px] transition hover:brightness-110"
            >
              📋 Continuar donde quedé
            </button>
          )}
          <div className="flex gap-2">
            <button
              type="button"
              disabled={busy}
              onClick={iniciarPausar}
              className={`flex flex-1 items-center justify-center gap-1.5 rounded-xl border px-3 py-2.5 text-xs font-bold min-h-[40px] transition-colors ${
                enProceso
                  ? "border-accent/40 bg-accent/5 text-accent hover:bg-accent/10"
                  : "border-border bg-surface-panel text-muted hover:border-accent hover:text-accent"
              }`}
            >
              <Icon name={enProceso ? "clock" : "lightning"} size={14} weight="bold" />
              {enProceso ? "Pausar" : "▶ Iniciar"}
            </button>
            <button
              type="button"
              disabled={busy}
              onClick={resolver}
              className="flex flex-1 items-center justify-center gap-1.5 rounded-xl border border-accent/50 bg-accent/5 px-3 py-2.5 text-xs font-bold text-accent min-h-[40px] transition-colors hover:bg-accent/10"
            >
              <Icon name="check" size={14} weight="bold" />
              Listo
            </button>
            <button
              type="button"
              disabled={busy}
              onClick={cancelar}
              title="Cancelar esta acción"
              className="flex items-center justify-center rounded-xl border border-border px-2.5 py-2.5 text-xs font-bold text-muted min-h-[40px] transition-colors hover:border-red-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/10"
            >
              ✕
            </button>
          </div>
        </div>
      )}
      {!resuelta && readOnly && (
        <p className="text-[10px] text-center text-muted">Vista de supervisión — solo lectura</p>
      )}
    </div>
  );
}

// ── tipos lista de compras ────────────────────────────────────────────────────
interface Adjunto {
  id: number;
  ticket_id: number;
  nombre_archivo: string;
  nombre_original: string;
  mime?: string | null;
  creado_por?: number | null;
  creado_por_nombre?: string | null;
  creado_en: string;
  paso_id?: number | null;
}

function esImagenPortapapeles(f: File): boolean {
  if (f.type.startsWith("image/")) return true;
  if ((!f.type || f.type === "application/octet-stream") && f.size > 0) return true;
  return /\.(png|jpe?g|gif|webp|bmp)$/i.test(f.name);
}

function normalizarImagenPegada(raw: File): File {
  const mime = raw.type.startsWith("image/") ? raw.type : "image/png";
  const ext = mime.split("/")[1]?.replace("jpeg", "jpg") || "png";
  const nombre = raw.name && !/^image\.(png|jpe?g)$/i.test(raw.name)
    ? raw.name
    : `pegado-${Date.now()}.${ext}`;
  if (raw.name === nombre && raw.type === mime) return raw;
  return new File([raw], nombre, { type: mime });
}

function imagenDesdePortapapeles(cd: DataTransfer | null | undefined): File | null {
  if (!cd) return null;
  for (const item of Array.from(cd.items)) {
    if (item.kind !== "file" && !item.type.startsWith("image/")) continue;
    const f = item.getAsFile();
    if (f && esImagenPortapapeles(f)) return normalizarImagenPegada(f);
  }
  for (const f of Array.from(cd.files)) {
    if (esImagenPortapapeles(f)) return normalizarImagenPegada(f);
  }
  return null;
}

/** Imagen del portapapeles (Ctrl+V / captura). Devuelve null si no hay imagen. */
function clipboardPastedImageFile(e: React.ClipboardEvent): File | null {
  const file = imagenDesdePortapapeles(e.clipboardData);
  if (!file) return null;
  e.preventDefault();
  e.stopPropagation();
  return file;
}

/** Pega captura en zona activa (fallback global cuando React no dispara onPaste). */
function usePegarCapturaEnZona(
  activo: boolean,
  containerRef: React.RefObject<HTMLElement | null>,
  onImagen: (file: File) => void,
) {
  const onImagenRef = useRef(onImagen);
  onImagenRef.current = onImagen;

  useEffect(() => {
    if (!activo) return;
    const onPaste = (e: ClipboardEvent) => {
      if (!containerRef.current) return;
      const el = document.activeElement;
      if (el && !containerRef.current.contains(el)) return;
      const file = imagenDesdePortapapeles(e.clipboardData);
      if (!file) return;
      e.preventDefault();
      onImagenRef.current(normalizarImagenPegada(file));
    };
    window.addEventListener("paste", onPaste, true);
    return () => window.removeEventListener("paste", onPaste, true);
  }, [activo, containerRef]);
}

function manejarPasteCaptura(e: React.ClipboardEvent, onImagen: (file: File) => void): boolean {
  const file = clipboardPastedImageFile(e);
  if (!file) return false;
  onImagen(normalizarImagenPegada(file));
  return true;
}

interface ProtocoloPaso {
  descripcion: string;
  notas?: string | null;
  adjuntos_ref?: { nombre_archivo: string; mime: string }[];
}

interface Protocolo {
  id: number;
  titulo: string;
  descripcion?: string | null;
  categoria?: string | null;
  pasos: ProtocoloPaso[];
  lista_compras?: ItemCompraAccion[];
  alcance?: "personal" | "global" | "seleccionado" | string;
  usuarios_compartidos?: { id: number; nombre: string }[];
  ticket_origen?: number | null;
  ticket_origen_numero?: string | null;
  ticket_origen_titulo?: string | null;
  creado_por?: number | null;
  creado_por_nombre?: string | null;
  creado_en: string;
}

/** Plantilla para re-ejecutar una acción sin volver a describirla. */
interface PlantillaAccion {
  titulo: string;
  listaCompras: ItemCompraAccion[];
  pasos: PasoAccionDraft[];
  protocoloId?: number;
}

function plantillaDesdeProtocolo(p: Protocolo): PlantillaAccion {
  const lista = Array.isArray(p.lista_compras) ? p.lista_compras : [];
  return {
    titulo: p.titulo,
    protocoloId: p.id,
    listaCompras: lista.map((it) => ({
      n: it.n || "",
      cantidad: it.cantidad || "",
      unidad: (it.unidad === "u" ? "u" : "g") as UnidadCompra,
      comprado: false,
    })),
    pasos: (p.pasos || []).map((paso) => ({
      nombre: paso.descripcion,
      desc: paso.notas || "",
      adjuntos_ref: paso.adjuntos_ref ?? [],
    })),
  };
}

type PlantillaAccionApi = {
  titulo: string;
  lista_compras?: { n?: string; nombre?: string; cantidad?: string; unidad?: string }[];
  pasos?: { descripcion: string; notas?: string | null }[];
  protocolo_id?: number | null;
};

function plantillaDesdeApi(d: PlantillaAccionApi): PlantillaAccion {
  const lista = Array.isArray(d.lista_compras) ? d.lista_compras : [];
  return {
    titulo: d.titulo || "",
    protocoloId: d.protocolo_id ?? undefined,
    listaCompras: lista.map((it) => ({
      n: (it.n || it.nombre || "").trim(),
      cantidad: String(it.cantidad ?? ""),
      unidad: (it.unidad === "u" || it.unidad === "und" ? "u" : "g") as UnidadCompra,
      comprado: false,
    })),
    pasos: (d.pasos || []).map((paso) => ({
      nombre: paso.descripcion,
      desc: paso.notas || "",
      adjuntos_ref: (paso as any).adjuntos_ref ?? [],
    })),
  };
}

function parseListaComprasDesdeNotas(notas: string): ItemCompraAccion[] {
  const items: ItemCompraAccion[] = [];
  for (const line of (notas || "").split("\n")) {
    const t = line.trim();
    if (!t.startsWith("•")) continue;
    const body = t.replace(/^•\s*/, "").trim();
    let nombre = body;
    let cantidad = "";
    let unidad: UnidadCompra = "g";
    if (body.includes("—")) {
      const [n, resto] = body.split("—", 2);
      nombre = n.trim();
      const partes = resto.trim().split(/\s+/);
      if (partes.length >= 2) {
        cantidad = partes[0];
        unidad = partes[1] === "u" || partes[1] === "und" ? "u" : "g";
      } else if (partes.length === 1) cantidad = partes[0];
    }
    if (nombre) items.push({ n: nombre, cantidad, unidad, comprado: false });
  }
  return items;
}

/** Pantalla de logro al completar una tarea (compras, pasos, etc.). */
function PantallaLogro({
  titulo,
  subtitulo,
  detalle,
  emoji = "🏆",
  variant = "gold",
  botonLabel = "Continuar →",
  onContinuar,
}: {
  titulo: string;
  subtitulo?: string;
  detalle?: string;
  emoji?: string;
  variant?: "gold" | "green";
  botonLabel?: string;
  onContinuar: () => void;
}) {
  const ringBg = variant === "green"
    ? "radial-gradient(circle, rgba(74,154,106,0.35) 0%, transparent 70%)"
    : "radial-gradient(circle, rgba(244,196,77,0.4) 0%, transparent 70%)";
  const iconClass = variant === "green" ? "mck-celebrate text-7xl" : "mck-bounce-in text-8xl";
  return (
    <div className="flex min-h-[70vh] flex-col items-center justify-center gap-6 text-center px-4">
      <div className="relative">
        <div className={`${iconClass} select-none`}>{emoji}</div>
        <div
          className="absolute inset-0 rounded-full pointer-events-none"
          style={{ animation: "mck-ring-pulse 1s ease-out 0.3s both", background: ringBg }}
        />
      </div>
      <div className="mck-slide-up space-y-2" style={{ animationDelay: "0.2s" }}>
        <h2 className="text-4xl font-extrabold text-ink">{titulo}</h2>
        {subtitulo && <p className="text-lg text-muted">{subtitulo}</p>}
        {detalle && <p className="text-sm text-muted">{detalle}</p>}
      </div>
      <button
        type="button"
        onClick={onContinuar}
        className="mck-slide-up mt-4 rounded-2xl border-2 border-border px-8 py-3 text-base font-bold text-muted transition hover:border-accent hover:text-accent"
        style={{ animationDelay: "0.4s" }}
      >
        {botonLabel}
      </button>
    </div>
  );
}

type SolicitudListaVariant = "compra" | "etiqueta";

function mapItemsCompra(raw: unknown[]): ItemCompra[] {
  return raw.map((row) => {
    const r = row as ItemCompra & { material_nombre?: string };
    return {
      ...r,
      nombre: (r.nombre || r.material_nombre || "").trim(),
    };
  });
}

/** Checklist con casillas: compras y etiquetas. Espacio/Enter agrega ítem; al marcar todos se resuelve sola. */
function SolicitudListaChecklist({
  ticket, token, user, onChanged, onTerminado, supervision, pantallaCompleta, variant,
}: {
  ticket: Ticket; token: string; user: TicketsUser;
  onChanged: () => void;
  onTerminado?: () => void;
  supervision?: boolean;
  pantallaCompleta?: boolean;
  variant: SolicitudListaVariant;
}) {
  const esEtiqueta = variant === "etiqueta";
  const [items, setItems] = useState<ItemCompra[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const [facturaFile, setFacturaFile] = useState<File | null>(null);
  const [nuevoNombre, setNuevoNombre] = useState("");
  const [nuevoCantidad, setNuevoCantidad] = useState("1");
  const [estadoLocal, setEstadoLocal] = useState(ticket.estado);
  const [faseLogro, setFaseLogro] = useState(false);
  const resolviendoRef = useRef(false);
  const comprasPasteRef = useRef<HTMLDivElement>(null);
  const esAsignado = uidEq(ticket.asignado_a, user.id);
  const puedeOperar = esAsignado && !supervision;
  const resuelta = estadoLocal === "resuelto" || estadoLocal === "rechazado";
  const itemsActivos = items.filter((i) => i.nombre.trim());
  const todosMarcados = itemsActivos.length > 0 && itemsActivos.every((i) => !!i.comprado);
  const tieneProductos = itemsActivos.length > 0;

  useEffect(() => { setEstadoLocal(ticket.estado); }, [ticket.id, ticket.estado]);

  async function asegurarEnProceso() {
    if (estadoLocal === "en_proceso" || resuelta) return;
    await tapi(`/${ticket.id}/estado`, token, {
      method: "PUT",
      body: JSON.stringify({ estado: "en_proceso" }),
    });
    setEstadoLocal("en_proceso");
    onChanged();
  }

  async function cargar() {
    setLoading(true);
    setMsg("");
    try {
      let data = await tapi(`/${ticket.id}/lista-compras`, token);
      let raw = Array.isArray(data) ? data : [];
      if (raw.length === 0 && esEtiqueta && ticket.descripcion?.trim()) {
        const lineas = parseLineasPedidoEtiqueta(ticket.descripcion);
        if (lineas.length > 0) {
          for (const linea of lineas) {
            await tapi(`/${ticket.id}/lista-compras`, token, {
              method: "POST",
              body: JSON.stringify({
                nombre: linea.label,
                cantidad: linea.cantidad || 1,
                unidad: "und",
              }),
            });
          }
          data = await tapi(`/${ticket.id}/lista-compras`, token);
          raw = Array.isArray(data) ? data : [];
        }
      }
      setItems(mapItemsCompra(raw));
    } catch (e: unknown) {
      setItems([]);
      setMsg(e instanceof Error ? e.message : "No se pudo cargar la lista");
    } finally { setLoading(false); }
  }

  useEffect(() => { void cargar(); }, [ticket.id, token]);

  usePegarCapturaEnZona(
    !esEtiqueta && puedeOperar && !resuelta,
    comprasPasteRef,
    setFacturaFile,
  );

  function handlePasteFactura(e: React.ClipboardEvent) {
    const file = clipboardPastedImageFile(e);
    if (file) setFacturaFile(file);
  }

  async function toggleItem(item: ItemCompra) {
    if (!puedeOperar || resuelta) return;
    try {
      await asegurarEnProceso();
      const data = await tapi(`/lista-compras/${item.id}`, token, {
        method: "PUT",
        body: JSON.stringify({ comprado: item.comprado ? 0 : 1 }),
      });
      setItems(Array.isArray(data) ? mapItemsCompra(data) : items);
    } catch { /* ignore */ }
  }

  async function agregarItem() {
    const nombre = nuevoNombre.trim();
    if (!nombre || !puedeOperar || resuelta) return;
    const cantidad = Math.max(1, Math.floor(parseFloat(nuevoCantidad) || 1));
    setBusy(true);
    setMsg("");
    try {
      await asegurarEnProceso();
      const data = await tapi(`/${ticket.id}/lista-compras`, token, {
        method: "POST",
        body: JSON.stringify({ nombre, cantidad, unidad: esEtiqueta ? "u" : "und" }),
      });
      setItems(Array.isArray(data) ? mapItemsCompra(data) : items);
      setNuevoNombre("");
      setNuevoCantidad("1");
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "No se pudo agregar");
    } finally { setBusy(false); }
  }

  function onNuevoItemKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if ((e.key === "Enter" || e.key === " ") && nuevoNombre.trim()) {
      e.preventDefault();
      void agregarItem();
    }
  }

  async function resolverLista() {
    if (!todosMarcados || resuelta || resolviendoRef.current) return;
    resolviendoRef.current = true;
    setBusy(true);
    setMsg("");
    try {
      if (!esEtiqueta && facturaFile) {
        const fd = new FormData();
        fd.append("archivo", facturaFile);
        await tapi(`/${ticket.id}/adjuntos`, token, { method: "POST", body: fd });
      }
      const nombre = user.nombre || "Operador";
      const n = itemsActivos.length;
      const textoComentario = esEtiqueta
        ? `✅ Pedido de etiquetas completado por ${nombre} (${n} ítem${n !== 1 ? "s" : ""}).`
        : facturaFile
          ? `✅ Compras terminadas por ${nombre} — factura adjunta.`
          : `✅ Compras terminadas por ${nombre}.`;
      await tapi(`/${ticket.id}/comentarios`, token, {
        method: "POST",
        body: JSON.stringify({ texto: textoComentario, es_interno: false }),
      });
      if (ticket.ticket_padre_id) {
        const padreTxt = esEtiqueta
          ? `🏷️ **Etiquetas listas** (${ticket.numero})\nPor: ${nombre}`
          : `🛒 **Compras delegadas listas** (${ticket.numero})\nPor: ${nombre}`;
        await tapi(`/${ticket.ticket_padre_id}/comentarios`, token, {
          method: "POST",
          body: JSON.stringify({ texto: padreTxt, es_interno: false }),
        }).catch(() => {});
      }
      await tapi(`/${ticket.id}/estado`, token, {
        method: "PUT",
        body: JSON.stringify({ estado: "resuelto" }),
      });
      setEstadoLocal("resuelto");
      onChanged();
      if (pantallaCompleta) {
        onTerminado?.();
      } else {
        setFaseLogro(true);
      }
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "Error al cerrar");
    } finally {
      setBusy(false);
      resolviendoRef.current = false;
    }
  }

  useEffect(() => {
    if (!esEtiqueta) return;
    if (loading || busy || resuelta || !puedeOperar || !todosMarcados) return;
    void resolverLista();
  }, [items, loading, busy, resuelta, puedeOperar, todosMarcados, esEtiqueta]);

  function fmtItem(it: ItemCompra) {
    if (esEtiqueta) {
      return fmtUnidadesEtiqueta(it.cantidad);
    }
    const q = String(it.cantidad ?? "");
    const u = (it.unidad || "und").toLowerCase();
    if (!q || q === "1") return "";
    return u === "g" ? `${q} g` : `${q} ${u}`;
  }

  const wrapClass = pantallaCompleta ? "space-y-4" : "space-y-3 pt-1";

  if (faseLogro && !pantallaCompleta) {
    const n = itemsActivos.length;
    return (
      <PantallaLogro
        emoji={esEtiqueta ? "🏷️" : "🛒"}
        variant="green"
        titulo={esEtiqueta ? "¡Etiquetas completadas!" : "¡Compras completadas!"}
        subtitulo={ticket.titulo}
        detalle={
          ticket.ticket_padre_titulo
            ? `${n} ítem${n !== 1 ? "s" : ""} · Para: ${ticket.ticket_padre_titulo}`
            : `${n} ítem${n !== 1 ? "s" : ""} marcados en la lista`
        }
        botonLabel="Listo →"
        onContinuar={() => {
          setFaseLogro(false);
          onTerminado?.();
        }}
      />
    );
  }

  return (
    <div
      ref={comprasPasteRef}
      className={wrapClass}
      onPasteCapture={!esEtiqueta && puedeOperar && !resuelta ? handlePasteFactura : undefined}
    >
      {pantallaCompleta && (
        <p className="text-xs font-bold uppercase tracking-widest text-accent">
          {esEtiqueta ? "Pedido de etiquetas" : "Ir de compras"}
        </p>
      )}
      {ticket.ticket_padre_titulo && (
        <p className={pantallaCompleta ? "text-sm text-muted" : "text-xs text-muted"}>
          Para la acción: <strong className="text-ink">{ticket.ticket_padre_titulo}</strong>
        </p>
      )}
      {loading && <p className="text-sm text-muted">Cargando lista…</p>}
      {!loading && !tieneProductos && !msg && puedeOperar && !resuelta && (
        <p className="text-sm text-muted">
          {esEtiqueta
            ? "Escribe un producto y pulsa Espacio para agregarlo."
            : "Escribe un producto y pulsa Espacio para agregarlo a la lista."}
        </p>
      )}
      {!loading && !tieneProductos && msg && (
        <div className="space-y-2">
          <p className="text-sm text-red-500">{msg}</p>
          <button
            type="button"
            onClick={() => void cargar()}
            className="w-full rounded-xl border border-border py-2 text-xs font-bold text-accent hover:border-accent"
          >
            Reintentar cargar lista
          </button>
        </div>
      )}
      {!loading && tieneProductos && itemsActivos.map((it) => (
        <button
          key={it.id}
          type="button"
          disabled={resuelta || !puedeOperar}
          onClick={() => void toggleItem(it)}
          className={`w-full flex items-center gap-3 rounded-2xl border-2 px-4 py-3 text-left transition
            ${it.comprado ? "border-accent bg-accent/10" : "border-border bg-surface-panel hover:border-accent/40"}
            disabled:opacity-60`}
        >
          <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border-2 text-sm font-bold
            ${it.comprado ? "border-accent bg-accent text-white" : "border-border text-muted"}`}>
            {it.comprado ? "✓" : ""}
          </span>
          <div className="min-w-0 flex-1">
            <p className={`text-sm font-bold ${it.comprado ? "text-accent line-through" : "text-ink"}`}>
              {it.nombre}
            </p>
            {fmtItem(it) && <p className="text-xs text-muted">{fmtItem(it)}</p>}
          </div>
        </button>
      ))}

      {!resuelta && puedeOperar && (
        <div className="space-y-2">
          <input
            type="text"
            value={nuevoNombre}
            onChange={(e) => setNuevoNombre(e.target.value)}
            onKeyDown={onNuevoItemKeyDown}
            disabled={busy}
            placeholder={esEtiqueta ? "Producto y presentación…" : "Producto o material…"}
            className="w-full rounded-xl border-2 border-border bg-surface-input px-4 py-3 text-sm text-ink outline-none focus:border-accent"
          />
          {esEtiqueta && (
            <div className="flex gap-2">
              <label className="flex flex-1 flex-col gap-1">
                <span className="text-[10px] font-bold uppercase tracking-widest text-muted">Unidades</span>
                <input
                  type="number"
                  min={1}
                  step={1}
                  value={nuevoCantidad}
                  onChange={(e) => setNuevoCantidad(e.target.value)}
                  disabled={busy}
                  placeholder="Cant."
                  className="w-full rounded-xl border-2 border-border bg-surface-input px-3 py-2 text-sm text-ink outline-none focus:border-accent"
                />
              </label>
              <button
                type="button"
                onClick={() => void agregarItem()}
                disabled={busy || !nuevoNombre.trim()}
                className="mt-auto rounded-xl border-2 border-accent px-4 py-2 text-sm font-bold text-accent hover:bg-accent hover:text-white disabled:opacity-40"
              >
                + Agregar
              </button>
            </div>
          )}
          <p className="text-[10px] text-center text-muted">
            {esEtiqueta
              ? "Espacio o Enter agrega el ítem · indica cuántas etiquetas imprimir"
              : "Espacio o Enter agrega un ítem · marca todo y confirma con el botón de abajo"}
          </p>
          {!esEtiqueta && tieneProductos && (
            <label className={`flex cursor-pointer flex-col items-center gap-2 rounded-xl border-2 border-dashed px-4 py-3 transition
              ${facturaFile ? "border-accent bg-accent/8" : "border-border hover:border-accent/60"}`}>
              <span className="text-xs font-bold text-accent">
                {facturaFile ? facturaFile.name : "📷 Factura de caja (opcional) — Ctrl+V"}
              </span>
              {facturaFile && (
                <button
                  type="button"
                  onClick={(e) => { e.preventDefault(); setFacturaFile(null); }}
                  className="text-[10px] text-danger hover:underline"
                >
                  Quitar
                </button>
              )}
              <input
                type="file"
                accept="image/*,.pdf,application/pdf"
                className="sr-only"
                onChange={(e) => setFacturaFile(e.target.files?.[0] ?? null)}
              />
            </label>
          )}
          {!esEtiqueta && tieneProductos && (
            <button
              type="button"
              disabled={busy || !todosMarcados}
              onClick={() => void resolverLista()}
              className="w-full rounded-2xl bg-accent py-3.5 text-base font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
            >
              {busy ? "Cerrando solicitud…" : "✅ Todo listo — cerrar solicitud"}
            </button>
          )}
          {esEtiqueta && puedeVerSeccionPanel(user, "etiquetas") && (
            <button
              type="button"
              onClick={() => irAImprimirDesdeSolicitud({
                id: ticket.id,
                titulo: ticket.titulo,
                descripcion: ticket.descripcion,
                numero: ticket.numero,
                creado_por_nombre: ticket.creado_por_nombre ?? undefined,
              })}
              className="w-full rounded-xl border-2 border-accent/50 py-2.5 text-sm font-bold text-accent hover:bg-accent/5"
            >
              🖨 Abrir Impresora · Etiquetas
            </button>
          )}
        </div>
      )}
      {!resuelta && esAsignado && supervision && tieneProductos && (
        <p className="text-[10px] text-center text-muted">Vista de supervisión</p>
      )}
      {busy && todosMarcados && !resuelta && esEtiqueta && (
        <p className="text-xs text-center text-accent font-semibold">Cerrando solicitud…</p>
      )}
      {msg && !busy && <p className="text-xs text-accent font-semibold">{msg}</p>}
    </div>
  );
}

function SolicitudCompraChecklist(props: Omit<React.ComponentProps<typeof SolicitudListaChecklist>, "variant">) {
  return <SolicitudListaChecklist {...props} variant="compra" />;
}

/** Pantalla dedicada: solo lista de compras (sin wizard de acción completa). */
function PanelIrDeCompras({
  ticket, token, user, onSalir, onTerminado,
}: {
  ticket: Ticket; token: string; user: TicketsUser;
  onSalir: () => void;
  onTerminado: () => void;
}) {
  const [faseLogro, setFaseLogro] = useState(false);

  if (faseLogro) {
    return (
      <div className="mx-auto max-w-lg">
        <PantallaLogro
          emoji="🛒"
          variant="green"
          titulo="¡Compras completadas!"
          subtitulo={ticket.titulo}
          detalle={
            ticket.ticket_padre_titulo
              ? `Quien delegó puede continuar: ${ticket.ticket_padre_titulo}`
              : "Tu solicitud de compras quedó cerrada"
          }
          botonLabel="Volver a solicitudes →"
          onContinuar={onTerminado}
        />
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-lg space-y-4 pb-10">
      <button
        type="button"
        onClick={onSalir}
        className="rounded-xl border-2 border-border px-3 py-1.5 text-xs font-bold text-muted hover:border-accent hover:text-accent"
      >
        ← Volver a solicitudes
      </button>
      <div>
        <h2 className="text-2xl font-extrabold text-ink leading-tight">Ir de compras</h2>
        <p className="mt-1 font-mono text-sm text-muted">{ticket.numero}</p>
        <p className="mt-2 text-sm text-ink">{ticket.titulo}</p>
      </div>
      <div className="rounded-2xl border-2 border-accent/40 bg-surface p-4 shadow-sm">
        <SolicitudCompraChecklist
          ticket={ticket}
          token={token}
          user={user}
          pantallaCompleta
          onChanged={() => {}}
          onTerminado={() => setFaseLogro(true)}
        />
      </div>
      <p className="text-center text-xs text-muted">
        Marca todos los ítems y pulsa «Todo listo» para cerrar la solicitud.
      </p>
    </div>
  );
}

interface ItemCompra {
  id: number;
  ticket_id: number;
  nombre: string;
  sku: string | null;
  material_id: number | null;
  cantidad: number;
  unidad: string;
  precio_estimado: number | null;
  comprado: number;
  notas: string | null;
  creado_por_nombre: string | null;
  material_nombre: string | null;
  material_unidad: string | null;
}

interface ProductoCatalogo {
  id: number;
  nombre: string;
  codigo: string | null;
  unidad_medida: string | null;
  tipo: string;
}

function shortNumero(numero: string): string {
  const m = numero.match(/(\d+)$/);
  return m ? `# ${m[1]}` : numero;
}

// ── SolicitudCard ─────────────────────────────────────────────────────────────

function SolicitudCard({
  ticket, token, user, onChanged, onCerrarDetalle, isAdmin, supervision, protocolos = [],
  onRegistrarEjecucion, detalleAmpliado = false, onIrAIntervencion,
}: {
  ticket: Ticket; token: string; user: TicketsUser;
  onChanged: () => void;
  /** Llamado tras resolver o aprobar exitosamente (para cerrar el panel de detalle). */
  onCerrarDetalle?: () => void;
  isAdmin?: boolean;
  /** Vista equipo/admin: estado visible, sin botones ni aviso de "solo el asignado". */
  supervision?: boolean;
  protocolos?: Protocolo[];
  /** Abre el asistente de acción vinculado a esta solicitud. */
  onRegistrarEjecucion?: (ticket: Ticket) => void;
  /** Vista expandida: tipografía mayor y secciones visibles de inmediato. */
  detalleAmpliado?: boolean;
  /** Abre el ticket hijo de intervención que bloquea esta solicitud. */
  onIrAIntervencion?: (intervencionId: number) => void;
}) {
  const nivel = (user.rol?.nivel ?? 1);
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [msg, setMsg] = useState("");
  const [showEdit, setShowEdit] = useState(false);
  const [editDraft, setEditDraft] = useState({ titulo: "", descripcion: "", prioridad: "" });
  const [guardandoEdit, setGuardandoEdit] = useState(false);
  const esAsignado = uidEq(ticket.asignado_a, user.id);
  const esCreadoPorMi = uidEq(ticket.creado_por, user.id);
  const esParticipante = ticket.participantes?.some((p) => p.usuario_id === user.id) ?? false;
  const esIntervencion = !!ticket.ticket_padre_id;
  const resuelta = ticket.estado === "resuelto" || ticket.estado === "rechazado";
  const puedeVerChat = esAsignado || esCreadoPorMi || esParticipante || supervision || isAdmin || nivel >= 2;
  const puedeEnviarChat = !resuelta && puedeVerChat && !ticket.bloqueado_por;
  const puedeVerSensible = nivel >= 2 || esAsignado || esCreadoPorMi || esParticipante;
  const puedeSubirAdjuntos = (esAsignado || esCreadoPorMi || nivel >= 2) && !resuelta;
  // El backend manda a revisión del solicitante cuando cierra quien la ejecutó
  // (tickets_db._requiere_aprobacion_del_solicitante): mismas excepciones aquí.
  const cierreVaARevision =
    (ticket.tipo ?? "solicitud") === "solicitud"
    && esAsignado && !esCreadoPorMi && !esIntervencion
    && !["compra", "etiqueta"].includes((ticket.subtipo ?? "").trim());

  // Pasos/checklist
  const [pasos, setPasos] = useState<Paso[]>([]);
  const [loadingPasos, setLoadingPasos] = useState(false);
  const [showPasos, setShowPasos] = useState(false);
  const [editandoPasoId, setEditandoPasoId] = useState<number | null>(null);
  const [editPasoDesc, setEditPasoDesc] = useState("");
  const [editPasoNotas, setEditPasoNotas] = useState("");
  const [nuevoPasoDesc, setNuevoPasoDesc] = useState("");
  const [agregandoPaso, setAgregandoPaso] = useState(false);
  const [showAddPaso, setShowAddPaso] = useState(false);

  // Lista de compras
  const [showCompras, setShowCompras] = useState(false);
  const [compras, setCompras] = useState<ItemCompra[]>([]);
  const [loadingCompras, setLoadingCompras] = useState(false);
  const [nuevoProducto, setNuevoProducto] = useState({ nombre: "", sku: "", cantidad: "1", unidad: "und", precio: "" });
  const [busqProducto, setBusqProducto] = useState("");
  const [resultadosBusq, setResultadosBusq] = useState<ProductoCatalogo[]>([]);
  const [agregandoCompra, setAgregandoCompra] = useState(false);

  // Intervención (blocker)
  const [showIntervencion, setShowIntervencion] = useState(false);
  const [interForm, setInterForm] = useState({ titulo: "", descripcion: "", asignado_a: "", paso_ref: "", paso_id: 0 });
  const [usuarios, setUsuarios] = useState<UserInfo[]>([]);
  const [creandoInter, setCreandoInter] = useState(false);

  // Resolución de intervención
  const [resolucionInter, setResolucionInter] = useState("");

  // Comentarios (respuestas de intervención)
  const [comentarios, setComentarios] = useState<Comentario[]>([]);
  const [loadingComentarios, setLoadingComentarios] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [chatDraft, setChatDraft] = useState("");
  const [archivoPendiente, setArchivoPendiente] = useState<File | null>(null);
  const [archivoPreview, setArchivoPreview] = useState<string | null>(null);
  const [archivoListo, setArchivoListo] = useState(false);
  const archivoPendienteRef = useRef<File | null>(null);
  const intervencionZoneRef = useRef<HTMLDivElement>(null);
  const chatMensajesRef = useRef<HTMLDivElement>(null);
  const interArchivoRef = useRef<HTMLInputElement>(null);
  const chatArchivoRef = useRef<HTMLInputElement>(null);
  const [enviandoChat, setEnviandoChat] = useState(false);
  const hayArchivoPendiente = archivoListo || !!archivoPendiente || !!archivoPreview;
  const puedeResolverIntervencion = !busy && (!!resolucionInter.trim() || hayArchivoPendiente);

  // Adjuntos
  const [adjuntos, setAdjuntos] = useState<Adjunto[]>([]);
  const [loadingAdjuntos, setLoadingAdjuntos] = useState(false);
  const [showAdjuntos, setShowAdjuntos] = useState(false);
  const [eliminandoAdj, setEliminandoAdj] = useState<number | null>(null);
  const [subiendoAdjPaso, setSubiendoAdjPaso] = useState<number | null>(null);
  const [pasoPasteId, setPasoPasteId] = useState<number | null>(null);
  const pasosChecklistRef = useRef<HTMLDivElement>(null);
  const [subiendoAdjTicket, setSubiendoAdjTicket] = useState(false);
  const [lightboxUrl, setLightboxUrl] = useState<string | null>(null);
  const [showExtrasMenu, setShowExtrasMenu] = useState(false);

  const adjuntosPorPaso = useMemo(() => {
    const map = new Map<number, Adjunto[]>();
    for (const a of adjuntos) {
      if (a.paso_id) {
        if (!map.has(a.paso_id)) map.set(a.paso_id, []);
        map.get(a.paso_id)!.push(a);
      }
    }
    return map;
  }, [adjuntos]);

  const [showPedirRevision, setShowPedirRevision] = useState(false);
  const [notaRevision, setNotaRevision] = useState("");
  const [showPedirAjustes, setShowPedirAjustes] = useState(false);
  const [ajustesMensaje, setAjustesMensaje] = useState("");
  const [ajustesArchivo, setAjustesArchivo] = useState<File | null>(null);
  const [ajustesArchivoPreview, setAjustesArchivoPreview] = useState<string | null>(null);

  // Guardar como protocolo
  const [showProtocoloForm, setShowProtocoloForm] = useState(false);
  const [protocoloForm, setProtocoloForm] = useState({ titulo: "", descripcion: "", categoria: "" });
  const [guardandoProtocolo, setGuardandoProtocolo] = useState(false);
  const [protocoloMsg, setProtocoloMsg] = useState("");
  const [guardarComoProcedimiento, setGuardarComoProcedimiento] = useState(false);
  const [alcanceProcedimiento, setAlcanceProcedimiento] = useState<"personal" | "global">("personal");
  const [generandoProcedimiento, setGenerandoProcedimiento] = useState(false);

  // Enlazar protocolo existente
  const [showVincularProtocolo, setShowVincularProtocolo] = useState(false);
  const [protocoloVincularId, setProtocoloVincularId] = useState<number | "">("");
  const [reemplazarPasosProtocolo, setReemplazarPasosProtocolo] = useState(false);
  const [vinculandoProtocolo, setVinculandoProtocolo] = useState(false);
  const [vincularProtocoloMsg, setVincularProtocoloMsg] = useState("");

  // Datos sensibles
  const [showSensible, setShowSensible] = useState(false);
  const [sensibleTexto, setSensibleTexto] = useState("");
  const [editandoSensible, setEditandoSensible] = useState(false);
  const [sensibleDraft, setSensibleDraft] = useState("");
  const [loadingSensible, setLoadingSensible] = useState(false);
  const [sensibleMsg, setSensibleMsg] = useState("");

  // Adjuntos visibles para todo el equipo al abrir la solicitud
  useEffect(() => {
    void cargarAdjuntos();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ticket.id]);

  useEffect(() => {
    if (adjuntos.length > 0) setShowAdjuntos(true);
  }, [adjuntos.length]);

  useEffect(() => {
    if (adjuntos.some((a) => a.paso_id) && pasos.length === 0) void cargarPasos();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [adjuntos, ticket.id]);

  // Cargar pasos al iniciar (en proceso o supervisión). En detalleAmpliado no los mostramos
  // automáticamente: el usuario los abre desde "+ Opciones" para no saturar la vista de chat.
  useEffect(() => {
    if (ticket.estado === "en_proceso" || supervision) {
      void cargarPasos();
      if (ticket.estado === "en_proceso" && !detalleAmpliado) setShowPasos(true);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ticket.id, ticket.estado, supervision]);

  // Vista ampliada: mostrar conversación de inmediato
  useEffect(() => {
    if (!detalleAmpliado) return;
    setShowChat(true);
    void cargarComentarios();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [detalleAmpliado, ticket.id]);

  useEffect(() => {
    limpiarArchivoPendiente();
    setResolucionInter("");
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ticket.id]);

  async function cargarPasos() {
    setLoadingPasos(true);
    try {
      const data = await tapi(`/${ticket.id}/pasos`, token);
      setPasos(Array.isArray(data) ? data : []);
    } catch { /* ignore */ } finally { setLoadingPasos(false); }
  }

  async function togglePaso(paso: Paso) {
    try {
      const data = await tapi(`/${ticket.id}/pasos/${paso.id}`, token, {
        method: "PUT",
        body: JSON.stringify({ completado: paso.completado ? 0 : 1 }),
      });
      if (data.pasos) setPasos(data.pasos);
      else if (Array.isArray(data)) setPasos(data);
      onChanged();
    } catch { /* ignore */ }
  }

  async function subirAdjuntoPaso(pasoId: number, file: File) {
    setSubiendoAdjPaso(pasoId);
    try {
      const fd = new FormData();
      fd.append("archivo", file);
      const res = await fetch(`/api/tickets/${ticket.id}/pasos/${pasoId}/adjuntos`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: fd,
      });
      if (res.ok) void cargarAdjuntos();
    } catch { /* no crítico */ } finally {
      setSubiendoAdjPaso(null);
    }
  }

  usePegarCapturaEnZona(showPasos && esAsignado && !supervision && !resuelta, pasosChecklistRef, (file) => {
    const targetId = pasoPasteId ?? pasos.find((p) => !pasoEstaCompletado(p))?.id ?? pasos[0]?.id;
    if (targetId) void subirAdjuntoPaso(targetId, file);
  });

  async function subirAdjuntoTicket(file: File) {
    setSubiendoAdjTicket(true);
    try {
      const fd = new FormData();
      fd.append("archivo", file);
      await tapi(`/${ticket.id}/adjuntos`, token, { method: "POST", body: fd });
      void cargarAdjuntos();
    } catch { /* no crítico */ } finally {
      setSubiendoAdjTicket(false);
    }
  }

  function asignarImagenPendiente(
    file: File,
    setFile: (f: File | null) => void,
    preview: string | null,
    setPreview: (u: string | null) => void,
  ) {
    if (preview) URL.revokeObjectURL(preview);
    setFile(file);
    setPreview(file.type.startsWith("image/") ? URL.createObjectURL(file) : null);
  }

  function quitarImagenPendiente(
    setFile: (f: File | null) => void,
    preview: string | null,
    setPreview: (u: string | null) => void,
  ) {
    if (preview) URL.revokeObjectURL(preview);
    setFile(null);
    setPreview(null);
  }

  function limpiarArchivoPendiente() {
    archivoPendienteRef.current = null;
    quitarImagenPendiente(setArchivoPendiente, archivoPreview, setArchivoPreview);
    setArchivoListo(false);
  }

  function asignarArchivoPendiente(file: File) {
    const norm = normalizarImagenPegada(file);
    archivoPendienteRef.current = norm;
    if (archivoPreview) URL.revokeObjectURL(archivoPreview);
    setArchivoPendiente(norm);
    setArchivoPreview(URL.createObjectURL(norm));
    setArchivoListo(true);
    if (puedeEnviarChat) setShowChat(true);
  }

  function handlePasteImagen(e: React.ClipboardEvent) {
    const file = clipboardPastedImageFile(e);
    if (!file) return;
    if (showPedirAjustes) {
      asignarImagenPendiente(file, setAjustesArchivo, ajustesArchivoPreview, setAjustesArchivoPreview);
      return;
    }
    asignarArchivoPendiente(file);
  }

  function onArchivoInterSeleccionado(f: File | null) {
    if (!f || !esImagenPortapapeles(f)) return;
    asignarArchivoPendiente(f);
  }

  usePegarCapturaEnZona(
    !resuelta && esAsignado && !supervision && esIntervencion,
    intervencionZoneRef,
    asignarArchivoPendiente,
  );
  usePegarCapturaEnZona(
    puedeEnviarChat && (showChat || detalleAmpliado),
    chatMensajesRef,
    asignarArchivoPendiente,
  );

  function vistaPreviaPegada(className = "") {
    if (!hayArchivoPendiente) return null;
    return (
      <div className={`flex items-center gap-2 rounded-lg border border-accent/40 bg-accent/5 px-2 py-1.5 ${className}`}>
        {archivoPreview ? (
          <img src={archivoPreview} alt="" className="h-12 w-12 rounded object-cover border border-border" />
        ) : (
          <span className="flex h-12 w-12 items-center justify-center rounded border border-border bg-surface text-lg">📷</span>
        )}
        <span className="min-w-0 flex-1 truncate text-xs text-muted">{archivoPendiente?.name ?? "Imagen lista"}</span>
        <button type="button" onClick={limpiarArchivoPendiente} className="shrink-0 text-xs text-danger hover:underline">
          Quitar
        </button>
      </div>
    );
  }

  function iniciarEditPaso(p: Paso) {
    setEditandoPasoId(p.id);
    setEditPasoDesc(p.descripcion);
    setEditPasoNotas((p.notas as string | null) ?? "");
  }

  async function guardarEditPaso(paso: Paso) {
    if (!editPasoDesc.trim()) return;
    try {
      const data = await tapi(`/${ticket.id}/pasos/${paso.id}`, token, {
        method: "PUT",
        body: JSON.stringify({ descripcion: editPasoDesc, notas: editPasoNotas }),
      });
      setPasos(Array.isArray(data) ? data : data.pasos ?? pasos);
    } catch { /* ignore */ } finally {
      setEditandoPasoId(null);
    }
  }

  async function agregarPasoInline() {
    if (!nuevoPasoDesc.trim()) return;
    setAgregandoPaso(true);
    try {
      const data = await tapi(`/${ticket.id}/pasos`, token, {
        method: "POST",
        body: JSON.stringify({ descripcion: nuevoPasoDesc }),
      });
      setPasos(Array.isArray(data) ? data : pasos);
      setNuevoPasoDesc("");
      setShowAddPaso(false);
      onChanged();
    } catch { /* ignore */ } finally { setAgregandoPaso(false); }
  }

  async function eliminarPasoInline(pasoId: number) {
    try {
      const data = await tapi(`/pasos/${pasoId}`, token, { method: "DELETE" });
      setPasos(Array.isArray(data) ? data : pasos);
      onChanged();
    } catch { /* ignore */ }
  }

  async function cargarCompras() {
    setLoadingCompras(true);
    try {
      const data = await tapi(`/${ticket.id}/lista-compras`, token);
      setCompras(Array.isArray(data) ? data : []);
    } catch { /* ignore */ } finally { setLoadingCompras(false); }
  }

  async function buscarProducto(q: string) {
    setBusqProducto(q);
    setNuevoProducto((p) => ({ ...p, nombre: q }));
    if (q.length < 2) { setResultadosBusq([]); return; }
    try {
      const data = await tapi(`/productos/buscar?q=${encodeURIComponent(q)}`, token);
      setResultadosBusq(Array.isArray(data) ? data : []);
    } catch { setResultadosBusq([]); }
  }

  function seleccionarProductoCatalogo(prod: ProductoCatalogo) {
    setNuevoProducto((p) => ({
      ...p,
      nombre: prod.nombre,
      sku: prod.codigo ?? "",
      unidad: prod.unidad_medida ?? "und",
    }));
    setBusqProducto(prod.nombre);
    setResultadosBusq([]);
  }

  async function agregarCompra() {
    if (!nuevoProducto.nombre.trim()) return;
    setAgregandoCompra(true);
    try {
      const data = await tapi(`/${ticket.id}/lista-compras`, token, {
        method: "POST",
        body: JSON.stringify({
          nombre: nuevoProducto.nombre,
          sku: nuevoProducto.sku || undefined,
          cantidad: parseFloat(nuevoProducto.cantidad) || 1,
          unidad: nuevoProducto.unidad,
          precio_estimado: nuevoProducto.precio ? parseFloat(nuevoProducto.precio) : undefined,
        }),
      });
      setCompras(Array.isArray(data) ? data : compras);
      setNuevoProducto({ nombre: "", sku: "", cantidad: "1", unidad: "und", precio: "" });
      setBusqProducto("");
    } catch { /* ignore */ } finally { setAgregandoCompra(false); }
  }

  async function toggleComprado(item: ItemCompra) {
    try {
      const data = await tapi(`/lista-compras/${item.id}`, token, {
        method: "PUT",
        body: JSON.stringify({ comprado: item.comprado ? 0 : 1 }),
      });
      setCompras(Array.isArray(data) ? data : compras);
    } catch { /* ignore */ }
  }

  async function eliminarCompra(itemId: number) {
    try {
      const data = await tapi(`/lista-compras/${itemId}`, token, { method: "DELETE" });
      setCompras(Array.isArray(data) ? data : compras);
    } catch { /* ignore */ }
  }

  function abrirIntervencionDesdePaso(paso: Paso) {
    void abrirIntervencion();
    setInterForm((f) => ({
      ...f,
      titulo: `Paso ${paso.orden}: ${paso.descripcion}`,
      descripcion: "",
      paso_ref: `Paso ${paso.orden}: ${paso.descripcion}`,
      paso_id: paso.id,
    }));
  }

  async function resolver() {
    if (!esAsignado || busy) return;
    if (ticket.bloqueado_por) {
      setMsg("No se puede terminar: hay una intervención pendiente de otro usuario.");
      setTimeout(() => setMsg(""), 4000);
      return;
    }
    // Validación previa en el cliente usando contadores del ticket
    const total = ticket.pasos_total ?? 0;
    const hechos = ticket.pasos_completados ?? 0;
    if (total > 0 && hechos < total) {
      setMsg(`Faltan ${total - hechos} paso(s) por completar antes de marcar como lista.`);
      setTimeout(() => setMsg(""), 4000);
      return;
    }
    // Validación adicional con pasos cargados en memoria
    const pasosPendientes = pasos.filter((p) => !pasoEstaCompletado(p));
    if (pasos.length > 0 && pasosPendientes.length > 0) {
      setMsg(`Faltan ${pasosPendientes.length} paso(s) por completar antes de marcar como lista.`);
      setTimeout(() => setMsg(""), 4000);
      return;
    }
    const aviso = cierreVaARevision
      ? `¿Marcar "${ticket.titulo}" como lista?\n\nPasa a revisión de ${ticket.creado_por_nombre ?? "quien la pidió"}, que la cierra al aprobarla.`
      : `¿Marcar "${ticket.titulo}" como lista?\n\nEsta acción no se puede deshacer.`;
    if (!isMcKennaAndroidApp() && !confirm(aviso)) return;
    setBusy(true);
    try {
      if (guardarComoProcedimiento) {
        if (pasos.length === 0 && (ticket.pasos_total ?? 0) > 0) await cargarPasos();
        await guardarProcedimientoDesdeSolicitud();
      }
      await tapi(`/${ticket.id}/estado`, token, { method: "PUT", body: JSON.stringify({ estado: "resuelto" }) });
      onChanged();
      onCerrarDetalle?.();
    } catch (e: any) {
      setMsg(e.message ?? "Error");
      setTimeout(() => setMsg(""), 4000);
    } finally { setBusy(false); }
  }

  async function pedirRevision() {
    if (!esAsignado || busy) return;
    const total = ticket.pasos_total ?? 0;
    const hechos = ticket.pasos_completados ?? 0;
    if (total > 0 && hechos < total) {
      setMsg(`Faltan ${total - hechos} paso(s) por completar antes de pedir revisión.`);
      setTimeout(() => setMsg(""), 4000);
      return;
    }
    setBusy(true);
    try {
      if (guardarComoProcedimiento) {
        if (pasos.length === 0 && (ticket.pasos_total ?? 0) > 0) await cargarPasos();
        await guardarProcedimientoDesdeSolicitud();
      }
      await tapi(`/${ticket.id}/estado`, token, {
        method: "PUT",
        body: JSON.stringify({
          estado: "esperando_aprobacion",
          motivo: notaRevision.trim() || undefined,
        }),
      });
      setShowPedirRevision(false);
      setNotaRevision("");
      onChanged();
    } catch (e: any) {
      setMsg(e.message ?? "Error al pedir revisión");
      setTimeout(() => setMsg(""), 4000);
    } finally { setBusy(false); }
  }

  async function aprobar() {
    if (!esCreadoPorMi || busy) return;
    if (!isMcKennaAndroidApp() && !confirm(`¿Aprobar y cerrar la solicitud "${ticket.titulo}"?`)) return;
    setBusy(true);
    try {
      await tapi(`/${ticket.id}/estado`, token, {
        method: "PUT",
        body: JSON.stringify({ estado: "resuelto" }),
      });
      onChanged();
      onCerrarDetalle?.();
    } catch (e: any) {
      setMsg(e.message ?? "Error al aprobar");
      setTimeout(() => setMsg(""), 4000);
    } finally { setBusy(false); }
  }

  async function cerrarDirecto() {
    if ((!esCreadoPorMi && !isAdmin) || busy) return;
    if (!isMcKennaAndroidApp() && !confirm(`¿Finalizar y cerrar la solicitud "${ticket.titulo}"?\n\nEsta acción no se puede deshacer.`)) return;
    setBusy(true);
    try {
      await tapi(`/${ticket.id}/estado`, token, { method: "PUT", body: JSON.stringify({ estado: "resuelto" }) });
      onChanged();
      onCerrarDetalle?.();
    } catch (e: any) {
      setMsg(e.message ?? "Error al cerrar");
      setTimeout(() => setMsg(""), 4000);
    } finally { setBusy(false); }
  }

  async function pedirAjustes() {
    if (!esCreadoPorMi || busy) return;
    if (!ajustesMensaje.trim()) {
      setMsg("Describe qué ajustes necesitas.");
      setTimeout(() => setMsg(""), 3000);
      return;
    }
    setBusy(true);
    try {
      await tapi(`/${ticket.id}/estado`, token, {
        method: "PUT",
        body: JSON.stringify({ estado: "en_proceso", motivo: ajustesMensaje.trim() }),
      });
      if (ajustesArchivo) {
        const fd = new FormData();
        fd.append("archivo", ajustesArchivo);
        await fetch(`/api/tickets/${ticket.id}/adjuntos`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: fd,
        }).catch(() => { /* adjunto no crítico */ });
      }
      setShowPedirAjustes(false);
      setAjustesMensaje("");
      setAjustesArchivo(null);
      setAjustesArchivoPreview(null);
      onChanged();
    } catch (e: any) {
      setMsg(e.message ?? "Error");
      setTimeout(() => setMsg(""), 4000);
    } finally { setBusy(false); }
  }

  async function rechazarRevision() {
    if (!esCreadoPorMi || busy) return;
    const motivo = prompt("Motivo del rechazo (opcional):");
    if (motivo === null) return;
    setBusy(true);
    try {
      await tapi(`/${ticket.id}/estado`, token, {
        method: "PUT",
        body: JSON.stringify({ estado: "rechazado", motivo: motivo.trim() || undefined }),
      });
      onChanged();
    } catch (e: any) {
      setMsg(e.message ?? "Error al rechazar");
      setTimeout(() => setMsg(""), 4000);
    } finally { setBusy(false); }
  }

  async function cancelarRevision() {
    if (!esAsignado || busy) return;
    setBusy(true);
    try {
      await tapi(`/${ticket.id}/estado`, token, {
        method: "PUT",
        body: JSON.stringify({ estado: "en_proceso" }),
      });
      onChanged();
    } catch (e: any) {
      setMsg(e.message ?? "Error");
      setTimeout(() => setMsg(""), 4000);
    } finally { setBusy(false); }
  }

  async function resolverIntervencion() {
    if (!esAsignado || busy) return;
    const texto = resolucionInter.trim();
    const archivo = archivoPendienteRef.current ?? archivoPendiente;
    if (!texto && !archivo) {
      setMsg("Escribe tu respuesta o adjunta una imagen antes de resolver.");
      setTimeout(() => setMsg(""), 3000);
      return;
    }
    setBusy(true);
    try {
      if (archivo) {
        const fd = new FormData();
        fd.append("archivo", archivo);
        await tapi(`/${ticket.id}/adjuntos`, token, { method: "POST", body: fd });
        limpiarArchivoPendiente();
        void cargarAdjuntos();
      }
      await tapi(`/${ticket.id}/comentarios`, token, {
        method: "POST",
        body: JSON.stringify({
          texto: texto || "📎 Resolución con imagen adjunta",
        }),
      });
      await tapi(`/${ticket.id}/estado`, token, {
        method: "PUT",
        body: JSON.stringify({ estado: "resuelto" }),
      });
      setResolucionInter("");
      onChanged();
    } catch (e: any) {
      setMsg(e.message ?? "Error");
      setTimeout(() => setMsg(""), 3000);
    } finally { setBusy(false); }
  }

  async function iniciarPausar() {
    if (!esAsignado || busy) return;
    setBusy(true);
    try {
      const nuevoEstado = ticket.estado === "en_proceso" ? "pendiente" : "en_proceso";
      await tapi(`/${ticket.id}/estado`, token, { method: "PUT", body: JSON.stringify({ estado: nuevoEstado }) });
      onChanged();
    } catch { /* ignore */ } finally { setBusy(false); }
  }

  async function eliminar() {
    if (busy) return;
    setBusy(true);
    try {
      await tapi(`/${ticket.id}`, token, { method: "DELETE" });
      onChanged();
    } catch { /* ignore */ } finally { setBusy(false); setConfirmDelete(false); }
  }

  async function guardarEdit() {
    if (!editDraft.titulo.trim()) return;
    setGuardandoEdit(true);
    try {
      await tapi(`/${ticket.id}`, token, {
        method: "PUT",
        body: JSON.stringify({
          titulo: editDraft.titulo.trim(),
          descripcion: editDraft.descripcion.trim() || undefined,
          prioridad: editDraft.prioridad || undefined,
        }),
      });
      setShowEdit(false);
      onChanged();
    } catch (e: any) {
      setMsg(e.message ?? "Error al guardar");
      setTimeout(() => setMsg(""), 3000);
    } finally { setGuardandoEdit(false); }
  }

  async function abrirIntervencion() {
    if (usuarios.length === 0) {
      try {
        const data = await tapi("/usuarios", token);
        setUsuarios(Array.isArray(data) ? data.filter((u: UserInfo) => u.id !== user.id && u.activo) : []);
      } catch { /* ignore */ }
    }
    setShowIntervencion(true);
  }

  async function crearIntervencion() {
    if (!interForm.titulo.trim() || !interForm.asignado_a) return;
    setCreandoInter(true);
    try {
      const desc = interForm.paso_ref
        ? `${interForm.descripcion}\n\n[Origen: ${interForm.paso_ref}]`
        : interForm.descripcion;
      await tapi(`/${ticket.id}/pedir-intervencion`, token, {
        method: "POST",
        body: JSON.stringify({
          titulo: interForm.titulo,
          descripcion: desc,
          asignado_a: Number(interForm.asignado_a),
          paso_id: interForm.paso_id || undefined,
        }),
      });
      setShowIntervencion(false);
      setInterForm({ titulo: "", descripcion: "", asignado_a: "", paso_ref: "", paso_id: 0 });
      await cargarPasos();
      onChanged();
    } catch (e: any) {
      setMsg(e.message ?? "Error al crear intervencion");
      setTimeout(() => setMsg(""), 4000);
    } finally { setCreandoInter(false); }
  }

  async function cargarComentarios() {
    setLoadingComentarios(true);
    try {
      const data = await tapi(`/${ticket.id}/comentarios`, token);
      const lista = Array.isArray(data) ? data : [];
      setComentarios(lista);
    } catch { /* ignore */ } finally { setLoadingComentarios(false); }
  }

  async function enviarMensajeChat() {
    const texto = chatDraft.trim();
    const archivo = archivoPendienteRef.current ?? archivoPendiente;
    if ((!texto && !archivo) || enviandoChat || !puedeEnviarChat) return;
    const textoEnvio = texto || (archivo ? "📎 Imagen adjunta" : "");
    setEnviandoChat(true);
    try {
      if (archivo) {
        const fd = new FormData();
        fd.append("archivo", archivo);
        await tapi(`/${ticket.id}/adjuntos`, token, { method: "POST", body: fd });
        limpiarArchivoPendiente();
        void cargarAdjuntos();
        setShowAdjuntos(true);
      }
      if (textoEnvio) {
        await tapi(`/${ticket.id}/comentarios`, token, {
          method: "POST",
          body: JSON.stringify({ texto: textoEnvio }),
        });
      }
      setChatDraft("");
      await cargarComentarios();
      setShowChat(true);
      onChanged();
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "No se pudo enviar el mensaje");
      setTimeout(() => setMsg(""), 3500);
    } finally {
      setEnviandoChat(false);
    }
  }

  // Auto-cargar comentarios al montar y cuando el ticket se desbloquea
  useEffect(() => {
    void cargarComentarios();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ticket.id]);

  useEffect(() => {
    if (!ticket.bloqueado_por) {
      void cargarComentarios();
      if (showPasos) void cargarPasos(); // recargar pasos para mostrar respuesta inline
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ticket.bloqueado_por]);

  useEffect(() => {
    if (!showChat) return;
    void cargarComentarios();
    const iv = setInterval(() => void cargarComentarios(), 12000);
    return () => clearInterval(iv);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showChat, ticket.id]);

  async function cargarAdjuntos() {
    setLoadingAdjuntos(true);
    try {
      const data = await tapi(`/${ticket.id}/adjuntos`, token);
      setAdjuntos(Array.isArray(data) ? data : []);
    } catch { /* ignore */ } finally { setLoadingAdjuntos(false); }
  }

  async function eliminarAdjunto(adjId: number) {
    if (!confirm("¿Eliminar este archivo adjunto?")) return;
    setEliminandoAdj(adjId);
    try {
      await tapi(`/adjuntos/${adjId}`, token, { method: "DELETE" });
      setAdjuntos((prev) => prev.filter((a) => a.id !== adjId));
    } catch { /* ignore */ } finally { setEliminandoAdj(null); }
  }

  async function guardarComoProtocolo() {
    if (!protocoloForm.titulo.trim()) return;
    setGuardandoProtocolo(true);
    try {
      await tapi(`/${ticket.id}/guardar-como-protocolo`, token, {
        method: "POST",
        body: JSON.stringify(protocoloForm),
      });
      setProtocoloMsg("Procedimiento guardado");
      setShowProtocoloForm(false);
      setProtocoloForm({ titulo: "", descripcion: "", categoria: "" });
      setTimeout(() => setProtocoloMsg(""), 3000);
    } catch (e: any) {
      setProtocoloMsg(e.message ?? "Error al guardar procedimiento");
      setTimeout(() => setProtocoloMsg(""), 4000);
    } finally { setGuardandoProtocolo(false); }
  }

  async function guardarProcedimientoDesdeSolicitud(alcance = alcanceProcedimiento) {
    const itemsLista = compras
      .filter((m) => m.nombre?.trim())
      .map((m) => ({
        n: m.nombre.trim(),
        cantidad: String(m.cantidad ?? ""),
        unidad: m.unidad || "und",
        comprado: !!m.comprado,
      }));
    await tapi(`/${ticket.id}/guardar-procedimiento`, token, {
      method: "POST",
      body: JSON.stringify({ lista_compras: itemsLista, alcance }),
    });
  }

  async function generarProcedimientoAhora() {
    const totalPasos = pasos.length > 0 ? pasos.length : (ticket.pasos_total ?? 0);
    if (totalPasos === 0) {
      setMsg("Agrega al menos un paso antes de generar el procedimiento.");
      setTimeout(() => setMsg(""), 4000);
      return;
    }
    if (!confirm(`¿Generar procedimiento a partir de "${ticket.titulo}"?\n\nSe guardarán los pasos actuales para reutilizar.`)) return;
    setGenerandoProcedimiento(true);
    setProtocoloMsg("");
    try {
      if (pasos.length === 0) await cargarPasos();
      await guardarProcedimientoDesdeSolicitud();
      setProtocoloMsg("✓ Procedimiento generado — ver Acciones → Procedimientos");
      setTimeout(() => setProtocoloMsg(""), 5000);
    } catch (e: any) {
      setMsg(e.message ?? "No se pudo generar el procedimiento");
      setTimeout(() => setMsg(""), 4000);
    } finally {
      setGenerandoProcedimiento(false);
    }
  }

  async function vincularProtocolo() {
    const pid = protocoloVincularId;
    if (!pid) return;
    setVinculandoProtocolo(true);
    setVincularProtocoloMsg("");
    try {
      await tapi(`/${ticket.id}/vincular-protocolo`, token, {
        method: "POST",
        body: JSON.stringify({
          protocolo_id: pid,
          reemplazar_pasos: reemplazarPasosProtocolo,
        }),
      });
      setVincularProtocoloMsg("Procedimiento vinculado");
      setShowVincularProtocolo(false);
      setProtocoloVincularId("");
      setReemplazarPasosProtocolo(false);
      setShowPasos(true);
      void cargarPasos();
      onChanged();
      setTimeout(() => setVincularProtocoloMsg(""), 3000);
    } catch (e: any) {
      setVincularProtocoloMsg(e.message ?? "Error al vincular");
    } finally { setVinculandoProtocolo(false); }
  }

  const puedeVincularProtocolo = !resuelta && !supervision
    && (nivel >= 2 || esAsignado || esCreadoPorMi || esParticipante);

  async function cargarSensible() {
    if (!puedeVerSensible) {
      setSensibleMsg("Sin permisos para ver datos sensibles");
      return;
    }
    setLoadingSensible(true);
    try {
      const data = await tapi(`/${ticket.id}/sensible`, token);
      setSensibleTexto(data.texto ?? "");
      setSensibleDraft(data.texto ?? "");
    } catch (e: any) {
      setSensibleMsg(e.message ?? "Error");
    } finally { setLoadingSensible(false); }
  }

  async function guardarSensible() {
    setLoadingSensible(true);
    try {
      await tapi(`/${ticket.id}/sensible`, token, {
        method: "PUT",
        body: JSON.stringify({ texto: sensibleDraft }),
      });
      setSensibleTexto(sensibleDraft);
      setEditandoSensible(false);
      setSensibleMsg("Guardado");
      setTimeout(() => setSensibleMsg(""), 2000);
      onChanged();
    } catch (e: any) {
      setSensibleMsg(e.message ?? "Error");
    } finally { setLoadingSensible(false); }
  }

  const FREC_SHORT: Record<string, string> = {
    diaria: "Diaria", cada_2_dias: "Cada 2 días", cada_3_dias: "Cada 3 días",
    semanal: "Semanal", quincenal: "Quincenal", mensual: "Mensual",
    bimestral: "Bimestral", trimestral: "Trimestral", semestral: "Semestral",
  };

  const pasosCompletados = pasos.filter((p) => p.completado).length;
  const pasosTotal = pasos.length;

  function etiquetaPasoAdjunto(pasoId: number): string {
    const p = pasos.find((x) => x.id === pasoId);
    if (!p) return `Paso #${pasoId}`;
    return `Paso ${p.orden}: ${p.descripcion}`;
  }

  if (esSolicitudCompraDelegada(ticket)) {
    return (
      <div
        className={`flex flex-col gap-2 rounded-xl border border-accent/40 bg-surface p-3 shadow-sm transition-opacity ${resuelta ? "opacity-60" : ""}`}
      >
        <div className="flex items-start gap-2">
          <div className="min-w-0 flex-1">
            <span className="text-sm font-bold text-ink">🛒 {ticket.titulo}</span>
            <p className="mt-0.5 text-xs text-muted font-mono">{ticket.numero}</p>
          </div>
          <span className="shrink-0 rounded-full border border-border px-2 py-0.5 text-[10px]">
            {ESTADO_LABEL[ticket.estado] ?? ticket.estado}
          </span>
        </div>
        <p className="text-xs text-muted">
          {esCreadoPorMi ? "Delegaste esta lista" : `Te la asignó ${ticket.creado_por_nombre ?? "?"}`}
        </p>
        <SolicitudCompraChecklist
          ticket={ticket}
          token={token}
          user={user}
          onChanged={onChanged}
          supervision={supervision}
        />
      </div>
    );
  }

  if (esSolicitudEtiqueta(ticket)) {
    return (
      <div
        className={`flex flex-col gap-2 rounded-xl border border-accent/40 bg-surface p-3 shadow-sm transition-opacity ${resuelta ? "opacity-60" : ""}`}
      >
        <div className="flex items-start gap-2">
          <div className="min-w-0 flex-1">
            <span className="text-sm font-bold text-ink">🏷️ {ticket.titulo}</span>
            <p className="mt-0.5 text-xs text-muted font-mono">{ticket.numero}</p>
          </div>
          <span className="shrink-0 rounded-full border border-border px-2 py-0.5 text-[10px]">
            {ESTADO_LABEL[ticket.estado] ?? ticket.estado}
          </span>
        </div>
        <p className="text-xs text-muted">
          {esCreadoPorMi ? "Pediste estas etiquetas" : `Te las pidió ${ticket.creado_por_nombre ?? "?"}`}
        </p>
        <SolicitudListaChecklist
          ticket={ticket}
          token={token}
          user={user}
          variant="etiqueta"
          onChanged={onChanged}
          supervision={supervision}
        />
      </div>
    );
  }

  const adjuntosEntregaRevision = adjuntos.filter((a) =>
    a.creado_por != null
      ? uidEq(a.creado_por, ticket.asignado_a)
      : a.creado_por_nombre === ticket.asignado_a_nombre,
  );
  const comentariosEntregaRevision = comentarios.filter((c) =>
    uidEq(c.usuario_id, ticket.asignado_a)
    && !/^\s*📎\s*(imagen|archivo)\s+adjunt[oa]/i.test(c.texto),
  );

  return (
    <div
      className={`flex flex-col transition-opacity ${detalleAmpliado ? "gap-4 min-h-0" : "gap-2 rounded-xl border border-border bg-surface p-3 shadow-sm"} ${resuelta ? "opacity-60" : ""}`}
    >

      {detalleAmpliado ? (
        /* ── Encabezado ampliado: número, título, quién ── */
        <div className="shrink-0 space-y-2">
          {/* Fila: número + badges + acciones */}
          <div className="flex items-center gap-2 flex-wrap">
            <span className="font-mono text-[10px] font-bold text-muted/50 tracking-widest">{shortNumero(ticket.numero)}</span>
            <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${PRIORIDAD_COLOR[ticket.prioridad ?? "media"] ?? "bg-gray-200 text-gray-700"}`}>
              {ticket.prioridad ?? "media"}
            </span>
            <span className="rounded-full border border-border/60 bg-surface px-2 py-0.5 text-[10px] text-muted">{ESTADO_LABEL[ticket.estado] ?? ticket.estado}</span>
            <div className="ml-auto flex items-center gap-0.5">
              <button
                type="button"
                title={ticket.tiene_datos_sensibles ? "Ver datos sensibles 🔒" : "Datos sensibles 🔓"}
                onClick={() => { setShowSensible((v) => !v); if (!showSensible) void cargarSensible(); }}
                className={`rounded p-1 transition-colors ${ticket.tiene_datos_sensibles ? "text-accent/50 hover:text-accent/40" : "text-muted hover:text-accent"}`}
              >
                <svg className="h-3.5 w-3.5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                  <path d="M7 11V7a5 5 0 0 1 10 0v4" />
                </svg>
              </button>
              {(isAdmin || esCreadoPorMi) && !confirmDelete && !showEdit && (
                <button type="button" title="Editar" onClick={() => {
                  setEditDraft({ titulo: ticket.titulo, descripcion: ticket.descripcion ?? "", prioridad: ticket.prioridad ?? "media" });
                  setShowEdit(true);
                }} className="rounded p-1 text-muted hover:text-accent transition-colors">
                  <Icon name="pencil" size={13} />
                </button>
              )}
              {(isAdmin || esCreadoPorMi) && !confirmDelete && !showEdit && (
                <button type="button" title="Eliminar" onClick={() => setConfirmDelete(true)}
                  className="rounded p-1 text-muted hover:text-red-600 transition-colors">
                  <Icon name="trash" size={13} />
                </button>
              )}
              {(isAdmin || esCreadoPorMi) && confirmDelete && (
                <div className="flex items-center gap-1">
                  <button type="button" disabled={busy} onClick={eliminar}
                    className="rounded bg-red-600 px-1.5 py-0.5 text-[10px] font-bold text-white hover:bg-red-700">Sí</button>
                  <button type="button" onClick={() => setConfirmDelete(false)}
                    className="rounded bg-surface-hover px-1.5 py-0.5 text-[10px] font-bold text-muted hover:text-ink">No</button>
                </div>
              )}
            </div>
          </div>
          {/* Título */}
          <h2 className="text-lg font-bold text-ink leading-snug tracking-tight">{ticket.titulo}</h2>
          {ticket.descripcion && ticket.descripcion !== ticket.titulo && (
            <p className="text-sm leading-relaxed text-muted/80 whitespace-pre-wrap">{ticket.descripcion}</p>
          )}
          {/* De quién → para quién */}
          <div className="flex items-center gap-2 text-xs text-muted flex-wrap">
            <span className="font-medium text-ink/70">
              {esCreadoPorMi ? "Tú" : (ticket.creado_por_nombre ?? "?")}
            </span>
            <svg className="h-3 w-3 text-muted/40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
            <span className="font-semibold text-ink">{ticket.asignado_a_nombre ?? "Sin asignar"}</span>
          </div>
          {(ticket.frecuencia || ticket.protocolo_titulo) && (
            <div className="flex flex-wrap gap-2 pt-0.5">
              {ticket.frecuencia && (
                <span className="inline-flex items-center gap-1 text-xs text-muted">♻️ {FREC_SHORT[ticket.frecuencia] ?? ticket.frecuencia}</span>
              )}
              {ticket.protocolo_titulo && (
                <span className="inline-flex items-center gap-1 text-xs text-accent/80" title="Procedimiento vinculado">📋 {ticket.protocolo_titulo}</span>
              )}
            </div>
          )}
        </div>
      ) : (
        <>
          {/* Encabezado compacto */}
          <div className="flex items-start gap-2">
            <div className="min-w-0 flex-1">
              <span className="text-sm font-medium text-ink">{ticket.titulo}</span>
              {ticket.descripcion && ticket.descripcion !== ticket.titulo && (
                <p className="mt-0.5 text-xs text-muted line-clamp-2">{ticket.descripcion}</p>
              )}
            </div>
            <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${PRIORIDAD_COLOR[ticket.prioridad ?? "media"] ?? "bg-gray-200 text-gray-700"}`}>
              {ticket.prioridad ?? "media"}
            </span>
            <button
              type="button"
              title={ticket.tiene_datos_sensibles ? "Ver datos sensibles 🔒" : "Agregar datos sensibles 🔓"}
              onClick={() => {
                setShowSensible((v) => !v);
                if (!showSensible) void cargarSensible();
              }}
              className={`shrink-0 rounded p-0.5 transition-colors ${ticket.tiene_datos_sensibles ? "text-accent/50 hover:text-accent/40" : "text-muted hover:text-accent"}`}
            >
              <svg className="h-3.5 w-3.5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                <path d="M7 11V7a5 5 0 0 1 10 0v4" />
              </svg>
            </button>
            {(isAdmin || esCreadoPorMi) && !confirmDelete && !showEdit && (
              <button type="button" title="Editar solicitud" onClick={() => {
                setEditDraft({ titulo: ticket.titulo, descripcion: ticket.descripcion ?? "", prioridad: ticket.prioridad ?? "media" });
                setShowEdit(true);
              }}
                className="shrink-0 rounded p-0.5 text-muted hover:text-accent transition-colors">
                <Icon name="pencil" size={13} />
              </button>
            )}
            {(isAdmin || esCreadoPorMi) && !confirmDelete && !showEdit && (
              <button type="button" title="Eliminar" onClick={() => setConfirmDelete(true)}
                className="shrink-0 rounded p-0.5 text-muted hover:text-red-600 transition-colors">
                <Icon name="trash" size={13} />
              </button>
            )}
            {(isAdmin || esCreadoPorMi) && confirmDelete && (
              <div className="flex items-center gap-1">
                <button type="button" disabled={busy} onClick={eliminar}
                  className="rounded bg-red-600 px-1.5 py-0.5 text-[10px] font-bold text-white hover:bg-red-700">Sí</button>
                <button type="button" onClick={() => setConfirmDelete(false)}
                  className="rounded bg-surface-hover px-1.5 py-0.5 text-[10px] font-bold text-muted hover:text-ink">No</button>
              </div>
            )}
          </div>
          {/* Meta compacta */}
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted">
            <span className="flex items-center gap-1">
              <Icon name="user" size={11} />
              {esCreadoPorMi ? "Solicitado por ti" : `Solicitado por ${ticket.creado_por_nombre ?? "?"}`}
            </span>
            <span className="flex items-center gap-1">
              <Icon name="user" size={11} />
              Para: <strong className="text-ink">{ticket.asignado_a_nombre ?? "Sin asignar"}</strong>
            </span>
            {ticket.frecuencia && (
              <span className="flex items-center gap-1">
                ♻️ {FREC_SHORT[ticket.frecuencia] ?? ticket.frecuencia}
              </span>
            )}
            {(ticket.pasos_total ?? 0) > 0 && !showPasos && (
              <button type="button" onClick={() => { setShowPasos(true); void cargarPasos(); }}
                className="flex items-center gap-1 text-accent hover:underline">
                ☑ {ticket.pasos_completados}/{ticket.pasos_total} pasos
              </button>
            )}
            {ticket.protocolo_titulo && (
              <span className="flex items-center gap-1 text-accent/90" title="Procedimiento vinculado">
                📋 {ticket.protocolo_titulo}
              </span>
            )}
            {(adjuntos.length > 0 || loadingAdjuntos) && (
              <button
                type="button"
                onClick={() => { setShowAdjuntos(true); if (!adjuntos.length && !loadingAdjuntos) void cargarAdjuntos(); }}
                className="flex items-center gap-1 text-accent hover:underline"
              >
                📎 {loadingAdjuntos ? "Cargando…" : `${adjuntos.length} adjunto${adjuntos.length !== 1 ? "s" : ""}`}
              </button>
            )}
            {puedeVerChat && (
              <button
                type="button"
                onClick={() => {
                  setShowChat((v) => {
                    const next = !v;
                    if (next) void cargarComentarios();
                    return next;
                  });
                }}
                className={`flex items-center gap-1 rounded-lg border px-2 py-0.5 text-[10px] font-bold transition ${
                  showChat
                    ? "border-accent bg-accent/10 text-accent"
                    : "border-border text-muted hover:border-accent hover:text-accent"
                }`}
              >
                <Icon name="chat" size={12} weight="bold" />
                Mensajes{comentarios.length > 0 ? ` (${comentarios.length})` : ""}
              </button>
            )}
            <span className="ml-auto rounded-full border border-border px-2 py-0.5 text-[10px]">
              {ESTADO_LABEL[ticket.estado] ?? ticket.estado}
            </span>
          </div>
        </>
      )}

      {/* Formulario de edición inline — visible al creador o admin */}
      {showEdit && (
        <div className="rounded-xl border-2 border-accent/40 bg-accent/5 p-3 space-y-2">
          <p className="text-xs font-extrabold uppercase tracking-wide text-accent">✏️ Editar solicitud</p>
          {msg && <p className="text-xs text-red-400">{msg}</p>}
          <ProseInput
            className="quest-input w-full text-sm"
            placeholder="Título"
            value={editDraft.titulo}
            onChange={e => setEditDraft(d => ({ ...d, titulo: e.target.value }))}
          />
          <ProseTextarea
            className="quest-input w-full text-xs resize-none"
            rows={3}
            placeholder="Descripción (opcional)"
            value={editDraft.descripcion}
            onChange={e => setEditDraft(d => ({ ...d, descripcion: e.target.value }))}
          />
          <select
            className="quest-input w-full text-xs"
            value={editDraft.prioridad}
            onChange={e => setEditDraft(d => ({ ...d, prioridad: e.target.value }))}
          >
            <option value="baja">🟢 Baja</option>
            <option value="media">🟡 Media</option>
            <option value="alta">🟠 Alta</option>
            <option value="urgente">🔴 Urgente</option>
          </select>
          <div className="flex gap-2">
            <button type="button" disabled={guardandoEdit || !editDraft.titulo.trim()} onClick={guardarEdit}
              className="flex-1 rounded-xl bg-accent py-2 text-xs font-bold text-white disabled:opacity-40 hover:bg-accent/80 transition-colors">
              {guardandoEdit ? "Guardando…" : "Guardar cambios"}
            </button>
            <button type="button" onClick={() => setShowEdit(false)}
              className="rounded-xl border border-border px-3 py-2 text-xs text-muted hover:text-ink">
              Cancelar
            </button>
          </div>
        </div>
      )}

      {/* Banner: esta solicitud ES una intervención que otro usuario necesita */}
      {esIntervencion && (
        <div className="rounded-lg border border-accent/60 bg-accent/60  px-3 py-2.5 space-y-1">
          <div className="flex items-center gap-2 text-xs font-bold text-accent">
            <span>🛑</span>
            <span>Intervención solicitada</span>
          </div>
          <p className="text-xs text-accent/80  leading-snug">
            <strong>{ticket.creado_por_nombre ?? "Un compañero"}</strong> necesita tu ayuda
            para continuar{ticket.ticket_padre_numero ? ` el ticket ${ticket.ticket_padre_numero}` : ""}.
            {ticket.ticket_padre_titulo ? ` — ${ticket.ticket_padre_titulo}` : ""}
          </p>
          {ticket.descripcion && ticket.descripcion !== ticket.titulo && (
            <p className="text-xs text-accent/70  italic">
              {ticket.descripcion}
            </p>
          )}
        </div>
      )}

      {/* Resolver intervención — arriba del chat para que sea visible de inmediato */}
      {!resuelta && esAsignado && !supervision && esIntervencion && (
        <div ref={intervencionZoneRef} className={`space-y-2 ${detalleAmpliado ? "shrink-0 rounded-xl border-2 border-accent/50 bg-accent/40  p-3" : "pt-1"}`}>
          {msg && <p className="text-xs text-red-400">{msg}</p>}
          <ProseTextarea
            className="quest-input w-full resize-none text-sm"
            rows={3}
            placeholder="Escribe tu respuesta o resolución aquí… (Ctrl+V o 📷 para adjuntar imagen)"
            value={resolucionInter}
            onChange={(e) => setResolucionInter(e.target.value)}
            onPaste={handlePasteImagen}
          />
          {vistaPreviaPegada("border-accent/40 bg-accent/30")}
          <div className="flex gap-2">
            <button
              type="button"
              disabled={!puedeResolverIntervencion}
              onClick={() => void resolverIntervencion()}
              className="flex flex-1 items-center justify-center gap-1.5 rounded-xl border border-accent/50 bg-accent/50 px-3 py-2.5 text-sm font-bold text-white min-h-[44px] transition-colors hover:bg-accent disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Icon name="check" size={15} weight="bold" />
              {busy ? "Resolviendo…" : "Resolver intervención"}
            </button>
            <button
              type="button"
              title="Adjuntar imagen (o Ctrl+V)"
              onClick={() => interArchivoRef.current?.click()}
              className={`rounded-xl border px-3 py-2.5 text-sm transition-colors ${
                hayArchivoPendiente ? "border-accent text-accent bg-accent/10" : "border-border text-muted hover:text-accent hover:border-accent"
              }`}
            >
              📷
            </button>
            <input
              ref={interArchivoRef}
              type="file"
              accept="image/*"
              className="sr-only"
              onChange={(e) => {
                const f = e.target.files?.[0] ?? null;
                onArchivoInterSeleccionado(f);
                e.target.value = "";
              }}
            />
            <button type="button"
              onClick={() => { setShowAdjuntos(true); void cargarAdjuntos(); }}
              className={`rounded-xl border px-3 py-2.5 text-sm transition-colors ${showAdjuntos ? "border-accent text-accent" : "border-border text-muted hover:text-accent hover:border-accent"}`}>
              📎
            </button>
          </div>
          <p className="text-[10px] text-muted text-center">
            {hayArchivoPendiente && !resolucionInter.trim()
              ? "Imagen lista — pulsa Resolver intervención para enviar."
              : !puedeResolverIntervencion
                ? "Escribe un mensaje o adjunta una imagen (📷 / Ctrl+V) para habilitar el botón."
                : "Tu respuesta quedará registrada y desbloqueará al compañero que la solicitó."}
          </p>
        </div>
      )}

      {/* Bloqueado por intervención */}
      {ticket.bloqueado_por && (
        <div className="rounded-lg border border-accent/40 bg-accent/50  px-3 py-2.5 text-xs text-accent  space-y-2">
          <div className="flex items-center gap-2">
            <svg className="h-3.5 w-3.5 shrink-0" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
              <rect x="3" y="11" width="18" height="11" rx="2" ry="2" /><path d="M7 11V7a5 5 0 0 1 10 0v4" />
            </svg>
            <span>
              Esperando intervención <strong>{ticket.bloqueado_por_numero}</strong>
            </span>
          </div>
          {onIrAIntervencion && (
            <button
              type="button"
              onClick={() => onIrAIntervencion(ticket.bloqueado_por!)}
              className="w-full rounded-lg border border-accent/60 bg-accent/80  px-3 py-2 text-xs font-bold text-accent  hover:bg-accent/80 transition-colors"
            >
              Ir a resolver {ticket.bloqueado_por_numero} →
            </button>
          )}
          <p className="text-[10px] text-accent/80">
            La solicitud se desbloquea cuando el asignado a esa intervención la resuelve.
          </p>
        </div>
      )}

      {/* Datos sensibles */}
      {showSensible && (
        <div className="rounded-xl border border-accent/50 bg-accent/30  p-3 space-y-2">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold text-accent  flex items-center gap-1">
              🔒 Datos sensibles / Protocolo privado
              <InfoTooltip text="Visible solo para el asignado, quien creó la solicitud, participantes directos y supervisores. Aquí puedes guardar contraseñas, procedimientos internos o notas confidenciales de resolución. Solo supervisores pueden editar." />
            </span>
            <button type="button" onClick={() => setShowSensible(false)} className="text-muted hover:text-ink text-xs">✕</button>
          </div>
          {loadingSensible && <p className="text-xs text-muted">Cargando…</p>}
          {sensibleMsg && <p className="text-xs text-accent">{sensibleMsg}</p>}
          {!loadingSensible && !puedeVerSensible && (
            <p className="text-xs text-muted">Sin permisos para ver datos sensibles.</p>
          )}
          {!loadingSensible && puedeVerSensible && !editandoSensible && (
            <>
              <p className="text-xs text-ink whitespace-pre-wrap min-h-[2rem]">
                {sensibleTexto || <span className="text-muted italic">Sin datos sensibles aún.</span>}
              </p>
              {nivel >= 2 && (
                <button type="button" onClick={() => { setEditandoSensible(true); setSensibleDraft(sensibleTexto); }}
                  className="text-xs text-accent hover:underline">Editar</button>
              )}
            </>
          )}
          {!loadingSensible && puedeVerSensible && editandoSensible && (
            <div className="space-y-2">
              <ProseTextarea
                className="quest-input w-full resize-none text-xs"
                rows={4}
                placeholder="Escribe aquí contraseñas, pasos de resolución, notas privadas…"
                value={sensibleDraft}
                onChange={(e) => setSensibleDraft(e.target.value)}
              />
              <div className="flex gap-2">
                <button type="button" disabled={loadingSensible} onClick={guardarSensible}
                  className="quest-btn-primary px-3 py-1 text-xs">Guardar</button>
                <button type="button" onClick={() => setEditandoSensible(false)} className="text-xs text-muted hover:text-ink">Cancelar</button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Conversación — chat unificado */}
      {(showChat || detalleAmpliado) && puedeVerChat && (
        <div
          className={detalleAmpliado
            ? "flex flex-col flex-1 min-h-0 rounded-xl border border-border/50 overflow-hidden"
            : "rounded-xl border border-border overflow-hidden bg-surface-hover"}
        >
          {/* Cabecera solo en modo tarjeta */}
          {!detalleAmpliado && (
            <div className="flex items-center justify-between gap-2 px-3 py-2 border-b border-border bg-surface">
              <span className="flex items-center gap-1.5 text-xs font-bold text-ink">
                <Icon name="chat" size={13} weight="bold" />
                Mensajes{supervision && <span className="font-normal text-muted/70"> · equipo</span>}
              </span>
              <button type="button" onClick={() => setShowChat(false)} className="text-muted hover:text-ink text-xs">✕</button>
            </div>
          )}

          {/* Lista de mensajes */}
          <div className={detalleAmpliado
            ? "flex-1 min-h-0 overflow-y-auto bg-surface/50 px-3 pt-3 pb-1 space-y-1"
            : "overflow-y-auto bg-surface px-3 py-3 max-h-52 space-y-1"}
          >
            {loadingComentarios && comentarios.length === 0 && (
              <p className="text-xs text-muted text-center py-4">Cargando mensajes…</p>
            )}
            {!loadingComentarios && comentarios.length === 0 && (
              <p className="text-xs text-muted text-center py-6 italic">
                Aún no hay mensajes. Escribe abajo para empezar.
              </p>
            )}
            {(() => {
              const getDateLabel = (ts: string) => {
                try {
                  const d = new Date(ts.includes("T") || ts.includes("Z") ? ts : ts + "Z");
                  const hoy = new Date();
                  const ayer = new Date(); ayer.setDate(ayer.getDate() - 1);
                  if (d.toDateString() === hoy.toDateString()) return "Hoy";
                  if (d.toDateString() === ayer.toDateString()) return "Ayer";
                  return d.toLocaleDateString("es-CO", { day: "numeric", month: "short" });
                } catch { return null; }
              };
              return comentarios.flatMap((c, idx) => {
                const esMio = c.usuario_id === user.id;
                const fechaLabel = c.creado_en ? getDateLabel(c.creado_en) : null;
                const prevFechaLabel = comentarios[idx - 1]?.creado_en ? getDateLabel(comentarios[idx - 1].creado_en) : null;
                const mostrarSep = fechaLabel && fechaLabel !== prevFechaLabel;
                const horaStr = c.creado_en ? (() => {
                  try { return new Date(c.creado_en.includes("T") || c.creado_en.includes("Z") ? c.creado_en : c.creado_en + "Z").toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" }); }
                  catch { return ""; }
                })() : "";
                const items = [];
                if (mostrarSep) {
                  items.push(
                    <div key={`sep-${idx}`} className="flex items-center gap-2 py-2">
                      <div className="flex-1 h-px bg-border/40" />
                      <span className="text-[10px] text-muted/70 font-medium px-1">{fechaLabel}</span>
                      <div className="flex-1 h-px bg-border/40" />
                    </div>
                  );
                }
                items.push(
                  <div key={c.id} className={`flex ${esMio ? "justify-end" : "justify-start"} mb-1`}>
                    <div className={`max-w-[85%] rounded-2xl px-3 py-2 text-xs shadow-sm ${
                      esMio
                        ? "rounded-br-sm bg-accent text-white"
                        : "rounded-bl-sm border border-border bg-surface-panel text-ink"
                    }`}>
                      {!esMio && (
                        <p className="mb-0.5 text-[10px] font-bold text-muted">{c.autor_nombre}</p>
                      )}
                      <p className="whitespace-pre-wrap leading-relaxed">{c.texto}</p>
                      <p className={`mt-0.5 text-[9px] text-right ${esMio ? "text-white/60" : "text-muted/70"}`}>{horaStr}</p>
                    </div>
                  </div>
                );
                return items;
              });
            })()}
          </div>

          {/* Área de entrada — pegada al fondo */}
          {puedeEnviarChat ? (
            <div ref={chatMensajesRef} className="shrink-0 border-t border-border/40 bg-surface px-3 py-2.5 space-y-2">
              {vistaPreviaPegada()}
              <ProseTextarea
                className="quest-input w-full text-sm resize-none"
                rows={3}
                placeholder="Escribe un mensaje… (Enter envía · Shift+Enter nueva línea)"
                value={chatDraft}
                onChange={(e) => setChatDraft(e.target.value)}
                onPaste={handlePasteImagen}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    void enviarMensajeChat();
                  }
                }}
                maxLength={2000}
              />
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  title="Pegar / adjuntar imagen"
                  onClick={() => chatArchivoRef.current?.click()}
                  className="shrink-0 rounded-lg border border-border px-2.5 py-1.5 text-base text-muted hover:border-accent hover:text-accent transition-colors"
                >
                  📷
                </button>
                <input
                  ref={chatArchivoRef}
                  type="file"
                  accept="image/*"
                  className="sr-only"
                  onChange={(e) => {
                    const f = e.target.files?.[0] ?? null;
                    onArchivoInterSeleccionado(f);
                    e.target.value = "";
                  }}
                />
                <div className="flex-1" />
                <button
                  type="button"
                  disabled={enviandoChat || (!chatDraft.trim() && !hayArchivoPendiente)}
                  onClick={() => void enviarMensajeChat()}
                  className="quest-btn-primary shrink-0 px-5 py-2 text-sm font-bold disabled:opacity-40"
                >
                  {enviandoChat ? "…" : "Enviar"}
                </button>
              </div>
            </div>
          ) : (
            <div className="shrink-0 border-t border-border/40 bg-surface px-3 py-2.5">
              <p className="text-[10px] text-center text-muted">
                {resuelta ? "Solicitud cerrada — solo lectura." : "En pausa por intervención activa."}
              </p>
            </div>
          )}
        </div>
      )}

      {/* Adjuntos — visibles para todo el equipo (lectura); subir solo asignado/creador/supervisor */}
      {((!detalleAmpliado && adjuntos.length > 0) || showAdjuntos) && (
        <div className="rounded-xl border border-border bg-surface-hover p-3 space-y-2">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold text-ink">
              📎 Adjuntos {adjuntos.length > 0 && <span className="font-normal text-muted">({adjuntos.length})</span>}
            </span>
            <div className="flex items-center gap-2">
              {puedeSubirAdjuntos && (
                <label title="Subir archivo o pegar imagen (Ctrl+V)" className="cursor-pointer flex items-center gap-1 rounded-lg border border-border px-2 py-0.5 text-[10px] font-semibold text-muted hover:border-accent hover:text-accent transition-colors">
                  {subiendoAdjTicket
                    ? <span className="inline-block h-2.5 w-2.5 rounded-full border-2 border-current border-t-transparent animate-spin" />
                    : <span>+ Subir</span>
                  }
                  <input
                    type="file"
                    accept="image/*,.pdf,application/pdf,.doc,.docx"
                    className="sr-only"
                    onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) void subirAdjuntoTicket(f);
                      e.target.value = "";
                    }}
                  />
                </label>
              )}
              <button type="button" onClick={() => setShowAdjuntos(false)} className="text-muted hover:text-ink text-xs">▲</button>
            </div>
          </div>
          {loadingAdjuntos && <p className="text-xs text-muted">Cargando…</p>}
          {!loadingAdjuntos && adjuntos.length === 0 && (
            <p className="text-xs text-muted italic">
              {puedeSubirAdjuntos
                ? "Sin archivos adjuntos. Pegue una captura con Ctrl+V o use + Subir."
                : "Sin archivos adjuntos en esta solicitud."}
            </p>
          )}
          {lightboxUrl && <ImageLightbox url={lightboxUrl} onClose={() => setLightboxUrl(null)} />}
          <div className="space-y-1">
            {adjuntos.map((a) => {
              const esImagen = (a.mime?.startsWith("image/"))
                || /\.(jpg|jpeg|png|gif|webp)$/i.test(a.nombre_original);
              const esPdf = /\.pdf$/i.test(a.nombre_original);
              const icono = esImagen ? "🖼" : esPdf ? "📄" : "📁";
              const url = ticketsUploadUrl(a.nombre_archivo, token);
              return (
                <div key={a.id} className="flex items-center gap-2 rounded-lg border border-border/50 bg-surface px-2 py-1.5">
                  {esImagen ? (
                    <button type="button" onClick={() => setLightboxUrl(url)} className="shrink-0 group relative" title="Ver imagen">
                      <img src={url} alt={a.nombre_original} className="h-8 w-8 rounded object-cover border border-border group-hover:opacity-80 transition-opacity" />
                      <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-[10px] font-bold transition-opacity">🔍</span>
                    </button>
                  ) : (
                    <span className="text-base shrink-0">{icono}</span>
                  )}
                  <div className="min-w-0 flex-1">
                    <a href={url} target="_blank" rel="noreferrer"
                      className="block text-xs text-accent hover:underline truncate">
                      {a.nombre_original}
                    </a>
                    {a.paso_id && (
                      <p className="text-[10px] text-muted truncate">{etiquetaPasoAdjunto(a.paso_id)}</p>
                    )}
                  </div>
                  {a.creado_por_nombre && (
                    <span className="text-[10px] text-muted shrink-0 hidden sm:inline">{a.creado_por_nombre}</span>
                  )}
                  {(nivel >= 2 || ticket.creado_por === user.id) && (
                    <button type="button" disabled={eliminandoAdj === a.id}
                      onClick={() => void eliminarAdjunto(a.id)}
                      className="shrink-0 text-muted hover:text-red-500 transition-colors p-0.5">
                      <Icon name="trash" size={12} />
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Checklist de pasos — con edición inline, agregar paso y botón de intervención por paso */}
      {showPasos && (
        <div
          ref={pasosChecklistRef}
          className="rounded-xl border border-border bg-surface-hover p-3 space-y-1.5"
          onPaste={(e) => {
            if (!esAsignado || supervision || resuelta) return;
            const targetId = pasoPasteId ?? pasos.find((p) => !pasoEstaCompletado(p))?.id ?? pasos[0]?.id;
            if (!targetId) return;
            manejarPasteCaptura(e, (file) => void subirAdjuntoPaso(targetId, file));
          }}
        >
          <div className="flex items-center justify-between mb-1">
            <span className="text-xs font-bold text-ink flex items-center gap-1">
              Protocolo de pasos
              <InfoTooltip text="Manual de operación: marca cada paso al completarlo. Puedes editar o agregar pasos en cualquier momento. Si un paso necesita que otro usuario haga algo, usa el botón 🛑 para pedir intervención en ese paso específico." />
              {pasosTotal > 0 && <span className="text-muted font-normal">({pasosCompletados}/{pasosTotal})</span>}
              {esAsignado && !supervision && !resuelta && (
                <span className="text-[10px] font-normal text-muted">· Ctrl+V en un paso</span>
              )}
              {ticket.protocolo_titulo && (
                <span className="text-[10px] font-normal text-accent bg-accent/10 rounded-full px-2 py-0.5">
                  📋 {ticket.protocolo_titulo}
                </span>
              )}
            </span>
            <div className="flex items-center gap-2">
              {puedeVincularProtocolo && protocolos.length > 0 && (
                <button type="button"
                  onClick={() => setShowVincularProtocolo((v) => !v)}
                  className="text-[10px] text-accent hover:underline">
                  {showVincularProtocolo ? "Cancelar" : "Enlazar procedimiento"}
                </button>
              )}
              <button type="button" onClick={() => setShowPasos(false)} className="text-muted hover:text-ink text-xs">▲</button>
            </div>
          </div>
          {vincularProtocoloMsg && <p className="text-xs text-accent">{vincularProtocoloMsg}</p>}
          {showVincularProtocolo && puedeVincularProtocolo && (
            <div className="rounded-lg border border-accent/30 bg-accent/5 p-2.5 space-y-2">
              <p className="text-[11px] font-semibold text-ink">Enlazar procedimiento estándar</p>
              <select
                className="quest-input w-full text-xs"
                value={protocoloVincularId}
                onChange={(e) => setProtocoloVincularId(e.target.value ? Number(e.target.value) : "")}
              >
                <option value="">Selecciona un procedimiento…</option>
                {protocolos.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.titulo}{p.categoria ? ` (${p.categoria})` : ""} — {p.pasos.length} paso{p.pasos.length !== 1 ? "s" : ""}
                  </option>
                ))}
              </select>
              {(ticket.pasos_total ?? 0) > 0 && (
                <label className="flex items-center gap-2 text-[11px] text-muted cursor-pointer">
                  <input type="checkbox" checked={reemplazarPasosProtocolo}
                    onChange={(e) => setReemplazarPasosProtocolo(e.target.checked)}
                    className="rounded border-border accent-accent" />
                  Reemplazar pasos actuales por los del procedimiento
                </label>
              )}
              <button type="button"
                disabled={vinculandoProtocolo || !protocoloVincularId}
                onClick={() => void vincularProtocolo()}
                className="quest-btn-primary px-3 py-1 text-xs">
                {vinculandoProtocolo ? "Vinculando…" : "Vincular"}
              </button>
            </div>
          )}
          {loadingPasos && <p className="text-xs text-muted">Cargando pasos…</p>}
          {!loadingPasos && pasos.length === 0 && (
            <p className="text-xs text-muted italic">Sin pasos definidos. Agrega el primero abajo.</p>
          )}
          <div className="space-y-1">
            {pasos.map((p) => (
              <div
                key={p.id}
                className={`rounded-lg border px-2 py-1.5 transition-colors ${
                  pasoPasteId === p.id ? "border-accent/50 bg-accent/5" : p.completado ? "border-transparent opacity-60" : "border-border/50 hover:bg-surface"
                }`}
                onMouseEnter={() => setPasoPasteId(p.id)}
                onFocusCapture={() => setPasoPasteId(p.id)}
                onPaste={(e) => {
                  if (!esAsignado || supervision || resuelta) return;
                  if (manejarPasteCaptura(e, (file) => void subirAdjuntoPaso(p.id, file))) {
                    e.stopPropagation();
                  }
                }}
              >
                {editandoPasoId === p.id ? (
                  /* Modo edición inline */
                  <div className="space-y-1.5">
                    <ProseInput autoFocus className="quest-input w-full text-xs" value={editPasoDesc}
                      onChange={(e) => setEditPasoDesc(e.target.value)}
                      onKeyDown={(e) => e.key === "Enter" && void guardarEditPaso(p)} />
                    <ProseTextarea className="quest-input w-full text-xs resize-none" placeholder="Notas (opcional)" rows={2} value={editPasoNotas}
                      onChange={(e) => setEditPasoNotas(e.target.value)} />
                    <div className="flex gap-2">
                      <button type="button" onClick={() => void guardarEditPaso(p)}
                        className="text-xs text-accent hover:underline">Guardar</button>
                      <button type="button" onClick={() => setEditandoPasoId(null)}
                        className="text-xs text-muted hover:text-ink">Cancelar</button>
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col gap-1">
                    <div className="flex items-start gap-2">
                      <input type="checkbox"
                        checked={pasoEstaCompletado(p)}
                        onChange={() => esAsignado && !supervision && !p.intervencion_pendiente_numero && void togglePaso(p)}
                        disabled={!esAsignado || supervision || !!p.intervencion_pendiente_numero}
                        className="mt-0.5 h-4 w-4 rounded border-border accent-accent shrink-0 cursor-pointer disabled:cursor-not-allowed" />
                      <div className="min-w-0 flex-1">
                        <span className={`text-xs ${pasoEstaCompletado(p) ? "line-through text-muted" : "text-ink"}`}>
                          <span className="text-muted mr-1">{p.orden}.</span>{p.descripcion}
                        </span>
                        {pasoEstaCompletado(p) && p.completado_por_nombre && (
                          <p className="text-[10px] text-muted">
                            ✓ {p.completado_por_nombre}
                            {p.duracion_segundos ? ` · ⏱ ${fmtTiempo(p.duracion_segundos)}` : ""}
                          </p>
                        )}
                      </div>
                      {/* Acciones del paso */}
                      {esAsignado && !supervision && !pasoEstaCompletado(p) && !p.intervencion_pendiente_numero && (
                        <div className="flex items-center gap-1 shrink-0">
                          <button type="button" title="Editar paso" onClick={() => iniciarEditPaso(p)}
                            className="text-muted hover:text-accent transition-colors p-0.5">
                            <svg className="h-3 w-3" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                              <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7" />
                              <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z" />
                            </svg>
                          </button>
                          {ticket.estado === "en_proceso" && !ticket.bloqueado_por && (
                            <button type="button" title="Necesito ayuda en este paso"
                              onClick={() => abrirIntervencionDesdePaso(p)}
                              className="text-muted hover:text-accent/50 transition-colors p-0.5 text-[10px]">
                              🛑
                            </button>
                          )}
                          <button type="button" title="Eliminar paso" onClick={() => void eliminarPasoInline(p.id)}
                            className="text-muted hover:text-red-500 transition-colors p-0.5">
                            <Icon name="trash" size={11} />
                          </button>
                        </div>
                      )}
                      {/* Adjuntar archivo al paso — visible para el ejecutor en cualquier estado */}
                      {esAsignado && !supervision && (
                        <label title="Adjuntar archivo o Ctrl+V en este paso" className="cursor-pointer text-muted hover:text-accent transition-colors p-0.5 shrink-0">
                          {subiendoAdjPaso === p.id
                            ? <span className="inline-block h-3 w-3 rounded-full border-2 border-current border-t-transparent animate-spin" />
                            : <span className="text-[11px]">📎</span>
                          }
                          <input
                            type="file"
                            accept="image/*,.pdf,application/pdf,.doc,.docx"
                            className="sr-only"
                            onChange={(e) => {
                              const f = e.target.files?.[0];
                              if (f) void subirAdjuntoPaso(p.id, f);
                              e.target.value = "";
                            }}
                          />
                        </label>
                      )}
                    </div>
                    {/* Intervención pendiente en este paso */}
                    {p.intervencion_pendiente_numero && (
                      <div className="ml-6 rounded-lg border border-accent/60 bg-accent/60  px-2.5 py-1.5 text-[11px]">
                        <span className="font-semibold text-accent">
                          🛑 Esperando intervención {p.intervencion_pendiente_numero}
                        </span>
                        {p.intervencion_asignado_nombre && (
                          <span className="text-accent/70"> — asignada a <strong>{p.intervencion_asignado_nombre}</strong></span>
                        )}
                      </div>
                    )}
                    {/* Respuesta de la intervención resuelta */}
                    {p.respuesta_intervencion && !p.intervencion_pendiente_numero && (
                      <div className="ml-6 rounded-lg border border-accent/60 bg-accent/60  px-2.5 py-1.5 text-[11px] space-y-0.5">
                        <p className="font-semibold text-accent">✅ Intervención resuelta</p>
                        <p className="text-accent/80  whitespace-pre-wrap leading-relaxed">{p.respuesta_intervencion}</p>
                      </div>
                    )}
                    {/* Notas del paso (si no son respuesta de intervención) */}
                    {p.notas && !p.respuesta_intervencion && (
                      <p className="ml-6 text-[10px] text-muted">{p.notas}</p>
                    )}
                    {/* Imágenes/archivos vinculados a este paso */}
                    {(() => {
                      const pasoAdjs = adjuntosPorPaso.get(p.id) ?? [];
                      if (pasoAdjs.length === 0) return null;
                      return (
                        <div className="ml-6 flex flex-wrap gap-1.5 pt-0.5">
                          {pasoAdjs.map((a) => {
                            const esImagen = (a.mime?.startsWith("image/"))
                              || /\.(jpg|jpeg|png|gif|webp)$/i.test(a.nombre_original);
                            const url = ticketsUploadUrl(a.nombre_archivo, token);
                            return (
                              <div key={a.id} className="relative group">
                                {esImagen ? (
                                  <button type="button" onClick={() => setLightboxUrl(url)} className="block" title={a.nombre_original}>
                                    <img src={url} alt="" className="h-14 w-14 rounded-lg object-cover border border-border group-hover:opacity-80 transition-opacity" />
                                    <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-xs font-bold transition-opacity pointer-events-none">🔍</span>
                                  </button>
                                ) : (
                                  <a href={url} target="_blank" rel="noreferrer"
                                    className="flex h-14 w-14 items-center justify-center rounded-lg border border-border bg-surface text-lg"
                                    title={a.nombre_original}>📄</a>
                                )}
                                {(nivel >= 2 || ticket.creado_por === user.id) && (
                                  <button type="button" disabled={eliminandoAdj === a.id}
                                    onClick={() => void eliminarAdjunto(a.id)}
                                    className="absolute -top-1 -right-1 hidden group-hover:flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-white text-[9px] font-bold shadow">
                                    ✕
                                  </button>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      );
                    })()}
                    {/* Zona de pegado explícita por paso — click o foco + Ctrl+V */}
                    {esAsignado && !supervision && !pasoEstaCompletado(p) && !resuelta && (
                      <label
                        tabIndex={0}
                        onFocus={() => setPasoPasteId(p.id)}
                        onPaste={(e) => {
                          if (manejarPasteCaptura(e, (file) => void subirAdjuntoPaso(p.id, file))) {
                            e.stopPropagation();
                          }
                        }}
                        className={`ml-6 mt-1 flex items-center gap-1.5 rounded-lg border px-2.5 py-1 text-[10px] font-semibold cursor-pointer select-none outline-none transition-colors
                          ${subiendoAdjPaso === p.id
                            ? "border-accent/50 text-accent"
                            : "border-dashed border-border/50 text-muted/60 hover:border-accent/50 hover:text-accent/80 focus:border-accent focus:bg-accent/5 focus:text-accent"
                          }`}
                        title="Haz click aquí y presiona Ctrl+V para pegar un pantallazo en este paso"
                      >
                        {subiendoAdjPaso === p.id ? (
                          <><span className="inline-block h-3 w-3 rounded-full border-2 border-current border-t-transparent animate-spin" /> Subiendo…</>
                        ) : (
                          <><span>📷</span> Ctrl+V — pegar pantallazo</>
                        )}
                        <input
                          type="file"
                          accept="image/*"
                          className="sr-only"
                          onChange={(e) => {
                            const f = e.target.files?.[0];
                            if (f) void subirAdjuntoPaso(p.id, f);
                            e.target.value = "";
                          }}
                        />
                      </label>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>
          {/* Barra de progreso */}
          {pasosTotal > 0 && (
            <div className="h-1 rounded-full bg-border overflow-hidden">
              <div className="h-full rounded-full bg-accent transition-all" style={{ width: `${(pasosCompletados / pasosTotal) * 100}%` }} />
            </div>
          )}
          {/* Agregar paso inline */}
          {esAsignado && !supervision && (
            showAddPaso ? (
              <div className="flex gap-2 pt-1">
                <ProseInput autoFocus className="quest-input flex-1 text-xs" placeholder="Descripción del nuevo paso…"
                  value={nuevoPasoDesc} onChange={(e) => setNuevoPasoDesc(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && void agregarPasoInline()} />
                <button type="button" disabled={agregandoPaso || !nuevoPasoDesc.trim()} onClick={() => void agregarPasoInline()}
                  className="shrink-0 quest-btn-primary px-2 py-1 text-xs">
                  {agregandoPaso ? "…" : "Agregar"}
                </button>
                <button type="button" onClick={() => { setShowAddPaso(false); setNuevoPasoDesc(""); }}
                  className="shrink-0 text-muted hover:text-ink text-xs px-1">✕</button>
              </div>
            ) : (
              <button type="button" onClick={() => setShowAddPaso(true)}
                className="flex items-center gap-1 text-xs text-accent hover:underline pt-0.5">
                <Icon name="plus" size={11} weight="bold" /> Agregar paso
              </button>
            )
          )}
        </div>
      )}

      {/* Modal: Pedir intervención */}
      {showIntervencion && (
        <div className="rounded-xl border border-accent/50 bg-accent/30  p-3 space-y-2">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold text-accent  flex items-center gap-1">
              🛑 Pedir intervención
              <InfoTooltip text="Crea una sub-solicitud para otro usuario. Esta solicitud quedará PAUSADA hasta que el otro usuario resuelva su tarea. Cuando termine, la solicitud se reactiva sola y puedes continuar donde quedaste." />
            </span>
            <button type="button" onClick={() => { setShowIntervencion(false); setInterForm({ titulo: "", descripcion: "", asignado_a: "", paso_ref: "", paso_id: 0 }); }} className="text-muted hover:text-ink text-xs">✕</button>
          </div>
          {interForm.paso_ref && (
            <p className="text-[10px] text-accent/80 bg-accent/50  rounded px-2 py-1">
              Origen: {interForm.paso_ref}
            </p>
          )}
          <ProseInput
            className="quest-input w-full text-sm"
            placeholder="¿Qué necesita hacer el otro usuario?"
            value={interForm.titulo}
            onChange={(e) => setInterForm((f) => ({ ...f, titulo: e.target.value }))}
          />
          <ProseTextarea
            className="quest-input w-full text-xs resize-none"
            rows={2}
            placeholder="Contexto adicional — ¿por qué se necesita esta intervención?"
            value={interForm.descripcion}
            onChange={(e) => setInterForm((f) => ({ ...f, descripcion: e.target.value }))}
          />
          <select
            className="quest-input w-full text-sm"
            value={interForm.asignado_a}
            onChange={(e) => setInterForm((f) => ({ ...f, asignado_a: e.target.value }))}
          >
            <option value="">Selecciona a quién necesitas…</option>
            {usuarios.map((u) => (
              <option key={u.id} value={u.id}>{u.nombre}</option>
            ))}
          </select>
          <div className="flex gap-2">
            <button
              type="button"
              disabled={creandoInter || !interForm.titulo.trim() || !interForm.asignado_a}
              onClick={crearIntervencion}
              className="quest-btn-primary px-3 py-1.5 text-xs"
            >
              {creandoInter ? "Creando…" : "Solicitar intervención — pausar esta solicitud"}
            </button>
            <button type="button" onClick={() => { setShowIntervencion(false); setInterForm({ titulo: "", descripcion: "", asignado_a: "", paso_ref: "", paso_id: 0 }); }} className="text-xs text-muted hover:text-ink">Cancelar</button>
          </div>
        </div>
      )}

      {/* Lista de compras */}
      {showCompras && (
        <div className="rounded-xl border border-accent/40 bg-accent/20  p-3 space-y-2">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold text-accent  flex items-center gap-1">
              🛒 Lista de compras
              <InfoTooltip text="Agrega los productos que se deben comprar para esta solicitud. Puedes buscarlos en el catálogo de materiales o escribir uno nuevo. Marca los que ya se compraron." />
            </span>
            <button type="button" onClick={() => setShowCompras(false)} className="text-muted hover:text-ink text-xs">▲</button>
          </div>
          {loadingCompras && <p className="text-xs text-muted">Cargando…</p>}
          {/* Items existentes */}
          {compras.length > 0 && (
            <div className="space-y-1">
              {compras.map((item) => (
                <div key={item.id} className={`flex items-center gap-2 rounded-lg border border-border/40 px-2 py-1.5 text-xs ${item.comprado ? "opacity-50" : ""}`}>
                  <input type="checkbox" checked={!!item.comprado}
                    onChange={() => !supervision && void toggleComprado(item)}
                    className="h-3.5 w-3.5 accent-blue-500 shrink-0" />
                  <div className="flex-1 min-w-0">
                    <span className={item.comprado ? "line-through text-muted" : "text-ink"}>{item.nombre}</span>
                    {item.sku && <span className="ml-1 text-muted text-[10px]">({item.sku})</span>}
                    <span className="ml-1 text-muted">{item.cantidad} {item.unidad}</span>
                    {item.precio_estimado && <span className="ml-1 text-muted">${item.precio_estimado.toLocaleString("es-CO")}</span>}
                    {item.notas && <p className="text-[10px] text-muted">{item.notas}</p>}
                  </div>
                  {!supervision && (
                    <button type="button" onClick={() => void eliminarCompra(item.id)}
                      className="text-muted hover:text-red-500 shrink-0">
                      <Icon name="trash" size={11} />
                    </button>
                  )}
                </div>
              ))}
              {/* Total estimado */}
              {compras.some((i) => i.precio_estimado) && (
                <p className="text-[10px] text-right text-muted pt-0.5">
                  Total estimado: <strong className="text-ink">
                    ${compras.reduce((sum, i) => sum + (i.precio_estimado ?? 0) * i.cantidad, 0).toLocaleString("es-CO")}
                  </strong>
                </p>
              )}
            </div>
          )}
          {!loadingCompras && compras.length === 0 && (
            <p className="text-xs text-muted italic">Sin productos en la lista.</p>
          )}
          {/* Agregar producto */}
          {!supervision && (
            <div className="space-y-1.5 pt-1 border-t border-border/30">
              <p className="text-[10px] font-semibold text-muted uppercase tracking-wide">Agregar producto</p>
              <div className="relative">
                <input className="quest-input w-full text-xs"
                  placeholder="Buscar en catálogo o escribir nombre…"
                  value={busqProducto}
                  onChange={(e) => void buscarProducto(e.target.value)} />
                {resultadosBusq.length > 0 && (
                  <div className="absolute top-full left-0 z-50 w-full rounded-xl border border-border bg-surface shadow-xl mt-1 max-h-40 overflow-y-auto">
                    {resultadosBusq.map((prod) => (
                      <button key={prod.id} type="button"
                        onClick={() => seleccionarProductoCatalogo(prod)}
                        className="w-full text-left px-3 py-2 text-xs hover:bg-accent/10 border-b border-border/30 last:border-0">
                        <span className="font-medium text-ink">{prod.nombre}</span>
                        {prod.codigo && <span className="ml-1 text-muted">[{prod.codigo}]</span>}
                        <span className="ml-1 text-muted">{prod.unidad_medida}</span>
                      </button>
                    ))}
                  </div>
                )}
              </div>
              <div className="flex gap-1.5">
                <input className="quest-input w-16 text-xs" placeholder="Cant." type="number" min="0.01" step="0.01"
                  value={nuevoProducto.cantidad} onChange={(e) => setNuevoProducto((p) => ({ ...p, cantidad: e.target.value }))} />
                <input className="quest-input w-16 text-xs" placeholder="Unid."
                  value={nuevoProducto.unidad} onChange={(e) => setNuevoProducto((p) => ({ ...p, unidad: e.target.value }))} />
                <input className="quest-input flex-1 text-xs" placeholder="$ Precio est."
                  value={nuevoProducto.precio} onChange={(e) => setNuevoProducto((p) => ({ ...p, precio: e.target.value }))} />
                <button type="button" disabled={agregandoCompra || !nuevoProducto.nombre.trim()} onClick={() => void agregarCompra()}
                  className="shrink-0 quest-btn-primary px-2 py-1 text-xs">
                  {agregandoCompra ? "…" : "Agregar"}
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ── Solicitud normal: interfaz estándar ── */}
      {!resuelta && esAsignado && !supervision && !esIntervencion && !esSolicitudCompraDelegada(ticket) && (
        <div className="space-y-2 pt-1">
          {msg && <p className="text-xs text-red-400">{msg}</p>}
          {protocoloMsg && <p className="text-xs font-semibold text-accent">{protocoloMsg}</p>}

          {/* Generar procedimiento al contestar / cerrar */}
          <div className="rounded-xl border-2 border-dashed border-accent/30 bg-accent/5 p-3 space-y-2">
            <button
              type="button"
              onClick={() => setGuardarComoProcedimiento((v) => !v)}
              className={`w-full flex items-center gap-3 rounded-xl border-2 px-3 py-2.5 text-left transition ${
                guardarComoProcedimiento
                  ? "border-accent bg-accent/10 text-accent"
                  : "border-border bg-surface-panel text-muted hover:border-accent/50"
              }`}
            >
              <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded border-2 text-xs font-black transition ${
                guardarComoProcedimiento ? "border-accent bg-accent text-white" : "border-border"
              }`}>{guardarComoProcedimiento ? "✓" : ""}</span>
              <div>
                <p className="text-sm font-semibold text-ink">Guardar como procedimiento al cerrar</p>
                <p className="text-[11px] text-muted">Al marcar lista o pedir revisión, queda en Procedimientos</p>
              </div>
            </button>
            {guardarComoProcedimiento && (
              <div className="flex gap-2 rounded-xl border border-accent/20 bg-surface-panel p-1">
                <button
                  type="button"
                  onClick={() => setAlcanceProcedimiento("personal")}
                  className={`flex-1 rounded-lg py-2 text-xs font-bold transition ${
                    alcanceProcedimiento === "personal" ? "bg-accent text-white shadow" : "text-muted hover:text-ink"
                  }`}
                >
                  🔒 Solo para mí
                </button>
                <button
                  type="button"
                  onClick={() => setAlcanceProcedimiento("global")}
                  className={`flex-1 rounded-lg py-2 text-xs font-bold transition ${
                    alcanceProcedimiento === "global" ? "bg-accent text-white shadow" : "text-muted hover:text-ink"
                  }`}
                >
                  🌐 Compartir equipo
                </button>
              </div>
            )}
            <button
              type="button"
              disabled={generandoProcedimiento || busy || !!ticket.bloqueado_por}
              onClick={() => void generarProcedimientoAhora()}
              title={ticket.bloqueado_por ? "Intervención pendiente" : "Guardar pasos actuales sin cerrar la solicitud"}
              className="w-full rounded-xl border border-accent/40 bg-surface-panel py-2 text-xs font-bold text-accent hover:bg-accent/10 transition-colors disabled:opacity-40"
            >
              {generandoProcedimiento ? "Generando…" : "📋 Generar procedimiento ahora"}
            </button>
          </div>

          {/* Solicitud con protocolo → botón único que abre el wizard + Listo secundario */}
          {onRegistrarEjecucion && ticket.protocolo_id ? (
            <div className="space-y-1.5">
              <button
                type="button"
                disabled={busy || !!ticket.bloqueado_por}
                onClick={() => onRegistrarEjecucion(ticket)}
                title={ticket.bloqueado_por ? "Intervención pendiente — no disponible" : undefined}
                className="flex w-full items-center justify-center gap-2 rounded-xl bg-accent px-3 py-3 text-sm font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
              >
                <Icon name="lightning" size={15} weight="bold" />
                {ticket.estado === "en_proceso" ? "Continuar ejecución" : "Ejecutar procedimiento"}
              </button>
              <div className="flex gap-2">
                {ticket.estado === "en_proceso" && (
                  <button type="button" disabled={busy} onClick={iniciarPausar}
                    className="flex flex-1 items-center justify-center gap-1.5 rounded-xl border border-accent/40 bg-accent/5 px-3 py-2 text-xs font-bold text-accent transition hover:bg-accent/10   disabled:opacity-40"
                  >
                    <Icon name="clock" size={13} weight="bold" /> Pausar
                  </button>
                )}
                <button
                  type="button"
                  disabled={busy || !!ticket.bloqueado_por}
                  onClick={resolver}
                  title={ticket.bloqueado_por ? "Intervención pendiente — no disponible" : "Marcar como lista sin pasar por el protocolo"}
                  className={`flex flex-1 items-center justify-center gap-1.5 rounded-xl border px-3 py-2 text-xs font-bold transition-colors ${
                    ticket.bloqueado_por
                      ? "border-border bg-surface-hover text-muted cursor-not-allowed"
                      : "border-accent/50 bg-accent/5 text-accent hover:bg-accent/10"
                  }`}
                >
                  <Icon name="check" size={13} weight="bold" />
                  Listo
                </button>
              </div>
            </div>
          ) : ticket.estado === "esperando_aprobacion" ? (
            /* En revisión — esperando al creador */
            <div className="rounded-xl border border-accent/50 bg-accent/30  px-3 py-2.5 space-y-2">
              <p className="text-sm font-bold text-accent  flex items-center gap-2">
                🔔 Esperando revisión del solicitante
              </p>
              <p className="text-xs text-accent/80">
                {ticket.creado_por_nombre ?? "El solicitante"} debe aprobar para cerrar la solicitud.
              </p>
              <button type="button" disabled={busy} onClick={cancelarRevision}
                className="text-xs text-muted hover:text-ink border border-border rounded-lg px-3 py-1 transition-colors">
                Cancelar revisión — volver a en proceso
              </button>
            </div>
          ) : (
            /* Solicitud libre → Iniciar/Pausar + Listo + Solicitar revisión */
            <div className="space-y-2">
              <div className="flex gap-2">
                <button type="button" disabled={busy} onClick={iniciarPausar}
                  className={`flex flex-1 items-center justify-center gap-1.5 rounded-xl border px-3 py-2.5 text-sm font-bold min-h-[44px] transition-colors ${
                    ticket.estado === "en_proceso"
                      ? "border-accent/40 bg-accent/5 text-accent hover:bg-accent/10"
                      : "border-accent bg-accent/10 text-accent hover:bg-accent/20"
                  }`}
                >
                  <Icon name={ticket.estado === "en_proceso" ? "clock" : "lightning"} size={15} weight="bold" />
                  {ticket.estado === "en_proceso" ? "Pausar" : "Iniciar"}
                </button>
                {(() => {
                  const total = ticket.pasos_total ?? 0;
                  const hechos = ticket.pasos_completados ?? 0;
                  const pasosFaltantes = total > 0 ? total - hechos : 0;
                  const bloqueado = !!ticket.bloqueado_por;
                  const noPermite = pasosFaltantes > 0 || bloqueado;
                  return (
                    <button type="button" disabled={busy || noPermite} onClick={resolver}
                      title={bloqueado ? "Intervención pendiente — no disponible" : pasosFaltantes > 0 ? `Faltan ${pasosFaltantes} paso(s) por completar` : undefined}
                      className={`flex flex-1 items-center justify-center gap-1.5 rounded-xl border px-3 py-2.5 text-sm font-bold min-h-[44px] transition-colors ${
                        noPermite
                          ? "border-border bg-surface-hover text-muted cursor-not-allowed"
                          : "border-accent/50 bg-accent/5 text-accent hover:bg-accent/10"
                      }`}
                    >
                      <Icon name="check" size={15} weight="bold" />
                      {bloqueado
                        ? "Listo 🔒"
                        : pasosFaltantes > 0
                          ? `Listo (${hechos}/${total} pasos)`
                          : cierreVaARevision ? "Marcar lista" : "Listo"}
                    </button>
                  );
                })()}
              </div>
              {/* Solicitar revisión del solicitante */}
              {!showPedirRevision ? (
                <button type="button" disabled={busy}
                  onClick={() => setShowPedirRevision(true)}
                  className="flex w-full items-center justify-center gap-1.5 rounded-xl border border-accent/50 bg-accent/20  px-3 py-2 text-xs font-bold text-accent  hover:bg-accent/50  transition-colors">
                  🔔 Solicitar revisión del solicitante
                </button>
              ) : (
                <div className="rounded-xl border border-accent/40 bg-accent/20  p-3 space-y-2">
                  <p className="text-xs font-bold text-accent">
                    Solicitar revisión a {ticket.creado_por_nombre ?? "el solicitante"}
                  </p>
                  <ProseTextarea
                    className="quest-input w-full text-xs resize-none"
                    rows={2}
                    placeholder="Nota para el solicitante (opcional): qué revisó, cómo quedó…"
                    value={notaRevision}
                    onChange={(e) => setNotaRevision(e.target.value)}
                  />
                  <div className="flex gap-2">
                    <button type="button" disabled={busy} onClick={pedirRevision}
                      className="flex-1 rounded-xl bg-accent/50 py-2 text-xs font-bold text-white disabled:opacity-40 hover:bg-accent transition-colors">
                      {busy ? "Enviando…" : "Enviar para revisión"}
                    </button>
                    <button type="button" onClick={() => { setShowPedirRevision(false); setNotaRevision(""); }}
                      className="rounded-xl border border-border px-3 py-2 text-xs text-muted hover:text-ink">
                      Cancelar
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Botones secundarios */}
          {detalleAmpliado ? (
            <div className="flex items-center gap-1.5 flex-wrap">
              <button
                type="button"
                onClick={() => setShowExtrasMenu((v) => !v)}
                title="Adjuntos, pasos y lista de compras"
                className={`flex items-center gap-1 rounded-lg border px-2.5 py-1.5 text-xs font-bold transition-colors ${showExtrasMenu ? "border-accent bg-accent/10 text-accent" : "border-border text-muted hover:border-accent hover:text-accent"}`}
              >
                <span className="text-sm leading-none font-black">{showExtrasMenu ? "✕" : "+"}</span>
                Opciones
              </button>
              {showExtrasMenu && (
                <>
                  <button type="button"
                    onClick={() => { setShowAdjuntos((v) => !v); if (!showAdjuntos) void cargarAdjuntos(); }}
                    className={`rounded-lg border px-2 py-1.5 text-xs transition-colors ${showAdjuntos ? "border-accent text-accent" : "border-border text-muted hover:text-accent hover:border-accent"}`}>
                    📎 Adjuntos{adjuntos.length > 0 ? ` (${adjuntos.length})` : ""}
                  </button>
                  {!(onRegistrarEjecucion && ticket.protocolo_id) && (ticket.pasos_total ?? 0) > 0 && !showPasos && (
                    <button type="button" onClick={() => { setShowPasos(true); void cargarPasos(); }}
                      className="rounded-lg border border-border px-2 py-1.5 text-xs text-muted hover:text-accent hover:border-accent transition-colors">
                      ☑ Ver pasos
                    </button>
                  )}
                  {(ticket.pasos_total ?? 0) === 0 && !showPasos && puedeVincularProtocolo && protocolos.length > 0 && (
                    <button type="button"
                      onClick={() => { setShowPasos(true); setShowVincularProtocolo(true); void cargarPasos(); }}
                      className="rounded-lg border border-accent/40 px-2 py-1.5 text-xs text-accent hover:bg-accent/10 transition-colors">
                      📋 Enlazar
                    </button>
                  )}
                  {ticket.estado === "en_proceso" && !ticket.bloqueado_por && showPasos && (
                    <button type="button" onClick={() => setShowAddPaso(true)}
                      className="rounded-lg border border-border px-2 py-1.5 text-xs text-muted hover:text-accent hover:border-accent transition-colors">
                      + Paso
                    </button>
                  )}
                  <button type="button"
                    onClick={() => { setShowCompras((v) => !v); if (!showCompras) void cargarCompras(); }}
                    className={`rounded-lg border px-2 py-1.5 text-xs transition-colors ${showCompras ? "border-accent/40 text-accent" : "border-border text-muted hover:text-accent/50 hover:border-accent/40"}`}>
                    🛒 Compras{compras.length > 0 ? ` (${compras.length})` : ""}
                  </button>
                </>
              )}
            </div>
          ) : (
            <div className="flex flex-wrap gap-1.5">
              <button type="button"
                onClick={() => { setShowAdjuntos(true); void cargarAdjuntos(); }}
                className={`rounded-lg border px-2 py-1.5 text-xs transition-colors ${showAdjuntos ? "border-accent text-accent" : "border-border text-muted hover:text-accent hover:border-accent"}`}>
                📎 Adjuntos{adjuntos.length > 0 ? ` (${adjuntos.length})` : ""}
              </button>
              {/* Ver pasos solo para solicitudes sin protocolo (las de protocolo usan el wizard) */}
              {!(onRegistrarEjecucion && ticket.protocolo_id) && (ticket.pasos_total ?? 0) > 0 && !showPasos && (
                <button type="button" onClick={() => { setShowPasos(true); void cargarPasos(); }}
                  className="rounded-lg border border-border px-2 py-1.5 text-xs text-muted hover:text-accent hover:border-accent transition-colors">
                  ☑ Ver pasos
                </button>
              )}
              {(ticket.pasos_total ?? 0) === 0 && !showPasos && puedeVincularProtocolo && protocolos.length > 0 && (
                <button type="button"
                  onClick={() => { setShowPasos(true); setShowVincularProtocolo(true); void cargarPasos(); }}
                  className="rounded-lg border border-accent/40 px-2 py-1.5 text-xs text-accent hover:bg-accent/10 transition-colors">
                  📋 Enlazar procedimiento
                </button>
              )}
              {ticket.estado === "en_proceso" && !ticket.bloqueado_por && showPasos && (
                <button type="button" onClick={() => setShowAddPaso(true)}
                  className="rounded-lg border border-border px-2 py-1.5 text-xs text-muted hover:text-accent hover:border-accent transition-colors">
                  + Paso
                </button>
              )}
              <button type="button"
                onClick={() => { setShowCompras((v) => !v); if (!showCompras) void cargarCompras(); }}
                className={`rounded-lg border px-2 py-1.5 text-xs transition-colors ${showCompras ? "border-accent/40 text-accent" : "border-border text-muted hover:text-accent/50 hover:border-accent/40"}`}>
                🛒 Compras{compras.length > 0 ? ` (${compras.length})` : ""}
              </button>
              {/* Intervención solo disponible por paso — botón general eliminado */}
            </div>
          )}
        </div>
      )}

      {/* Panel de aprobación — visible al creador cuando la solicitud espera revisión */}
      {!resuelta && esCreadoPorMi && !esAsignado && ticket.estado === "esperando_aprobacion" && (
        <div className="rounded-xl border-2 border-accent/50 bg-accent/30  p-3 space-y-3">
          <p className="text-sm font-extrabold text-accent  flex items-center gap-2">
            🔔 {ticket.asignado_a_nombre ?? "El ejecutor"} completó la solicitud y pide tu revisión
          </p>
          {msg && <p className="text-xs text-red-400">{msg}</p>}

          <div className="rounded-xl border border-accent/30 bg-surface p-3 space-y-2">
            <p className="text-xs font-extrabold uppercase tracking-wide text-ink">
              Resultado para revisar
            </p>
            {comentariosEntregaRevision.map((c) => (
              <p key={c.id} className="whitespace-pre-wrap text-sm text-ink">{c.texto}</p>
            ))}
            {adjuntosEntregaRevision.map((a) => {
              const esImagen = (a.mime?.startsWith("image/"))
                || /\.(jpg|jpeg|png|gif|webp)$/i.test(a.nombre_original);
              const url = ticketsUploadUrl(a.nombre_archivo, token);
              return esImagen ? (
                <button
                  key={a.id}
                  type="button"
                  onClick={() => setLightboxUrl(url)}
                  className="block w-full overflow-hidden rounded-xl border border-border bg-white"
                  title="Ampliar respuesta"
                >
                  <img
                    src={url}
                    alt={`Respuesta de ${ticket.asignado_a_nombre ?? "la persona asignada"}`}
                    className="max-h-80 w-full object-contain"
                  />
                  <span className="block border-t border-border bg-surface px-2 py-1 text-xs font-bold text-accent">
                    Ampliar respuesta 🔍
                  </span>
                </button>
              ) : (
                <a
                  key={a.id}
                  href={url}
                  target="_blank"
                  rel="noreferrer"
                  className="block rounded-lg border border-border px-3 py-2 text-xs font-semibold text-accent hover:underline"
                >
                  📎 {a.nombre_original}
                </a>
              );
            })}
            {adjuntosEntregaRevision.length === 0 && comentariosEntregaRevision.length === 0 && (
              <p className="text-xs font-semibold text-amber-700 dark:text-amber-300">
                No dejó respuesta escrita ni archivos. Pide ajustes antes de aprobar.
              </p>
            )}
          </div>

          {/* Aprobar */}
          <button type="button" disabled={busy} onClick={aprobar}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-accent px-3 py-2.5 text-sm font-extrabold text-white hover:bg-accent transition-colors disabled:opacity-40">
            <Icon name="check" size={15} weight="bold" />
            Aprobar y cerrar
          </button>

          {/* Pedir ajustes */}
          {!showPedirAjustes ? (
            <button type="button" disabled={busy}
              onClick={() => setShowPedirAjustes(true)}
              className="flex w-full items-center justify-center gap-2 rounded-xl border border-accent/50 px-3 py-2 text-xs font-bold text-accent  hover:bg-accent/40  transition-colors disabled:opacity-40">
              🔄 Pedir ajustes
            </button>
          ) : (
            <div className="space-y-2">
              <ProseTextarea
                autoFocus
                className="quest-input w-full text-xs resize-none"
                rows={3}
                placeholder="¿Qué necesita corregirse o completarse?"
                value={ajustesMensaje}
                onChange={(e) => setAjustesMensaje(e.target.value)}
              />
              {/* Adjuntar imagen */}
              <label className={`flex items-center gap-2 cursor-pointer rounded-lg border px-3 py-2 text-xs transition-colors ${ajustesArchivo ? "border-accent/40 bg-accent/30  text-accent" : "border-dashed border-border text-muted hover:border-accent/60 hover:text-accent"}`}>
                <span>{ajustesArchivo ? "📎" : "🖼️"}</span>
                <span className="flex-1 truncate">{ajustesArchivo ? ajustesArchivo.name : "Adjuntar imagen (opcional) — Ctrl+V"}</span>
                {ajustesArchivo && (
                  <span
                    role="button"
                    tabIndex={0}
                    className="ml-1 text-muted hover:text-red-500"
                    onClick={(e) => { e.preventDefault(); setAjustesArchivo(null); setAjustesArchivoPreview(null); }}
                    onKeyDown={(e) => { if (e.key === "Enter") { setAjustesArchivo(null); setAjustesArchivoPreview(null); } }}
                  >✕</span>
                )}
                <input
                  type="file"
                  accept="image/*,.pdf,application/pdf"
                  className="sr-only"
                  onChange={(e) => {
                    const f = e.target.files?.[0] ?? null;
                    setAjustesArchivo(f);
                    if (f && f.type.startsWith("image/")) {
                      const url = URL.createObjectURL(f);
                      setAjustesArchivoPreview(url);
                    } else {
                      setAjustesArchivoPreview(null);
                    }
                    e.target.value = "";
                  }}
                />
              </label>
              {ajustesArchivoPreview && (
                <img src={ajustesArchivoPreview} alt="Vista previa" className="rounded-lg max-h-32 object-contain border border-border" />
              )}
              <div className="flex gap-2">
                <button type="button" disabled={busy || !ajustesMensaje.trim()} onClick={pedirAjustes}
                  className="flex-1 rounded-xl bg-accent/50 py-2 text-xs font-bold text-white disabled:opacity-40 hover:bg-accent transition-colors">
                  {busy ? "Enviando…" : "Enviar ajustes"}
                </button>
                <button type="button" onClick={() => { setShowPedirAjustes(false); setAjustesMensaje(""); setAjustesArchivo(null); setAjustesArchivoPreview(null); }}
                  className="rounded-xl border border-border px-3 py-2 text-xs text-muted hover:text-ink">
                  Cancelar
                </button>
              </div>
            </div>
          )}

          {/* Rechazar */}
          <button type="button" disabled={busy} onClick={rechazarRevision}
            className="flex w-full items-center justify-center gap-2 rounded-xl border border-red-400/40 px-3 py-2 text-xs font-bold text-red-600 dark:text-red-400 hover:bg-red-50/30 dark:hover:bg-red-900/10 transition-colors disabled:opacity-40">
            ❌ Rechazar solicitud
          </button>
        </div>
      )}

      {/* Finalizar directamente: creador o admin puede cerrar sin pasar por el flujo de revisión */}
      {!resuelta && (esCreadoPorMi || isAdmin) && !esAsignado && !supervision
        && ticket.estado !== "esperando_aprobacion"
        && !esIntervencion && !esSolicitudCompraDelegada(ticket) && (
        <div className="pt-1 space-y-1">
          {msg && <p className="text-xs text-red-400">{msg}</p>}
          <button
            type="button"
            disabled={busy}
            onClick={() => void cerrarDirecto()}
            className="flex w-full items-center justify-center gap-2 rounded-xl border border-accent/50 bg-accent/5 px-3 py-2.5 text-sm font-bold text-accent hover:bg-accent/10 transition-colors disabled:opacity-40"
          >
            <Icon name="check" size={15} weight="bold" />
            {busy ? "Cerrando…" : "Finalizar y cerrar solicitud"}
          </button>
        </div>
      )}

      {/* Banner "solo el asignado puede resolver" — oculto cuando el creador tiene el panel de revisión o puede cerrar directamente */}
      {!resuelta && !esAsignado && !supervision
        && !(esCreadoPorMi && ticket.estado === "esperando_aprobacion")
        && !(esCreadoPorMi || isAdmin) && (
        <div className="rounded-lg border border-border bg-surface-hover px-3 py-2 text-xs text-muted text-center">
          {ticket.estado === "esperando_aprobacion"
            ? <span>🔔 Esperando revisión de <strong>{ticket.creado_por_nombre ?? "el solicitante"}</strong></span>
            : <span>Solo <strong>{ticket.asignado_a_nombre ?? "el asignado"}</strong> puede resolver esta solicitud</span>
          }
        </div>
      )}
      {!resuelta && supervision && !isAdmin && (
        <div className="space-y-2">
          {adjuntos.length === 0 && !loadingAdjuntos && (
            <button
              type="button"
              onClick={() => { setShowAdjuntos(true); void cargarAdjuntos(); }}
              className="w-full rounded-lg border border-border px-3 py-2 text-xs font-semibold text-muted hover:border-accent hover:text-accent transition-colors"
            >
              📎 Ver adjuntos
            </button>
          )}
          <p className="text-[10px] text-center text-muted">
            Seguimiento del equipo — usa <strong>Mensajes</strong> para conversar con quien solicita o ejecuta la tarea
          </p>
        </div>
      )}

      {/* Botón: guardar como protocolo (solicitudes resueltas) */}
      {resuelta && (puedeCrearProtocolos(user) || esAsignado) && (
        <div className="pt-1 space-y-2">
          {protocoloMsg && (
            <p className="text-xs text-accent">{protocoloMsg}</p>
          )}
          {!showProtocoloForm ? (
            <div className="flex flex-col gap-1.5">
              <button
                type="button"
                disabled={guardandoProtocolo}
                onClick={() => void (async () => {
                  setGuardandoProtocolo(true);
                  try {
                    await guardarProcedimientoDesdeSolicitud("personal");
                    setProtocoloMsg("✓ Procedimiento guardado");
                    setTimeout(() => setProtocoloMsg(""), 4000);
                  } catch (e: any) {
                    setProtocoloMsg(e.message ?? "Error al guardar");
                    setTimeout(() => setProtocoloMsg(""), 4000);
                  } finally { setGuardandoProtocolo(false); }
                })()}
                className="flex items-center gap-1.5 text-xs text-muted hover:text-accent border border-dashed border-border hover:border-accent rounded-lg px-3 py-1.5 w-full justify-center transition-colors disabled:opacity-40"
              >
                {guardandoProtocolo ? "Guardando…" : "📋 Guardar como procedimiento"}
              </button>
              {puedeCrearProtocolos(user) && (
                <button
                  type="button"
                  onClick={() => {
                    setProtocoloForm({ titulo: ticket.titulo, descripcion: ticket.descripcion ?? "", categoria: ticket.categoria ?? "" });
                    setShowProtocoloForm(true);
                  }}
                  className="flex items-center gap-1.5 text-xs text-muted hover:text-accent border border-dashed border-border hover:border-accent rounded-lg px-3 py-1.5 w-full justify-center transition-colors"
                >
                  ✏️ Personalizar nombre del procedimiento
                </button>
              )}
            </div>
          ) : (
            <div className="rounded-xl border border-accent/40 bg-accent/5 p-3 space-y-2">
              <p className="text-xs font-bold text-accent flex items-center gap-1">
                📋 Guardar como procedimiento
                <InfoTooltip text="Crea un procedimiento reutilizable a partir de esta solicitud resuelta. El procedimiento guardará todos los pasos ejecutados y servirá como plantilla para nuevas solicitudes del mismo tipo." />
              </p>
              <ProseInput
                className="quest-input w-full text-sm"
                placeholder="Nombre del procedimiento (ej: Pago a proveedor)"
                value={protocoloForm.titulo}
                onChange={(e) => setProtocoloForm((f) => ({ ...f, titulo: e.target.value }))}
              />
              <input
                className="quest-input w-full text-sm"
                placeholder="Categoría (ej: pagos, compras, logística)"
                value={protocoloForm.categoria}
                onChange={(e) => setProtocoloForm((f) => ({ ...f, categoria: e.target.value }))}
              />
              <ProseTextarea
                className="quest-input w-full text-xs resize-none"
                rows={2}
                placeholder="Descripción breve (opcional)"
                value={protocoloForm.descripcion}
                onChange={(e) => setProtocoloForm((f) => ({ ...f, descripcion: e.target.value }))}
              />
              <div className="flex gap-2">
                <button
                  type="button"
                  disabled={guardandoProtocolo || !protocoloForm.titulo.trim()}
                  onClick={() => void guardarComoProtocolo()}
                  className="quest-btn-primary px-3 py-1 text-xs"
                >
                  {guardandoProtocolo ? "Guardando…" : "Guardar procedimiento"}
                </button>
                <button type="button" onClick={() => setShowProtocoloForm(false)} className="text-xs text-muted hover:text-ink">
                  Cancelar
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ── useStt: hook voz → texto reutilizable ────────────────────────────────────

function useStt(token: string, chatApiToken: string | null | undefined) {
  const [grabando, setGrabando] = useState(false);
  const [transcribiendo, setTranscribiendo] = useState(false);
  const [error, setError] = useState("");
  const [segundos, setSegundos] = useState(0);
  const mrRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const startRef = useRef<number>(0);
  const onTextRef = useRef<((text: string) => void) | null>(null);

  async function iniciar(onText: (text: string) => void) {
    onTextRef.current = onText;
    setError("");
    setSegundos(0);
    unlockAudioContext();
    if (isMcKennaAndroidApp()) {
      const bridge = mckennaAndroidBridge();
      if (bridge?.hasAudioPermission && !bridge.hasAudioPermission()) {
        bridge.requestAudioPermission?.();
        setError("Concede el permiso de micrófono en el diálogo del sistema y toca el micrófono de nuevo.");
        return;
      }
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      chunksRef.current = [];
      const mr = new MediaRecorder(stream);
      mr.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      mr.onstop = async () => {
        if (timerRef.current) clearInterval(timerRef.current);
        stream.getTracks().forEach((t) => t.stop());
        const durSeg = Math.round((Date.now() - startRef.current) / 1000);
        const blob = new Blob(chunksRef.current, { type: mr.mimeType });
        if (blob.size === 0 || durSeg < 1) {
          setError("Grabación muy corta. Habla al menos 1 segundo.");
          setGrabando(false);
          return;
        }
        setTranscribiendo(true);
        try {
          const ext = blob.type.split("/")[1]?.split(";")[0] || "webm";
          const fd = new FormData();
          fd.append("audio", blob, `audio.${ext}`);
          const res = await fetch("/api/voz/transcribir", {
            method: "POST",
            headers: { Authorization: `Bearer ${chatApiToken ?? token}` },
            body: fd,
          });
          if (!res.ok) {
            setError(`Error del servidor (${res.status}). ¿Está activo Whisper?`);
          } else {
            const data = await res.json();
            const texto = (data.texto ?? "").trim();
            if (texto) {
              onTextRef.current?.(texto);
              setError("");
            } else {
              setError("Whisper no detectó palabras. Habla más cerca del micrófono e intenta de nuevo.");
            }
          }
        } catch {
          setError("Sin conexión con el servidor. Verifica que agente-pro esté activo.");
        }
        setTranscribiendo(false);
        setGrabando(false);
        setSegundos(0);
      };
      mrRef.current = mr;
      startRef.current = Date.now();
      mr.start(250);
      setGrabando(true);
      timerRef.current = setInterval(() => setSegundos((s) => s + 1), 1000);
    } catch (e: any) {
      if (e.name === "NotAllowedError") {
        setError(
          isMcKennaAndroidApp()
            ? "Permiso denegado. Ve a Ajustes del teléfono → Aplicaciones → McKenna → Permisos → Micrófono y actívalo."
            : "Permiso de micrófono denegado. Habilítalo en la configuración del navegador."
        );
      } else if (e.name === "NotFoundError") {
        setError("No se encontró micrófono en este dispositivo.");
      } else {
        setError(`Error al acceder al micrófono: ${e.message}`);
      }
    }
  }

  function detener() {
    if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    const mr = mrRef.current;
    if (mr && (mr.state === "recording" || mr.state === "paused")) {
      mr.stop();
    } else {
      setGrabando(false);
      setTranscribiendo(false);
    }
  }

  return { grabando, transcribiendo, error, setError, segundos, iniciar, detener };
}

const MIC_ICON = (
  <svg className="h-4 w-4" fill="none" stroke="currentColor" strokeWidth="1.8" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z" />
    <path strokeLinecap="round" strokeLinejoin="round" d="M19 10v2a7 7 0 01-14 0v-2M12 19v4M8 23h8" />
  </svg>
);

const STOP_ICON = (
  <svg className="h-4 w-4 shrink-0" fill="currentColor" viewBox="0 0 24 24">
    <rect x="5" y="5" width="14" height="14" rx="2" />
  </svg>
);

function SttBanner({ stt }: { stt: ReturnType<typeof useStt> }) {
  if (!stt.grabando) return null;
  return (
    <div className="flex items-center gap-3 rounded-xl border-2 border-red-400/60 bg-red-500/10 px-4 py-3">
      <span className="h-3 w-3 shrink-0 rounded-full bg-red-400 animate-pulse" />
      <span className="font-mono text-sm font-bold text-red-400 tabular-nums">
        {String(Math.floor(stt.segundos / 60)).padStart(2, "0")}:{String(stt.segundos % 60).padStart(2, "0")}
      </span>
      <span className="flex-1 text-sm text-red-400">Grabando…</span>
      <button
        type="button"
        onClick={stt.detener}
        className="flex items-center gap-2 rounded-xl bg-red-500 px-4 py-2.5 text-sm font-bold text-white min-h-[44px] shadow-md active:bg-red-700 hover:bg-red-600 transition-colors"
      >
        {STOP_ICON}
        Detener grabación
      </button>
    </div>
  );
}

function SttInlineBtn({ stt, onStart, label = "Voz" }: {
  stt: ReturnType<typeof useStt>;
  onStart: () => void;
  label?: string;
}) {
  if (stt.grabando) {
    return (
      <button
        type="button"
        onClick={stt.detener}
        title="Detener grabación"
        className="flex items-center justify-center gap-1.5 rounded-xl bg-red-500 px-3 py-2.5 text-sm font-bold text-white min-h-[44px] min-w-[72px] shadow active:bg-red-700 hover:bg-red-600 transition-colors"
      >
        {STOP_ICON}
        Stop
      </button>
    );
  }
  return (
    <button
      type="button"
      onClick={onStart}
      disabled={stt.transcribiendo}
      title="Dictar por voz (Whisper STT)"
      className="flex items-center justify-center gap-1.5 rounded-lg border border-border px-3 py-2.5 text-sm min-h-[44px] text-muted hover:border-accent hover:text-accent transition-colors disabled:opacity-50"
    >
      {stt.transcribiendo
        ? <span className="h-4 w-4 rounded-full border-2 border-current border-t-transparent animate-spin" />
        : MIC_ICON
      }
      <span className="hidden sm:inline">{stt.transcribiendo ? "…" : label}</span>
    </button>
  );
}

// ── Wizard: registrar nueva acción (estilo misión simple) ─────────────────────

type UnidadCompra = "g" | "u";
type ItemCompraAccion = { n: string; cantidad: string; unidad: UnidadCompra; comprado: boolean };
type PasoAccionDraft = {
  nombre: string;
  desc: string;
  foto?: File | null;
  adjuntos_ref?: { nombre_archivo: string; mime: string }[];
};
type FaseAccionWizard = "titulo" | "compras_lista" | "compras_tienda" | "pasos" | "cierre";

function nuevoItemCompra(): ItemCompraAccion {
  return { n: "", cantidad: "", unidad: "g", comprado: false };
}

function formatCantidadItem(m: ItemCompraAccion): string {
  const q = m.cantidad.trim();
  if (!q) return "";
  return m.unidad === "g" ? `${q} g` : `${q} u`;
}

function notasListaCompras(items: ItemCompraAccion[]): string {
  const ok = items.filter((m) => m.n.trim());
  return "📦 Lista de compras:\n"
    + ok.map((m) => {
      const c = formatCantidadItem(m);
      return `• ${m.n.trim()}${c ? ` — ${c}` : ""}`;
    }).join("\n");
}

function indiceProgresoWizard(fase: FaseAccionWizard, conCompras: boolean): number {
  if (fase === "titulo") return 1;
  if (fase === "compras_lista") return 2;
  if (fase === "compras_tienda") return 3;
  if (fase === "pasos") return conCompras ? 4 : 3;
  return conCompras ? 5 : 4;
}

/** Estado para reabrir el asistente donde el operador lo dejó. */
type ResumeAccionState = {
  ticketId: number;
  faseInicial: FaseAccionWizard;
  plantilla: PlantillaAccion;
  subCompras: "idle" | "editando";
  pasoComprasId: number | null;
  bloqueoCompras: {
    solicitud_id: number;
    numero: string;
    titulo: string;
    asignado_nombre: string | null;
    estado?: string;
  } | null;
  bloqueadoIntervencion?: string | null;
  ticket: Ticket;
};

async function cargarEstadoReanudacion(ticketId: number, token: string): Promise<ResumeAccionState> {
  const [det, pasosRaw, bloqueoResp] = await Promise.all([
    tapi(`/${ticketId}`, token) as Promise<Ticket>,
    tapi(`/${ticketId}/pasos`, token) as Promise<Paso[]>,
    tapi(`/${ticketId}/bloqueo-compras`, token) as Promise<{ bloqueo: ResumeAccionState["bloqueoCompras"] }>,
  ]);
  const pasosArr = Array.isArray(pasosRaw) ? pasosRaw : [];
  let listaCompras: ItemCompraAccion[] = [];
  const pasosEj: PasoAccionDraft[] = [];
  let pasoComprasId: number | null = null;
  let pasoComprasHecho = false;

  for (const p of pasosArr) {
    if (p.descripcion === "Ir de compras") {
      pasoComprasId = p.id;
      pasoComprasHecho = pasoEstaCompletado(p);
      listaCompras = parseListaComprasDesdeNotas((p.notas as string) || "");
      if (pasoComprasHecho) {
        listaCompras = listaCompras.map((it) => ({ ...it, comprado: true }));
      }
    } else if (p.descripcion) {
      pasosEj.push({ nombre: p.descripcion, desc: (p.notas as string) || "" });
    }
  }

  const bloqueo = bloqueoResp.bloqueo ?? null;
  const conCompras = listaCompras.length > 0;
  const pasosEnServidor = pasosArr.filter((p) => p.descripcion !== "Ir de compras").length > 0;

  let fase: FaseAccionWizard = "compras_lista";
  let subCompras: "idle" | "editando" = "idle";

  if (bloqueo) {
    fase = "compras_lista";
    subCompras = "editando";
  } else if (conCompras && !pasoComprasHecho) {
    fase = "compras_tienda";
    subCompras = "editando";
  } else if (pasosEnServidor) {
    // Los pasos pueden haberse guardado incrementalmente (desde "Guardar · agregar otro").
    // Regresar siempre a "pasos" para que el usuario pueda continuar añadiendo o avanzar.
    // Si ya habían llegado a cierre, un clic en "Continuar →" los lleva allá de nuevo.
    fase = "pasos";
  } else if (conCompras && pasoComprasHecho) {
    fase = "pasos";
    subCompras = "editando";
  } else if (det.estado === "en_proceso" || (det.segundos_trabajo ?? 0) > 0) {
    fase = "compras_lista";
    subCompras = conCompras ? "editando" : "idle";
  }

  const plantilla: PlantillaAccion = {
    titulo: det.titulo,
    protocoloId: det.protocolo_id ?? undefined,
    listaCompras,
    pasos: pasosEj,
  };

  return {
    ticketId,
    faseInicial: fase,
    plantilla,
    subCompras,
    pasoComprasId,
    bloqueoCompras: bloqueo,
    bloqueadoIntervencion: det.bloqueado_por ? (det.bloqueado_por_numero ?? `TCK-${det.bloqueado_por}`) : null,
    ticket: det,
  };
}

function NuevaAccionWizard({
  token,
  user,
  chatApiToken,
  tituloInicial = "",
  plantilla,
  reanudar,
  solicitudPadreId,
  onCancel,
  onCreated,
}: {
  token: string;
  user: TicketsUser;
  chatApiToken: string | null | undefined;
  tituloInicial?: string;
  plantilla?: PlantillaAccion;
  /** Reanudar acción en curso (misma UI, fase inferida del servidor). */
  reanudar?: ResumeAccionState;
  solicitudPadreId?: number;
  onCancel: () => void;
  onCreated: (ticketId: number) => void;
}) {
  const stt = useStt(token, chatApiToken);
  const plantillaEff = reanudar?.plantilla ?? plantilla;
  const [fase, setFase] = useState<FaseAccionWizard>(
    reanudar?.faseInicial ?? (plantillaEff ? "compras_lista" : "titulo"),
  );
  const [wizardDir, setWizardDir] = useState<"right" | "left">("right");
  const [titulo, setTitulo] = useState(plantillaEff?.titulo ?? tituloInicial);
  const [detalle, setDetalle] = useState("");
  const [conCompras, setConCompras] = useState((plantillaEff?.listaCompras?.length ?? 0) > 0);
  const [subCompras, setSubCompras] = useState<"idle" | "editando">(
    reanudar?.subCompras ?? ((plantillaEff?.listaCompras?.length ?? 0) > 0 ? "editando" : "idle"),
  );
  const [listaCompras, setListaCompras] = useState<ItemCompraAccion[]>(
    plantillaEff?.listaCompras?.length ? plantillaEff.listaCompras : [],
  );
  const [pasosGuardados, setPasosGuardados] = useState<PasoAccionDraft[]>(plantillaEff?.pasos ?? []);
  const [reporteSolicitud, setReporteSolicitud] = useState("");
  const [guardarComoProcedimiento, setGuardarComoProcedimiento] = useState(false);
  const [alcanceProcedimiento, setAlcanceProcedimiento] = useState<"personal" | "global">("personal");
  const [pasoNombre, setPasoNombre] = useState("");
  const [pasoDesc, setPasoDesc] = useState("");
  const [pasoFoto, setPasoFoto] = useState<File | null>(null);
  const [editandoPasoIdx, setEditandoPasoIdx] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [ticketId, setTicketId] = useState<number | null>(reanudar?.ticketId ?? null);
  const [pasoComprasId, setPasoComprasId] = useState<number | null>(reanudar?.pasoComprasId ?? null);
  const [bloqueadoIntervencion, setBloqueadoIntervencion] = useState<string | null>(
    reanudar?.bloqueadoIntervencion ?? null,
  );
  const [facturaFile, setFacturaFile] = useState<File | null>(null);
  const [facturaPreview, setFacturaPreview] = useState<string | null>(null);
  const [cierreArchivo, setCierreArchivo] = useState<File | null>(null);
  const [cierrePreview, setCierrePreview] = useState<string | null>(null);
  const [usuariosDelegar, setUsuariosDelegar] = useState<UserInfo[]>([]);
  const [delegarAId, setDelegarAId] = useState<number | "">("");
  const [delegacionMsg, setDelegacionMsg] = useState("");
  const [bloqueoCompras, setBloqueoCompras] = useState<{
    solicitud_id: number;
    numero: string;
    titulo: string;
    asignado_nombre: string | null;
    estado?: string;
  } | null>(reanudar?.bloqueoCompras ?? null);
  const [showInterPaso, setShowInterPaso] = useState(false);
  const [interPasoIdx, setInterPasoIdx] = useState<number | null>(null);
  const [interForm, setInterForm] = useState({ titulo: "", descripcion: "", asignado_a: "" });
  const [creandoInter, setCreandoInter] = useState(false);
  const pasosWizardRef = useRef<HTMLDivElement>(null);

  usePegarCapturaEnZona(fase === "pasos", pasosWizardRef, setPasoFoto);

  const inicioRef = useRef<number | null>(null);
  const [segBase, setSegBase] = useState(0);
  const [segLive, setSegLive] = useState(0);
  const [cronometroActivo, setCronometroActivo] = useState(false);
  const [corridaPausada, setCorridaPausada] = useState(false);
  const corridaIdRef = useRef<number | null>(null);

  const maxProgreso = conCompras ? 5 : 4;
  const progresoActual = indiceProgresoWizard(fase, conCompras);
  const segDisplay = segBase + segLive;
  const itemsCompraOk = listaCompras.filter((m) => m.n.trim());
  const todosComprados = itemsCompraOk.length > 0 && itemsCompraOk.every((m) => m.comprado);

  useEffect(() => {
    const iv = setInterval(() => {
      if (inicioRef.current == null) return;
      const s = Math.floor((Date.now() - inicioRef.current) / 1000);
      setSegLive((p) => (p === s ? p : s));
    }, 250);
    return () => clearInterval(iv);
  }, []);

  useEffect(() => {
    return () => {
      if (facturaPreview) URL.revokeObjectURL(facturaPreview);
      if (cierrePreview) URL.revokeObjectURL(cierrePreview);
    };
  }, [facturaPreview, cierrePreview]);

  useEffect(() => {
    if (!["compras_lista", "pasos"].includes(fase) || usuariosDelegar.length > 0) return;
    tapi("/usuarios", token)
      .then((data) => setUsuariosDelegar(Array.isArray(data) ? data : []))
      .catch(() => setUsuariosDelegar([]));
  }, [fase, token, usuariosDelegar.length]);

  const refrescarBloqueoCompras = useCallback(async (tid?: number) => {
    const id = tid ?? ticketId;
    if (!id) return;
    try {
      const data = await tapi(`/${id}/bloqueo-compras`, token) as {
        bloqueo: typeof bloqueoCompras;
      };
      setBloqueoCompras(data.bloqueo ?? null);
    } catch {
      setBloqueoCompras(null);
    }
  }, [ticketId, token]);

  useEffect(() => {
    if (!ticketId) return;
    void refrescarBloqueoCompras(ticketId);
    const iv = setInterval(() => void refrescarBloqueoCompras(ticketId), 8000);
    return () => clearInterval(iv);
  }, [ticketId, refrescarBloqueoCompras]);

  useEffect(() => {
    if (!reanudar) return;
    const t = reanudar.ticket;
    setBloqueoCompras(reanudar.bloqueoCompras);
    setBloqueadoIntervencion(reanudar.bloqueadoIntervencion ?? null);
    if (t.corrida) {
      corridaIdRef.current = t.corrida.id ?? null;
      setSegBase(t.corrida.segundos_acumulados ?? t.segundos_trabajo ?? 0);
      if (t.corrida.estado === "activa" && (t.corrida.reanudada_en || t.corrida.iniciada_en)) {
        const srvTs = parseUtcTs(t.corrida.reanudada_en || t.corrida.iniciada_en!);
        inicioRef.current = srvTs;
        _timerStore.set(reanudar.ticketId, srvTs);
        setCronometroActivo(true);
        setSegLive(Math.max(0, Math.floor((Date.now() - srvTs) / 1000)));
      } else {
        inicioRef.current = null;
        _timerStore.delete(reanudar.ticketId);
        setCronometroActivo(false);
        setCorridaPausada(t.corrida.estado === "pausada");
        setSegLive(0);
      }
    } else if ((t.segundos_trabajo ?? 0) > 0) {
      setSegBase(t.segundos_trabajo ?? 0);
    }
    if (reanudar.bloqueoCompras) setConCompras(true);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function irFase(next: FaseAccionWizard) {
    const orden: FaseAccionWizard[] = ["titulo", "compras_lista", "compras_tienda", "pasos", "cierre"];
    const prev = orden.indexOf(fase);
    const nxt = orden.indexOf(next);
    setWizardDir(nxt >= prev ? "right" : "left");
    setFase(next);
    setError("");
  }

  async function asegurarTicketIniciado(): Promise<number> {
    if (ticketId) return ticketId;
    const ticket = await tapi("/", token, {
      method: "POST",
      body: JSON.stringify({
        titulo: titulo.trim(),
        descripcion: detalle.trim() || titulo.trim(),
        prioridad: "media",
        categoria: solicitudPadreId ? "logistica" : "logistica",
        asignado_a: user.id,
        tipo: "accion",
        ticket_padre_id: solicitudPadreId ?? undefined,
        protocolo_id: plantilla?.protocoloId,
      }),
    }) as Ticket;
    const tid = ticket.id;
    setTicketId(tid);
    return tid;
  }

  /** Inicia la corrida (cronómetro) solo cuando el usuario empieza a ejecutar la acción.
   *  Separado de asegurarTicketIniciado para no contar el tiempo de llenado del wizard. */
  async function iniciarCorridaSiNecesario(tid: number): Promise<void> {
    if (corridaIdRef.current) return;
    const t0 = Date.now();
    inicioRef.current = t0;
    setSegLive(0);
    setCronometroActivo(true);
    try {
      const data = await tapi(`/${tid}/corridas/iniciar`, token, {
        method: "POST",
        body: JSON.stringify({ segundos_previos: segBase }),
      }) as Ticket;
      if (data.corrida) {
        corridaIdRef.current = data.corrida.id ?? null;
        setSegBase(data.corrida.segundos_acumulados ?? 0);
        if (data.corrida.iniciada_en) {
          const srvTs = parseUtcTs(data.corrida.iniciada_en);
          if (srvTs < t0 && t0 - srvTs < 30_000) inicioRef.current = srvTs;
        }
      }
    } catch { /* cronómetro local sigue */ }
  }

  async function pausarCronometroWizard() {
    if (!corridaIdRef.current || corridaPausada) return;
    if (inicioRef.current != null) {
      const elapsed = Math.floor((Date.now() - inicioRef.current) / 1000);
      setSegBase((b) => b + elapsed);
      setSegLive(0);
      inicioRef.current = null;
    }
    setCronometroActivo(false);
    setCorridaPausada(true);
    try {
      await tapi(`/corridas/${corridaIdRef.current}/pausar`, token, { method: "POST" });
    } catch { /* pausa local aplicada igual */ }
  }

  async function reanudarCronometroWizard() {
    if (!corridaIdRef.current || !corridaPausada) return;
    const t0 = Date.now();
    inicioRef.current = t0;
    setCronometroActivo(true);
    setCorridaPausada(false);
    try {
      const data = await tapi(`/corridas/${corridaIdRef.current}/reanudar`, token, { method: "POST" }) as Ticket;
      if (data.corrida?.reanudada_en) {
        const srvTs = parseUtcTs(data.corrida.reanudada_en);
        if (srvTs <= Date.now() && Date.now() - srvTs < 30_000) {
          inicioRef.current = srvTs;
          setSegBase(data.corrida.segundos_acumulados ?? 0);
        }
      }
    } catch { /* reanudación local aplicada igual */ }
  }

  async function avanzarDesdeTitulo() {
    if (!titulo.trim()) return;
    setLoading(true);
    setError("");
    try {
      await asegurarTicketIniciado();
      irFase("compras_lista");
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "No se pudo iniciar la acción");
    } finally {
      setLoading(false);
    }
  }

  async function delegarListaCompras() {
    if (!delegarAId) {
      setError("Elige quién irá de compras");
      return;
    }
    const items = listaCompras.filter((m) => m.n.trim());
    if (items.length === 0) {
      setError("Agrega productos antes de delegar");
      return;
    }
    setLoading(true);
    setError("");
    setDelegacionMsg("");
    try {
      const tid = await asegurarTicketIniciado();
      const res = await tapi(`/${tid}/delegar-compras`, token, {
        method: "POST",
        body: JSON.stringify({ asignado_a: delegarAId, items }),
      }) as { solicitud?: Ticket; accion?: Ticket };
      const sol = res.solicitud;
      const nombre = usuariosDelegar.find((u) => u.id === delegarAId)?.nombre ?? "compañero";
      if (sol) {
        setDelegacionMsg(`Solicitud ${sol.numero} creada para ${nombre}`);
        setBloqueoCompras({
          solicitud_id: sol.id,
          numero: sol.numero,
          titulo: sol.titulo,
          asignado_nombre: nombre,
          estado: sol.estado,
        });
      } else {
        setDelegacionMsg(`Lista enviada a ${nombre}`);
      }
      setDelegarAId("");
      void refrescarBloqueoCompras(tid);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "No se pudo delegar la lista");
    } finally {
      setLoading(false);
    }
  }

  function pantallaEsperaCompras() {
    if (!bloqueoCompras) return null;
    return (
      <div className="rounded-2xl border-2 border-accent/60 bg-accent/80  p-4 space-y-3">
        <p className="text-sm font-extrabold text-accent">
          Esperando compras delegadas
        </p>
        <p className="text-sm text-accent/90">
          <strong>{bloqueoCompras.asignado_nombre ?? "Tu compañero"}</strong> está con la lista
          ({bloqueoCompras.numero}). Cuando marque <em>Terminé las compras</em>, podrás continuar.
        </p>
        <p className="text-xs text-muted font-mono">{bloqueoCompras.titulo}</p>
        <button
          type="button"
          disabled={loading}
          onClick={() => void refrescarBloqueoCompras()}
          className="w-full rounded-xl border border-accent/50 py-2 text-xs font-bold text-accent"
        >
          Actualizar estado
        </button>
      </div>
    );
  }

  async function pedirIntervencionPaso() {
    if (!interForm.titulo.trim() || !interForm.asignado_a) return;
    const paso = interPasoIdx != null ? pasosGuardados[interPasoIdx] : null;
    setCreandoInter(true);
    setError("");
    try {
      const tid = ticketId ?? await asegurarTicketIniciado();
      const desc = paso
        ? `${interForm.descripcion}\n\n[Paso: ${paso.nombre}]`
        : interForm.descripcion;
      await tapi(`/${tid}/pedir-intervencion`, token, {
        method: "POST",
        body: JSON.stringify({
          titulo: interForm.titulo.trim(),
          descripcion: desc.trim(),
          asignado_a: Number(interForm.asignado_a),
        }),
      });
      setShowInterPaso(false);
      setInterForm({ titulo: "", descripcion: "", asignado_a: "" });
      setInterPasoIdx(null);
      await refrescarBloqueoCompras(tid);
      setError("");
      setDelegacionMsg("Intervención solicitada — la acción queda en pausa hasta que respondan");
      setTimeout(() => setDelegacionMsg(""), 4000);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Error al pedir intervención");
    } finally {
      setCreandoInter(false);
    }
  }

  async function terminarListaCompras() {
    if (bloqueoCompras) {
      setError("Hay compras delegadas pendientes. Espera a que terminen o continúa sin ir tú.");
      return;
    }
    const items = listaCompras.filter((m) => m.n.trim());
    if (items.length === 0) {
      setError("Agrega al menos un producto a la lista");
      return;
    }
    setLoading(true);
    setError("");
    try {
      const tid = await asegurarTicketIniciado();
      const pasos = await tapi(`/${tid}/pasos`, token, {
        method: "POST",
        body: JSON.stringify({
          descripcion: "Ir de compras",
          notas: notasListaCompras(items),
        }),
      }) as { id: number; descripcion: string }[];
      const pasoCompras = Array.isArray(pasos)
        ? pasos.find((p) => p.descripcion === "Ir de compras")
        : null;
      setPasoComprasId(pasoCompras?.id ?? (Array.isArray(pasos) && pasos.length ? pasos[pasos.length - 1].id : null));
      setListaCompras(items.map((m) => ({ ...m, comprado: false })));
      setConCompras(true);
      irFase("compras_tienda");
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Error al guardar la lista");
    } finally {
      setLoading(false);
    }
  }

  async function termineCompras() {
    if (!todosComprados) {
      setError("Marca todos los productos de la lista antes de continuar");
      return;
    }
    setLoading(true);
    setError("");
    try {
      const tid = ticketId ?? await asegurarTicketIniciado();
      if (facturaFile) {
        const fd = new FormData();
        fd.append("archivo", facturaFile);
        await tapi(`/${tid}/adjuntos`, token, { method: "POST", body: fd });
      }
      if (pasoComprasId) {
        await tapi(`/${tid}/pasos/${pasoComprasId}`, token, {
          method: "PUT",
          body: JSON.stringify({ completado: 1 }),
        });
      }
      await tapi(`/${tid}/comentarios`, token, {
        method: "POST",
        body: JSON.stringify({
          texto: facturaFile
            ? "✅ Compras terminadas — factura adjunta."
            : "✅ Compras terminadas.",
          es_interno: false,
        }),
      }).catch(() => {});
      await iniciarCorridaSiNecesario(tid); // El timer arranca al empezar la ejecución
      irFase("pasos");
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Error al cerrar compras");
    } finally {
      setLoading(false);
    }
  }

  async function saltarCompras() {
    setLoading(true);
    try {
      const tid = await asegurarTicketIniciado();
      await iniciarCorridaSiNecesario(tid); // El timer arranca al empezar la ejecución
      irFase("pasos");
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Error al continuar");
    } finally {
      setLoading(false);
    }
  }

  function iniciarEditarPaso(idx: number) {
    const p = pasosGuardados[idx];
    setPasoNombre(p.nombre);
    setPasoDesc(p.desc);
    setPasoFoto(p.foto ?? null);
    setEditandoPasoIdx(idx);
  }

  function cancelarEdicionPaso() {
    setPasoNombre("");
    setPasoDesc("");
    setPasoFoto(null);
    setEditandoPasoIdx(null);
  }

  async function guardarPasoEnLista(soloGuardar: boolean) {
    if (!pasoNombre.trim()) {
      setError("Escribe o dicta qué harás en este paso");
      return;
    }
    setError("");
    const p: PasoAccionDraft = { nombre: pasoNombre.trim(), desc: pasoDesc.trim(), foto: pasoFoto };
    const fotoASubir = pasoFoto;
    if (editandoPasoIdx !== null) {
      setPasosGuardados((ps) => ps.map((x, i) => (i === editandoPasoIdx ? p : x)));
      cancelarEdicionPaso();
    } else {
      setPasosGuardados((ps) => [...ps, p]);
      setPasoNombre("");
      setPasoDesc("");
      setPasoFoto(null);
    }
    if (!soloGuardar) {
      void finalizarConPasos(editandoPasoIdx !== null
        ? pasosGuardados.map((x, i) => (i === editandoPasoIdx ? p : x))
        : [...pasosGuardados, p]);
      return;
    }
    // Persistir paso en servidor inmediatamente para no perderlo si el móvil mata la app
    const tid = ticketId;
    if (!tid) return;
    try {
      setLoading(true);
      const nombre = p.nombre.trim();
      const res = await tapi(`/${tid}/pasos`, token, {
        method: "POST",
        body: JSON.stringify({
          descripcion: nombre,
          notas: p.desc.trim() || undefined,
        }),
      }) as { id?: number } | Paso[];
      const creado = Array.isArray(res) ? res.find((x) => x.descripcion?.trim() === nombre) : res;
      const pasoId: number | null = (creado as any)?.id ?? null;
      if (fotoASubir && pasoId) {
        const fd = new FormData();
        fd.append("archivo", fotoASubir);
        await fetch(`/api/tickets/${tid}/pasos/${pasoId}/adjuntos`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: fd,
        }).catch(() => {});
        // Limpiar foto local ya que está subida al servidor
        setPasosGuardados((ps) =>
          ps.map((x) => x.nombre === nombre && x.foto === fotoASubir ? { ...x, foto: null } : x),
        );
      }
    } catch { /* no crítico: el paso queda en estado local */ } finally {
      setLoading(false);
    }
  }

  async function finalizarConPasos(pasosEjec?: PasoAccionDraft[]) {
    setError("");
    const ejec = (pasosEjec ?? pasosGuardados).filter((p) => p.nombre.trim());
    if (ejec.length === 0) {
      setError("Agrega al menos un paso de ejecución");
      return;
    }
    setLoading(true);
    try {
      const tid = ticketId ?? await asegurarTicketIniciado();
      await iniciarCorridaSiNecesario(tid); // El timer arranca al registrar la ejecución
      const existentes = await tapi(`/${tid}/pasos`, token).catch(() => []) as Paso[];
      const nombresExistentes = new Map(
        (Array.isArray(existentes) ? existentes : [])
          .filter((p) => p.descripcion !== "Ir de compras")
          .map((p) => [p.descripcion.trim(), p.id as number]),
      );
      for (const p of ejec) {
        const nombre = p.nombre.trim();
        let pasoId: number | null = nombresExistentes.get(nombre) ?? null;
        if (!pasoId) {
          const res = await tapi(`/${tid}/pasos`, token, {
            method: "POST",
            body: JSON.stringify({
              descripcion: nombre,
              notas: p.desc.trim() || undefined,
            }),
          }) as { id?: number } | Paso[];
          const creado = Array.isArray(res) ? res.find((x) => x.descripcion?.trim() === nombre) : res;
          pasoId = (creado as any)?.id ?? null;
          if (pasoId) nombresExistentes.set(nombre, pasoId);
        }
        if (p.foto && pasoId) {
          try {
            const fd = new FormData();
            fd.append("archivo", p.foto);
            await fetch(`/api/tickets/${tid}/pasos/${pasoId}/adjuntos`, {
              method: "POST",
              headers: { Authorization: `Bearer ${token}` },
              body: fd,
            });
          } catch { /* no crítico */ }
        }
      }
      irFase("cierre");
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Error al registrar pasos");
    } finally {
      setLoading(false);
    }
  }

  async function completarAccionEnServidor(tid: number, itemsLista: ItemCompraAccion[]) {
    const payload = {
      reporte: reporteSolicitud.trim(),
      lista_compras: itemsLista,
      cerrar_solicitud: !!solicitudPadreId,
      guardar_como_procedimiento: guardarComoProcedimiento,
      alcance_procedimiento: alcanceProcedimiento,
    };
    const res = await fetch(`/api/tickets/${tid}/completar-accion`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
    });
    if (res.status === 404) {
      try {
        await tapi(`/${tid}/guardar-procedimiento`, token, {
          method: "POST",
          body: JSON.stringify({ lista_compras: itemsLista, alcance: alcanceProcedimiento }),
        });
      } catch { /* servidor antiguo sin procedimientos */ }
      if (solicitudPadreId && reporteSolicitud.trim()) {
        const nombre = user.nombre || "Operador";
        await tapi(`/${solicitudPadreId}/comentarios`, token, {
          method: "POST",
          body: JSON.stringify({
            texto: `📋 **Reporte de ejecución**\nPor: ${nombre}\n\n${reporteSolicitud.trim()}`,
            es_interno: false,
          }),
        });
      }
      await tapi(`/${tid}/estado`, token, {
        method: "PUT",
        body: JSON.stringify({ estado: "resuelto" }),
      });
      if (solicitudPadreId) {
        await tapi(`/${solicitudPadreId}/estado`, token, {
          method: "PUT",
          body: JSON.stringify({ estado: "resuelto" }),
        });
      }
      return;
    }
    let data: { error?: string };
    try {
      data = await res.json();
    } catch {
      if (!res.ok) throw new Error(`Error ${res.status}`);
      return;
    }
    if (!res.ok) throw new Error(data?.error || `Error ${res.status}`);
  }

  async function terminarAccion() {
    if (solicitudPadreId && !reporteSolicitud.trim()) {
      setError("Escribe el reporte para quien solicitó la acción");
      return;
    }
    setLoading(true);
    setError("");
    try {
      const tid = ticketId ?? await asegurarTicketIniciado();
      // Garantizar que hay corrida antes de finalizar (fallback si falló iniciarCorridaSiNecesario)
      await iniciarCorridaSiNecesario(tid);
      if (corridaIdRef.current) {
        try {
          await tapi(`/corridas/${corridaIdRef.current}/finalizar`, token, { method: "POST" });
        } catch { /* ignore */ }
      }
      if (cierreArchivo) {
        const fd = new FormData();
        fd.append("archivo", cierreArchivo);
        await tapi(`/${tid}/adjuntos`, token, { method: "POST", body: fd });
      }
      const itemsLista = listaCompras.filter((m) => m.n.trim());
      await completarAccionEnServidor(tid, itemsLista);
      onCreated(tid);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Error al terminar la acción");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    if (!plantilla) return;
    void asegurarTicketIniciado().catch(() => {});
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function finalizar() {
    const extra: PasoAccionDraft[] = pasoNombre.trim()
      ? [{ nombre: pasoNombre.trim(), desc: pasoDesc.trim(), foto: pasoFoto }]
      : [];
    await finalizarConPasos([...pasosGuardados, ...extra]);
  }

  async function cancelarWizard() {
    if (ticketId && !confirm("¿Cancelar? La acción iniciada seguirá en tu tablero como borrador.")) return;
    if (ticketId && corridaIdRef.current && !corridaPausada) {
      try {
        await tapi(`/corridas/${corridaIdRef.current}/pausar`, token, { method: "POST" });
      } catch { /* ignore */ }
    }
    onCancel();
  }

  function onArchivoSeleccionado(
    file: File | null,
    setFile: (f: File | null) => void,
    preview: string | null,
    setPreview: (u: string | null) => void,
  ) {
    if (preview) URL.revokeObjectURL(preview);
    setFile(file);
    if (file && file.type.startsWith("image/")) {
      setPreview(URL.createObjectURL(file));
    } else {
      setPreview(null);
    }
  }

  function handlePasteCierreArchivo(e: React.ClipboardEvent) {
    const file = clipboardPastedImageFile(e);
    if (file) onArchivoSeleccionado(file, setCierreArchivo, cierrePreview, setCierrePreview);
  }

  const slide = wizardDir === "right" ? "mck-slide-right" : "mck-slide-left";
  const cronometroVisible = fase !== "titulo" && (!!ticketId || cronometroActivo || segBase > 0);

  return (
    <div className="mx-auto w-full max-w-lg pb-10">
      <div className="mb-6 flex items-center justify-between">
        <button
          type="button"
          onClick={() => void cancelarWizard()}
          className="rounded-xl border-2 border-border px-3 py-2 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
        >
          ← Cancelar
        </button>
        <span className="text-xs font-bold uppercase tracking-widest text-muted">
          {reanudar ? "Continuar acción" : "Nueva acción"}
        </span>
      </div>

      {bloqueadoIntervencion && !bloqueoCompras && (
        <div className="mb-4 rounded-xl border border-accent/50 bg-accent/60  px-4 py-3 text-sm text-accent">
          Esperando intervención <strong>{bloqueadoIntervencion}</strong> antes de seguir.
        </div>
      )}

      <div className="mb-4 flex items-center gap-2">
        {Array.from({ length: maxProgreso }, (_, i) => i + 1).map((n) => (
          <div
            key={n}
            className={`h-2 flex-1 rounded-full transition-all ${n <= progresoActual ? "bg-accent" : "bg-border"}`}
          />
        ))}
      </div>

      {cronometroVisible && (
        <div className={`mb-4 flex items-center gap-3 rounded-2xl border-2 px-4 py-3 transition-colors ${
          corridaPausada
            ? "border-accent/50 bg-accent/80"
            : "border-accent/35 bg-accent/8"
        }`}>
          <span className="text-[10px] font-bold uppercase tracking-widest text-muted flex-1">
            {corridaPausada ? "En pausa" : "En proceso"}
          </span>
          <span className={`font-mono text-2xl font-extrabold tabular-nums ${
            corridaPausada ? "text-accent" : "text-accent"
          }`}>
            {fmtTiempo(segDisplay)}
          </span>
          {cronometroActivo && !corridaPausada && (
            <button
              type="button"
              onClick={() => void pausarCronometroWizard()}
              title="Pausar"
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border-2 border-accent/70 text-accent  transition hover:bg-accent/5  active:scale-95"
            >
              <Icon name="pause" size={18} weight="bold" />
            </button>
          )}
          {corridaPausada && (
            <button
              type="button"
              onClick={() => void reanudarCronometroWizard()}
              title="Reanudar"
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-accent text-white shadow-[0_2px_0_rgba(2,45,51,0.25)] transition hover:bg-accent-hover active:translate-y-0.5 active:shadow-none"
            >
              <Icon name="play" size={18} weight="bold" />
            </button>
          )}
        </div>
      )}

      <SttBanner stt={stt} />
      {error && (
        <p className="mb-4 rounded-xl border border-danger/30 bg-danger/10 px-4 py-3 text-sm text-danger">
          {error}
        </p>
      )}

      {fase === "titulo" && (
        <div key="acc-p1" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 1 de {maxProgreso}
            </p>
            <h2 className="text-3xl font-extrabold text-ink leading-tight">
              ¿Qué vas<br />a hacer?
            </h2>
            <p className="mt-2 text-sm text-muted">Nombre corto y, si quieres, más detalle de la acción.</p>
          </div>
          <div className="space-y-3">
            <div className="flex gap-2">
              <ProseInput
                autoFocus
                className="w-full flex-1 rounded-2xl border-2 border-border bg-surface-input px-5 py-4 text-xl font-semibold text-ink outline-none focus:border-accent placeholder:text-muted/50"
                placeholder="Ej: Preparar torta de zanahoria"
                value={titulo}
                onChange={(e) => setTitulo(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey && titulo.trim() && !loading) void avanzarDesdeTitulo();
                }}
                maxLength={150}
              />
              <SttInlineBtn
                stt={stt}
                onStart={() => void stt.iniciar((t) => setTitulo(proseText(t)))}
              />
            </div>
            <div className="flex gap-2 items-start">
              <ProseTextarea
                className="w-full flex-1 rounded-2xl border-2 border-border bg-surface-input px-5 py-3 text-sm text-ink outline-none focus:border-accent placeholder:text-muted/50 resize-none min-h-[100px]"
                placeholder="Detalle opcional: pasos, ingredientes, observaciones…"
                rows={4}
                value={detalle}
                onChange={(e) => setDetalle(e.target.value)}
              />
              <SttInlineBtn
                stt={stt}
                label="Detalle"
                onStart={() => void stt.iniciar((t) => setDetalle(proseText(t)))}
              />
            </div>
            <ProseHint />
          </div>
          <button
            type="button"
            disabled={!titulo.trim() || loading}
            onClick={() => void avanzarDesdeTitulo()}
            className="w-full rounded-2xl bg-accent py-4 text-lg font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            {loading ? "Iniciando…" : "Siguiente →"}
          </button>
        </div>
      )}

      {fase === "compras_lista" && (
        <div key="acc-p2" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 2 de {maxProgreso}
            </p>
            <h2 className="text-2xl font-extrabold text-ink leading-tight">Tu acción<br />ha comenzado</h2>
            <p className="mt-3 rounded-2xl border-2 border-accent/30 bg-accent/5 px-4 py-3 text-base font-bold text-ink">
              {titulo.trim()}
            </p>
          </div>

          {subCompras === "idle" && (
            <div className="space-y-3">
              <p className="text-sm text-muted">¿Necesitas conseguir ingredientes o materiales antes?</p>
              <button
                type="button"
                onClick={() => {
                  setConCompras(true);
                  setSubCompras("editando");
                  if (listaCompras.length === 0) setListaCompras([nuevoItemCompra()]);
                }}
                className="w-full flex items-center gap-4 rounded-2xl border-2 border-border bg-surface-panel px-5 py-4 text-left transition hover:border-accent/60"
              >
                <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-border bg-surface text-ink">
                  <TopicIcon value="🛒" size={22} />
                </span>
                <div>
                  <p className="text-base font-extrabold text-ink">Ir de compras</p>
                  <p className="text-xs text-muted">Arma la lista con gramos o unidades</p>
                </div>
              </button>
              <button
                type="button"
                disabled={loading}
                onClick={() => void saltarCompras()}
                className="w-full rounded-2xl border-2 border-border py-3.5 text-sm font-bold text-muted transition hover:border-accent hover:text-accent disabled:opacity-40"
              >
                Ya tengo todo · continuar →
              </button>
            </div>
          )}

          {subCompras === "editando" && (
            <div className="space-y-4 mck-slide-up">
              <p className="text-xs font-bold uppercase tracking-wide text-accent">Lista de compras</p>
              {listaCompras.map((m, mi) => (
                <div key={mi} className="flex flex-wrap gap-2 sm:flex-nowrap">
                  <input
                    className="min-w-0 flex-[2] rounded-xl border-2 border-border bg-surface-input px-3 py-2.5 text-sm text-ink outline-none focus:border-accent placeholder:text-muted/40"
                    placeholder="Producto"
                    value={m.n}
                    onChange={(e) => setListaCompras((ms) => ms.map((x, j) => (j === mi ? { ...x, n: e.target.value } : x)))}
                  />
                  <input
                    className="w-20 rounded-xl border-2 border-border bg-surface-input px-3 py-2.5 text-sm text-ink outline-none focus:border-accent placeholder:text-muted/40"
                    placeholder="Cant."
                    inputMode="decimal"
                    value={m.cantidad}
                    onChange={(e) => setListaCompras((ms) => ms.map((x, j) => (j === mi ? { ...x, cantidad: e.target.value } : x)))}
                  />
                  <select
                    className="w-[5.5rem] rounded-xl border-2 border-border bg-surface-input px-2 py-2.5 text-sm font-bold text-ink outline-none focus:border-accent"
                    value={m.unidad}
                    onChange={(e) => setListaCompras((ms) => ms.map((x, j) => (
                      j === mi ? { ...x, unidad: e.target.value as UnidadCompra } : x
                    )))}
                    aria-label="Unidad de medida"
                  >
                    <option value="g">g</option>
                    <option value="u">u</option>
                  </select>
                  <button
                    type="button"
                    onClick={() => setListaCompras((ms) => ms.filter((_, j) => j !== mi))}
                    className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border-2 border-border text-muted transition hover:border-danger hover:text-danger"
                  >
                    ✕
                  </button>
                </div>
              ))}
              <button
                type="button"
                onClick={() => setListaCompras((ms) => [...ms, nuevoItemCompra()])}
                className="flex items-center gap-1.5 rounded-xl border border-dashed border-border px-3 py-1.5 text-xs font-bold text-muted transition hover:border-accent hover:text-accent"
              >
                + Agregar producto
              </button>

              <div className="rounded-2xl border border-accent/30 bg-accent/30  p-3 space-y-2">
                <p className="text-xs font-bold text-ink">¿Alguien más va de compras?</p>
                <p className="text-[11px] text-muted">
                  Se crea una solicitud solo con este checklist para esa persona.
                </p>
                <select
                  className="quest-input w-full text-sm"
                  value={delegarAId}
                  onChange={(e) => setDelegarAId(e.target.value ? Number(e.target.value) : "")}
                >
                  <option value="">Elegir compañero…</option>
                  {usuariosDelegar
                    .filter((u) => u.id !== user.id && u.activo !== 0)
                    .map((u) => (
                      <option key={u.id} value={u.id}>{u.nombre}</option>
                    ))}
                </select>
                <button
                  type="button"
                  disabled={loading || !delegarAId || itemsCompraOk.length === 0}
                  onClick={() => void delegarListaCompras()}
                  className="w-full rounded-xl border-2 border-accent/50 py-2.5 text-sm font-bold text-accent  hover:bg-accent/10 disabled:opacity-40"
                >
                  Enviar lista a compañero
                </button>
                {delegacionMsg && (
                  <p className="text-xs font-semibold text-accent">{delegacionMsg}</p>
                )}
              </div>

              {bloqueoCompras && pantallaEsperaCompras()}

              {!bloqueoCompras && (
                <button
                  type="button"
                  disabled={loading || itemsCompraOk.length === 0}
                  onClick={() => void terminarListaCompras()}
                  className="w-full rounded-2xl bg-accent py-4 text-base font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
                >
                  {loading ? "Guardando…" : "Yo voy de compras →"}
                </button>
              )}
              {bloqueoCompras && (
                <button
                  type="button"
                  disabled={loading}
                  onClick={async () => {
                    setLoading(true);
                    try {
                      const tid = ticketId ?? await asegurarTicketIniciado();
                      const data = await tapi(`/${tid}/bloqueo-compras`, token) as {
                        bloqueo: typeof bloqueoCompras;
                      };
                      if (data.bloqueo) {
                        setBloqueoCompras(data.bloqueo);
                        setError("Aún esperando que terminen las compras delegadas");
                      } else {
                        setBloqueoCompras(null);
                        await iniciarCorridaSiNecesario(tid);
                        irFase("pasos");
                      }
                    } catch (e: unknown) {
                      setError(e instanceof Error ? e.message : "Error al verificar");
                    } finally {
                      setLoading(false);
                    }
                  }}
                  className="w-full rounded-2xl border-2 border-accent/50 py-3.5 text-sm font-bold text-accent"
                >
                  Compras delegadas — verificar y continuar →
                </button>
              )}
            </div>
          )}

          <button
            type="button"
            onClick={() => {
              if (subCompras === "editando") setSubCompras("idle");
              else irFase("titulo");
            }}
            className="w-full rounded-2xl border-2 border-border py-3 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
          >
            ← Atrás
          </button>
        </div>
      )}

      {fase === "compras_tienda" && (
        <div key="acc-p3-tienda" className={`space-y-5 ${slide}`}>
          {bloqueoCompras ? (
            <>
              {pantallaEsperaCompras()}
              <button
                type="button"
                disabled={loading}
                onClick={async () => {
                  setLoading(true);
                  try {
                    const tid = ticketId ?? await asegurarTicketIniciado();
                    const data = await tapi(`/${tid}/bloqueo-compras`, token) as {
                      bloqueo: typeof bloqueoCompras;
                    };
                    if (data.bloqueo) {
                      setBloqueoCompras(data.bloqueo);
                      setError("Aún esperando las compras delegadas");
                    } else {
                      setBloqueoCompras(null);
                      await iniciarCorridaSiNecesario(tid);
                      irFase("pasos");
                    }
                  } catch (e: unknown) {
                    setError(e instanceof Error ? e.message : "Error al verificar");
                  } finally {
                    setLoading(false);
                  }
                }}
                className="w-full rounded-2xl border-2 border-accent/50 py-3 text-sm font-bold text-accent"
              >
                Verificar si ya terminaron →
              </button>
            </>
          ) : (
          <>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 3 de {maxProgreso}
            </p>
            <h2 className="text-2xl font-extrabold text-ink leading-tight">En la tienda</h2>
            <p className="mt-1 text-sm text-muted">Marca cada producto al conseguirlo.</p>
          </div>

          <div className="space-y-2">
            {listaCompras.map((m, mi) => !m.n.trim() ? null : (
              <button
                key={mi}
                type="button"
                onClick={() => setListaCompras((ms) => ms.map((x, j) => (
                  j === mi ? { ...x, comprado: !x.comprado } : x
                )))}
                className={`w-full flex items-center gap-3 rounded-2xl border-2 px-4 py-3 text-left transition
                  ${m.comprado ? "border-accent bg-accent/10" : "border-border bg-surface-panel hover:border-accent/40"}`}
              >
                <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border-2 text-sm font-bold
                  ${m.comprado ? "border-accent bg-accent text-white" : "border-border text-muted"}`}>
                  {m.comprado ? "✓" : ""}
                </span>
                <div className="min-w-0 flex-1">
                  <p className={`text-sm font-bold ${m.comprado ? "text-accent line-through decoration-accent/50" : "text-ink"}`}>
                    {m.n.trim()}
                  </p>
                  {formatCantidadItem(m) && (
                    <p className="text-xs text-muted">{formatCantidadItem(m)}</p>
                  )}
                </div>
              </button>
            ))}
          </div>

          <div className="rounded-2xl border-2 border-dashed border-border bg-surface-panel p-4 space-y-3">
            <p className="text-xs font-bold uppercase tracking-wide text-muted">Factura de caja</p>
            <p className="text-xs text-muted">Foto o PDF del ticket al pagar (opcional antes de salir).</p>
            <label className="flex cursor-pointer flex-col items-center gap-2 rounded-xl border-2 border-border bg-surface-input px-4 py-6 transition hover:border-accent">
              <TopicIcon value="📷" size={28} className="text-muted" />
              <span className="text-sm font-bold text-accent">
                {facturaFile ? facturaFile.name : "Subir captura de factura"}
              </span>
              <input
                type="file"
                accept="image/*,.pdf,application/pdf"
                className="sr-only"
                onChange={(e) => onArchivoSeleccionado(
                  e.target.files?.[0] ?? null,
                  setFacturaFile,
                  facturaPreview,
                  setFacturaPreview,
                )}
              />
            </label>
            {facturaPreview && (
              <img src={facturaPreview} alt="Vista previa factura" className="max-h-40 w-full rounded-xl object-contain border border-border" />
            )}
          </div>

          <button
            type="button"
            disabled={loading || !todosComprados}
            onClick={() => void termineCompras()}
            className="w-full rounded-2xl bg-accent py-4 text-base font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            {loading ? "Guardando…" : "Terminé las compras →"}
          </button>
          {!todosComprados && itemsCompraOk.length > 0 && (
            <p className="text-center text-xs text-muted">
              Marca los {itemsCompraOk.length} productos de la lista
            </p>
          )}

          <button
            type="button"
            onClick={() => irFase("compras_lista")}
            className="w-full rounded-2xl border-2 border-border py-3 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
          >
            ← Editar lista
          </button>
          </>
          )}
        </div>
      )}

      {fase === "pasos" && (
        <div
          key="acc-p3"
          ref={pasosWizardRef}
          className={`space-y-5 ${slide}`}
          onPaste={(e) => manejarPasteCaptura(e, setPasoFoto)}
        >
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso {progresoActual} de {maxProgreso}
            </p>
            <h2 className="text-2xl font-extrabold text-ink leading-tight">
              Describe los pasos<br />de tu labor
            </h2>
            <p className="mt-1 text-sm text-muted">Texto, voz o Ctrl+V para pegar capturas en cada paso.</p>
          </div>

          {bloqueoCompras && pantallaEsperaCompras()}

          {pasosGuardados.length > 0 && (
            <div className="space-y-2">
              {pasosGuardados.map((p, i) => (
                <div
                  key={i}
                  className={`mck-slide-up flex items-center gap-3 rounded-2xl border-2 px-4 py-2.5 transition
                    ${editandoPasoIdx === i ? "border-accent bg-accent/8" : "border-border bg-surface-panel"}`}
                  style={{ animationDelay: `${i * 40}ms` }}
                >
                  <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-accent text-xs font-extrabold text-white">
                    {i + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-bold text-ink">{p.nombre}</p>
                    <div className="flex items-center gap-2">
                      {p.desc && (
                        <p className="truncate text-xs text-muted">
                          {p.desc.slice(0, 48)}{p.desc.length > 48 ? "…" : ""}
                        </p>
                      )}
                      {p.foto && <span className="text-xs text-accent shrink-0">📎</span>}
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => iniciarEditarPaso(i)}
                    className="shrink-0 rounded-lg border border-border px-2 py-1 text-[10px] font-bold text-muted transition hover:border-accent hover:text-accent"
                    title="Editar paso"
                  >
                    ✏️
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setInterPasoIdx(i);
                      setInterForm({
                        titulo: `Verificar: ${p.nombre}`,
                        descripcion: p.desc || "",
                        asignado_a: "",
                      });
                      setShowInterPaso(true);
                    }}
                    className="shrink-0 rounded-lg border border-accent/50 px-2 py-1 text-[10px] font-bold text-accent transition hover:bg-accent/5"
                    title="Pedir verificación a otro usuario"
                  >
                    🛑
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setPasosGuardados((ps) => ps.filter((_, j) => j !== i));
                      if (editandoPasoIdx === i) cancelarEdicionPaso();
                    }}
                    className="shrink-0 rounded-lg border border-border px-2 py-1 text-[10px] font-bold text-muted transition hover:border-danger hover:text-danger"
                  >
                    ✕
                  </button>
                </div>
              ))}
            </div>
          )}

          {showInterPaso && (
            <div className="rounded-2xl border border-accent/50 bg-accent/50  p-4 space-y-3">
              <p className="text-sm font-bold text-accent">
                Pedir verificación{interPasoIdx != null ? ` — paso ${interPasoIdx + 1}` : ""}
              </p>
              <ProseInput
                className="quest-input w-full text-sm"
                placeholder="Título de la intervención"
                value={interForm.titulo}
                onChange={(e) => setInterForm((f) => ({ ...f, titulo: e.target.value }))}
              />
              <ProseTextarea
                className="quest-input w-full resize-none text-sm"
                rows={2}
                placeholder="Qué debe verificar o hacer…"
                value={interForm.descripcion}
                onChange={(e) => setInterForm((f) => ({ ...f, descripcion: e.target.value }))}
              />
              <select
                className="quest-input w-full text-sm"
                value={interForm.asignado_a}
                onChange={(e) => setInterForm((f) => ({ ...f, asignado_a: e.target.value }))}
              >
                <option value="">Usuario que verifica…</option>
                {usuariosDelegar
                  .filter((u) => u.id !== user.id && u.activo !== 0)
                  .map((u) => (
                    <option key={u.id} value={u.id}>{u.nombre}</option>
                  ))}
              </select>
              <div className="flex gap-2">
                <button
                  type="button"
                  disabled={creandoInter || !interForm.titulo.trim() || !interForm.asignado_a}
                  onClick={() => void pedirIntervencionPaso()}
                  className="flex-1 rounded-xl bg-accent/50 py-2 text-sm font-bold text-white disabled:opacity-40"
                >
                  {creandoInter ? "Enviando…" : "Solicitar intervención"}
                </button>
                <button
                  type="button"
                  onClick={() => { setShowInterPaso(false); setInterPasoIdx(null); }}
                  className="rounded-xl border border-border px-3 py-2 text-sm text-muted"
                >
                  Cancelar
                </button>
              </div>
            </div>
          )}

          <div className="rounded-2xl border-2 border-accent/40 bg-surface-panel p-4 space-y-4">
            <p className="text-xs font-bold uppercase tracking-widest text-accent">
              {editandoPasoIdx !== null
                ? `Editando paso ${editandoPasoIdx + 1}`
                : `Paso ${pasosGuardados.length + 1}`}
            </p>
            <div>
              <label className="mb-1.5 block text-xs font-bold text-muted uppercase tracking-wide">
                ¿Qué haces en este paso?
              </label>
              <div className="flex gap-2">
                <ProseInput
                  autoFocus
                  className="w-full flex-1 rounded-xl border-2 border-border bg-surface-input px-4 py-3 text-base font-semibold text-ink outline-none focus:border-accent placeholder:text-muted/40"
                  placeholder="Ej: Mezclar harina y zanahoria"
                  value={pasoNombre}
                  maxLength={120}
                  onChange={(e) => setPasoNombre(e.target.value)}
                />
                <SttInlineBtn
                  stt={stt}
                  onStart={() => void stt.iniciar((t) => setPasoNombre(proseText(t)))}
                />
              </div>
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-bold text-muted uppercase tracking-wide">
                Detalle <span className="normal-case font-normal">(opcional)</span>
              </label>
              <div className="flex gap-2">
                <ProseTextarea
                  className="w-full flex-1 rounded-xl border-2 border-border bg-surface-input px-4 py-2.5 text-sm text-ink outline-none focus:border-accent resize-none placeholder:text-muted/40"
                  placeholder="Instrucciones, tiempos, temperatura…"
                  rows={2}
                  value={pasoDesc}
                  onChange={(e) => setPasoDesc(e.target.value)}
                />
                <SttInlineBtn
                  stt={stt}
                  label="Det."
                  onStart={() => void stt.iniciar((t) => setPasoDesc((d) => proseText(d ? `${d} ${t}` : t)))}
                />
              </div>
              <ProseHint className="mt-1" />
            </div>
            <div>
              <label className={`flex items-center gap-3 rounded-xl border-2 cursor-pointer px-4 py-2.5 transition
                ${pasoFoto ? "border-accent bg-accent/8" : "border-dashed border-border hover:border-accent/60"}`}>
                <span className="text-lg">{pasoFoto ? "📎" : "📷"}</span>
                <span className="text-sm font-semibold text-muted truncate">
                  {pasoFoto ? pasoFoto.name : "Adjuntar archivo o Ctrl+V para pegar captura"}
                </span>
                {pasoFoto && (
                  <button
                    type="button"
                    onClick={(e) => { e.preventDefault(); setPasoFoto(null); }}
                    className="ml-auto text-xs text-danger hover:underline shrink-0"
                  >
                    Quitar
                  </button>
                )}
                <input
                  type="file"
                  accept="image/*,.pdf,application/pdf,.doc,.docx"
                  className="sr-only"
                  onChange={(e) => setPasoFoto(e.target.files?.[0] ?? null)}
                />
              </label>
            </div>
            <div className="flex gap-2 pt-1">
              {editandoPasoIdx !== null && (
                <button
                  type="button"
                  onClick={cancelarEdicionPaso}
                  className="rounded-xl border-2 border-border px-3 py-2 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
                >
                  Cancelar
                </button>
              )}
              <button
                type="button"
                disabled={!pasoNombre.trim()}
                onClick={() => guardarPasoEnLista(true)}
                className="flex-1 rounded-xl border-2 border-accent/60 py-2.5 text-sm font-extrabold text-accent transition hover:bg-accent/10 disabled:opacity-40"
              >
                {editandoPasoIdx !== null ? "✓ Guardar cambios" : "✓ Guardar · agregar otro"}
              </button>
            </div>
          </div>

          {ticketId && (
            <NotaAccionInline
              ticketId={ticketId}
              token={token}
              initialValue={""}
            />
          )}

          <div className="flex gap-3">
            <button
              type="button"
              onClick={() => {
                cancelarEdicionPaso();
                irFase(conCompras ? "compras_tienda" : "compras_lista");
              }}
              className="rounded-2xl border-2 border-border px-4 py-3 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
            >
              ← Atrás
            </button>
            <button
              type="button"
              disabled={loading || (pasosGuardados.length === 0 && !pasoNombre.trim())}
              onClick={() => void finalizar()}
              className="flex-1 rounded-2xl bg-accent py-3 text-base font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
            >
              {loading ? "Guardando…" : "Continuar →"}
            </button>
          </div>
          {pasosGuardados.length === 0 && !pasoNombre.trim() && (
            <p className="text-center text-xs text-muted">Guarda al menos un paso antes de continuar</p>
          )}
        </div>
      )}

      {fase === "cierre" && (
        <div key="acc-cierre" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso {progresoActual} de {maxProgreso}
            </p>
            <h2 className="text-2xl font-extrabold text-ink leading-tight">Cerrar acción</h2>
            <p className="mt-2 text-sm text-muted">
              {solicitudPadreId
                ? "Envía el reporte a quien solicitó la tarea."
                : "Revisa los pasos y cierra la acción."}
            </p>
            <p className="mt-3 rounded-2xl border-2 border-accent/30 bg-accent/5 px-4 py-3 text-base font-bold text-ink">
              {titulo.trim()}
            </p>
          </div>

          {pasosGuardados.length > 0 && (
            <div className="rounded-2xl border border-border bg-surface-panel px-4 py-3 space-y-1">
              <p className="text-xs font-bold uppercase text-muted">Pasos registrados</p>
              {pasosGuardados.map((p, i) => (
                <p key={i} className="text-sm text-ink">
                  <span className="text-muted">{i + 1}.</span> {p.nombre}
                </p>
              ))}
            </div>
          )}

          {solicitudPadreId && (
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-wide text-accent">
                Reporte para el solicitante
              </label>
              <ProseTextarea
                className="w-full rounded-xl border-2 border-border bg-surface-input px-4 py-3 text-sm text-ink outline-none focus:border-accent resize-none"
                rows={4}
                placeholder="Qué hiciste, resultados, observaciones…"
                value={reporteSolicitud}
                onChange={(e) => setReporteSolicitud(e.target.value)}
              />
              <ProseHint />
            </div>
          )}

          <div
            className="rounded-2xl border-2 border-dashed border-border bg-surface-panel p-4 space-y-3"
            onPasteCapture={handlePasteCierreArchivo}
          >
            <p className="text-xs font-bold uppercase tracking-wide text-muted">Adjunto opcional</p>
            <p className="text-xs text-muted">Foto o imagen de referencia (resultado, comprobante, etc.). Pegue con Ctrl+V.</p>
            <label className="flex cursor-pointer flex-col items-center gap-2 rounded-xl border-2 border-border bg-surface-input px-4 py-6 transition hover:border-accent">
              <TopicIcon value="📎" size={28} className="text-muted" />
              <span className="text-sm font-bold text-accent">
                {cierreArchivo ? cierreArchivo.name : "Adjuntar captura o imagen (Ctrl+V)"}
              </span>
              <input
                type="file"
                accept="image/*,.pdf,application/pdf"
                className="sr-only"
                onChange={(e) => onArchivoSeleccionado(
                  e.target.files?.[0] ?? null,
                  setCierreArchivo,
                  cierrePreview,
                  setCierrePreview,
                )}
              />
            </label>
            {cierrePreview && (
              <img
                src={cierrePreview}
                alt="Vista previa adjunto"
                className="max-h-40 w-full rounded-xl object-contain border border-border"
              />
            )}
          </div>

          <button
            type="button"
            onClick={() => setGuardarComoProcedimiento((v) => !v)}
            className={`w-full flex items-center gap-3 rounded-2xl border-2 px-4 py-3 text-left transition ${
              guardarComoProcedimiento
                ? "border-accent bg-accent/8 text-accent"
                : "border-border text-muted hover:border-accent/60"
            }`}
          >
            <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded border-2 text-xs font-black transition ${
              guardarComoProcedimiento ? "border-accent bg-accent text-white" : "border-border"
            }`}>{guardarComoProcedimiento ? "✓" : ""}</span>
            <div>
              <p className="text-sm font-semibold">Guardar como procedimiento</p>
              <p className="text-xs text-muted">Quedará en «Mis procedimientos» para reutilizar</p>
            </div>
          </button>

          {guardarComoProcedimiento && (
            <div className="flex gap-2 rounded-2xl border-2 border-accent/30 bg-accent/5 p-1">
              <button
                type="button"
                onClick={() => setAlcanceProcedimiento("personal")}
                className={`flex-1 rounded-xl py-2.5 text-xs font-bold transition ${
                  alcanceProcedimiento === "personal"
                    ? "bg-accent text-white shadow"
                    : "text-muted hover:text-ink"
                }`}
              >
                🔒 Solo para mí
              </button>
              <button
                type="button"
                onClick={() => setAlcanceProcedimiento("global")}
                className={`flex-1 rounded-xl py-2.5 text-xs font-bold transition ${
                  alcanceProcedimiento === "global"
                    ? "bg-accent text-white shadow"
                    : "text-muted hover:text-ink"
                }`}
              >
                🌐 Compartir con el equipo
              </button>
            </div>
          )}

          <button
            type="button"
            disabled={loading}
            onClick={() => void terminarAccion()}
            className="w-full rounded-2xl bg-accent py-4 text-lg font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            {loading ? "Guardando…" : "Terminar acción"}
          </button>

          <button
            type="button"
            onClick={() => irFase("pasos")}
            className="w-full rounded-2xl border-2 border-border py-3 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
          >
            ← Atrás
          </button>
        </div>
      )}
    </div>
  );
}

// ── ProtocolosView ────────────────────────────────────────────────────────────

function ProtocolosView({
  token, user, protocolos, loading, onRecargar, onUsarProtocolo,
}: {
  token: string;
  user: TicketsUser;
  protocolos: Protocolo[];
  loading: boolean;
  onRecargar: () => void;
  onUsarProtocolo: (p: Protocolo) => void;
}) {
  const [expandido, setExpandido] = useState<number | null>(null);
  const [delegarId, setDelegarId] = useState<number | null>(null);
  const [eliminandoId, setEliminandoId] = useState<number | null>(null);
  const [msg, setMsg] = useState("");

  async function eliminarProcedimiento(p: Protocolo) {
    if (!confirm(`¿Eliminar el procedimiento "${p.titulo}"?\n\nLas solicitudes ya delegadas no se borran.`)) return;
    setEliminandoId(p.id);
    setMsg("");
    try {
      await tapi(`/protocolos/${p.id}`, token, { method: "DELETE" });
      if (expandido === p.id) setExpandido(null);
      if (delegarId === p.id) setDelegarId(null);
      onRecargar();
      setMsg("✓ Procedimiento eliminado");
      setTimeout(() => setMsg(""), 4000);
    } catch (e: any) {
      setMsg(e.message ?? "No se pudo eliminar");
      setTimeout(() => setMsg(""), 4000);
    } finally {
      setEliminandoId(null);
    }
  }

  if (loading) return <div className="py-8 text-center text-sm text-muted">Cargando procedimientos…</div>;

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm font-semibold text-ink flex items-center gap-1">
            <TopicIconLabel value="📋" size={16} weight="bold">Procedimientos disponibles</TopicIconLabel>
            <InfoTooltip text="Procedimientos del equipo que puedes usar como plantilla al crear una solicitud. Para editarlos o crear nuevos, ve a Acciones → Procedimientos." />
          </p>
          <p className="text-xs text-muted mt-0.5">
            Para editar o crear procedimientos ve a <strong>Acciones → Procedimientos</strong>
          </p>
        </div>
        <button type="button" onClick={onRecargar} className="text-xs text-muted hover:text-accent transition-colors shrink-0">
          ↻ Actualizar
        </button>
      </div>
      {msg && <p className="text-xs text-accent">{msg}</p>}

      {protocolos.length === 0 && (
        <div className="py-12 text-center space-y-2">
          <TopicIcon value="📋" size={36} className="mx-auto text-muted" />
          <p className="text-sm text-muted">Aún no hay procedimientos compartidos con el equipo.</p>
        </div>
      )}

      <div className="space-y-2">
        {protocolos.map((p) => (
          <div key={p.id} className="rounded-xl border border-border bg-surface shadow-sm">
            <div className="flex items-start gap-2 p-3">
              <button
                type="button"
                onClick={() => setExpandido(expandido === p.id ? null : p.id)}
                className="min-w-0 flex-1 text-left"
              >
                <div className="flex items-center gap-2">
                  <TopicIcon value="📋" size={16} className="shrink-0 text-muted" />
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-semibold text-ink truncate">{p.titulo}</p>
                    <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5 mt-0.5">
                      {p.categoria && (
                        <span className="text-[10px] bg-accent/10 text-accent rounded-full px-2 py-0.5 font-medium">
                          {p.categoria}
                        </span>
                      )}
                      <span className="text-[10px] text-muted">{p.pasos.length} paso{p.pasos.length !== 1 ? "s" : ""}</span>
                      {p.creado_por_nombre && (
                        <span className="text-[10px] text-muted">por {p.creado_por_nombre}</span>
                      )}
                    </div>
                  </div>
                  <span className="text-muted text-xs shrink-0">{expandido === p.id ? "▲" : "▼"}</span>
                </div>
              </button>
              <div className="flex shrink-0 flex-col gap-1">
                {puedeEliminarProtocolo(user, p) && (
                  <button
                    type="button"
                    onClick={() => void eliminarProcedimiento(p)}
                    disabled={eliminandoId === p.id}
                    title="Eliminar procedimiento"
                    className="flex h-7 w-full items-center justify-center rounded-lg border border-border text-xs text-muted transition hover:border-danger hover:text-danger disabled:opacity-40"
                  >
                    {eliminandoId === p.id ? "…" : "✕"}
                  </button>
                )}
                <button
                  type="button"
                  onClick={() => onUsarProtocolo(p)}
                  title="Usar como plantilla en nueva solicitud"
                  className="rounded-lg border border-accent/40 px-3 py-1.5 text-xs font-bold text-accent hover:bg-accent/10 transition-colors"
                >
                  Usar
                </button>
                <button
                  type="button"
                  onClick={() => setDelegarId(delegarId === p.id ? null : p.id)}
                  title="Delegar a un aliado del equipo"
                  className={`rounded-lg border px-3 py-1.5 text-xs font-bold transition-colors ${
                    delegarId === p.id
                      ? "border-accent/50 bg-accent/15 text-accent"
                      : "border-accent/40 text-accent  hover:bg-accent/10"
                  }`}
                >
                  Delegar
                </button>
              </div>
            </div>

            {delegarId === p.id && (
              <div className="border-t border-border px-3 pb-3 pt-2">
                <DelegarProcedimientoPanel
                  protocolo={p}
                  token={token}
                  user={user}
                  onCancel={() => setDelegarId(null)}
                  onDelegado={(n) => {
                    setDelegarId(null);
                    setMsg(`✓ Delegado a ${n} aliado${n !== 1 ? "s" : ""} — ver Solicitudes → Por resolver`);
                    setTimeout(() => setMsg(""), 5000);
                  }}
                />
              </div>
            )}

            {expandido === p.id && (
              <div className="border-t border-border px-3 pb-3 pt-2 space-y-1.5">
                {p.descripcion && <p className="text-xs text-muted italic">{p.descripcion}</p>}
                {p.pasos.length === 0 && <p className="text-xs text-muted">Sin pasos definidos.</p>}
                {p.pasos.map((paso, idx) => (
                  <div key={idx} className="flex gap-2 items-start">
                    <span className="text-xs text-muted shrink-0 w-5 text-right">{idx + 1}.</span>
                    <div>
                      <p className="text-xs text-ink">{paso.descripcion}</p>
                      {paso.notas && <p className="text-[10px] text-muted">{paso.notas}</p>}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

// ── NuevaSolicitudWizard ──────────────────────────────────────────────────────

type FaseSolicWizard = "tipo" | "descripcion" | "compras" | "elegir_proc" | "asignados" | "confirmar";
type VarianteSolicitud = "nueva" | "etiqueta" | "compra" | "protocolo";

const PLANTILLA_SOLICITUD_ETIQUETAS =
  "Indica producto, presentación y cantidad de etiquetas que necesitas:\n\n• \n• \n";

interface CompraDraftSolicitud {
  nombre: string;
  cantidad: string;
  unidad: string;
}

interface ListaComprasOcrItem {
  nombre?: string;
  cantidad?: number | string;
  unidad?: string;
}

function mapUnidadOcrSolicitud(unidad?: string): string {
  const u = (unidad || "").trim().toLowerCase();
  if (!u) return "und";
  if (["un", "u", "pcs", "pc", "pieza", "piezas", "unidad", "unidades"].includes(u)) return "und";
  if (["gr", "grs", "gramo", "gramos"].includes(u)) return "g";
  if (["mililitro", "mililitros"].includes(u)) return "ml";
  if (["l", "lt", "lts", "litro", "litros"].includes(u)) return "L";
  if (["kilo", "kilos", "kilogramo", "kilogramos"].includes(u)) return "kg";
  return unidad!.trim() || "und";
}

function itemsDesdeOcrListaCompras(
  items: ListaComprasOcrItem[],
  modo: "compra" | "etiqueta" = "compra",
): CompraDraftSolicitud[] {
  const out: CompraDraftSolicitud[] = [];
  const seen = new Set<string>();
  for (const it of items) {
    const nombre = (it.nombre || "").trim();
    if (!nombre) continue;
    const key = nombre.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    const cantRaw = it.cantidad;
    const cantNum = typeof cantRaw === "number"
      ? cantRaw
      : parseFloat(String(cantRaw ?? "1").replace(",", "."));
    const cantOk = Number.isFinite(cantNum) && cantNum > 0 ? cantNum : 1;
    if (modo === "etiqueta") {
      out.push({
        nombre,
        cantidad: String(Math.max(1, Math.round(cantOk))),
        unidad: "u",
      });
    } else {
      out.push({
        nombre,
        cantidad: String(cantOk),
        unidad: mapUnidadOcrSolicitud(it.unidad),
      });
    }
  }
  return out;
}

function esBootEtiquetas(tituloInicial: string, descripcionInicial: string): boolean {
  if (/etiqueta/i.test(tituloInicial)) return true;
  return descripcionInicial.trim().length > 0 && /•|producto|presentaci/i.test(descripcionInicial);
}

function NuevaSolicitudWizard({
  token,
  user,
  protocolos,
  usuarios,
  tituloInicial = "",
  descripcionInicial = "",
  onCancel,
  onCreated,
}: {
  token: string;
  user: TicketsUser;
  protocolos: Protocolo[];
  usuarios: UserInfo[];
  tituloInicial?: string;
  descripcionInicial?: string;
  onCancel: () => void;
  onCreated: (meta?: { subtipo?: string }) => void;
}) {
  const bootEtiqueta = esBootEtiquetas(tituloInicial, descripcionInicial);
  const bootEtiquetaDraft = bootEtiqueta && descripcionInicial.trim()
    ? parseLineasPedidoEtiqueta(descripcionInicial).map((l) => ({
        nombre: l.label,
        cantidad: String(l.cantidad || 1),
        unidad: "u",
      }))
    : [];
  const { apiToken: chatApiToken } = useTicketsAuth();
  const stt = useStt(token, chatApiToken);
  const [fase, setFase] = useState<FaseSolicWizard>(
    descripcionInicial.trim() ? "asignados" : "tipo",
  );
  const [wizardDir, setWizardDir] = useState<"right" | "left">("right");
  const [variante, setVariante] = useState<VarianteSolicitud | null>(
    descripcionInicial.trim() ? (bootEtiqueta ? "etiqueta" : "nueva") : null,
  );
  const [titulo, setTitulo] = useState(
    tituloInicial || (bootEtiqueta ? "Pedido de etiquetas" : ""),
  );
  const [descripcion, setDescripcion] = useState(descripcionInicial);
  const [listaComprasDraft, setListaComprasDraft] = useState<CompraDraftSolicitud[]>(bootEtiquetaDraft);
  const [compraNombre, setCompraNombre] = useState("");
  const [compraCantidad, setCompraCantidad] = useState("1");
  const [compraUnidad, setCompraUnidad] = useState("und");
  const [protocoloId, setProtocoloId] = useState<number | null>(null);
  const [asignados, setAsignados] = useState<number[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [adjuntoFile, setAdjuntoFile] = useState<File | null>(null);
  const [ocrLoading, setOcrLoading] = useState(false);
  const [ocrMsg, setOcrMsg] = useState("");
  const comprasZoneRef = useRef<HTMLDivElement>(null);
  const ocrAbortRef = useRef(0);

  const otrosUsuarios = usuarios.filter((u) => u.id !== user.id && u.activo);
  const protDisp = protocolos.filter((p) => p.alcance === "global" || !p.alcance || p.alcance === "seleccionado");
  const protSel = protDisp.find((p) => p.id === protocoloId) ?? null;

  const pasoActual = fase === "tipo" ? 1
    : (fase === "descripcion" || fase === "compras" || fase === "elegir_proc") ? 2
    : fase === "asignados" ? 3 : 4;
  const totalPasos = 4;
  const slide = wizardDir === "right" ? "mck-slide-right" : "mck-slide-left";

  function faseAnterior(): FaseSolicWizard {
    if (fase === "descripcion" || fase === "compras" || fase === "elegir_proc") return "tipo";
    if (fase === "asignados") {
      if (variante === "compra" || variante === "etiqueta") return "compras";
      if (variante === "protocolo") return "elegir_proc";
      return "descripcion";
    }
    if (fase === "confirmar") return "asignados";
    return "tipo";
  }

  function irFase(next: FaseSolicWizard, dir: "right" | "left" = "right") {
    setWizardDir(dir);
    setFase(next);
    setError("");
  }

  function elegirVariante(v: VarianteSolicitud) {
    setVariante(v);
    setProtocoloId(null);
    setAdjuntoFile(null);
    setOcrMsg("");
    setOcrLoading(false);
    ocrAbortRef.current += 1;
    if (v === "nueva") {
      setTitulo("");
      setDescripcion("");
      irFase("descripcion");
    } else if (v === "etiqueta") {
      setTitulo("Pedido de etiquetas");
      setDescripcion("");
      setListaComprasDraft([]);
      irFase("compras");
    } else if (v === "compra") {
      setTitulo("Solicitud de compras");
      setDescripcion("");
      setListaComprasDraft([]);
      irFase("compras");
    } else {
      irFase("elegir_proc");
    }
  }

  function agregarItemCompra() {
    const nombre = compraNombre.trim();
    if (!nombre) return;
    setListaComprasDraft((prev) => [
      ...prev,
      { nombre, cantidad: compraCantidad.trim() || "1", unidad: compraUnidad.trim() || "und" },
    ]);
    setCompraNombre("");
    setCompraCantidad("1");
    setCompraUnidad("und");
  }

  function quitarItemCompra(idx: number) {
    setListaComprasDraft((prev) => prev.filter((_, i) => i !== idx));
  }

  function toggleAsignado(uid: number) {
    setAsignados((prev) =>
      prev.includes(uid) ? prev.filter((id) => id !== uid) : [...prev, uid],
    );
  }

  function handlePasteAdjunto(e: React.ClipboardEvent) {
    const file = clipboardPastedImageFile(e);
    if (!file) return;
    if (fase === "compras" && (variante === "compra" || variante === "etiqueta")) {
      void recibirAdjuntoLista(file);
      return;
    }
    setAdjuntoFile(normalizarImagenPegada(file));
  }

  async function recibirAdjuntoLista(file: File) {
    const modoOcr: "compra" | "etiqueta" = variante === "etiqueta" ? "etiqueta" : "compra";
    const norm = normalizarImagenPegada(file);
    setAdjuntoFile(norm);
    setOcrMsg("");
    const esImagen =
      norm.type.startsWith("image/")
      || /\.(png|jpe?g|gif|webp|bmp)$/i.test(norm.name)
      || norm.type === "application/pdf"
      || /\.pdf$/i.test(norm.name);
    if (!esImagen) return;

    const gen = ++ocrAbortRef.current;
    setOcrLoading(true);
    try {
      const fd = new FormData();
      fd.append("imagen", norm);
      fd.append("modo", modoOcr);
      const json = await api.upload<{
        items?: ListaComprasOcrItem[];
        error?: string;
      }>("/api/tickets/extraer-lista-compras", fd);
      if (gen !== ocrAbortRef.current) return;
      const nuevos = itemsDesdeOcrListaCompras(json.items || [], modoOcr);
      if (!nuevos.length) {
        setOcrMsg(
          json.error
            || (modoOcr === "etiqueta"
              ? "No se detectaron etiquetas. Agrégalas a mano."
              : "No se detectaron productos. Agrégalos a mano."),
        );
        return;
      }
      setListaComprasDraft((prev) => {
        const existing = new Set(prev.map((p) => p.nombre.trim().toLowerCase()));
        const add = nuevos.filter((n) => !existing.has(n.nombre.trim().toLowerCase()));
        return [...prev, ...add];
      });
      const noun = modoOcr === "etiqueta" ? "etiqueta(s)" : "producto(s)";
      setOcrMsg(`Se extrajeron ${nuevos.length} ${noun}. Revisa la lista antes de continuar.`);
    } catch (e: unknown) {
      if (gen !== ocrAbortRef.current) return;
      setOcrMsg(e instanceof Error ? e.message : "No se pudo leer la imagen");
    } finally {
      if (gen === ocrAbortRef.current) setOcrLoading(false);
    }
  }

  usePegarCapturaEnZona(
    fase === "compras" && (variante === "compra" || variante === "etiqueta"),
    comprasZoneRef,
    (file) => { void recibirAdjuntoLista(file); },
  );

  async function crear() {
    const desc = descripcion.trim();
    const esCompra = variante === "compra";
    const esEtiquetaVar = variante === "etiqueta";
    if (esCompra || esEtiquetaVar) {
      if (listaComprasDraft.length === 0 || asignados.length === 0) return;
    } else if (!desc || asignados.length === 0) {
      return;
    }
    let tituloFinal = (titulo.trim() || desc.split(/\n/)[0]?.trim() || desc).slice(0, 150);
    if (esEtiquetaVar && !titulo.trim()) tituloFinal = "Pedido de etiquetas";
    if (esCompra) {
      const resumen = listaComprasDraft.map((i) => i.nombre).join(", ");
      tituloFinal = (`Compras: ${resumen}`).slice(0, 150);
    }
    if (esEtiquetaVar) {
      const resumen = listaComprasDraft.map((i) => i.nombre).join(", ");
      tituloFinal = resumen ? (`Etiquetas: ${resumen}`).slice(0, 150) : "Pedido de etiquetas";
    }
    const descripcionFinal = (esCompra || esEtiquetaVar)
      ? listaComprasDraft.map((i) => {
          if (esCompra) return `• ${i.nombre} — ${i.cantidad} ${i.unidad}`;
          return lineaDescripcionEtiqueta(i.nombre, parseFloat(i.cantidad) || 1);
        }).join("\n")
      : desc;
    const subtipo = esEtiquetaVar ? "etiqueta" : esCompra ? "compra" : undefined;
    if (ocrLoading) return;
    setLoading(true);
    setError("");
    try {
      const tickets = await Promise.all(
        asignados.map((uid) =>
          tapi("/", token, {
            method: "POST",
            body: JSON.stringify({
              titulo: tituloFinal,
              descripcion: descripcionFinal,
              categoria: "logistica",
              prioridad: "media",
              asignado_a: uid,
              tipo: "solicitud",
              subtipo,
              pasos: undefined,
              protocolo_id: protocoloId ?? undefined,
            }),
          }),
        ),
      ) as { id: number }[];
      if (esCompra || esEtiquetaVar) {
        await Promise.all(
          tickets.flatMap((t) =>
            listaComprasDraft.map((item) =>
              tapi(`/${t.id}/lista-compras`, token, {
                method: "POST",
                body: JSON.stringify({
                  nombre: item.nombre,
                  cantidad: parseFloat(item.cantidad) || 1,
                  unidad: esCompra ? (item.unidad || "und") : "u",
                }),
              }),
            ),
          ),
        );
      }
      if (adjuntoFile) {
        await Promise.all(tickets.map(async (t) => {
          const fd = new FormData();
          fd.append("archivo", adjuntoFile);
          await fetch(`/api/tickets/${t.id}/adjuntos`, {
            method: "POST",
            headers: { Authorization: `Bearer ${token}` },
            body: fd,
          });
        }));
      }
      onCreated(variante === "etiqueta" ? { subtipo: "etiqueta" } : variante === "compra" ? { subtipo: "compra" } : undefined);
    } catch (e: any) {
      setError(e.message ?? "Error al crear la solicitud");
      setLoading(false);
    }
  }

  return (
    <div className="mx-auto w-full max-w-lg pb-10">
      {/* Header */}
      <div className="mb-6 flex items-center justify-between">
        <button
          type="button"
          onClick={fase === "tipo" ? onCancel : () => irFase(faseAnterior(), "left")}
          className="rounded-xl border-2 border-border px-3 py-2 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
        >
          {fase === "tipo" ? "✕ Cancelar" : "← Atrás"}
        </button>
        <span className="text-xs font-bold uppercase tracking-widest text-muted">
          Nueva solicitud
        </span>
      </div>

      {/* Barra de progreso */}
      <div className="mb-6 flex items-center gap-2">
        {Array.from({ length: totalPasos }, (_, i) => i + 1).map((n) => (
          <div
            key={n}
            className={`h-2 flex-1 rounded-full transition-all ${n <= pasoActual ? "bg-accent" : "bg-border"}`}
          />
        ))}
      </div>

      <SttBanner stt={stt} />
      {error && (
        <p className="mb-4 rounded-xl border border-danger/30 bg-danger/10 px-4 py-3 text-sm text-danger">
          {error}
        </p>
      )}

      {/* Paso 1: Tipo */}
      {fase === "tipo" && (
        <div key="sol-p1" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 1 de {totalPasos}
            </p>
            <h2 className="text-3xl font-extrabold text-ink leading-tight">
              ¿Qué quieres<br />hacer?
            </h2>
            <p className="mt-2 text-sm text-muted">Elige cómo quieres enviar esta solicitud.</p>
          </div>
          <div className="space-y-3">
            <button
              type="button"
              onClick={() => elegirVariante("etiqueta")}
              className="w-full text-left rounded-2xl border-2 border-border bg-surface px-5 py-5 transition hover:border-accent hover:bg-accent/5 group"
            >
              <p className="text-lg font-extrabold text-ink group-hover:text-accent transition-colors">
                🏷️ Solicitud de etiquetas
              </p>
              <p className="mt-1 text-sm text-muted">
                Pedir impresión de etiquetas: producto, presentación y unidades.
              </p>
            </button>
            <button
              type="button"
              onClick={() => elegirVariante("compra")}
              className="w-full text-left rounded-2xl border-2 border-border bg-surface px-5 py-5 transition hover:border-accent hover:bg-accent/5 group"
            >
              <p className="text-lg font-extrabold text-ink group-hover:text-accent transition-colors">
                🛒 Solicitud de compras
              </p>
              <p className="mt-1 text-sm text-muted">
                Armar una lista de materiales o insumos para que alguien los compre.
              </p>
            </button>
            <button
              type="button"
              onClick={() => elegirVariante("nueva")}
              className="w-full text-left rounded-2xl border-2 border-border bg-surface px-5 py-5 transition hover:border-accent hover:bg-accent/5 group"
            >
              <p className="text-lg font-extrabold text-ink group-hover:text-accent transition-colors">
                ✍️ Nueva solicitud
              </p>
              <p className="mt-1 text-sm text-muted">
                Describir con tus palabras cualquier otra tarea que necesites delegar.
              </p>
            </button>
            {protDisp.length > 0 && (
              <button
                type="button"
                onClick={() => elegirVariante("protocolo")}
                className="w-full text-center rounded-xl border border-dashed border-border px-4 py-3 text-sm font-semibold text-muted transition hover:border-accent hover:text-accent"
              >
                📋 O delegar un procedimiento existente →
              </button>
            )}
          </div>
        </div>
      )}

      {/* Paso 2A: Descripción (solicitud nueva / etiquetas) */}
      {fase === "descripcion" && (
        <div key="sol-p2a" className={`space-y-6 ${slide}`} onPasteCapture={handlePasteAdjunto}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 2 de {totalPasos}
            </p>
            <h2 className="text-3xl font-extrabold text-ink leading-tight">
              {variante === "etiqueta"
                ? <>¿Qué etiquetas<br />necesitas?</>
                : <>¿Qué quieres<br />que haga?</>}
            </h2>
            <p className="mt-2 text-sm text-muted">
              {variante === "etiqueta"
                ? "Lista cada producto con su presentación y cuántas etiquetas imprimir."
                : "Redacta la tarea con todos los detalles necesarios."}
            </p>
          </div>
          <div className="space-y-3">
            {variante === "etiqueta" && (
              <input
                type="text"
                value={titulo}
                onChange={(e) => setTitulo(e.target.value)}
                placeholder="Pedido de etiquetas"
                className="w-full rounded-2xl border-2 border-border bg-surface-input px-5 py-3 text-base font-bold text-ink outline-none focus:border-accent"
              />
            )}
            <div className="flex gap-2 items-start">
              <ProseTextarea
                autoFocus
                className="w-full flex-1 rounded-2xl border-2 border-border bg-surface-input px-5 py-4 text-base text-ink outline-none focus:border-accent placeholder:text-muted/50 resize-none min-h-[140px]"
                placeholder={variante === "etiqueta"
                  ? "• Elastina 30 ml × 50 u\n• Vitamina C 30 ml × 30 u\n• …"
                  : "Ej: Revisar el inventario de la bodega y enviarme un listado de lo que falta. Incluir referencias y cantidades."}
                rows={5}
                value={descripcion}
                onChange={(e) => setDescripcion(e.target.value)}
                onPaste={handlePasteAdjunto}
              />
              <SttInlineBtn
                stt={stt}
                label="Dictar"
                onStart={() => void stt.iniciar((t) => setDescripcion(proseText(t)))}
              />
            </div>
            <ProseHint />
            {variante !== "etiqueta" && (
            <label className={`flex items-center gap-3 rounded-2xl border-2 cursor-pointer px-4 py-3 transition
              ${adjuntoFile ? "border-accent bg-accent/8" : "border-dashed border-border hover:border-accent/60"}`}>
              <span className="text-xl">{adjuntoFile ? "📎" : "📷"}</span>
              <span className="text-sm font-semibold text-muted truncate">
                {adjuntoFile ? adjuntoFile.name : "Adjuntar foto o archivo (opcional) — Ctrl+V"}
              </span>
              {adjuntoFile && (
                <button
                  type="button"
                  onClick={(e) => { e.preventDefault(); setAdjuntoFile(null); }}
                  className="ml-auto text-xs text-danger hover:underline shrink-0"
                >
                  Quitar
                </button>
              )}
              <input
                type="file"
                accept="image/*,.pdf,application/pdf,.doc,.docx,.xls,.xlsx"
                className="sr-only"
                onChange={(e) => setAdjuntoFile(e.target.files?.[0] ?? null)}
              />
            </label>
            )}
          </div>
          <button
            type="button"
            disabled={!descripcion.trim()}
            onClick={() => {
              const d = descripcion.trim();
              if (variante !== "etiqueta") {
                setTitulo(d.split(/\n/)[0]?.trim().slice(0, 150) ?? d.slice(0, 150));
              } else if (!titulo.trim()) {
                setTitulo("Pedido de etiquetas");
              }
              irFase("asignados");
            }}
            className="w-full rounded-2xl bg-accent py-4 text-lg font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            Siguiente →
          </button>
        </div>
      )}

      {/* Paso 2B: Lista de ítems (compras / etiquetas) */}
      {fase === "compras" && (
        <div
          key="sol-p2c"
          ref={comprasZoneRef}
          className={`space-y-6 ${slide}`}
          onPasteCapture={(variante === "compra" || variante === "etiqueta") ? handlePasteAdjunto : undefined}
        >
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 2 de {totalPasos}
            </p>
            <h2 className="text-3xl font-extrabold text-ink leading-tight">
              {variante === "etiqueta"
                ? <>¿Qué etiquetas<br />necesitas?</>
                : <>¿Qué hay<br />que comprar?</>}
            </h2>
            <p className="mt-2 text-sm text-muted">
              {variante === "etiqueta"
                ? "Agrega a mano o pega/sube un pantallazo — la IA arma producto, presentación y unidades."
                : "Agrega productos a mano o pega/sube un pantallazo para extraer la lista."}
            </p>
          </div>
          {(variante === "compra" || variante === "etiqueta") && (
            <div className="space-y-2">
              <label className={`flex flex-col gap-2 rounded-2xl border-2 cursor-pointer px-4 py-4 transition
                ${ocrLoading
                  ? "border-accent/50 bg-accent/5"
                  : adjuntoFile
                    ? "border-accent bg-accent/8"
                    : "border-dashed border-border hover:border-accent/60"}`}>
                <div className="flex items-center gap-3">
                  <span className="text-xl">{ocrLoading ? "⏳" : adjuntoFile ? "📎" : "📷"}</span>
                  <span className="min-w-0 flex-1 text-sm font-semibold text-muted">
                    {ocrLoading
                      ? (variante === "etiqueta"
                        ? "Extrayendo etiquetas del pantallazo…"
                        : "Extrayendo productos del pantallazo…")
                      : adjuntoFile
                        ? adjuntoFile.name
                        : (variante === "etiqueta"
                          ? "Pegar (Ctrl+V) o subir foto/pantallazo — la IA arma el pedido"
                          : "Pegar (Ctrl+V) o subir foto/pantallazo — la IA arma la lista")}
                  </span>
                  {adjuntoFile && !ocrLoading && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.preventDefault();
                        ocrAbortRef.current += 1;
                        setAdjuntoFile(null);
                        setOcrMsg("");
                        setOcrLoading(false);
                      }}
                      className="text-xs text-danger hover:underline shrink-0"
                    >
                      Quitar
                    </button>
                  )}
                </div>
                <input
                  type="file"
                  accept="image/*,.pdf,application/pdf"
                  className="sr-only"
                  disabled={ocrLoading}
                  onChange={(e) => {
                    const f = e.target.files?.[0];
                    if (f) void recibirAdjuntoLista(f);
                    e.target.value = "";
                  }}
                />
              </label>
              {ocrMsg && (
                <p className={`text-xs font-semibold ${ocrMsg.startsWith("Se extrajeron") ? "text-accent" : "text-danger"}`}>
                  {ocrMsg}
                </p>
              )}
            </div>
          )}
          {listaComprasDraft.length > 0 && (
            <ul className="space-y-2 rounded-2xl border-2 border-border bg-surface px-4 py-3">
              {listaComprasDraft.map((item, idx) => (
                <li key={`${item.nombre}-${idx}`} className="flex items-center gap-2 text-sm">
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded border-2 border-border text-[10px] text-muted">☐</span>
                  <span className="min-w-0 flex-1 truncate text-ink font-semibold">{item.nombre}</span>
                  {variante === "compra" && (
                    <span className="shrink-0 text-muted">{item.cantidad} {item.unidad}</span>
                  )}
                  {variante === "etiqueta" && fmtUnidadesEtiqueta(item.cantidad) && (
                    <span className="shrink-0 font-semibold text-accent">{fmtUnidadesEtiqueta(item.cantidad)}</span>
                  )}
                  <button
                    type="button"
                    onClick={() => quitarItemCompra(idx)}
                    className="shrink-0 text-xs text-danger hover:underline"
                  >
                    Quitar
                  </button>
                </li>
              ))}
            </ul>
          )}
          <div className="space-y-2 rounded-2xl border-2 border-dashed border-border px-4 py-4">
            <input
              type="text"
              value={compraNombre}
              onChange={(e) => setCompraNombre(e.target.value)}
              placeholder={variante === "etiqueta"
                ? "Ej: Elastina 30 ml"
                : "Nombre del producto o material"}
              className="w-full rounded-xl border border-border bg-surface-input px-4 py-3 text-sm text-ink outline-none focus:border-accent"
              onKeyDown={(e) => {
                if ((e.key === "Enter" || e.key === " ") && compraNombre.trim()) {
                  e.preventDefault();
                  agregarItemCompra();
                }
              }}
            />
            {variante === "etiqueta" && (
              <div className="flex gap-2">
                <label className="flex flex-1 flex-col gap-1">
                  <span className="text-[10px] font-bold uppercase tracking-widest text-muted">Unidades</span>
                  <input
                    type="number"
                    min={1}
                    step={1}
                    value={compraCantidad}
                    onChange={(e) => setCompraCantidad(e.target.value)}
                    placeholder="Cant."
                    className="w-full rounded-xl border border-border bg-surface-input px-3 py-2 text-sm text-ink outline-none focus:border-accent"
                  />
                </label>
                <button
                  type="button"
                  onClick={agregarItemCompra}
                  disabled={!compraNombre.trim()}
                  className="mt-auto flex-1 rounded-xl border-2 border-accent px-3 py-2 text-sm font-bold text-accent hover:bg-accent hover:text-white disabled:opacity-40"
                >
                  + Agregar
                </button>
              </div>
            )}
            {variante === "compra" && (
              <div className="flex gap-2">
                <input
                  type="number"
                  min="0.01"
                  step="0.01"
                  value={compraCantidad}
                  onChange={(e) => setCompraCantidad(e.target.value)}
                  placeholder="Cant."
                  className="w-24 rounded-xl border border-border bg-surface-input px-3 py-2 text-sm text-ink outline-none focus:border-accent"
                />
                <input
                  type="text"
                  value={compraUnidad}
                  onChange={(e) => setCompraUnidad(e.target.value)}
                  placeholder="Unidad"
                  className="w-24 rounded-xl border border-border bg-surface-input px-3 py-2 text-sm text-ink outline-none focus:border-accent"
                />
                <button
                  type="button"
                  onClick={agregarItemCompra}
                  disabled={!compraNombre.trim()}
                  className="flex-1 rounded-xl border-2 border-accent px-3 py-2 text-sm font-bold text-accent hover:bg-accent hover:text-white disabled:opacity-40"
                >
                  + Agregar
                </button>
              </div>
            )}
            {variante === "etiqueta" && (
              <p className="text-[10px] text-center text-muted">Espacio o Enter agrega el ítem con las unidades indicadas</p>
            )}
          </div>
          <button
            type="button"
            disabled={listaComprasDraft.length === 0 || ocrLoading}
            onClick={() => {
              if (variante === "compra") {
                const resumen = listaComprasDraft.map((i) => i.nombre).join(", ");
                setTitulo(`Compras: ${resumen}`.slice(0, 150));
              } else if (variante === "etiqueta") {
                const resumen = listaComprasDraft.map((i) => i.nombre).join(", ");
                setTitulo(resumen ? `Etiquetas: ${resumen}`.slice(0, 150) : "Pedido de etiquetas");
              }
              setDescripcion(listaComprasDraft.map((i) => {
                if (variante === "compra") return `• ${i.nombre} — ${i.cantidad} ${i.unidad}`;
                return lineaDescripcionEtiqueta(i.nombre, parseFloat(i.cantidad) || 1);
              }).join("\n"));
              irFase("asignados");
            }}
            className="w-full rounded-2xl bg-accent py-4 text-lg font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            Siguiente →
          </button>
        </div>
      )}

      {/* Paso 2C: Elegir procedimiento */}
      {fase === "elegir_proc" && (
        <div key="sol-p2b" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 2 de {totalPasos}
            </p>
            <h2 className="text-3xl font-extrabold text-ink leading-tight">
              ¿Qué procedimiento<br />quieres delegar?
            </h2>
            <p className="mt-2 text-sm text-muted">Selecciona el proceso que el otro usuario debe ejecutar.</p>
          </div>
          {protDisp.length === 0 ? (
            <div className="rounded-2xl border-2 border-dashed border-border px-5 py-8 text-center text-sm text-muted">
              No hay procedimientos disponibles.<br />
              <button type="button" onClick={() => elegirVariante("nueva")} className="mt-2 text-accent hover:underline text-sm font-semibold">
                Crear solicitud nueva en cambio →
              </button>
            </div>
          ) : (
            <div className="space-y-2 max-h-80 overflow-y-auto pr-1">
              {protDisp.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => {
                    setProtocoloId(p.id);
                    setVariante("protocolo");
                    setTitulo(p.titulo);
                    setDescripcion(p.descripcion ?? "");
                    irFase("asignados");
                  }}
                  className={`w-full text-left rounded-2xl border-2 px-4 py-4 transition ${
                    protocoloId === p.id
                      ? "border-accent bg-accent/10"
                      : "border-border bg-surface hover:border-accent hover:bg-accent/5"
                  }`}
                >
                  <p className="font-bold text-ink">{p.titulo}</p>
                  {p.descripcion && (
                    <p className="mt-0.5 text-xs text-muted line-clamp-2">{p.descripcion}</p>
                  )}
                  {p.pasos?.length > 0 && (
                    <p className="mt-1 text-xs text-accent font-semibold">
                      {p.pasos.length} paso{p.pasos.length !== 1 ? "s" : ""}
                    </p>
                  )}
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Paso 3: Asignados */}
      {fase === "asignados" && (
        <div key="sol-p3" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 3 de {totalPasos}
            </p>
            <h2 className="text-3xl font-extrabold text-ink leading-tight">
              ¿A quién se<br />lo asignas?
            </h2>
            <p className="mt-2 rounded-2xl border-2 border-accent/30 bg-accent/5 px-4 py-3 text-base font-bold text-ink">
              {titulo.trim()}
            </p>
            {asignados.length > 1 && (
              <p className="mt-2 text-xs text-muted">
                Se creará una solicitud independiente para cada persona seleccionada.
              </p>
            )}
          </div>
          {otrosUsuarios.length === 0 ? (
            <p className="text-sm text-muted">No hay otros usuarios disponibles.</p>
          ) : (
            <div className="flex flex-wrap gap-2">
              {otrosUsuarios.map((u) => (
                <button
                  key={u.id}
                  type="button"
                  onClick={() => toggleAsignado(u.id)}
                  className={`flex items-center gap-2 rounded-2xl border-2 px-4 py-3 text-sm font-semibold transition ${
                    asignados.includes(u.id)
                      ? "border-accent bg-accent/10 text-accent"
                      : "border-border text-muted hover:border-accent hover:text-accent"
                  }`}
                >
                  <span
                    className="h-6 w-6 flex items-center justify-center rounded-full text-[11px] font-black text-white shrink-0"
                    style={{ background: u.departamento?.color || "#0c6069" }}
                  >
                    {u.nombre.charAt(0).toUpperCase()}
                  </span>
                  <span className="flex flex-col items-start leading-tight">
                    <span>{u.nombre}</span>
                    {u.username && (
                      <span className="text-[10px] font-medium text-muted">@{u.username.replace(/^@/, "")}</span>
                    )}
                  </span>
                  {asignados.includes(u.id) && <Icon name="check" size={13} weight="bold" />}
                </button>
              ))}
            </div>
          )}
          <button
            type="button"
            disabled={asignados.length === 0}
            onClick={() => irFase("confirmar")}
            className="w-full rounded-2xl bg-accent py-4 text-lg font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            Siguiente →
          </button>
        </div>
      )}

      {/* Paso 4: Confirmar */}
      {fase === "confirmar" && (
        <div key="sol-p4" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">
              Paso 4 de {totalPasos}
            </p>
            <h2 className="text-3xl font-extrabold text-ink leading-tight">
              Listo para<br />enviar
            </h2>
            <p className="mt-2 text-sm text-muted">Revisa antes de crear la solicitud.</p>
          </div>
          <div className="rounded-2xl border-2 border-border bg-surface px-5 py-5 space-y-3">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted mb-0.5">Tarea</p>
              <p className="text-lg font-extrabold text-ink">{titulo.trim()}</p>
              {descripcion.trim() && descripcion.trim() !== titulo.trim() && (
                <p className="mt-1 text-sm text-muted">{descripcion.trim()}</p>
              )}
            </div>
            {variante === "etiqueta" && (
              <div>
                <p className="text-[10px] font-bold uppercase tracking-widest text-muted mb-0.5">Tipo</p>
                <p className="text-sm font-semibold text-accent">🏷️ Solicitud de etiquetas</p>
                {listaComprasDraft.length > 0 && (
                  <ul className="mt-2 space-y-1 text-sm text-muted">
                    {listaComprasDraft.map((item, idx) => (
                      <li key={`${item.nombre}-${idx}`}>
                        • {item.nombre}
                        {fmtUnidadesEtiqueta(item.cantidad) ? ` — ${fmtUnidadesEtiqueta(item.cantidad)}` : ""}
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            )}
            {variante === "compra" && (
              <div>
                <p className="text-[10px] font-bold uppercase tracking-widest text-muted mb-0.5">Tipo</p>
                <p className="text-sm font-semibold text-accent">🛒 Solicitud de compras</p>
                {listaComprasDraft.length > 0 && (
                  <ul className="mt-2 space-y-1 text-sm text-muted">
                    {listaComprasDraft.map((item, idx) => (
                      <li key={`${item.nombre}-${idx}`}>• {item.nombre} — {item.cantidad} {item.unidad}</li>
                    ))}
                  </ul>
                )}
              </div>
            )}
            {protSel && (
              <div>
                <p className="text-[10px] font-bold uppercase tracking-widest text-muted mb-0.5">Procedimiento</p>
                <p className="text-sm font-semibold text-accent">📋 {protSel.titulo}</p>
              </div>
            )}
            <div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted mb-1">Para</p>
              <div className="flex flex-wrap gap-1.5">
                {asignados.map((uid) => {
                  const u = otrosUsuarios.find((x) => x.id === uid);
                  if (!u) return null;
                  return (
                    <span
                      key={uid}
                      className="flex items-center gap-1.5 rounded-xl border border-accent/40 bg-accent/8 px-3 py-1 text-sm font-semibold text-accent"
                    >
                      <span
                        className="h-5 w-5 flex items-center justify-center rounded-full text-[10px] font-black text-white shrink-0"
                        style={{ background: u.departamento?.color || "#0c6069" }}
                      >
                        {u.nombre.charAt(0).toUpperCase()}
                      </span>
                      {u.nombre}
                    </span>
                  );
                })}
              </div>
            </div>
          </div>
          <button
            type="button"
            disabled={loading}
            onClick={() => void crear()}
            className="w-full rounded-2xl bg-accent py-4 text-lg font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            {loading ? "Creando…" : asignados.length > 1 ? `Crear ${asignados.length} solicitudes` : "Crear solicitud"}
          </button>
        </div>
      )}
    </div>
  );
}

// ── Historial detalle — helpers ───────────────────────────────────────────────

function _fmtDuracionMs(ms: number): string {
  const totalMin = Math.floor(ms / 60000);
  if (totalMin < 1) return "< 1 min";
  if (totalMin < 60) return `${totalMin} min`;
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  return m > 0 ? `${h} h ${m} min` : `${h} h`;
}

function _fmtSegs(s: number): string {
  if (s < 60) return `${s} s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  const rm = m % 60;
  return rm > 0 ? `${h} h ${rm} min` : `${h} h`;
}

function _fmtFechaHist(s: string | null | undefined): string {
  if (!s) return "—";
  try {
    return new Date(s.includes("T") ? s : s + "T00:00:00").toLocaleString("es-CO", {
      day: "2-digit", month: "short", year: "numeric",
      hour: "2-digit", minute: "2-digit",
    });
  } catch { return s; }
}

// ── SolicitudResumenCard — tarjeta compacta (lista Por resolver) ─────────────

function SolicitudResumenCard({
  ticket,
  user,
  onClick,
}: {
  ticket: Ticket;
  user: TicketsUser;
  onClick: () => void;
}) {
  const esCreadoPorMi = uidEq(ticket.creado_por, user.id);
  const pasoTotal = ticket.pasos_total ?? 0;
  const pasoComp = ticket.pasos_completados ?? 0;

  return (
    <button
      type="button"
      onClick={onClick}
      className="group w-full rounded-2xl border-2 border-border bg-surface-panel/80 px-4 py-3.5 text-left transition hover:border-accent/60 hover:bg-surface-hover hover:shadow-paper-sm space-y-2"
    >
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <p className="text-sm font-extrabold text-ink leading-snug">{ticket.titulo}</p>
          {ticket.descripcion && ticket.descripcion !== ticket.titulo && (
            <p className="text-xs text-muted mt-0.5 line-clamp-2">{ticket.descripcion}</p>
          )}
        </div>
        <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${PRIORIDAD_COLOR[ticket.prioridad ?? "media"] ?? "bg-gray-200 text-gray-700"}`}>
          {ticket.prioridad ?? "media"}
        </span>
      </div>
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-muted">
        <span>{esCreadoPorMi ? "📋 Tú" : `📋 ${ticket.creado_por_nombre ?? "?"}`}</span>
        {ticket.asignado_a_nombre && <span>→ 👤 {ticket.asignado_a_nombre}</span>}
        {pasoTotal > 0 && <span>☑ {pasoComp}/{pasoTotal} pasos</span>}
        {ticket.protocolo_titulo && <span className="text-accent/90">📋 {ticket.protocolo_titulo}</span>}
        <span className="rounded-full border border-border px-2 py-0.5 text-[10px]">
          {ESTADO_LABEL[ticket.estado] ?? ticket.estado}
        </span>
        <span className="ml-auto text-[10px] font-bold text-accent/70 group-hover:text-accent transition-colors">
          Ver detalle →
        </span>
      </div>
    </button>
  );
}

// ── HistorialSeguimientoChat — conversación sobre solicitud cerrada ───────────

function HistorialSeguimientoChat({
  ticket,
  token,
  user,
  onActualizado,
  onReabierta,
}: {
  ticket: Ticket;
  token: string;
  user: TicketsUser;
  onActualizado?: () => void;
  onReabierta?: () => void;
}) {
  const [comentarios, setComentarios] = useState<Comentario[]>([]);
  const [draft, setDraft] = useState("");
  const [loading, setLoading] = useState(false);
  const [enviando, setEnviando] = useState(false);
  const [msg, setMsg] = useState("");
  const [reabierta, setReabierta] = useState(false);
  const cerrada = ticket.estado === "resuelto" || ticket.estado === "rechazado";

  const puedeChatear =
    uidEq(ticket.creado_por, user.id)
    || uidEq(ticket.asignado_a, user.id)
    || (user.rol?.nivel ?? 1) >= 2;

  const cargar = useCallback(async () => {
    setLoading(true);
    try {
      const data = await tapi(`/${ticket.id}/comentarios`, token);
      setComentarios(Array.isArray(data) ? data : []);
    } catch { /* ignore */ } finally { setLoading(false); }
  }, [ticket.id, token]);

  useEffect(() => { void cargar(); }, [cargar]);

  async function enviar() {
    const texto = draft.trim();
    if (!texto || enviando || !puedeChatear) return;
    setEnviando(true);
    setMsg("");
    try {
      if (cerrada && !reabierta) {
        await tapi(`/${ticket.id}/estado`, token, {
          method: "PUT",
          body: JSON.stringify({
            estado: "en_proceso",
            motivo: "Seguimiento desde historial — quedó algo por revisar",
          }),
        });
        setReabierta(true);
        onReabierta?.();
      }
      await tapi(`/${ticket.id}/comentarios`, token, {
        method: "POST",
        body: JSON.stringify({ texto: `🔁 Seguimiento:\n${texto}` }),
      });
      setDraft("");
      await cargar();
      onActualizado?.();
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "No se pudo enviar el mensaje");
    } finally {
      setEnviando(false);
    }
  }

  if (!puedeChatear) {
    return (
      <p className="text-[10px] text-muted italic px-1 py-2">
        Solo participantes de la solicitud pueden iniciar conversación.
      </p>
    );
  }

  return (
    <div className="mt-2 rounded-xl border border-border bg-surface p-3 space-y-2" onClick={(e) => e.stopPropagation()}>
      <p className="text-[10px] text-muted leading-snug">
        {cerrada && !reabierta
          ? "Al enviar el primer mensaje la solicitud vuelve a activas para coordinar lo pendiente."
          : reabierta
            ? "Solicitud reabierta — la conversación continúa en activas."
            : "Conversación sobre esta solicitud."}
      </p>
      <div className="max-h-40 overflow-y-auto space-y-2 rounded-lg border border-border/50 bg-surface-panel px-2 py-2">
        {loading && comentarios.length === 0 && (
          <p className="text-xs text-muted text-center py-2">Cargando mensajes…</p>
        )}
        {!loading && comentarios.length === 0 && (
          <p className="text-xs text-muted text-center py-2 italic">Sin mensajes aún.</p>
        )}
        {comentarios.map((c) => {
          const esMio = c.usuario_id === user.id;
          return (
            <div key={c.id} className={`flex ${esMio ? "justify-end" : "justify-start"}`}>
              <div
                className={`max-w-[90%] rounded-2xl px-2.5 py-1.5 text-xs ${
                  esMio
                    ? "rounded-br-md bg-accent text-white"
                    : "rounded-bl-md border border-border bg-surface text-ink"
                }`}
              >
                {!esMio && (
                  <p className={`mb-0.5 text-[9px] font-bold ${esMio ? "text-white/80" : "text-muted"}`}>
                    {c.autor_nombre}
                  </p>
                )}
                <p className="whitespace-pre-wrap leading-relaxed">{c.texto}</p>
              </div>
            </div>
          );
        })}
      </div>
      {msg && <p className="text-[10px] text-red-500">{msg}</p>}
      <div className="flex gap-2 items-end">
        <ProseInput
          className="quest-input flex-1 text-sm"
          placeholder="Algo que quedó pendiente…"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              void enviar();
            }
          }}
          maxLength={2000}
        />
        <button
          type="button"
          disabled={enviando || !draft.trim()}
          onClick={() => void enviar()}
          className="quest-btn-primary shrink-0 px-3 py-2 text-xs disabled:opacity-40"
        >
          {enviando ? "…" : "Enviar"}
        </button>
      </div>
    </div>
  );
}

// ── HistorialSolicitudCard — tarjeta compacta del historial ───────────────────

function HistorialSolicitudCard({
  ticket,
  user,
  onClick,
  chatAbierto,
  onToggleChat,
  token,
  onConversacionActualizada,
  onSolicitudReabierta,
}: {
  ticket: Ticket;
  user: TicketsUser;
  onClick: () => void;
  chatAbierto: boolean;
  onToggleChat: () => void;
  token: string;
  onConversacionActualizada?: () => void;
  onSolicitudReabierta?: () => void;
}) {
  const duracionMs = ticket.creado_en && ticket.resuelto_en
    ? new Date(ticket.resuelto_en).getTime() - new Date(ticket.creado_en).getTime()
    : null;
  const pasoTotal = ticket.pasos_total ?? 0;
  const pasoComp  = ticket.pasos_completados ?? 0;
  const rechazado = ticket.estado === "rechazado";
  const puedeMensaje =
    uidEq(ticket.creado_por, user.id)
    || uidEq(ticket.asignado_a, user.id)
    || (user.rol?.nivel ?? 1) >= 2;

  return (
    <div
      className={`rounded-2xl border-2 px-4 py-3.5 transition space-y-2
        ${rechazado
          ? "border-red-400/30 bg-red-50/10 dark:bg-red-900/10"
          : "border-accent/30 bg-accent/20"
        }`}
    >
      <button
        type="button"
        onClick={onClick}
        className="w-full text-left space-y-2 group"
      >
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0 flex-1">
            <p className="text-sm font-extrabold text-ink leading-snug truncate">{ticket.titulo}</p>
            {ticket.descripcion && ticket.descripcion !== ticket.titulo && (
              <p className="text-xs text-muted mt-0.5 line-clamp-1">{ticket.descripcion}</p>
            )}
          </div>
          <span className={`shrink-0 text-[10px] font-bold rounded-full px-2 py-0.5 border
            ${rechazado
              ? "text-red-600 dark:text-red-400 bg-red-500/15 border-red-500/25"
              : "text-accent  bg-accent/15 border-accent/25"
            }`}>
            {rechazado ? "✕ Rechazada" : "✓ Resuelta"}
          </span>
        </div>
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-muted">
          {ticket.creado_por_nombre && <span>📋 {ticket.creado_por_nombre}</span>}
          {ticket.asignado_a_nombre && <span>→ 👤 {ticket.asignado_a_nombre}</span>}
          {duracionMs !== null && <span>⏱ {_fmtDuracionMs(duracionMs)}</span>}
          {pasoTotal > 0 && <span>☑ {pasoComp}/{pasoTotal} pasos</span>}
          <span className="ml-auto rounded-lg bg-accent/10 px-2 py-1 text-[10px] font-bold text-accent group-hover:bg-accent/20 transition-colors">
            Ver respuesta y archivos →
          </span>
        </div>
      </button>
      <div className="flex flex-wrap gap-2 pt-0.5">
        {puedeMensaje && (
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); onToggleChat(); }}
            className={`inline-flex items-center gap-1 rounded-lg border px-2.5 py-1 text-[10px] font-bold transition ${
              chatAbierto
                ? "border-accent bg-accent/10 text-accent"
                : "border-border text-muted hover:border-accent hover:text-accent"
            }`}
          >
            <Icon name="chat" size={12} weight="bold" />
            Mensaje
          </button>
        )}
      </div>
      {chatAbierto && puedeMensaje && (
        <HistorialSeguimientoChat
          ticket={ticket}
          token={token}
          user={user}
          onActualizado={onConversacionActualizada}
          onReabierta={onSolicitudReabierta}
        />
      )}
    </div>
  );
}

// ── HistorialSolicitudDetalle — vista completa de solo lectura ────────────────

function HistorialSolicitudDetalle({
  ticket: ticketResumen,
  token,
  user,
  onBack,
  onConversacionActualizada,
  onSolicitudReabierta,
}: {
  ticket: Ticket;
  token: string;
  user: TicketsUser;
  onBack: () => void;
  onConversacionActualizada?: () => void;
  onSolicitudReabierta?: () => void;
}) {
  const [ticket, setTicket]       = useState<Ticket | null>(null);
  const [pasos, setPasos]         = useState<Paso[]>([]);
  const [adjuntos, setAdjuntos]   = useState<Adjunto[]>([]);
  const [comentarios, setComentarios] = useState<Comentario[]>([]);
  const [loading, setLoading]     = useState(true);
  const [usuarios, setUsuarios]   = useState<UserInfo[]>([]);
  const [showRepetir, setShowRepetir] = useState(false);
  const [showSeguimientoChat, setShowSeguimientoChat] = useState(false);
  const [repetirAsignado, setRepetirAsignado] = useState<number | "">("");
  const [repetirMsg, setRepetirMsg] = useState("");
  const [creandoRepeticion, setCreandoRepeticion] = useState(false);

  useEffect(() => {
    setLoading(true);
    Promise.all([
      tapi(`/${ticketResumen.id}`, token),
      tapi(`/${ticketResumen.id}/pasos`, token).catch(() => []),
      tapi(`/${ticketResumen.id}/adjuntos`, token).catch(() => []),
      tapi(`/${ticketResumen.id}/comentarios`, token).catch(() => []),
    ]).then(([t, p, a, c]) => {
      setTicket(t as Ticket);
      setPasos(Array.isArray(p) ? p as Paso[] : []);
      setAdjuntos(Array.isArray(a) ? a as Adjunto[] : []);
      setComentarios(Array.isArray(c) ? c as Comentario[] : []);
    }).catch(() => {}).finally(() => setLoading(false));
    tapi("/usuarios", token).then((d) => setUsuarios(Array.isArray(d) ? d as UserInfo[] : [])).catch(() => {});
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ticketResumen.id]);

  async function repetirSolicitud() {
    const t = ticket ?? ticketResumen;
    setCreandoRepeticion(true);
    setRepetirMsg("");
    try {
      await tapi("/", token, {
        method: "POST",
        body: JSON.stringify({
          titulo: t.titulo,
          descripcion: t.descripcion || t.titulo,
          tipo: "solicitud",
          asignado_a: repetirAsignado || t.asignado_a || undefined,
          protocolo_id: (t as any).protocolo_id || undefined,
        }),
      });
      setRepetirMsg("✓ Solicitud creada. Aparecerá en tu lista de solicitudes.");
      setShowRepetir(false);
      setRepetirAsignado("");
    } catch (e: any) {
      setRepetirMsg(`Error: ${e instanceof Error ? e.message : "No se pudo crear"}`);
    } finally { setCreandoRepeticion(false); }
  }

  const t = ticket ?? ticketResumen;
  const duracionMs = t.creado_en && t.resuelto_en
    ? new Date(t.resuelto_en).getTime() - new Date(t.creado_en).getTime()
    : null;

  const adjuntosPorPaso = useMemo(() => {
    const map = new Map<number, Adjunto[]>();
    for (const a of adjuntos) {
      if (a.paso_id) {
        if (!map.has(a.paso_id)) map.set(a.paso_id, []);
        map.get(a.paso_id)!.push(a);
      }
    }
    return map;
  }, [adjuntos]);

  const adjuntosEntrega = useMemo(() => {
    const delEjecutor = adjuntos.filter((a) =>
      a.creado_por != null
        ? uidEq(a.creado_por, t.asignado_a)
        : a.creado_por_nombre === t.asignado_a_nombre,
    );
    // Datos antiguos pueden no traer autor; no ocultar evidencia por eso.
    return delEjecutor.length > 0 ? delEjecutor : adjuntos;
  }, [adjuntos, t.asignado_a, t.asignado_a_nombre]);

  const comentariosEntrega = useMemo(
    () => comentarios.filter((c) =>
      uidEq(c.usuario_id, t.asignado_a)
      && !/^\s*📎\s*(imagen|archivo)\s+adjunt[oa]/i.test(c.texto),
    ),
    [comentarios, t.asignado_a],
  );

  function AdjuntoResultado({ a }: { a: Adjunto }) {
    const [lbUrl, setLbUrl] = useState<string | null>(null);
    const esImagen = (a.mime?.startsWith("image/"))
      || /\.(jpg|jpeg|png|gif|webp)$/i.test(a.nombre_original);
    const url = ticketsUploadUrl(a.nombre_archivo, token);
    if (!esImagen) return <AdjuntoLink a={a} />;
    return (
      <>
        {lbUrl && <ImageLightbox url={lbUrl} onClose={() => setLbUrl(null)} />}
        <button
          type="button"
          onClick={() => setLbUrl(url)}
          className="group w-full overflow-hidden rounded-xl border-2 border-accent/30 bg-surface text-left"
          title="Abrir respuesta"
        >
          <img
            src={url}
            alt={`Respuesta de ${a.creado_por_nombre ?? t.asignado_a_nombre ?? "la persona asignada"}`}
            className="max-h-[28rem] w-full object-contain bg-white"
          />
          <span className="flex items-center justify-between gap-2 border-t border-border px-3 py-2 text-xs">
            <span className="min-w-0 truncate font-semibold text-ink">{a.nombre_original}</span>
            <span className="shrink-0 font-bold text-accent group-hover:underline">Ampliar 🔍</span>
          </span>
        </button>
      </>
    );
  }

  function AdjuntoLink({ a }: { a: Adjunto }) {
    const [lbUrl, setLbUrl] = useState<string | null>(null);
    const esImagen = /\.(jpg|jpeg|png|gif|webp)$/i.test(a.nombre_original);
    const esPdf    = /\.pdf$/i.test(a.nombre_original);
    const icono    = esImagen ? "🖼" : esPdf ? "📄" : "📁";
    const url      = ticketsUploadUrl(a.nombre_archivo, token);
    return (
      <>
        {lbUrl && <ImageLightbox url={lbUrl} onClose={() => setLbUrl(null)} />}
        <div className="flex items-center gap-2 rounded-xl border border-border bg-surface px-3 py-2 text-xs min-w-0">
          {esImagen ? (
            <button type="button" onClick={() => setLbUrl(url)} className="group relative shrink-0" title="Ver imagen">
              <img src={url} alt={a.nombre_original} className="h-8 w-8 rounded object-cover border border-border group-hover:opacity-80 transition-opacity" />
              <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-[10px] font-bold transition-opacity">🔍</span>
            </button>
          ) : (
            <span className="text-base shrink-0">{icono}</span>
          )}
          <a href={url} target="_blank" rel="noreferrer"
            className="min-w-0 truncate flex-1 text-accent hover:underline">
            {a.nombre_original}
          </a>
          {a.creado_por_nombre && (
            <span className="text-[10px] text-muted shrink-0 hidden sm:inline">{a.creado_por_nombre}</span>
          )}
        </div>
      </>
    );
  }

  if (loading) return (
    <div className="flex min-h-[50vh] items-center justify-center">
      <div className="h-10 w-10 rounded-full border-4 border-border border-t-accent animate-spin" />
    </div>
  );

  const rechazado = t.estado === "rechazado";

  return (
    <div className="space-y-5 pb-10">
      {/* Nav: volver */}
      <div className="flex items-center gap-3">
        <button type="button" onClick={onBack}
          className="flex items-center gap-1.5 rounded-xl border border-border px-3 py-2 text-sm font-bold text-muted hover:border-accent hover:text-accent transition-colors shrink-0">
          <svg className="h-4 w-4" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
          </svg>
          Historial
        </button>
        <span className={`text-[10px] font-bold rounded-full px-2.5 py-1 border
          ${rechazado
            ? "text-red-600 dark:text-red-400 bg-red-500/15 border-red-500/25"
            : "text-accent  bg-accent/15 border-accent/25"
          }`}>
          {rechazado ? "✕ Rechazada" : "✓ Resuelta"}
        </span>
      </div>

      {/* Título */}
      <div>
        <h2 className="text-2xl font-extrabold text-ink leading-tight">{t.titulo}</h2>
        {t.descripcion && t.descripcion !== t.titulo && (
          <p className="mt-2 text-sm text-muted leading-relaxed">{t.descripcion}</p>
        )}
      </div>

      {/* Quién */}
      <div className="flex flex-wrap gap-3">
        {t.creado_por_nombre && (
          <div className="flex items-center gap-2 rounded-xl border border-border bg-surface-panel px-3 py-2 text-sm">
            <span className="text-base">📋</span>
            <div>
              <p className="text-[10px] text-muted font-bold uppercase tracking-wide leading-none mb-0.5">Solicitado por</p>
              <p className="font-semibold text-ink">{t.creado_por_nombre}</p>
            </div>
          </div>
        )}
        {t.asignado_a_nombre && (
          <div className="flex items-center gap-2 rounded-xl border border-border bg-surface-panel px-3 py-2 text-sm">
            <span className="text-base">👤</span>
            <div>
              <p className="text-[10px] text-muted font-bold uppercase tracking-wide leading-none mb-0.5">Resuelto por</p>
              <p className="font-semibold text-ink">{t.asignado_a_nombre}</p>
            </div>
          </div>
        )}
      </div>

      {/* Resultado entregado: debe verse antes que tiempos y actividad. */}
      <div className={`rounded-2xl border-2 p-4 space-y-3 ${
        adjuntosEntrega.length > 0 || comentariosEntrega.length > 0
          ? "border-accent/50 bg-accent/10"
          : "border-amber-400/50 bg-amber-50/50 dark:bg-amber-950/15"
      }`}>
        <div>
          <p className="text-xs font-extrabold uppercase tracking-wide text-ink">
            ✅ Resultado entregado por {t.asignado_a_nombre ?? "la persona asignada"}
          </p>
          <p className="mt-0.5 text-xs text-muted">
            Esto fue lo que adjuntó o escribió al terminar la solicitud.
          </p>
        </div>
        {comentariosEntrega.map((c) => (
          <div key={c.id} className="rounded-xl border border-border bg-surface px-3 py-2">
            <p className="whitespace-pre-wrap text-sm text-ink">{c.texto}</p>
            <p className="mt-1 text-[10px] text-muted">{_fmtFechaHist(c.creado_en)}</p>
          </div>
        ))}
        {adjuntosEntrega.length > 0 && (
          <div className="grid gap-3 lg:grid-cols-2">
            {adjuntosEntrega.map((a) => <AdjuntoResultado key={a.id} a={a} />)}
          </div>
        )}
        {adjuntosEntrega.length === 0 && comentariosEntrega.length === 0 && (
          <p className="text-sm font-semibold text-amber-700 dark:text-amber-300">
            No dejó una respuesta escrita ni archivos como evidencia.
          </p>
        )}
      </div>

      {/* Estadísticas de tiempo */}
      <div className="rounded-2xl border-2 border-border bg-surface-panel p-4 grid grid-cols-2 gap-4 sm:grid-cols-4">
        <div>
          <p className="text-[10px] font-bold uppercase tracking-wide text-muted mb-0.5">Creada</p>
          <p className="text-xs font-semibold text-ink leading-snug">{_fmtFechaHist(t.creado_en)}</p>
        </div>
        <div>
          <p className="text-[10px] font-bold uppercase tracking-wide text-muted mb-0.5">Resuelta</p>
          <p className="text-xs font-semibold text-ink leading-snug">{_fmtFechaHist(t.resuelto_en)}</p>
        </div>
        {duracionMs !== null && (
          <div>
            <p className="text-[10px] font-bold uppercase tracking-wide text-muted mb-0.5">Duración total</p>
            <p className="text-sm font-extrabold text-ink">{_fmtDuracionMs(duracionMs)}</p>
          </div>
        )}
        {(t.segundos_trabajo ?? 0) > 0 && (
          <div>
            <p className="text-[10px] font-bold uppercase tracking-wide text-muted mb-0.5">Tiempo activo</p>
            <p className="text-sm font-extrabold text-accent">{_fmtSegs(t.segundos_trabajo!)}</p>
          </div>
        )}
      </div>

      {/* Pasos — solo lectura */}
      {pasos.length > 0 && (
        <div className="rounded-2xl border-2 border-border bg-surface-panel p-4 space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-xs font-extrabold uppercase tracking-wide text-ink flex items-center gap-2">
              ☑ Protocolo de pasos
              <span className="text-[10px] font-normal text-muted normal-case tracking-normal">
                ({pasos.filter(pasoEstaCompletado).length}/{pasos.length} completados)
              </span>
            </p>
          </div>
          <div className="h-1.5 rounded-full bg-border overflow-hidden">
            <div
              className="h-full rounded-full bg-accent/50 transition-all"
              style={{ width: `${pasos.length ? (pasos.filter(pasoEstaCompletado).length / pasos.length) * 100 : 0}%` }}
            />
          </div>
          <div className="space-y-2">
            {pasos.map((p) => {
              const hecho    = pasoEstaCompletado(p);
              const pasoAdjs = adjuntosPorPaso.get(p.id) ?? [];
              return (
                <div key={p.id}
                  className={`rounded-xl border px-3 py-2.5 space-y-1.5 transition-colors
                    ${hecho
                      ? "border-accent/30 bg-accent/20"
                      : "border-border/40 bg-surface opacity-55"
                    }`}>
                  <div className="flex items-start gap-2.5">
                    {/* Visual checkbox — nunca interactivo */}
                    <span className={`mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded border-2
                      ${hecho ? "border-accent/50 bg-accent/50" : "border-border/60"}`}>
                      {hecho && (
                        <svg className="h-2.5 w-2.5 text-white" fill="none" stroke="currentColor" strokeWidth="3" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                        </svg>
                      )}
                    </span>
                    <div className="min-w-0 flex-1">
                      <p className={`text-sm font-semibold leading-snug ${hecho ? "text-ink" : "text-muted"}`}>
                        <span className="text-muted/50 text-xs mr-1">{p.orden}.</span>{p.descripcion}
                      </p>
                      {p.notas && !p.respuesta_intervencion && (
                        <p className="text-[11px] text-muted mt-0.5">{p.notas}</p>
                      )}
                      {p.respuesta_intervencion && (
                        <p className="text-[11px] text-accent  mt-0.5">
                          ✅ {p.respuesta_intervencion}
                        </p>
                      )}
                      {hecho && p.completado_por_nombre && (
                        <p className="text-[10px] text-muted mt-0.5">
                          ✓ {p.completado_por_nombre}
                          {p.completado_en ? ` · ${_fmtFechaHist(p.completado_en)}` : ""}
                          {p.duracion_segundos ? ` · ⏱ ${fmtTiempo(p.duracion_segundos)}` : ""}
                        </p>
                      )}
                    </div>
                  </div>
                  {pasoAdjs.length > 0 && (
                    <div className="ml-6 flex flex-wrap gap-2 pt-0.5">
                      {pasoAdjs.map((a) => <AdjuntoLink key={a.id} a={a} />)}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Archivos adjuntos (generales y por paso) */}
      {adjuntos.length > 0 && (
        <div className="rounded-2xl border-2 border-border bg-surface-panel p-4 space-y-3">
          <p className="text-xs font-extrabold uppercase tracking-wide text-ink">📎 Archivos adjuntos</p>
          <div className="grid gap-2 sm:grid-cols-2">
            {adjuntos.map((a) => {
              const paso = a.paso_id ? pasos.find((p) => p.id === a.paso_id) : null;
              return (
                <div key={a.id} className="min-w-0">
                  {paso && (
                    <p className="mb-0.5 text-[10px] text-muted truncate">
                      Paso {paso.orden}: {paso.descripcion}
                    </p>
                  )}
                  <AdjuntoLink a={a} />
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Timeline de comentarios / actividad */}
      {comentarios.length > 0 && (
        <div className="rounded-2xl border-2 border-border bg-surface-panel p-4 space-y-4">
          <p className="text-xs font-extrabold uppercase tracking-wide text-ink">💬 Actividad</p>
          <div className="space-y-4">
            {comentarios.map((c) => (
              <div key={c.id} className="flex gap-3">
                <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-surface-hover border border-border text-xs font-extrabold text-ink/60">
                  {(c.autor_nombre || "?").charAt(0).toUpperCase()}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-baseline gap-2 flex-wrap mb-0.5">
                    <span className="text-xs font-bold text-ink">{c.autor_nombre ?? "—"}</span>
                    <span className="text-[10px] text-muted">{_fmtFechaHist(c.creado_en)}</span>
                  </div>
                  <p className="text-sm text-muted whitespace-pre-wrap leading-relaxed">{c.texto}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {pasos.length === 0 && adjuntos.length === 0 && comentarios.length === 0 && (
        <p className="text-sm text-muted text-center py-6 italic">Sin registros adicionales para esta solicitud.</p>
      )}

      {/* Seguimiento — conversación sobre algo pendiente */}
      <div className="rounded-2xl border-2 border-accent/30 bg-accent/5 p-4 space-y-3">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="text-sm font-extrabold text-ink flex items-center gap-1.5">
              <Icon name="chat" size={14} weight="bold" />
              Seguimiento
            </p>
            <p className="text-xs text-muted mt-0.5">
              Escribe si quedó algo por aclarar o corregir de esta solicitud cerrada.
            </p>
          </div>
          <button
            type="button"
            onClick={() => setShowSeguimientoChat((v) => !v)}
            className={`shrink-0 rounded-xl border px-3 py-1.5 text-xs font-bold transition ${
              showSeguimientoChat
                ? "border-accent bg-accent text-white"
                : "border-border text-muted hover:border-accent hover:text-accent"
            }`}
          >
            {showSeguimientoChat ? "Ocultar" : "Mensaje"}
          </button>
        </div>
        {showSeguimientoChat && (
          <HistorialSeguimientoChat
            ticket={t}
            token={token}
            user={user}
            onActualizado={onConversacionActualizada}
            onReabierta={() => {
              onSolicitudReabierta?.();
              onBack();
            }}
          />
        )}
      </div>

      {/* Repetir solicitud */}
      <div className="rounded-2xl border-2 border-dashed border-border p-4 space-y-3">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="text-sm font-extrabold text-ink">🔁 Repetir esta solicitud</p>
            <p className="text-xs text-muted mt-0.5">
              Crea una nueva solicitud con el mismo contenido para que alguien la resuelva de nuevo.
            </p>
          </div>
          {!showRepetir && (
            <button type="button" onClick={() => setShowRepetir(true)}
              className="shrink-0 rounded-xl border border-border px-3 py-1.5 text-xs font-bold text-muted hover:border-accent hover:text-accent transition-colors">
              Repetir
            </button>
          )}
        </div>
        {repetirMsg && (
          <p className={`text-xs font-semibold ${repetirMsg.startsWith("✓") ? "text-accent/50" : "text-red-400"}`}>
            {repetirMsg}
          </p>
        )}
        {showRepetir && (
          <div className="space-y-3">
            <div>
              <p className="text-[11px] font-bold text-muted uppercase tracking-wide mb-1">Asignar a</p>
              <select
                className="quest-input w-full text-sm"
                value={repetirAsignado}
                onChange={(e) => setRepetirAsignado(e.target.value ? Number(e.target.value) : "")}
              >
                <option value="">Mismo ejecutor ({t.asignado_a_nombre ?? "sin asignar"})</option>
                {usuarios
                  .filter((u) => u.activo !== 0)
                  .map((u) => (
                    <option key={u.id} value={u.id}>{u.nombre}</option>
                  ))}
              </select>
            </div>
            <div className="flex gap-2">
              <button type="button" disabled={creandoRepeticion} onClick={repetirSolicitud}
                className="flex-1 rounded-xl bg-accent py-2 text-sm font-extrabold text-white disabled:opacity-40 hover:brightness-110 transition-all">
                {creandoRepeticion ? "Creando…" : "Crear solicitud"}
              </button>
              <button type="button" onClick={() => { setShowRepetir(false); setRepetirAsignado(""); }}
                className="rounded-xl border border-border px-3 py-2 text-sm text-muted hover:text-ink">
                Cancelar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ── ContratosView ─────────────────────────────────────────────────────────────

function ContratosView({
  token, user, onBack, onSelect, onCreate,
}: {
  token: string;
  user: TicketsUser;
  onBack: () => void;
  onSelect: (id: number) => void;
  onCreate: () => void;
}) {
  const [tab, setTab] = useState<"activas" | "historial">("activas");
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const params = new URLSearchParams({ categoria: "contratos" });
      if (tab === "activas") params.set("activas", "1");
      const data = await tapi(`/?${params}`, token);
      const list = Array.isArray(data) ? data.map(normalizeTicketForList) : [];
      setTickets(
        tab === "historial"
          ? list.filter((t) => t.estado === "resuelto" || t.estado === "rechazado")
          : list,
      );
    } catch {
      if (!silent) setTickets([]);
    } finally {
      if (!silent) setLoading(false);
    }
  }, [token, tab]);

  useEffect(() => { void load(false); }, [load]);
  useEffect(() => {
    const iv = setInterval(() => { void load(true); }, 30000);
    return () => clearInterval(iv);
  }, [load]);
  useEffect(() => onPanelResume(() => { void load(true); }), [load]);

  const pendientes = tickets.filter((t) => t.estado !== "resuelto" && t.estado !== "rechazado").length;

  return (
    <div className="space-y-5 pb-8">
      <div className="flex flex-wrap items-center gap-3">
        <button type="button" onClick={onBack}
          className="rounded-paper border-2 border-border px-3 py-1.5 text-xs font-bold text-muted transition hover:border-accent hover:text-accent">
          ← Volver al Centro
        </button>
        <h2 className="text-xl font-extrabold text-ink">Contratos</h2>
        <button type="button" onClick={onCreate}
          className="ml-auto rounded-paper border-2 border-accent bg-accent px-4 py-2 text-sm font-bold text-white shadow-[0_3px_0_#045159] transition hover:bg-accent-hover active:translate-y-0.5 active:shadow-none">
          + Nueva solicitud de contrato
        </button>
      </div>

      <div className="rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-800 dark:border-slate-700/50 dark:bg-slate-950/40 dark:text-slate-200">
        Crea solicitudes de contrato y envíalas a un aliado del equipo. Usa la plantilla de prestación de servicios o adjunta tu documento (PDF, Word o imagen).
        El aliado las verá en <strong>Solicitudes → Por resolver</strong>.
      </div>

      <div className="flex gap-2">
        {(["activas", "historial"] as const).map((t) => (
          <button
            key={t}
            type="button"
            onClick={() => setTab(t)}
            className={`rounded-paper border-2 px-4 py-2 text-sm font-bold transition ${
              tab === t
                ? "border-accent bg-accent/10 text-accent"
                : "border-border text-muted hover:border-accent hover:text-accent"
            }`}
          >
            {t === "activas" ? `Activos${pendientes > 0 && tab === "activas" ? ` (${pendientes})` : ""}` : "Historial"}
          </button>
        ))}
        <button type="button" onClick={() => void load(false)} disabled={loading}
          className="ml-auto text-xs text-accent hover:underline disabled:opacity-50">
          ↻ Actualizar
        </button>
      </div>

      {loading && <div className="py-8 text-center text-sm text-muted">Cargando contratos…</div>}

      {!loading && tickets.length === 0 && (
        <div className="rounded-2xl border-2 border-dashed border-border py-12 text-center">
          <TopicIcon value="📄" size={36} className="mx-auto mb-2 text-muted" />
          <p className="text-sm font-bold text-muted">
            {tab === "activas" ? "No hay contratos activos." : "Sin historial de contratos."}
          </p>
          {tab === "activas" && (
            <button type="button" onClick={onCreate}
              className="mt-4 rounded-paper border-2 border-accent px-4 py-2 text-sm font-bold text-accent hover:bg-accent hover:text-white transition">
              Enviar primera solicitud de contrato
            </button>
          )}
        </div>
      )}

      {!loading && tickets.length > 0 && (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {tickets.map((t) => (
            <TicketCard key={t.id} t={t} onClick={() => onSelect(t.id)} />
          ))}
        </div>
      )}
    </div>
  );
}

// ── SolicitudesView ───────────────────────────────────────────────────────────

const FRECUENCIA_OPTS: { value: Frecuencia; label: string }[] = [
  { value: "diaria", label: "Diaria" },
  { value: "cada_2_dias", label: "Cada 2 días" },
  { value: "cada_3_dias", label: "Cada 3 días" },
  { value: "semanal", label: "Semanal" },
  { value: "quincenal", label: "Quincenal" },
  { value: "mensual", label: "Mensual" },
  { value: "bimestral", label: "Bimestral" },
  { value: "trimestral", label: "Trimestral" },
  { value: "semestral", label: "Semestral" },
];

function SolicitudesView({
  token, user, onInicio, boot, onBootConsumed,
}: {
  token: string; user: TicketsUser;
  onInicio?: () => void;
  boot?: SolicitudBoot | null;
  onBootConsumed?: () => void;
}) {
  const isAdmin = (user.rol?.nivel ?? 1) >= 3;
  const { apiToken: chatApiToken } = useTicketsAuth();
  const stt = useStt(token, chatApiToken);
  const [showEjecWizard, setShowEjecWizard] = useState(false);
  const [showRepetirEjecWizard, setShowRepetirEjecWizard] = useState(false);
  const [plantillaRepetirEjec, setPlantillaRepetirEjec] = useState<PlantillaAccion | undefined>();
  const [showWizard, setShowWizard] = useState(false);
  const [wizardPrefill, setWizardPrefill] = useState({ titulo: "", descripcion: "" });
  const [plantillaEjec, setPlantillaEjec] = useState<PlantillaAccion | undefined>();
  const [solicitudEjecId, setSolicitudEjecId] = useState<number | undefined>();
  const [tab, setTab] = useState<"subhome" | "asignadas" | "creadas" | "equipo" | "historial" | "protocolos">("subhome");
  const [selectedHistorialTicket, setSelectedHistorialTicket] = useState<Ticket | null>(null);
  const [asignadaDetalle, setAsignadaDetalle] = useState<Ticket | null>(null);
  const [solicitudes, setSolicitudes] = useState<Ticket[]>([]);
  const [solicitudesEquipo, setSolicitudesEquipo] = useState<Ticket[]>([]);
  const [comprasDelegadas, setComprasDelegadas] = useState<Ticket[]>([]);
  const [compraActiva, setCompraActiva] = useState<Ticket | null>(null);
  const [usuarios, setUsuarios] = useState<UserInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [msg, setMsg] = useState("");
  const [protocolos, setProtocolos] = useState<Protocolo[]>([]);
  const [loadingProtocolos, setLoadingProtocolos] = useState(false);
  const [historialSol, setHistorialSol] = useState<Ticket[]>([]);
  const [loadingHistorial, setLoadingHistorial] = useState(false);
  const [historialGruposAbiertos, setHistorialGruposAbiertos] = useState<Set<number>>(new Set());
  const [historialChatId, setHistorialChatId] = useState<number | null>(null);
  const [historialBusqueda, setHistorialBusqueda] = useState("");

  const load = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    setMsg("");
    const [solRes, equipoRes, usrsRes, comprasRes] = await Promise.allSettled([
      tapi("/?tipo=solicitud&activas=1", token),
      tapi("/?tipo=solicitud&vista_equipo=1&activas=1", token),
      tapi("/usuarios", token),
      tapiSafe("/compras-delegadas", token),
    ]);
    if (solRes.status === "fulfilled" && Array.isArray(solRes.value)) {
      setSolicitudes(solRes.value.map(normalizeTicketForList));
    } else if (!silent) {
      setSolicitudes([]);
      setMsg("No se pudieron cargar tus solicitudes");
    }
    if (equipoRes.status === "fulfilled" && Array.isArray(equipoRes.value)) {
      setSolicitudesEquipo(equipoRes.value.map(normalizeTicketForList));
    }
    if (usrsRes.status === "fulfilled" && Array.isArray(usrsRes.value)) {
      setUsuarios(usrsRes.value);
    }
    if (comprasRes.status === "fulfilled" && Array.isArray(comprasRes.value)) {
      setComprasDelegadas(comprasRes.value.map(normalizeTicketForList));
    }
    if (!silent) setLoading(false);
  }, [token, user.id]);

  const cargarHistorial = useCallback(async () => {
    setLoadingHistorial(true);
    try {
      const data = await tapi("/?tipo=solicitud", token) as Ticket[];
      const resueltas = (Array.isArray(data) ? data : [])
        .map(normalizeTicketForList)
        .filter((t) => t.estado === "resuelto" || t.estado === "rechazado");
      setHistorialSol(resueltas);
    } catch { /* ignore */ } finally { setLoadingHistorial(false); }
  }, [token]);

  useEffect(() => { void load(false); }, [load]);
  useEffect(() => {
    const iv = setInterval(() => void load(true), 15000);
    return () => clearInterval(iv);
  }, [load]);
  useEffect(() => onPanelResume(() => { void load(true); }), [load]);

  useEffect(() => {
    if (!boot) return;
    if (boot.abrirWizard) {
      setWizardPrefill({
        titulo: boot.prefillTitulo ?? "",
        descripcion: boot.prefillDescripcion ?? "",
      });
      setShowWizard(true);
    }
    if (boot.abrirTicketId != null) {
      const id = boot.abrirTicketId;
      setTab("asignadas");
      const enLista = solicitudes.find((t) => t.id === id) ?? solicitudesEquipo.find((t) => t.id === id);
      if (enLista) {
        setAsignadaDetalle(enLista);
      } else {
        tapi(`/${id}`, token)
          .then((t) => setAsignadaDetalle(normalizeTicketForList(t)))
          .catch(() => { /* ignore */ });
      }
    }
    onBootConsumed?.();
  }, [boot, onBootConsumed, solicitudes, solicitudesEquipo, token]);

  async function cargarProtocolos() {
    setLoadingProtocolos(true);
    try {
      const data = await tapi("/protocolos", token);
      setProtocolos(Array.isArray(data) ? data : []);
    } catch { /* ignore */ } finally { setLoadingProtocolos(false); }
  }

  useEffect(() => { void cargarProtocolos(); }, [token]);
  useEffect(() => {
    if (tab === "protocolos" || tab === "subhome") void cargarProtocolos();
    if (tab === "historial") void cargarHistorial();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab]);

  useEffect(() => {
    if (tab !== "historial") return;
    const iv = setInterval(() => { void cargarHistorial(); }, 15000);
    return onPanelResume(() => { void cargarHistorial(); });
  }, [tab, cargarHistorial]);

  const asignadas = solicitudes.filter(
    (t) => uidEq(t.asignado_a, user.id) && t.estado !== "resuelto" && t.estado !== "rechazado",
  );
  const comprasPendientes = comprasDelegadas.length > 0
    ? comprasDelegadas
    : asignadas.filter(esSolicitudCompraDelegada);
  const etiquetasPendientes = asignadas.filter(esSolicitudEtiquetaPanel);
  const otrasAsignadas = asignadas.filter(
    (t) => !esSolicitudCompraDelegada(t) && !esSolicitudEtiquetaPanel(t),
  );
  const creadas = solicitudes.filter(
    (t) => uidEq(t.creado_por, user.id) && t.estado !== "resuelto" && t.estado !== "rechazado",
  );
  const enEquipo = solicitudesEquipo;
  const historial = historialSol;
  const lista = tab === "asignadas"
    ? otrasAsignadas
    : tab === "creadas"
      ? creadas
      : tab === "historial"
        ? historial
        : enEquipo;
  const pendientes = otrasAsignadas.length + comprasPendientes.length;

  useEffect(() => {
    if (compraActiva && !comprasPendientes.some((t) => t.id === compraActiva.id)) {
      setCompraActiva(null);
    }
  }, [compraActiva, comprasPendientes]);

  useEffect(() => {
    if (!asignadaDetalle) return;
    const fresh = otrasAsignadas.find((t) => t.id === asignadaDetalle.id);
    if (fresh) setAsignadaDetalle(fresh);
    else setAsignadaDetalle(null);
  }, [otrasAsignadas, asignadaDetalle?.id]);

  useEffect(() => {
    if (tab !== "asignadas") setAsignadaDetalle(null);
  }, [tab]);

  const abrirIntervencionBloqueante = useCallback((intervencionId: number) => {
    const t = otrasAsignadas.find((x) => x.id === intervencionId)
      ?? asignadas.find((x) => x.id === intervencionId);
    setTab("asignadas");
    if (t) {
      setAsignadaDetalle(t);
    } else {
      setMsg(`La intervención no está en tu bandeja Por resolver. Pide al asignado que la cierre.`);
      setTimeout(() => setMsg(""), 5000);
    }
  }, [otrasAsignadas, asignadas]);

  const equipoPorAsignado = useMemo(() => {
    const map = new Map<number, { nombre: string; items: Ticket[] }>();
    for (const t of enEquipo) {
      const uid = t.asignado_a ?? 0;
      if (!map.has(uid)) map.set(uid, { nombre: t.asignado_a_nombre ?? "Sin asignar", items: [] });
      map.get(uid)!.items.push(t);
    }
    return [...map.values()].sort((a, b) => a.nombre.localeCompare(b.nombre, "es"));
  }, [enEquipo]);

  const historialFiltrado = useMemo(() => {
    const q = historialBusqueda.trim().toLowerCase().replace(/^@/, "");
    if (!q) return historial;
    return historial.filter((t) => {
      const uid = t.asignado_a ?? 0;
      const uname = usuarios.find((u) => u.id === uid)?.username?.replace(/^@/, "") ?? "";
      const haystack = [
        t.titulo,
        t.descripcion,
        t.numero,
        t.asignado_a_nombre,
        t.creado_por_nombre,
        uname,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(q);
    });
  }, [historial, historialBusqueda, usuarios]);

  const historialPorAsignado = useMemo(() => {
    const map = new Map<number, { uid: number; nombre: string; items: Ticket[] }>();
    for (const t of historialFiltrado) {
      const uid = t.asignado_a ?? 0;
      if (!map.has(uid)) map.set(uid, { uid, nombre: t.asignado_a_nombre ?? "Sin asignar", items: [] });
      map.get(uid)!.items.push(t);
    }
    const ts = (x: Ticket) =>
      new Date(x.resuelto_en || x.actualizado_en || x.creado_en || 0).getTime();
    return [...map.values()]
      .map((g) => ({
        ...g,
        items: [...g.items].sort((a, b) => ts(b) - ts(a)),
      }))
      .sort((a, b) => a.nombre.localeCompare(b.nombre, "es"));
  }, [historialFiltrado]);

  useEffect(() => {
    if (tab !== "historial" || historialPorAsignado.length === 0) return;
    setHistorialGruposAbiertos((prev) => {
      if (prev.size > 0) return prev;
      return new Set(historialPorAsignado.map((g) => g.uid));
    });
  }, [tab, historialPorAsignado]);

  function toggleHistorialGrupo(uid: number) {
    setHistorialGruposAbiertos((prev) => {
      const next = new Set(prev);
      if (next.has(uid)) next.delete(uid);
      else next.add(uid);
      return next;
    });
  }

  async function iniciarEjecucionSolicitud(t: Ticket) {
    let plantilla: PlantillaAccion = {
      titulo: t.titulo,
      listaCompras: [],
      pasos: [],
    };
    if (t.protocolo_id) {
      try {
        const p = await tapi(`/protocolos/${t.protocolo_id}`, token) as Protocolo;
        plantilla = plantillaDesdeProtocolo(p);
      } catch { /* usar título de solicitud */ }
    }
    setSolicitudEjecId(t.id);
    // Si el protocolo tiene ingredientes o pasos definidos, usar el flujo
    // paso-a-paso (RepetirAccionWizard) en lugar del formulario editable.
    const tieneContenido = plantilla.listaCompras.length > 0 || plantilla.pasos.length > 0;
    if (tieneContenido) {
      setPlantillaRepetirEjec(plantilla);
      setShowRepetirEjecWizard(true);
    } else {
      setPlantillaEjec(plantilla);
      setShowEjecWizard(true);
    }
  }

  if (showRepetirEjecWizard && plantillaRepetirEjec) {
    return (
      <RepetirAccionWizard
        token={token}
        user={user}
        chatApiToken={chatApiToken}
        plantilla={plantillaRepetirEjec}
        solicitudPadreId={solicitudEjecId}
        onCancel={() => {
          setShowRepetirEjecWizard(false);
          setPlantillaRepetirEjec(undefined);
          setSolicitudEjecId(undefined);
        }}
        onCreated={() => {
          setShowRepetirEjecWizard(false);
          setPlantillaRepetirEjec(undefined);
          setSolicitudEjecId(undefined);
          void load(false);
          setMsg("Ejecución completada");
          setTimeout(() => setMsg(""), 3000);
        }}
      />
    );
  }

  if (showWizard) {
    return (
      <NuevaSolicitudWizard
        token={token}
        user={user}
        protocolos={protocolos}
        usuarios={usuarios}
        tituloInicial={wizardPrefill.titulo}
        descripcionInicial={wizardPrefill.descripcion}
        onCancel={() => setShowWizard(false)}
        onCreated={(meta) => {
          setShowWizard(false);
          void load(false);
          if (meta?.subtipo === "etiqueta") {
            setMsg("Pedido enviado al apartado Impresora · Etiquetas del asignado");
          } else if (meta?.subtipo === "compra") {
            setMsg("Solicitud de compras creada correctamente");
          } else {
            setMsg("Solicitud creada correctamente");
          }
          setTimeout(() => setMsg(""), 4000);
        }}
      />
    );
  }

  if (showEjecWizard) {
    return (
      <NuevaAccionWizard
        token={token}
        user={user}
        chatApiToken={chatApiToken}
        plantilla={plantillaEjec}
        solicitudPadreId={solicitudEjecId}
        onCancel={() => { setShowEjecWizard(false); setSolicitudEjecId(undefined); }}
        onCreated={() => {
          setShowEjecWizard(false);
          setSolicitudEjecId(undefined);
          void load(false);
          setMsg("Ejecución registrada y reporte enviado");
          setTimeout(() => setMsg(""), 3000);
        }}
      />
    );
  }

  if (compraActiva) {
    return (
      <PanelIrDeCompras
        ticket={compraActiva}
        token={token}
        user={user}
        onSalir={() => setCompraActiva(null)}
        onTerminado={() => {
          setCompraActiva(null);
          void load(false);
          setMsg("Compras terminadas");
          setTimeout(() => setMsg(""), 2500);
        }}
      />
    );
  }

  if (selectedHistorialTicket) {
    return (
      <HistorialSolicitudDetalle
        ticket={selectedHistorialTicket}
        token={token}
        user={user}
        onBack={() => setSelectedHistorialTicket(null)}
        onConversacionActualizada={() => void cargarHistorial()}
        onSolicitudReabierta={() => {
          setSelectedHistorialTicket(null);
          setHistorialChatId(null);
          void load(true);
          void cargarHistorial();
          setTab("asignadas");
          setMsg("Solicitud reabierta — revisa en activas");
          setTimeout(() => setMsg(""), 3500);
        }}
      />
    );
  }

  // Vista detalle de solicitud asignada — layout full-height tipo chat
  if (tab === "asignadas" && asignadaDetalle) {
    return (
      <div className="flex flex-col flex-1 min-h-0 h-full">
        <div className="shrink-0 flex items-center gap-3 border-b border-border/50 bg-surface-panel px-4 py-2.5">
          <button
            type="button"
            onClick={() => setAsignadaDetalle(null)}
            className="flex h-8 w-8 items-center justify-center rounded-lg border border-border text-muted text-lg font-bold hover:border-accent hover:text-accent transition"
          >‹</button>
          <span className="flex-1 truncate text-sm font-semibold text-ink">{asignadaDetalle.titulo}</span>
          <span className="shrink-0 font-mono text-[11px] text-muted/50">{shortNumero(asignadaDetalle.numero)}</span>
        </div>
        <div className="flex-1 min-h-0 overflow-y-auto px-4 pt-4 pb-4">
          <SolicitudCard
            ticket={asignadaDetalle}
            token={token}
            user={user}
            isAdmin={isAdmin}
            protocolos={protocolos}
            detalleAmpliado
            onIrAIntervencion={abrirIntervencionBloqueante}
            onChanged={() => void load(true)}
            onCerrarDetalle={() => setAsignadaDetalle(null)}
            onRegistrarEjecucion={
              esSolicitudCompraDelegada(asignadaDetalle)
                ? undefined
                : (sol) => void iniciarEjecucionSolicitud(sol)
            }
          />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      {tab === "subhome" ? (
        <div className="rounded-xl border border-accent/20  bg-accent/5  px-3 py-2.5">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg border border-border/60 bg-surface/80 text-ink">
              <TopicIcon value="📋" size={15} />
            </span>
            <span className="text-sm font-bold text-ink">Solicitudes</span>
            <div className="ml-auto flex items-center gap-1.5 flex-wrap">
              <button
                type="button"
                onClick={() => setShowWizard(true)}
                className={`${CENTRO_MANDO_CTA_BTN} bg-accent/50 hover:bg-accent shadow-[0_2px_0_#9f1239]`}
              >
                <Icon name="plus" size={13} weight="bold" />
                Nueva solicitud
              </button>
              <button
                type="button"
                onClick={() => void load(false)}
                disabled={loading}
                className="rounded-lg border border-accent/30  px-2.5 py-1 text-xs font-bold text-accent  hover:bg-accent/10  disabled:opacity-50"
              >
                ↻
              </button>
              {onInicio && (
                <button
                  type="button"
                  onClick={onInicio}
                  className="flex items-center gap-1 rounded-lg border border-border/60 px-2.5 py-1 text-xs font-bold text-muted hover:border-accent hover:text-accent transition"
                  title="Volver al inicio"
                >
                  <TopicIcon value="🏠" size={13} className="shrink-0" /> Inicio
                </button>
              )}
            </div>
          </div>
        </div>
      ) : (
        <div className="flex flex-wrap items-center gap-2">
          {onInicio && (
            <button
              type="button"
              onClick={onInicio}
              className="flex items-center gap-1 rounded-xl border-2 border-border px-3 py-1.5 text-xs font-bold text-muted hover:border-accent hover:text-accent transition shrink-0"
              title="Volver al inicio"
            >
              <TopicIcon value="🏠" size={14} className="shrink-0" /> Inicio
            </button>
          )}
          <button
            type="button"
            onClick={() => setTab("subhome")}
            className="flex items-center gap-1.5 rounded-xl border-2 border-border px-3 py-1.5 text-xs font-bold text-muted hover:border-accent hover:text-accent transition"
          >
            ← Volver a Solicitudes
          </button>
          <button
            type="button"
            onClick={() => setShowWizard(true)}
            className="ml-auto quest-board-toolbar-btn quest-board-toolbar-btn--active flex items-center gap-1 px-3 shrink-0"
          >
            <Icon name="plus" size={14} weight="bold" />
            Nueva solicitud
          </button>
        </div>
      )}

      {/* Título de la sub-sección activa */}
      {tab !== "subhome" && (
        <p className="text-base font-extrabold text-ink">
          {tab === "asignadas" ? <TopicIconLabel value="📥" size={16} weight="bold">Por resolver</TopicIconLabel>
            : tab === "creadas" ? <TopicIconLabel value="📤" size={16} weight="bold">Enviadas</TopicIconLabel>
            : tab === "equipo" ? <TopicIconLabel value="👥" size={16} weight="bold">En curso — equipo</TopicIconLabel>
            : tab === "historial" ? <TopicIconLabel value="📜" size={16} weight="bold">Historial</TopicIconLabel>
            : <TopicIconLabel value="📋" size={16} weight="bold">Procedimientos</TopicIconLabel>}
        </p>
      )}

      {msg && (
        <p className="rounded-xl border border-accent/30 bg-accent/8 px-4 py-2 text-sm text-accent font-semibold">
          {msg}
        </p>
      )}

      {/* ── Sub-home: cards de solicitudes ── */}
      {tab === "subhome" && !loading && (() => {
        const sc = [
          "group flex flex-col gap-5 rounded-3xl border p-6 text-left w-full",
          "shadow-[0_2px_14px_rgba(0,0,0,0.06)] hover:shadow-[0_6px_22px_rgba(0,0,0,0.10)]",
          "transition-all duration-200 cursor-pointer active:scale-[0.97]",
        ].join(" ");
        const total = otrasAsignadas.length + comprasPendientes.length;
        return (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">

            <button type="button" onClick={() => setTab("asignadas")}
              className={`${sc} bg-accent/5  border-accent/20`}>
              <div className="flex items-center justify-between gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="📥" size={24} />
                </span>
                <span className="text-4xl font-black text-ink dark:text-white tabular-nums leading-none tracking-tight">{total}</span>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">Por resolver</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Solicitudes que te asignaron y te están esperando. Ábrelas, ejecútalas y márcalas como listas.</p>
            </button>

            <button type="button" onClick={() => setTab("creadas")}
              className={`${sc} bg-accent/5  border-accent/20`}>
              <div className="flex items-center justify-between gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="📤" size={24} />
                </span>
                <span className="text-4xl font-black text-ink dark:text-white tabular-nums leading-none tracking-tight">{creadas.length}</span>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">Enviadas</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Lo que tú le pediste a alguien del equipo. Revisa cómo van las tareas que mandaste.</p>
            </button>

            <button type="button" onClick={() => setTab("equipo")}
              className={`${sc} bg-accent/5  border-accent/20`}>
              <div className="flex items-center justify-between gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="👥" size={24} />
                </span>
                <span className="text-4xl font-black text-ink dark:text-white tabular-nums leading-none tracking-tight">{enEquipo.length}</span>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">En curso — equipo</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Un vistazo general a lo que tiene todo el equipo activo en este momento.</p>
            </button>

            <button type="button" onClick={() => setTab("historial")}
              className={`${sc} bg-stone-50 dark:bg-stone-900/60 border-stone-200 dark:border-stone-600/50`}>
              <div className="flex items-center gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="📜" size={24} />
                </span>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">Historial</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Las solicitudes que ya se cerraron — resueltas o rechazadas. Pa' que quede el registro.</p>
            </button>

            <button type="button" onClick={() => setTab("protocolos")}
              className={`${sc} bg-accent/5  border-accent/20`}>
              <div className="flex items-center justify-between gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="📋" size={24} />
                </span>
                <span className="text-4xl font-black text-ink dark:text-white tabular-nums leading-none tracking-tight">{protocolos.length}</span>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">Procedimientos</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Procesos del equipo listos pa' delegar. Asígnale uno a alguien sin explicar todo desde cero.</p>
            </button>

            {etiquetasPendientes.length > 0 && puedeVerSeccionPanel(user, "etiquetas") && (
              <button
                type="button"
                onClick={() => {
                  useAppStore.getState().setEtiquetasTab("imprimir");
                  useAppStore.getState().setPanel("etiquetas");
                }}
                className={`${sc} bg-accent/5  border-accent/30`}
              >
                <div className="flex items-center justify-between gap-3">
                  <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                    <TopicIcon value="🏷️" size={24} />
                  </span>
                  <span className="text-4xl font-black text-ink dark:text-white tabular-nums leading-none tracking-tight">
                    {etiquetasPendientes.length}
                  </span>
                </div>
                <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">Pedidos de etiquetas</p>
                <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">
                  Te llegaron al apartado Impresora · Etiquetas. Abre Imprimir para ver la lista y ejecutar cada pedido.
                </p>
              </button>
            )}

          </div>
        );
      })()}

      {tab !== "subhome" && tab !== "historial" && (
        <div className="flex justify-end">
          <button
            type="button"
            onClick={() => void load(false)}
            disabled={loading}
            className="text-xs text-accent hover:underline disabled:opacity-50"
          >
            ↻ Actualizar lista
          </button>
        </div>
      )}

      {tab === "subhome" && loading && <div className="py-8 text-center text-sm text-muted">Cargando solicitudes…</div>}

      {tab !== "subhome" && loading && <div className="py-8 text-center text-sm text-muted">Cargando solicitudes…</div>}
      {tab === "historial" && loadingHistorial && <div className="py-8 text-center text-sm text-muted">Cargando historial…</div>}

      {tab === "asignadas" && !loading && comprasPendientes.length > 0 && (
        <div className="space-y-2">
          <p className="text-xs font-bold uppercase tracking-wide text-accent">Ir de compras</p>
          {comprasPendientes.map((t) => (
            <button
              key={t.id}
              type="button"
              onClick={() => setCompraActiva(t)}
              className="w-full rounded-xl border-2 border-accent/50 bg-accent/60  px-4 py-3 text-left transition hover:border-accent"
            >
              <p className="text-sm font-bold text-ink">🛒 {t.titulo}</p>
              <p className="text-xs text-muted font-mono">{t.numero}</p>
              {t.ticket_padre_titulo && (
                <p className="mt-1 text-xs text-muted">Para: {t.ticket_padre_titulo}</p>
              )}
              <p className="mt-2 text-xs font-bold text-accent">Toca para abrir → Iniciar compras</p>
            </button>
          ))}
        </div>
      )}

      {tab !== "subhome" && !loading && !loadingHistorial && lista.length === 0 && (tab !== "asignadas" || comprasPendientes.length === 0) && (
        <div className="py-12 text-center space-y-2">
          <p className="text-sm text-muted">
            {tab === "asignadas"
              ? "No tienes solicitudes pendientes."
              : tab === "creadas"
                ? "No tienes solicitudes activas enviadas."
                : tab === "historial"
                  ? "No hay solicitudes resueltas en tu historial."
                  : "No hay solicitudes en curso en el equipo."}
          </p>
          {tab === "historial" && (
            <button
              type="button"
              onClick={() => void cargarHistorial()}
              className="text-xs text-accent hover:underline"
            >
              ↻ Recargar historial
            </button>
          )}
        </div>
      )}

      {/* Vista historial: agrupado por miembro asignado (desplegable) */}
      {tab === "historial" && !loading && !loadingHistorial && historial.length > 0 && (
        <div className="space-y-3">
          <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
            <p className="text-xs text-muted flex items-center gap-1">
              {historialFiltrado.length === historial.length
                ? `${historial.length} solicitud${historial.length !== 1 ? "es" : ""} completada${historial.length !== 1 ? "s" : ""} o rechazada${historial.length !== 1 ? "s" : ""}`
                : `${historialFiltrado.length} de ${historial.length} coinciden con la búsqueda`}
              <InfoTooltip text="Agrupadas por quien las atendió. Solo aparecen resueltas o rechazadas (las activas están en «Enviadas» o «Por resolver»). Busca por nombre, título o número." />
            </p>
            <input
              type="search"
              value={historialBusqueda}
              onChange={(e) => setHistorialBusqueda(e.target.value)}
              placeholder="Buscar: Stella, fórmulas, TKT-…"
              className="w-full sm:w-64 rounded-xl border-2 border-border bg-surface px-3 py-2 text-sm text-ink placeholder:text-muted focus:border-accent focus:outline-none"
              aria-label="Buscar en historial de solicitudes"
            />
          </div>
          {historialFiltrado.length === 0 && (
            <p className="py-6 text-center text-sm text-muted">
              Ninguna solicitud resuelta coincide con «{historialBusqueda.trim()}».
            </p>
          )}
          {historialPorAsignado.map(({ uid, nombre, items }) => {
            const abierto = historialGruposAbiertos.has(uid);
            return (
              <div key={uid} className="overflow-hidden rounded-xl border border-border bg-surface-panel/60">
                <button
                  type="button"
                  onClick={() => toggleHistorialGrupo(uid)}
                  aria-expanded={abierto}
                  className="flex w-full items-center gap-2 px-3 py-2.5 text-left transition hover:bg-surface-hover"
                >
                  <span
                    className={`shrink-0 text-[10px] text-muted transition-transform duration-200 ${abierto ? "" : "-rotate-90"}`}
                    aria-hidden
                  >
                    ▼
                  </span>
                  <Icon name="user" size={13} className="shrink-0 text-muted" />
                  <span className="min-w-0 flex-1 truncate text-xs font-bold uppercase tracking-wide text-ink">
                    {nombre}
                    {(() => {
                      const uname = usuarios.find((u) => u.id === uid)?.username?.replace(/^@/, "");
                      return uname ? ` · @${uname}` : "";
                    })()}
                  </span>
                  <span className="shrink-0 rounded-full border border-border bg-surface px-1.5 py-0.5 text-[10px] text-muted">
                    {items.length}
                  </span>
                </button>
                {abierto && (
                  <div className="space-y-2 border-t border-border/60 px-3 pb-3 pt-2">
                    {items.map((t) => (
                      <HistorialSolicitudCard
                        key={t.id}
                        ticket={t}
                        user={user}
                        token={token}
                        chatAbierto={historialChatId === t.id}
                        onToggleChat={() => setHistorialChatId((prev) => (prev === t.id ? null : t.id))}
                        onClick={() => setSelectedHistorialTicket(t)}
                        onConversacionActualizada={() => void cargarHistorial()}
                        onSolicitudReabierta={() => {
                          setHistorialChatId(null);
                          void load(true);
                          void cargarHistorial();
                          setTab("asignadas");
                          setMsg("Solicitud reabierta — revisa en activas");
                          setTimeout(() => setMsg(""), 3500);
                        }}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {tab === "equipo" && !loading && equipoPorAsignado.length > 0 && (
        <div className="space-y-5">
          {equipoPorAsignado.map(({ nombre, items }) => (
            <div key={nombre}>
              <div className="mb-2 flex items-center gap-2">
                <Icon name="user" size={13} className="text-muted" />
                <span className="text-xs font-bold uppercase tracking-wide text-muted">{nombre}</span>
                <span className="rounded-full bg-surface border border-border px-1.5 py-0.5 text-[10px] text-muted">{items.length}</span>
              </div>
              <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
                {items.map((t) => (
                  <SolicitudCard
                    key={t.id}
                    ticket={t}
                    token={token}
                    user={user}
                    isAdmin={isAdmin}
                    supervision
                    onChanged={() => void load(true)}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {tab === "asignadas" && asignadaDetalle && (
        <div className="space-y-4">
          <button
            type="button"
            onClick={() => setAsignadaDetalle(null)}
            className="flex items-center gap-1.5 rounded-xl border border-border px-3 py-2 text-sm font-bold text-muted hover:border-accent hover:text-accent transition-colors"
          >
            <svg className="h-4 w-4" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
            </svg>
            Por resolver
          </button>
          <SolicitudCard
            ticket={asignadaDetalle}
            token={token}
            user={user}
            isAdmin={isAdmin}
            protocolos={protocolos}
            detalleAmpliado
            onIrAIntervencion={abrirIntervencionBloqueante}
            onChanged={() => void load(true)}
            onRegistrarEjecucion={
              esSolicitudCompraDelegada(asignadaDetalle)
                ? undefined
                : (sol) => void iniciarEjecucionSolicitud(sol)
            }
          />
        </div>
      )}

      {tab === "asignadas" && !asignadaDetalle && !loading && etiquetasPendientes.length > 0 && puedeVerSeccionPanel(user, "etiquetas") && (
        <div className="rounded-xl border-2 border-accent/30 bg-accent/5 px-4 py-3">
          <p className="text-sm font-bold text-accent">
            🏷️ {etiquetasPendientes.length} pedido{etiquetasPendientes.length !== 1 ? "s" : ""} de etiquetas
          </p>
          <p className="mt-1 text-xs text-accent">
            Estos pedidos están en Impresora · Etiquetas, no en esta lista de solicitudes.
          </p>
          <button
            type="button"
            onClick={() => {
              useAppStore.getState().setEtiquetasTab("imprimir");
              useAppStore.getState().setPanel("etiquetas");
            }}
            className="mt-2 rounded-lg bg-accent px-4 py-2 text-xs font-bold text-white hover:bg-accent"
          >
            Abrir Impresora · Etiquetas →
          </button>
        </div>
      )}

      {tab === "asignadas" && !asignadaDetalle && !loading && otrasAsignadas.length > 0 && (
        <div className="space-y-2">
          <p className="text-xs text-muted">
            {otrasAsignadas.length} solicitud{otrasAsignadas.length !== 1 ? "es" : ""} pendiente{otrasAsignadas.length !== 1 ? "s" : ""}
            {" · "}
            Toca una para ver el detalle completo
          </p>
          <div className="grid gap-2 sm:grid-cols-2">
            {otrasAsignadas.map((t) => (
              <SolicitudResumenCard
                key={t.id}
                ticket={t}
                user={user}
                onClick={() => setAsignadaDetalle(t)}
              />
            ))}
          </div>
        </div>
      )}

      {tab === "creadas" && (
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {!loading && creadas.map((t) => (
            <SolicitudCard
              key={t.id}
              ticket={t}
              token={token}
              user={user}
              isAdmin={isAdmin}
              protocolos={protocolos}
              onIrAIntervencion={abrirIntervencionBloqueante}
              onChanged={() => void load(true)}
              onRegistrarEjecucion={
                esSolicitudCompraDelegada(t)
                  ? undefined
                  : (sol) => void iniciarEjecucionSolicitud(sol)
              }
            />
          ))}
        </div>
      )}

      {tab !== "equipo" && tab !== "historial" && tab !== "protocolos" && tab !== "asignadas" && tab !== "creadas" && (
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {!loading && lista.map((t) => (
            <SolicitudCard
              key={t.id}
              ticket={t}
              token={token}
              user={user}
              isAdmin={isAdmin}
              protocolos={protocolos}
              onChanged={() => void load(true)}
              onRegistrarEjecucion={
                esSolicitudCompraDelegada(t)
                  ? undefined
                  : (sol) => void iniciarEjecucionSolicitud(sol)
              }
            />
          ))}
        </div>
      )}

      {/* Vista protocolos */}
      {tab === "protocolos" && (
        <ProtocolosView
          token={token}
          user={user}
          protocolos={protocolos}
          loading={loadingProtocolos}
          onRecargar={() => void cargarProtocolos()}
          onUsarProtocolo={() => { setShowWizard(true); setTab("asignadas"); }}
        />
      )}
    </div>
  );
}

// ── RepetirAccionWizard ───────────────────────────────────────────────────────

type FaseRepetir = "iniciando" | "bienvenida" | "compras_lista" | "compras_tienda" | "paso" | "cierre" | "completada";

type ReanudarRepetirState = {
  ticketId: number;
  pasosIds: number[];
  corridaId: number | null;
  segundosBase: number;
  startPasoIdx: number;
};

function RepetirAccionWizard({
  token,
  user,
  chatApiToken,
  plantilla,
  solicitudPadreId,
  reanudar,
  onCancel,
  onCreated,
}: {
  token: string;
  user: TicketsUser;
  chatApiToken: string | null | undefined;
  plantilla: PlantillaAccion;
  solicitudPadreId?: number;
  reanudar?: ReanudarRepetirState;
  onCancel: () => void;
  onCreated: (ticketId: number) => void;
}) {
  const stt = useStt(token, chatApiToken);
  const [fase, setFase] = useState<FaseRepetir>("iniciando");
  const [slideDir, setSlideDir] = useState<"right" | "left">("right");
  const [ticketId, setTicketId] = useState<number | null>(reanudar?.ticketId ?? null);
  const [pasosIds, setPasosIds] = useState<number[]>(reanudar?.pasosIds ?? []);
  const [pasoIdx, setPasoIdx] = useState(reanudar?.startPasoIdx ?? 0);
  const [reporteTexto, setReporteTexto] = useState("");
  const [completando, setCompletando] = useState(false);
  const [error, setError] = useState("");
  const [listaCompras, setListaCompras] = useState<ItemCompraAccion[]>(() =>
    plantilla.listaCompras.filter((m) => m.n.trim()).map((m) => ({ ...m, comprado: false }))
  );
  const [usuariosDelegar, setUsuariosDelegar] = useState<UserInfo[]>([]);
  const [delegarAId, setDelegarAId] = useState<number | "">("");
  const [delegacionMsg, setDelegacionMsg] = useState("");
  const [delegando, setDelegando] = useState(false);
  const [pasoFile, setPasoFile] = useState<File | null>(null);
  const [cierreFile, setCierreFile] = useState<File | null>(null);
  const pasoEjecRef = useRef<HTMLDivElement>(null);
  const pasoInicioRef = useRef(Date.now());
  const corridaIdRef = useRef<number | null>(reanudar?.corridaId ?? null);

  usePegarCapturaEnZona(fase === "paso", pasoEjecRef, (file) => setPasoFile(file));

  const activeTicketId = ticketId ?? reanudar?.ticketId ?? 0;
  const cronometro = useTicketCronometro(activeTicketId, token);

  const pasos = plantilla.pasos;
  const totalItems = pasos.length;
  const posActual = fase === "paso" ? pasoIdx : totalItems;
  const pct = totalItems > 0 ? Math.round((posActual / totalItems) * 100) : 0;
  const todosComprados = listaCompras.every((m) => !m.n.trim() || m.comprado);

  useEffect(() => {
    if (fase === "paso") pasoInicioRef.current = Date.now();
  }, [fase, pasoIdx]);

  useEffect(() => { void init(); }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (fase !== "compras_lista" || usuariosDelegar.length > 0) return;
    tapi("/usuarios", token)
      .then((data) => setUsuariosDelegar(Array.isArray(data) ? data : []))
      .catch(() => setUsuariosDelegar([]));
  }, [fase, token, usuariosDelegar.length]);

  async function init() {
    // ── Reanudar acción existente ──
    if (reanudar) {
      corridaIdRef.current = reanudar.corridaId;
      pasoInicioRef.current = Date.now();
      if (reanudar.startPasoIdx >= pasos.length && pasos.length > 0) {
        setFase("cierre");
      } else if (pasos.length > 0) {
        setFase("paso");
      } else {
        setFase("cierre");
      }
      return;
    }

    // ── Nueva acción ──
    try {
      const ticket = await tapi("/", token, {
        method: "POST",
        body: JSON.stringify({
          titulo: plantilla.titulo,
          descripcion: plantilla.titulo,
          prioridad: "media",
          categoria: "logistica",
          asignado_a: user.id,
          tipo: "accion",
          ticket_padre_id: solicitudPadreId ?? undefined,
          protocolo_id: plantilla.protocoloId ?? undefined,
        }),
      }) as Ticket;
      const tid = ticket.id;
      setTicketId(tid);
      try {
        const cr = await tapi(`/${tid}/corridas/iniciar`, token, {
          method: "POST", body: JSON.stringify({ segundos_previos: 0 }),
        }) as Ticket;
        corridaIdRef.current = cr.corrida?.id ?? null;
      } catch { /* hook sincroniza */ }
      pasoInicioRef.current = Date.now();
      const ids: number[] = [];
      for (const p of pasos) {
        try {
          const saved = await tapi(`/${tid}/pasos`, token, {
            method: "POST",
            body: JSON.stringify({ descripcion: p.nombre, notas: p.desc || "" }),
          }) as { id: number };
          ids.push(saved.id);
        } catch { /* no crítico */ }
      }
      setPasosIds(ids);
      setFase("bienvenida");
    } catch (e: any) {
      setError(e.message ?? "No se pudo iniciar la acción");
    }
  }

  async function delegarListaCompras() {
    if (!delegarAId) return;
    const items = listaCompras.filter((m) => m.n.trim());
    if (items.length === 0) { setError("Lista vacía"); return; }
    setDelegando(true);
    setError("");
    try {
      const tid = ticketId!;
      await tapi(`/${tid}/delegar-compras`, token, {
        method: "POST",
        body: JSON.stringify({ asignado_a: delegarAId, items }),
      });
      const nombre = usuariosDelegar.find((u) => u.id === delegarAId)?.nombre ?? "compañero";
      setDelegacionMsg(`✅ Lista enviada a ${nombre}`);
      setDelegarAId("");
    } catch (e) {
      setError(e instanceof Error ? e.message : "No se pudo delegar la lista");
    } finally {
      setDelegando(false);
    }
  }

  async function avanzarPaso() {
    const pid = pasosIds[pasoIdx];
    const duracionSeg = Math.max(1, Math.floor((Date.now() - pasoInicioRef.current) / 1000));
    pasoInicioRef.current = Date.now();
    if (pid && ticketId) {
      try {
        if (pasoFile) {
          const fd = new FormData();
          fd.append("archivo", pasoFile);
          await fetch(`/api/tickets/${ticketId}/pasos/${pid}/adjuntos`, {
            method: "POST",
            headers: { Authorization: `Bearer ${token}` },
            body: fd,
          });
        }
        await tapi(`/${ticketId}/pasos/${pid}`, token, {
          method: "PUT", body: JSON.stringify({ completado: 1, duracion_segundos: duracionSeg }),
        });
      } catch { /* no crítico */ }
    }
    setPasoFile(null);
    const next = pasoIdx + 1;
    setSlideDir("right");
    if (next >= pasos.length) {
      setFase("cierre");
    } else {
      setPasoIdx(next);
    }
  }

  function retrocederPaso() {
    setSlideDir("left");
    if (pasoIdx === 0) {
      setFase("bienvenida");
      return;
    }
    setPasoIdx(pasoIdx - 1);
  }

  async function completar() {
    if (solicitudPadreId && !reporteTexto.trim()) {
      setError("Escribe el reporte para quien te hizo la solicitud");
      return;
    }
    setCompletando(true);
    setError("");
    try {
      const tid = ticketId!;
      if (corridaIdRef.current) {
        try { await tapi(`/corridas/${corridaIdRef.current}/finalizar`, token, { method: "POST" }); } catch { /* */ }
      }
      if (cierreFile) {
        try {
          const fd = new FormData();
          fd.append("archivo", cierreFile);
          await fetch(`/api/tickets/${tid}/adjuntos`, {
            method: "POST",
            headers: { Authorization: `Bearer ${token}` },
            body: fd,
          });
        } catch { /* no crítico */ }
      }
      const res = await fetch(`/api/tickets/${tid}/completar-accion`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          reporte: reporteTexto.trim(),
          lista_compras: listaCompras,
          cerrar_solicitud: !!solicitudPadreId,
        }),
      });
      if (!res.ok && res.status !== 404) {
        const d = await res.json().catch(() => ({}));
        throw new Error((d as any).error || `Error ${res.status}`);
      }
      if (res.status === 404) {
        await tapi(`/${tid}/estado`, token, { method: "PUT", body: JSON.stringify({ estado: "resuelto" }) });
        if (solicitudPadreId) {
          await tapi(`/${solicitudPadreId}/estado`, token, { method: "PUT", body: JSON.stringify({ estado: "resuelto" }) });
        }
      }
      if (activeTicketId) localStorage.removeItem(`mckenna-accion-alarma-${activeTicketId}`);
      setFase("completada");
    } catch (e: any) {
      setError(e.message ?? "Error al completar");
    } finally {
      setCompletando(false);
    }
  }

  const slide = slideDir === "right" ? "mck-slide-right" : "mck-slide-left";

  // ── Iniciando ──
  if (fase === "iniciando") {
    if (error) return (
      <div className="flex min-h-[70vh] flex-col items-center justify-center gap-5 text-center px-6">
        <TopicIcon value="⚠️" size={40} className="text-muted" />
        <p className="text-base font-bold text-ink">{error}</p>
        <button onClick={onCancel} className="rounded-2xl border-2 border-border px-6 py-3 text-sm font-bold text-muted hover:border-accent hover:text-accent transition">
          Cancelar
        </button>
      </div>
    );
    return (
      <div className="flex min-h-[70vh] flex-col items-center justify-center gap-5 text-center px-6">
        <div className="h-12 w-12 rounded-full border-4 border-border border-t-accent animate-spin" />
        <div className="space-y-1">
          <p className="text-lg font-extrabold text-ink">{plantilla.titulo}</p>
          <p className="text-sm text-muted">Preparando acción…</p>
        </div>
      </div>
    );
  }

  // ── Completada 🏆 ──
  if (fase === "completada") {
    return (
      <div className="flex min-h-[70vh] flex-col items-center justify-center gap-6 text-center px-4">
        <div className="relative">
          <div className="mck-bounce-in text-8xl select-none">🏆</div>
          <div className="absolute inset-0 rounded-full pointer-events-none"
            style={{ animation: "mck-ring-pulse 1s ease-out 0.3s both", background: "radial-gradient(circle, rgba(244,196,77,0.4) 0%, transparent 70%)" }} />
        </div>
        <div className="mck-slide-up space-y-2" style={{ animationDelay: "0.2s" }}>
          <p className="text-xs font-bold uppercase tracking-widest text-accent">¡Acción completada!</p>
          <h2 className="text-4xl font-extrabold text-ink">{plantilla.titulo}</h2>
          {pasos.length > 0 && (
            <p className="text-sm text-muted">{pasos.length} paso{pasos.length !== 1 ? "s" : ""} completado{pasos.length !== 1 ? "s" : ""}</p>
          )}
          <div className="flex justify-center pt-1">
            <div className="flex items-center gap-1.5 rounded-full border border-accent/30 bg-accent/5  dark:border-accent px-3 py-1">
              <span className="text-sm">⏱</span>
              <span className="font-mono text-sm font-extrabold text-accent  tabular-nums">{cronometro.fmt(cronometro.segundos)}</span>
            </div>
          </div>
        </div>
        <button
          onClick={() => onCreated(ticketId!)}
          className="mck-slide-up mt-4 rounded-2xl border-2 border-border px-8 py-3 text-base font-bold text-muted transition hover:border-accent hover:text-accent"
          style={{ animationDelay: "0.4s" }}
        >
          Ver acción completa →
        </button>
      </div>
    );
  }

  const pasoActual = pasos[pasoIdx];

  return (
    <div className="mx-auto w-full max-w-lg pb-10">
      {/* Header */}
      <div className="mb-5 flex items-center justify-between">
        <button
          type="button"
          onClick={async () => {
            if (!confirm("¿Cancelar? La acción iniciada seguirá en tu tablero como borrador.")) return;
            if (ticketId && corridaIdRef.current) {
              try { await cronometro.pausar(); } catch { /* */ }
            }
            onCancel();
          }}
          className="rounded-xl border-2 border-border px-3 py-2 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
        >
          ← Salir
        </button>
        {cronometro.activo && (
          <div className="flex items-center gap-1.5 rounded-full border border-accent/30 bg-accent/8 px-3 py-1">
            <span className="h-1.5 w-1.5 rounded-full bg-accent animate-pulse" />
            <span className="font-mono text-sm font-extrabold text-accent tabular-nums">{cronometro.fmt(cronometro.segundos)}</span>
          </div>
        )}
        {fase === "paso" && totalItems > 0 && (
          <span className="text-xs font-bold text-muted">{pasoIdx + 1} / {totalItems}</span>
        )}
        {(fase === "cierre" || fase === "bienvenida" || fase === "compras_lista" || fase === "compras_tienda") && <span />}
      </div>

      {activeTicketId > 0 && (
        <AccionAlarmaRecordatorio
          ticketId={activeTicketId}
          tituloAccion={plantilla.titulo}
          cronometroActivo={cronometro.activo}
        />
      )}

      {/* Barra de progreso — solo durante los pasos */}
      {totalItems > 0 && fase === "paso" && (
        <div className="mb-8 h-2.5 w-full overflow-hidden rounded-full bg-border">
          <div
            className="h-full rounded-full bg-accent transition-all duration-700 ease-out"
            style={{ width: `${Math.max(pct, 2)}%` }}
          />
        </div>
      )}

      {error && (
        <p className="mb-4 rounded-xl border border-danger/30 bg-danger/10 px-4 py-3 text-sm text-danger">{error}</p>
      )}

      {/* ── Bienvenida ── */}
      {fase === "bienvenida" && (
        <div key="rep-bienvenida" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">Tu acción ha comenzado</p>
            <h2 className="text-2xl font-extrabold text-ink leading-tight">{plantilla.titulo}</h2>
          </div>
          <div className="space-y-3">
            <p className="text-sm text-muted">¿Necesitas conseguir ingredientes o materiales antes?</p>
            {listaCompras.length > 0 && (
              <button
                type="button"
                onClick={() => { setSlideDir("right"); setFase("compras_lista"); }}
                className="w-full flex items-center gap-4 rounded-2xl border-2 border-border bg-surface-panel px-5 py-4 text-left transition hover:border-accent/60"
              >
                <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-border bg-surface text-ink">
                  <TopicIcon value="🛒" size={22} />
                </span>
                <div>
                  <p className="text-base font-extrabold text-ink">Ir de compras</p>
                  <p className="text-xs text-muted">
                    {listaCompras.length} {listaCompras.length === 1 ? "producto" : "productos"} en lista
                  </p>
                </div>
              </button>
            )}
            <button
              type="button"
              onClick={() => { setSlideDir("right"); setFase(pasos.length > 0 ? "paso" : "cierre"); }}
              className="w-full rounded-2xl border-2 border-border py-3.5 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
            >
              Ya tengo todo · continuar →
            </button>
          </div>
        </div>
      )}

      {/* ── Lista de compras (read-only + delegable) ── */}
      {fase === "compras_lista" && (
        <div key="rep-compras-lista" className={`space-y-5 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">Lista de compras</p>
            <h2 className="text-2xl font-extrabold text-ink leading-tight">{plantilla.titulo}</h2>
            <p className="mt-1 text-sm text-muted">Productos necesarios para esta acción.</p>
          </div>

          <div className="space-y-2">
            {listaCompras.map((m, mi) => !m.n.trim() ? null : (
              <div key={mi} className="flex items-center gap-3 rounded-2xl border-2 border-border bg-surface-panel px-4 py-3">
                <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border-2 border-border text-sm font-bold text-muted">
                  {mi + 1}
                </span>
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-bold text-ink">{m.n.trim()}</p>
                  {formatCantidadItem(m) && <p className="text-xs text-muted">{formatCantidadItem(m)}</p>}
                </div>
              </div>
            ))}
          </div>

          <div className="rounded-2xl border border-accent/30 bg-accent/30  p-3 space-y-2">
            <p className="text-xs font-bold text-ink">¿Alguien más va de compras?</p>
            <p className="text-[11px] text-muted">Crea una solicitud con este checklist para esa persona.</p>
            <select
              className="quest-input w-full text-sm"
              value={delegarAId}
              onChange={(e) => setDelegarAId(e.target.value ? Number(e.target.value) : "")}
            >
              <option value="">Elegir compañero…</option>
              {usuariosDelegar
                .filter((u) => u.id !== user.id && u.activo !== 0)
                .map((u) => (
                  <option key={u.id} value={u.id}>{u.nombre}</option>
                ))}
            </select>
            <button
              type="button"
              disabled={delegando || !delegarAId}
              onClick={() => void delegarListaCompras()}
              className="w-full rounded-xl border-2 border-accent/50 py-2.5 text-sm font-bold text-accent  hover:bg-accent/10 disabled:opacity-40"
            >
              {delegando ? "Enviando…" : "Enviar lista a compañero"}
            </button>
            {delegacionMsg && <p className="text-xs font-semibold text-accent">{delegacionMsg}</p>}
          </div>

          {error && (
            <p className="rounded-xl border border-danger/30 bg-danger/10 px-4 py-3 text-sm text-danger">{error}</p>
          )}

          <button
            type="button"
            onClick={() => { setSlideDir("right"); setFase("compras_tienda"); }}
            className="w-full rounded-2xl bg-accent py-4 text-base font-extrabold text-white transition hover:brightness-110"
          >
            Yo voy de compras →
          </button>
          <button
            type="button"
            onClick={() => { setSlideDir("left"); setFase("bienvenida"); }}
            className="w-full rounded-2xl border-2 border-border py-3 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
          >
            ← Atrás
          </button>
        </div>
      )}

      {/* ── En la tienda (checklist) ── */}
      {fase === "compras_tienda" && (
        <div key="rep-compras-tienda" className={`space-y-5 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">En la tienda</p>
            <h2 className="text-2xl font-extrabold text-ink leading-tight">Marca cada producto al conseguirlo</h2>
          </div>

          <div className="space-y-2">
            {listaCompras.map((m, mi) => !m.n.trim() ? null : (
              <button
                key={mi}
                type="button"
                onClick={() => setListaCompras((ms) => ms.map((x, j) => (j === mi ? { ...x, comprado: !x.comprado } : x)))}
                className={`w-full flex items-center gap-3 rounded-2xl border-2 px-4 py-3 text-left transition
                  ${m.comprado ? "border-accent bg-accent/10" : "border-border bg-surface-panel hover:border-accent/40"}`}
              >
                <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border-2 text-sm font-bold
                  ${m.comprado ? "border-accent bg-accent text-white" : "border-border text-muted"}`}>
                  {m.comprado ? "✓" : ""}
                </span>
                <div className="min-w-0 flex-1">
                  <p className={`text-sm font-bold ${m.comprado ? "text-accent line-through decoration-accent/50" : "text-ink"}`}>
                    {m.n.trim()}
                  </p>
                  {formatCantidadItem(m) && <p className="text-xs text-muted">{formatCantidadItem(m)}</p>}
                </div>
              </button>
            ))}
          </div>

          <button
            type="button"
            disabled={!todosComprados}
            onClick={() => { setSlideDir("right"); setFase(pasos.length > 0 ? "paso" : "cierre"); }}
            className="w-full rounded-2xl bg-accent py-4 text-base font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            Ya tengo todo · continuar →
          </button>
          {!todosComprados && listaCompras.filter((m) => m.n.trim()).length > 0 && (
            <p className="text-center text-xs text-muted">
              Marca los {listaCompras.filter((m) => m.n.trim()).length} productos de la lista
            </p>
          )}
          <button
            type="button"
            onClick={() => { setSlideDir("left"); setFase("compras_lista"); }}
            className="w-full rounded-2xl border-2 border-border py-3 text-sm font-bold text-muted transition hover:border-accent hover:text-accent"
          >
            ← Ver lista
          </button>
        </div>
      )}

      {/* ── Paso uno a uno ── */}
      {fase === "paso" && pasoActual && (
        <div
          key={`rep-paso-${pasoIdx}`}
          ref={pasoEjecRef}
          className={`space-y-6 ${slide}`}
          onPaste={(e) => manejarPasteCaptura(e, setPasoFile)}
        >
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent/70 mb-2">
              {plantilla.titulo}
            </p>
            <h2 className="text-[2rem] font-extrabold leading-tight text-ink">
              {pasoActual.nombre}
            </h2>
            {pasoActual.desc && (
              <p className="mt-3 text-base text-muted">{pasoActual.desc}</p>
            )}
          </div>

          {/* Fotos/archivos de referencia del paso original */}
          {pasoActual.adjuntos_ref && pasoActual.adjuntos_ref.length > 0 && (
            <div className="space-y-2">
              <p className="text-[11px] font-bold uppercase tracking-widest text-muted">
                Referencia visual
              </p>
              <div className="flex flex-wrap gap-3">
                {pasoActual.adjuntos_ref.map((a, i) => {
                  const esImagen = a.mime.startsWith("image/") || /\.(jpg|jpeg|png|gif|webp)$/i.test(a.nombre_archivo);
                  const url = ticketsUploadUrl(a.nombre_archivo, token);
                  if (esImagen) {
                    return (
                      <a key={i} href={url} target="_blank" rel="noreferrer" className="shrink-0">
                        <img
                          src={url}
                          alt={`Referencia ${i + 1}`}
                          className="h-44 w-auto max-w-full rounded-2xl border-2 border-border object-cover shadow-md hover:border-accent transition-colors"
                        />
                      </a>
                    );
                  }
                  return (
                    <a key={i} href={url} target="_blank" rel="noreferrer"
                      className="flex items-center gap-2 rounded-2xl border-2 border-border bg-surface px-4 py-3 text-sm font-semibold text-accent hover:border-accent transition-colors">
                      📄 Ver archivo de referencia
                    </a>
                  );
                })}
              </div>
            </div>
          )}

          <label className={`flex items-center gap-3 rounded-2xl border-2 cursor-pointer px-4 py-3 transition
            ${pasoFile ? "border-accent bg-accent/8" : "border-dashed border-border hover:border-accent/60"}`}>
            <span className="text-xl">{pasoFile ? "📎" : "📷"}</span>
            <span className="text-sm font-semibold text-muted truncate">
              {pasoFile ? pasoFile.name : "Adjuntar foto o Ctrl+V para pegar captura"}
            </span>
            {pasoFile && (
              <button
                type="button"
                onClick={(e) => { e.preventDefault(); setPasoFile(null); }}
                className="ml-auto text-xs text-danger hover:underline shrink-0"
              >
                Quitar
              </button>
            )}
            <input
              type="file"
              accept="image/*,.pdf,application/pdf,.doc,.docx"
              className="sr-only"
              onChange={(e) => setPasoFile(e.target.files?.[0] ?? null)}
            />
          </label>
          <button
            type="button"
            onClick={() => void avanzarPaso()}
            className="w-full rounded-2xl bg-accent py-5 text-xl font-extrabold text-white transition hover:brightness-110 active:scale-95 shadow-lg"
          >
            ✓ &nbsp;Hecho
          </button>
          <div className="flex gap-3">
            <button
              type="button"
              onClick={retrocederPaso}
              className="flex-1 rounded-xl border-2 border-border py-2.5 text-sm font-bold text-muted transition hover:border-accent/60 hover:text-accent"
            >
              ← Atrás
            </button>
            <button
              type="button"
              onClick={() => { setPasoFile(null); setSlideDir("right"); const next = pasoIdx + 1; if (next >= pasos.length) setFase("cierre"); else setPasoIdx(next); }}
              className="flex-1 rounded-xl border-2 border-border py-2.5 text-sm font-bold text-muted/60 transition hover:border-accent/30 hover:text-muted"
            >
              Saltar →
            </button>
          </div>
        </div>
      )}

      {/* ── Cierre / reporte ── */}
      {fase === "cierre" && (
        <div key="rep-cierre" className={`space-y-6 ${slide}`}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-accent mb-1">Último paso</p>
            <h2 className="text-3xl font-extrabold text-ink leading-tight">
              {solicitudPadreId ? "Reporte final" : "¡Ya casi!"}
            </h2>
            <p className="mt-2 rounded-2xl border-2 border-accent/30 bg-accent/5 px-4 py-3 text-base font-bold text-ink">
              {plantilla.titulo}
            </p>
          </div>
          {solicitudPadreId ? (
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-wide text-muted">
                Reporte para quien te hizo la solicitud
              </label>
              <div className="flex gap-2">
                <ProseTextarea
                  autoFocus
                  className="w-full rounded-2xl border-2 border-border bg-surface-input px-4 py-3 text-sm text-ink outline-none focus:border-accent resize-none placeholder:text-muted/40"
                  placeholder="Describe cómo quedó la tarea…"
                  rows={4}
                  value={reporteTexto}
                  onChange={(e) => setReporteTexto(e.target.value)}
                />
                <SttInlineBtn stt={stt} onStart={() => void stt.iniciar((t) => setReporteTexto(proseText(t)))} />
              </div>
              <ProseHint />
            </div>
          ) : (
            <p className="text-sm text-muted">¿Todo listo? Marca la acción como completada.</p>
          )}

          <label className={`flex items-center gap-3 rounded-2xl border-2 cursor-pointer px-4 py-3 transition
            ${cierreFile ? "border-accent bg-accent/8" : "border-dashed border-border hover:border-accent/60"}`}>
            <span className="text-xl">{cierreFile ? "📎" : "📷"}</span>
            <span className="text-sm font-semibold text-muted truncate">
              {cierreFile ? cierreFile.name : "Adjuntar foto o evidencia (opcional)"}
            </span>
            {cierreFile && (
              <button
                type="button"
                onClick={(e) => { e.preventDefault(); setCierreFile(null); }}
                className="ml-auto text-xs text-danger hover:underline shrink-0"
              >
                Quitar
              </button>
            )}
            <input
              type="file"
              accept="image/*,.pdf,application/pdf,.doc,.docx"
              className="sr-only"
              onChange={(e) => setCierreFile(e.target.files?.[0] ?? null)}
            />
          </label>

          <button
            type="button"
            disabled={completando || (!!solicitudPadreId && !reporteTexto.trim())}
            onClick={() => void completar()}
            className="w-full rounded-2xl bg-accent py-4 text-lg font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            {completando ? "Completando…" : "Completar acción →"}
          </button>
          {pasos.length > 0 && (
            <button
              type="button"
              onClick={() => { setSlideDir("left"); setPasoIdx(pasos.length - 1); setFase("paso"); }}
              className="w-full text-center text-sm text-muted hover:text-ink transition"
            >
              ← Ver pasos
            </button>
          )}
        </div>
      )}
    </div>
  );
}

interface PendienteItem {
  id: number;
  titulo: string;
  descripcion?: string | null;
  fecha_recordatorio?: string | null;
  estado: "pendiente" | "iniciado" | "descartado";
  ticket_id?: number | null;
  creado_en: string;
}

interface RecordatorioItem {
  id: number;
  titulo: string;
  descripcion?: string | null;
  tipo_rep: "una_vez" | "diario" | "semanal" | "mensual" | "cada_n_dias" | "bimestral";
  proxima_fecha: string;
  cada_n_dias?: number | null;
  dias_semana?: number[] | null;
  dias_semana_parsed?: number[];
  dias_mes?: number[] | null;
  dias_mes_parsed?: number[];
  hora?: string | null;
  activo: number;
  creado_en: string;
  asignado_a?: number | null;
  asignado_a_nombre?: string | null;
  creado_por?: number | null;
  creado_por_nombre?: string | null;
}

// ── PendientesPanel ───────────────────────────────────────────────────────────

function PendientesPanel({
  token,
  pendientes,
  loading,
  onRecargar,
  abrirFormInicial = false,
  abrirFormSignal = 0,
}: {
  token: string;
  pendientes: PendienteItem[];
  loading: boolean;
  onRecargar: () => void;
  abrirFormInicial?: boolean;
  /** Incrementar desde el padre para abrir el formulario (p. ej. CTA del hero). */
  abrirFormSignal?: number;
}) {
  const hoy = new Date().toISOString().slice(0, 10);

  const [titulo, setTitulo] = useState("");
  const [descripcion, setDescripcion] = useState("");
  const [fecha, setFecha] = useState("");
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState("");
  const [editandoId, setEditandoId] = useState<number | null>(null);
  const [editTitulo, setEditTitulo] = useState("");
  const [editDesc, setEditDesc] = useState("");
  const [editFecha, setEditFecha] = useState("");
  const [guardandoEdit, setGuardandoEdit] = useState(false);

  function estadoFecha(f: string | null | undefined): "vencido" | "hoy" | "pronto" | "futuro" | null {
    if (!f) return null;
    if (f < hoy) return "vencido";
    if (f === hoy) return "hoy";
    const diff = Math.ceil((new Date(f).getTime() - new Date(hoy).getTime()) / 86400000);
    return diff <= 3 ? "pronto" : "futuro";
  }

  function fmtFecha(f: string) {
    try {
      const d = new Date(f + "T12:00:00");
      return d.toLocaleDateString("es-CO", { weekday: "short", day: "numeric", month: "short" });
    } catch { return f; }
  }

  async function crear() {
    if (!titulo.trim()) return;
    setGuardando(true);
    setError("");
    try {
      await tapi("/pendientes", token, {
        method: "POST",
        body: JSON.stringify({
          titulo: titulo.trim(),
          descripcion: descripcion.trim() || undefined,
          fecha_recordatorio: fecha || undefined,
        }),
      });
      setTitulo("");
      setDescripcion("");
      setFecha("");
      onRecargar();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error al guardar");
    } finally { setGuardando(false); }
  }

  async function descartar(id: number) {
    try {
      await tapi(`/pendientes/${id}`, token, { method: "DELETE" });
      onRecargar();
    } catch { /* ignore */ }
  }

  function abrirEditar(p: PendienteItem) {
    setEditandoId(p.id);
    setEditTitulo(p.titulo);
    setEditDesc(p.descripcion ?? "");
    setEditFecha(p.fecha_recordatorio ?? "");
  }

  async function guardarEdicion(id: number) {
    if (!editTitulo.trim()) return;
    setGuardandoEdit(true);
    try {
      await tapi(`/pendientes/${id}`, token, {
        method: "PUT",
        body: JSON.stringify({
          titulo: editTitulo.trim(),
          descripcion: editDesc.trim() || null,
          fecha_recordatorio: editFecha || null,
        }),
      });
      setEditandoId(null);
      onRecargar();
    } catch { /* ignore */ } finally { setGuardandoEdit(false); }
  }

  const badgeClases = {
    vencido: "bg-danger/15 text-danger border border-danger/30",
    hoy:     "bg-accent/10  text-accent  border border-accent/50",
    pronto:  "bg-accent/5  text-accent  border border-accent/40",
    futuro:  "bg-surface border border-border text-muted",
  };

  const [showForm, setShowForm] = useState(abrirFormInicial);

  useEffect(() => {
    if (abrirFormInicial) setShowForm(true);
  }, [abrirFormInicial]);

  useEffect(() => {
    if (abrirFormSignal > 0) setShowForm(true);
  }, [abrirFormSignal]);

  function resetForm() {
    setTitulo(""); setDescripcion(""); setFecha(""); setError("");
  }

  return (
    <div className="space-y-3">
      {/* Encabezado con botón crear */}
      <div className="flex items-center justify-between gap-2">
        <p className="text-xs font-bold uppercase tracking-widest text-muted flex items-center gap-2">
          🗓️ Acciones futuras
          {pendientes.length > 0 && (
            <span className="rounded-full bg-accent/10  px-2 py-0.5 text-[10px] font-bold text-accent">
              {pendientes.length}
            </span>
          )}
        </p>
        <button
          type="button"
          onClick={() => { setShowForm((v) => !v); if (showForm) resetForm(); }}
          className={`flex shrink-0 items-center gap-1 rounded-xl border-2 px-3 py-1.5 text-xs font-bold transition ${
            showForm ? "border-border text-muted hover:border-danger hover:text-danger" : "border-accent bg-accent/10 text-accent hover:bg-accent/20"
          }`}
        >
          {showForm ? "✕ Cancelar" : "+ Agregar"}
        </button>
      </div>

      {/* Formulario colapsable */}
      {showForm && (
        <div className="rounded-2xl border-2 border-accent/30 bg-accent/5 p-4 space-y-3">
          <ProseInput
            autoFocus
            className="w-full rounded-xl border-2 border-border bg-surface-input px-4 py-3 text-base font-semibold text-ink outline-none focus:border-accent placeholder:text-muted/40"
            placeholder="Ej: Reparar el computador, revisar la cotización del proveedor…"
            value={titulo}
            onChange={(e) => setTitulo(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter" && titulo.trim()) void crear().then(() => setShowForm(false)); }}
            maxLength={150}
          />
          <ProseTextarea
            className="w-full rounded-xl border-2 border-border bg-surface-input px-4 py-2.5 text-sm text-ink outline-none focus:border-accent resize-none placeholder:text-muted/40"
            placeholder="Detalle opcional…"
            rows={2}
            value={descripcion}
            onChange={(e) => setDescripcion(e.target.value)}
          />
          {/* Fecha opcional */}
          <div className="flex items-center gap-2 rounded-xl border-2 border-border bg-surface-input px-3 py-2">
            <span className="text-base shrink-0">📅</span>
            <span className="text-xs text-muted shrink-0">Fecha recordatorio</span>
            <input
              type="date"
              className="flex-1 bg-transparent text-sm text-ink outline-none"
              value={fecha}
              min={hoy}
              onChange={(e) => setFecha(e.target.value)}
              aria-label="Fecha de recordatorio (opcional)"
            />
            {fecha && (
              <button type="button" onClick={() => setFecha("")} className="shrink-0 text-xs text-muted hover:text-danger">✕</button>
            )}
          </div>
          {!fecha && <p className="text-[11px] text-muted -mt-1">Sin fecha — aparecerá en la lista sin recordatorio</p>}
          {error && <p className="text-xs text-danger">{error}</p>}
          <button
            type="button"
            disabled={!titulo.trim() || guardando}
            onClick={() => void crear().then(() => setShowForm(false))}
            className="w-full rounded-xl bg-accent py-3 text-sm font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            {guardando ? "Guardando…" : "Guardar acción futura"}
          </button>
        </div>
      )}

      {/* Lista */}
      {loading && <p className="py-6 text-center text-sm text-muted">Cargando…</p>}

      {!loading && pendientes.length === 0 && !showForm && (
        <div className="space-y-3 py-12 text-center">
          <p className="text-3xl">🗓️</p>
          <p className="text-sm text-muted">Sin acciones futuras anotadas.</p>
          <p className="text-xs text-muted">Anota ideas o tareas para más adelante. Si necesitas alerta en una fecha, créala en Recordatorios.</p>
          <button
            type="button"
            onClick={() => setShowForm(true)}
            className={`mx-auto ${CENTRO_MANDO_CTA_BTN} bg-accent hover:bg-accent shadow-[0_2px_0_#065f46]`}
          >
            + Nueva acción futura
          </button>
        </div>
      )}

      {!loading && pendientes.length > 0 && (
        <div className="divide-y divide-border/40 rounded-2xl border border-border overflow-hidden">
          {pendientes.map((p) => {
            const ef = estadoFecha(p.fecha_recordatorio);
            const esEditando = editandoId === p.id;
            return (
              <div key={p.id} className="bg-surface-panel">
                {esEditando ? (
                  <div className="p-3 space-y-2">
                    <input
                      autoFocus
                      className="w-full rounded-lg border border-border bg-surface-input px-3 py-2 text-sm font-semibold text-ink outline-none focus:border-accent"
                      value={editTitulo}
                      onChange={(e) => setEditTitulo(e.target.value)}
                      maxLength={150}
                    />
                    <ProseTextarea
                      className="w-full rounded-lg border border-border bg-surface-input px-3 py-2 text-xs text-ink outline-none focus:border-accent resize-none"
                      rows={2}
                      placeholder="Detalle (opcional)"
                      value={editDesc}
                      onChange={(e) => setEditDesc(e.target.value)}
                    />
                    <div className="flex items-center gap-2 rounded-lg border border-border bg-surface-input px-3 py-1.5">
                      <span className="text-sm shrink-0">📅</span>
                      <input
                        type="date"
                        className="flex-1 bg-transparent text-xs text-ink outline-none"
                        value={editFecha}
                        onChange={(e) => setEditFecha(e.target.value)}
                      />
                      {editFecha && (
                        <button type="button" onClick={() => setEditFecha("")} className="text-xs text-muted hover:text-danger">✕</button>
                      )}
                    </div>
                    <div className="flex gap-2">
                      <button
                        type="button"
                        disabled={guardandoEdit || !editTitulo.trim()}
                        onClick={() => void guardarEdicion(p.id)}
                        className="flex-1 rounded-lg bg-accent py-1.5 text-xs font-bold text-white disabled:opacity-40"
                      >
                        {guardandoEdit ? "Guardando…" : "✓ Guardar"}
                      </button>
                      <button
                        type="button"
                        onClick={() => setEditandoId(null)}
                        className="rounded-lg border border-border px-3 py-1.5 text-xs font-bold text-muted hover:border-accent hover:text-accent"
                      >
                        Cancelar
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="flex items-center gap-2 px-3 py-2.5">
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-ink leading-snug truncate">{p.titulo}</p>
                      {p.descripcion && <p className="text-[11px] text-muted truncate">{p.descripcion}</p>}
                    </div>
                    {ef && (
                      <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold ${badgeClases[ef]}`}>
                        {ef === "vencido" ? "⚠ Vencido" : ef === "hoy" ? "Hoy" : fmtFecha(p.fecha_recordatorio!)}
                      </span>
                    )}
                    <button
                      type="button"
                      onClick={() => abrirEditar(p)}
                      className="shrink-0 rounded-lg border border-border px-2 py-1 text-[11px] text-muted hover:border-accent hover:text-accent transition"
                    >✏️</button>
                    <button
                      type="button"
                      onClick={() => void descartar(p.id)}
                      className="shrink-0 rounded-lg border border-border px-2 py-1 text-[11px] text-muted hover:border-danger hover:text-danger transition"
                    >✕</button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ── RecordatoriosPanel ────────────────────────────────────────────────────────

const DIAS_SEMANA_LABELS = ["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"];
const TIPO_REP_LABELS: Record<string, string> = {
  una_vez:    "Una sola vez",
  diario:     "Diario",
  semanal:    "Semanal",
  mensual:    "Mensual",
  bimestral:  "Bimestral",
  cada_n_dias: "Cada N días",
};

function descRepeticion(r: RecordatorioItem): string {
  switch (r.tipo_rep) {
    case "una_vez":    return "Una sola vez";
    case "diario":     return "Todos los días";
    case "bimestral":  return "Cada 2 meses";
    case "cada_n_dias": return `Cada ${r.cada_n_dias ?? "?"} día${(r.cada_n_dias ?? 1) !== 1 ? "s" : ""}`;
    case "semanal": {
      const dias = (r.dias_semana_parsed ?? []).map((d) => DIAS_SEMANA_LABELS[d]).join(", ");
      return dias ? `Cada semana: ${dias}` : "Semanal";
    }
    case "mensual": {
      const dias = (r.dias_mes_parsed ?? []).join(", ");
      return dias ? `Día${(r.dias_mes_parsed ?? []).length !== 1 ? "s" : ""} ${dias} de cada mes` : "Mensual";
    }
    default: return r.tipo_rep;
  }
}

function RecordatoriosPanel({
  token,
  recordatorios,
  loading,
  onRecargar,
  abrirFormInicial = false,
  abrirFormSignal = 0,
  usuarios = [],
  usuarioActualId,
}: {
  token: string;
  recordatorios: RecordatorioItem[];
  loading: boolean;
  onRecargar: () => void;
  abrirFormInicial?: boolean;
  abrirFormSignal?: number;
  usuarios?: { id: number; nombre: string }[];
  usuarioActualId?: number;
}) {
  const hoy = new Date().toISOString().slice(0, 10);
  const [showForm, setShowForm] = useState(abrirFormInicial);
  const [titulo, setTitulo] = useState("");
  const [descripcion, setDescripcion] = useState("");
  const [tipoRep, setTipoRep] = useState<RecordatorioItem["tipo_rep"]>("una_vez");
  const [fechaInicio, setFechaInicio] = useState(hoy);
  const [cadaN, setCadaN] = useState(1);
  const [diasSemana, setDiasSemana] = useState<number[]>([]);
  const [diasMes, setDiasMes] = useState<number[]>([]);
  const [hora, setHora] = useState("");
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState("");
  const [editandoId, setEditandoId] = useState<number | null>(null);
  const [mostrarGridMes, setMostrarGridMes] = useState(false);
  const [asignadoA, setAsignadoA] = useState<number | null>(null);

  useEffect(() => {
    if (abrirFormInicial) setShowForm(true);
  }, [abrirFormInicial]);

  useEffect(() => {
    if (abrirFormSignal > 0) setShowForm(true);
  }, [abrirFormSignal]);

  function resetForm() {
    setTitulo("");
    setDescripcion("");
    setTipoRep("una_vez");
    setFechaInicio(hoy);
    setCadaN(1);
    setDiasSemana([]);
    setDiasMes([]);
    setHora("");
    setError("");
    setAsignadoA(null);
  }

  function toggleDiaSemana(d: number) {
    setDiasSemana((prev) => prev.includes(d) ? prev.filter((x) => x !== d) : [...prev, d].sort());
  }
  function toggleDiaMes(d: number) {
    setDiasMes((prev) => prev.includes(d) ? prev.filter((x) => x !== d) : [...prev, d].sort((a, b) => a - b));
  }

  function editarRecordatorio(r: RecordatorioItem) {
    setTitulo(r.titulo);
    setDescripcion(r.descripcion ?? "");
    setTipoRep(r.tipo_rep);
    setFechaInicio(r.proxima_fecha);
    setCadaN(r.cada_n_dias ?? 1);
    setDiasSemana(r.dias_semana_parsed ?? r.dias_semana ?? []);
    setDiasMes(r.dias_mes_parsed ?? r.dias_mes ?? []);
    setHora(r.hora ?? "");
    setAsignadoA(r.asignado_a ?? null);
    setError("");
    setEditandoId(r.id);
    setShowForm(true);
  }

  async function crear() {
    if (!titulo.trim()) return;
    if (tipoRep === "semanal" && diasSemana.length === 0) { setError("Elige al menos un día de la semana"); return; }
    setGuardando(true); setError("");
    const diaDeInicio = fechaInicio ? parseInt(fechaInicio.split("-")[2], 10) : new Date().getDate();
    const payload = {
      titulo: titulo.trim(),
      descripcion: descripcion.trim() || undefined,
      tipo_rep: tipoRep,
      fecha_inicio: fechaInicio || hoy,
      cada_n_dias: tipoRep === "cada_n_dias" ? cadaN : undefined,
      dias_semana: tipoRep === "semanal" ? diasSemana : undefined,
      dias_mes: tipoRep === "mensual"
        ? (diasMes.length > 0 ? diasMes : [diaDeInicio])
        : undefined,
      hora: hora || undefined,
      asignado_a: asignadoA || undefined,
    };
    try {
      if (editandoId !== null) {
        await tapi(`/recordatorios/${editandoId}`, token, {
          method: "PUT",
          body: JSON.stringify(payload),
        });
        setEditandoId(null);
      } else {
        await tapi("/recordatorios", token, {
          method: "POST",
          body: JSON.stringify(payload),
        });
      }
      resetForm();
      setShowForm(false);
      onRecargar();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error al guardar");
    } finally { setGuardando(false); }
  }

  async function marcarVisto(id: number) {
    try {
      await tapi(`/recordatorios/${id}/visto`, token, { method: "POST" });
      onRecargar();
    } catch { /* ignore */ }
  }

  async function eliminar(id: number) {
    if (!confirm("¿Eliminar este recordatorio?")) return;
    try {
      await tapi(`/recordatorios/${id}`, token, { method: "DELETE" });
      onRecargar();
    } catch { /* ignore */ }
  }

  function fmtFecha(f: string) {
    try {
      return new Date(f + "T12:00:00").toLocaleDateString("es-CO", {
        weekday: "short", day: "numeric", month: "short",
      });
    } catch { return f; }
  }

  const activos = recordatorios.filter((r) => r.proxima_fecha <= hoy);
  const proximos = recordatorios.filter((r) => r.proxima_fecha > hoy);

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between gap-2">
        <p className="text-sm font-semibold text-ink">
          {recordatorios.length > 0
            ? `${recordatorios.length} recordatorio${recordatorios.length !== 1 ? "s" : ""}`
            : "Recordatorios con alerta"}
        </p>
        <button
          type="button"
          onClick={() => { setShowForm((v) => !v); if (showForm) { resetForm(); setEditandoId(null); } }}
          className={`flex shrink-0 items-center gap-1 rounded-xl border-2 px-3 py-1.5 text-xs font-bold transition ${
            showForm ? "border-border text-muted hover:border-danger hover:text-danger" : "border-accent bg-accent/10 text-accent hover:bg-accent/20"
          }`}
        >
          {showForm ? "✕ Cancelar" : "+ Nuevo recordatorio"}
        </button>
      </div>

      {/* Formulario */}
      {showForm && (
      <div className="rounded-2xl border-2 border-accent/30 bg-accent/5 p-4 space-y-3">
        <p className="text-xs font-bold uppercase tracking-widest text-accent">{editandoId !== null ? "Editar recordatorio" : "Nuevo recordatorio"}</p>
        <p className="text-xs text-muted">Tarea con alerta en la fecha que elijas — puntual o recurrente. Te avisamos por voz cuando toque.</p>

        <ProseInput
          className="w-full rounded-xl border-2 border-border bg-surface-input px-4 py-3 text-base font-semibold text-ink outline-none focus:border-accent placeholder:text-muted/40"
          placeholder="Ej: Pagar recibo del celular, llamar al banco, renovar el seguro…"
          value={titulo}
          onChange={(e) => setTitulo(e.target.value)}
          maxLength={150}
        />
        <ProseTextarea
          className="w-full rounded-xl border-2 border-border bg-surface-input px-4 py-2.5 text-sm text-ink outline-none focus:border-accent resize-none placeholder:text-muted/40"
          placeholder="Detalle opcional…"
          rows={2}
          value={descripcion}
          onChange={(e) => setDescripcion(e.target.value)}
        />

        {/* Tipo de repetición */}
        <div className="grid grid-cols-2 gap-1.5 sm:grid-cols-3">
          {(Object.entries(TIPO_REP_LABELS) as [RecordatorioItem["tipo_rep"], string][]).map(([k, lbl]) => (
            <button
              key={k}
              type="button"
              onClick={() => setTipoRep(k)}
              className={`rounded-xl border-2 py-2 text-xs font-bold transition ${
                tipoRep === k ? "border-accent bg-accent text-white" : "border-border text-muted hover:border-accent/60"
              }`}
            >
              {lbl}
            </button>
          ))}
        </div>

        {/* Fecha y hora */}
        <div className="flex gap-2">
          <div className="flex flex-1 items-center gap-2 rounded-xl border-2 border-border bg-surface-input px-3 py-2">
            <span className="text-base">📅</span>
            <span className="text-xs text-muted shrink-0">
              {tipoRep === "una_vez" ? "Fecha:" : "Empieza el:"}
            </span>
            <input
              type="date"
              className="flex-1 bg-transparent text-sm text-ink outline-none"
              value={fechaInicio}
              onChange={(e) => setFechaInicio(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-2 rounded-xl border-2 border-border bg-surface-input px-3 py-2">
            <span className="text-base">🕐</span>
            <input
              type="time"
              className="bg-transparent text-sm text-ink outline-none w-[5.5rem]"
              value={hora}
              onChange={(e) => setHora(e.target.value)}
            />
          </div>
        </div>

        {/* Cada N días */}
        {tipoRep === "cada_n_dias" && (
          <div className="flex items-center gap-3 rounded-xl border-2 border-border bg-surface-input px-4 py-2.5">
            <span className="text-sm text-muted">Repetir cada</span>
            <input
              type="number"
              min={1}
              max={365}
              className="w-20 bg-transparent text-center text-base font-bold text-ink outline-none"
              value={cadaN}
              onChange={(e) => setCadaN(Math.max(1, Number(e.target.value)))}
            />
            <span className="text-sm text-muted">día{cadaN !== 1 ? "s" : ""}</span>
          </div>
        )}

        {/* Días de la semana */}
        {tipoRep === "semanal" && (
          <div className="space-y-1.5">
            <p className="text-xs text-muted font-semibold">Días de la semana:</p>
            <div className="flex gap-1.5 flex-wrap">
              {DIAS_SEMANA_LABELS.map((lbl, i) => (
                <button
                  key={i}
                  type="button"
                  onClick={() => toggleDiaSemana(i)}
                  className={`rounded-lg border-2 px-3 py-1.5 text-xs font-bold transition ${
                    diasSemana.includes(i) ? "border-accent bg-accent text-white" : "border-border text-muted hover:border-accent/60"
                  }`}
                >
                  {lbl}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Días del mes */}
        {tipoRep === "mensual" && (() => {
          const diaAuto = fechaInicio ? parseInt(fechaInicio.split("-")[2], 10) : new Date().getDate();
          const seleccion = diasMes.length > 0 ? diasMes : [diaAuto];
          const PRESETS = [
            { label: "1 y 15", dias: [1, 15] },
            { label: "Día 1", dias: [1] },
            { label: "Día 15", dias: [15] },
            { label: "Día 28", dias: [28] },
          ];
          return (
            <div className="space-y-2">
              {/* Presets rápidos */}
              <div className="flex gap-1.5 flex-wrap">
                {PRESETS.map((p) => {
                  const activo = p.dias.length === seleccion.length && p.dias.every((d) => seleccion.includes(d));
                  return (
                    <button key={p.label} type="button"
                      onClick={() => setDiasMes(p.dias)}
                      className={`rounded-lg border px-2.5 py-1 text-xs font-bold transition ${
                        activo ? "border-accent bg-accent text-white" : "border-border text-muted hover:border-accent/60"
                      }`}>
                      {p.label}
                    </button>
                  );
                })}
                <button type="button" onClick={() => setMostrarGridMes((v) => !v)}
                  className="rounded-lg border border-border px-2.5 py-1 text-xs font-bold text-muted hover:border-accent/60 transition">
                  {mostrarGridMes ? "✕ Cerrar" : "Personalizar…"}
                </button>
              </div>
              {/* Resumen */}
              <p className="text-xs text-muted">
                Se repetirá el <strong className="text-ink">día {seleccion.sort((a, b) => a - b).join(" y ")}</strong> de cada mes
              </p>
              {/* Grid completo */}
              {mostrarGridMes && (
                <div className="grid grid-cols-7 gap-1 pt-1">
                  {Array.from({ length: 31 }, (_, i) => i + 1).map((d) => (
                    <button key={d} type="button" onClick={() => toggleDiaMes(d)}
                      className={`rounded-lg border py-1.5 text-xs font-bold transition ${
                        seleccion.includes(d)
                          ? "border-accent bg-accent text-white"
                          : "border-border text-muted hover:border-accent/50"
                      }`}>
                      {d}
                    </button>
                  ))}
                </div>
              )}
            </div>
          );
        })()}

        {/* Asignar a miembro del equipo */}
        {usuarios.length > 0 && (
          <div className="flex items-center gap-2 rounded-xl border-2 border-border bg-surface-input px-3 py-2">
            <span className="text-base shrink-0">👤</span>
            <span className="text-xs text-muted shrink-0">Para:</span>
            <select
              className="flex-1 bg-transparent text-sm text-ink outline-none"
              value={asignadoA ?? ""}
              onChange={(e) => setAsignadoA(e.target.value ? Number(e.target.value) : null)}
            >
              <option value="">Yo mismo</option>
              {usuarios
                .filter((u) => u.id !== usuarioActualId)
                .map((u) => (
                  <option key={u.id} value={u.id}>{u.nombre}</option>
                ))}
            </select>
          </div>
        )}

        {error && <p className="text-xs text-danger">{error}</p>}

        <button
          type="button"
          disabled={!titulo.trim() || guardando}
          onClick={() => void crear()}
          className="w-full rounded-xl bg-accent py-3 text-sm font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
        >
          {guardando ? "Guardando…" : editandoId !== null ? "Guardar cambios" : "Programar recordatorio"}
        </button>
      </div>
      )}

      {loading && <p className="py-6 text-center text-sm text-muted">Cargando recordatorios…</p>}

      {/* Activos hoy / vencidos */}
      {!loading && activos.length > 0 && (
        <div className="space-y-2">
          <p className="text-xs font-bold uppercase tracking-wide text-danger flex items-center gap-1.5">
            🔔 Para hoy
          </p>
          {activos.map((r) => (
            <div key={r.id} className={`rounded-2xl border-2 bg-surface-panel p-4 space-y-2 ${
              r.proxima_fecha < hoy ? "border-danger/50" : "border-accent/60"
            }`}>
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0 flex-1">
                  <p className="font-bold text-sm text-ink leading-snug">{r.titulo}</p>
                  {r.descripcion && <p className="text-xs text-muted mt-0.5">{r.descripcion}</p>}
                  {r.asignado_a_nombre && (
                    <p className="text-[11px] text-accent  mt-0.5 font-semibold">
                      👤 Para: {r.asignado_a_nombre}
                    </p>
                  )}
                  {r.creado_por_nombre && (
                    <p className="text-[11px] text-muted mt-0.5">
                      De: {r.creado_por_nombre}
                    </p>
                  )}
                </div>
                <button
                  type="button"
                  onClick={() => eliminar(r.id)}
                  className="shrink-0 rounded-lg border border-border px-2 py-1 text-[10px] text-muted hover:border-danger hover:text-danger transition"
                >✕</button>
              </div>
              <p className="text-[11px] text-muted flex items-center gap-2">
                {descRepeticion(r)}
                {r.hora && <span className="font-semibold text-accent">🕐 {r.hora}</span>}
              </p>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => r.tipo_rep === "una_vez" ? editarRecordatorio(r) : void marcarVisto(r.id)}
                  className="flex-1 rounded-xl bg-accent py-2 text-xs font-extrabold text-white transition hover:brightness-110"
                >
                  {r.tipo_rep === "una_vez" ? "✓ Listo, reprogramar" : "✓ Visto · programar siguiente"}
                </button>
                <button
                  type="button"
                  onClick={() => editarRecordatorio(r)}
                  className="rounded-xl border-2 border-border px-3 py-2 text-xs font-bold text-muted hover:border-accent hover:text-accent transition"
                >✏️</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Próximos */}
      {!loading && proximos.length > 0 && (
        <div className="space-y-2">
          {activos.length > 0 && <p className="text-xs font-bold uppercase tracking-wide text-muted">Próximos</p>}
          {proximos.map((r) => (
            <div key={r.id} className="rounded-2xl border-2 border-border bg-surface-panel p-4 space-y-2">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0 flex-1">
                  <p className="font-semibold text-sm text-ink leading-snug">{r.titulo}</p>
                  {r.descripcion && <p className="text-xs text-muted mt-0.5">{r.descripcion}</p>}
                  {r.asignado_a_nombre && (
                    <p className="text-[11px] text-accent  mt-0.5 font-semibold">
                      👤 Para: {r.asignado_a_nombre}
                    </p>
                  )}
                </div>
                <div className="flex items-center gap-1 shrink-0">
                  <button
                    type="button"
                    onClick={() => editarRecordatorio(r)}
                    className="rounded-lg border border-border px-2 py-1 text-[10px] text-muted hover:border-accent hover:text-accent transition"
                  >✏️</button>
                  <button
                    type="button"
                    onClick={() => eliminar(r.id)}
                    className="rounded-lg border border-border px-2 py-1 text-[10px] text-muted hover:border-danger hover:text-danger transition"
                  >✕</button>
                </div>
              </div>
              <div className="flex items-center justify-between gap-2 flex-wrap">
                <span className="text-xs text-muted flex items-center gap-2">
                  {descRepeticion(r)}
                  {r.hora && <span className="font-semibold text-accent">🕐 {r.hora}</span>}
                </span>
                <span className="rounded-full bg-surface border border-border px-2.5 py-0.5 text-[11px] font-semibold text-ink">
                  📅 {fmtFecha(r.proxima_fecha)}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}

      {!loading && recordatorios.length === 0 && !showForm && (
        <div className="space-y-3 py-12 text-center">
          <p className="text-3xl">🔔</p>
          <p className="text-sm text-muted">Sin recordatorios programados.</p>
          <p className="text-xs text-muted">Crea tareas con alerta en la fecha que elijas — puntuales o recurrentes.</p>
          <button
            type="button"
            onClick={() => setShowForm(true)}
            className={`mx-auto ${CENTRO_MANDO_CTA_BTN} bg-accent hover:bg-accent shadow-[0_2px_0_#4c1d95]`}
          >
            + Crear recordatorio
          </button>
        </div>
      )}
    </div>
  );
}

// ── NuevoProcedimientoForm ────────────────────────────────────────────────────

function NuevoProcedimientoForm({
  token,
  user,
  onCreado,
  abrirFormInicial = false,
  abrirFormSignal = 0,
}: {
  token: string;
  user: TicketsUser;
  onCreado: () => void;
  abrirFormInicial?: boolean;
  abrirFormSignal?: number;
}) {
  type PasoNuevo = { descripcion: string; fotos: { nombre_archivo: string; mime: string }[] };

  const puedeCrear = puedeCrearProtocolos(user);
  const [showForm, setShowForm] = useState(abrirFormInicial && puedeCrear);
  const [titulo, setTitulo] = useState("");
  const [descripcion, setDescripcion] = useState("");
  const [pasos, setPasos] = useState<PasoNuevo[]>([{ descripcion: "", fotos: [] }]);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState("");
  const [subiendoFoto, setSubiendoFoto] = useState<number | null>(null);
  const [pasoActivo, setPasoActivo] = useState<number | null>(null);
  const [lbUrl, setLbUrl] = useState<string | null>(null);

  useEffect(() => {
    if (abrirFormInicial && puedeCrear) setShowForm(true);
  }, [abrirFormInicial, puedeCrear]);

  useEffect(() => {
    if (abrirFormSignal > 0 && puedeCrear) setShowForm(true);
  }, [abrirFormSignal, puedeCrear]);

  function resetForm() {
    setTitulo("");
    setDescripcion("");
    setPasos([{ descripcion: "", fotos: [] }]);
    setError("");
    setPasoActivo(null);
  }

  async function subirFotoPaso(pasoIdx: number, file: File) {
    setSubiendoFoto(pasoIdx);
    try {
      const fd = new FormData();
      fd.append("archivo", file);
      const res = await fetch("/api/tickets/protocolos/upload-foto", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: fd,
      });
      if (!res.ok) throw new Error(`Error ${res.status}`);
      const { nombre_archivo, mime } = await res.json() as { nombre_archivo: string; mime: string };
      setPasos((prev) =>
        prev.map((x, i) =>
          i === pasoIdx ? { ...x, fotos: [...x.fotos, { nombre_archivo, mime }] } : x
        )
      );
    } catch { /* no crítico */ } finally {
      setSubiendoFoto(null);
    }
  }

  async function crear() {
    if (!titulo.trim()) return;
    setGuardando(true);
    setError("");
    try {
      await tapi("/protocolos", token, {
        method: "POST",
        body: JSON.stringify({
          titulo: titulo.trim(),
          descripcion: descripcion.trim() || undefined,
          pasos: pasos
            .filter((p) => p.descripcion.trim())
            .map((p) => ({
              descripcion: p.descripcion.trim(),
              adjuntos_ref: p.fotos.length ? p.fotos : undefined,
            })),
        }),
      });
      resetForm();
      setShowForm(false);
      onCreado();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error al guardar");
    } finally {
      setGuardando(false);
    }
  }

  if (!puedeCrear) {
    return (
      <p className="rounded-xl border border-border bg-surface-panel px-4 py-3 text-xs text-muted">
        No tienes permiso para crear procedimientos nuevos. Puedes guardar una acción completada como procedimiento desde el historial.
      </p>
    );
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between gap-2">
        <p className="text-sm font-semibold text-ink">Procedimientos guardados</p>
        <button
          type="button"
          onClick={() => { setShowForm((v) => !v); if (showForm) resetForm(); }}
          className={`flex shrink-0 items-center gap-1 rounded-xl border-2 px-3 py-1.5 text-xs font-bold transition ${
            showForm ? "border-border text-muted hover:border-danger hover:text-danger" : "border-accent bg-accent/10 text-accent hover:bg-accent/20"
          }`}
        >
          {showForm ? "✕ Cancelar" : "+ Nuevo procedimiento"}
        </button>
      </div>

      {showForm && (
        <div className="space-y-3 rounded-2xl border-2 border-accent/30 bg-accent/5 p-4">
          {lbUrl && <ImageLightbox url={lbUrl} onClose={() => setLbUrl(null)} />}
          <p className="text-xs font-bold uppercase tracking-widest text-accent">Nuevo procedimiento</p>
          <ProseInput
            autoFocus
            className="w-full rounded-xl border-2 border-border bg-surface-input px-4 py-3 text-base font-semibold text-ink outline-none focus:border-accent placeholder:text-muted/40"
            placeholder="Ej: Cierre de caja, preparación de pedido MeLi…"
            value={titulo}
            onChange={(e) => setTitulo(e.target.value)}
            maxLength={150}
          />
          <ProseTextarea
            className="w-full resize-none rounded-xl border-2 border-border bg-surface-input px-4 py-2.5 text-sm text-ink outline-none focus:border-accent placeholder:text-muted/40"
            placeholder="Descripción opcional…"
            rows={2}
            value={descripcion}
            onChange={(e) => setDescripcion(e.target.value)}
          />
          <div className="space-y-2">
            <p className="text-xs font-bold text-muted">
              Pasos (opcional)
              <span className="ml-2 normal-case font-normal text-muted/70">· Ctrl+V en cada paso para pegar pantallazo</span>
            </p>
            {pasos.map((paso, i) => (
              <div
                key={i}
                className={`rounded-xl border-2 p-2.5 space-y-2 transition-colors ${
                  pasoActivo === i ? "border-accent/60 bg-accent/5" : "border-border"
                }`}
                onMouseEnter={() => setPasoActivo(i)}
                onPaste={(e) => {
                  if (manejarPasteCaptura(e, (file) => void subirFotoPaso(i, file))) {
                    e.stopPropagation();
                  }
                }}
              >
                <div className="flex gap-2">
                  <ProseInput
                    className="flex-1 rounded-xl border-2 border-border bg-surface-input px-3 py-2 text-sm text-ink outline-none focus:border-accent"
                    placeholder={`Paso ${i + 1}`}
                    value={paso.descripcion}
                    onFocus={() => setPasoActivo(i)}
                    onChange={(e) => setPasos((prev) => prev.map((x, j) => j === i ? { ...x, descripcion: e.target.value } : x))}
                  />
                  {pasos.length > 1 && (
                    <button
                      type="button"
                      onClick={() => setPasos((prev) => prev.filter((_, j) => j !== i))}
                      className="rounded-xl border-2 border-border px-3 text-muted hover:border-danger hover:text-danger"
                    >✕</button>
                  )}
                </div>

                {/* Miniaturas de fotos adjuntas al paso */}
                {paso.fotos.length > 0 && (
                  <div className="flex flex-wrap gap-2 ml-1">
                    {paso.fotos.map((f, fi) => {
                      const esImg = f.mime.startsWith("image/") || /\.(jpg|jpeg|png|gif|webp)$/i.test(f.nombre_archivo);
                      const url = ticketsUploadUrl(f.nombre_archivo, token);
                      return (
                        <div key={fi} className="relative group">
                          {esImg
                            ? <button type="button" onClick={() => setLbUrl(url)}>
                                <img src={url} alt="" className="h-14 w-14 rounded-lg object-cover border border-border group-hover:opacity-80 transition-opacity" />
                                <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-xs font-bold pointer-events-none">🔍</span>
                              </button>
                            : <div className="flex h-14 w-14 items-center justify-center rounded-lg border border-border bg-surface text-xl">📄</div>
                          }
                          <button
                            type="button"
                            onClick={() => setPasos((prev) => prev.map((x, j) => j === i ? { ...x, fotos: x.fotos.filter((_, k) => k !== fi) } : x))}
                            className="absolute -top-1 -right-1 hidden group-hover:flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-white text-[9px] font-bold shadow"
                          >✕</button>
                        </div>
                      );
                    })}
                  </div>
                )}

                {/* Zona de pegado / subida por paso */}
                <label
                  tabIndex={0}
                  onFocus={() => setPasoActivo(i)}
                  onPaste={(e) => {
                    if (manejarPasteCaptura(e, (file) => void subirFotoPaso(i, file))) {
                      e.stopPropagation();
                    }
                  }}
                  className={`flex items-center gap-1.5 rounded-lg border px-2.5 py-1 text-[10px] font-semibold cursor-pointer select-none outline-none transition-colors
                    ${subiendoFoto === i
                      ? "border-accent/50 text-accent"
                      : "border-dashed border-border/50 text-muted/60 hover:border-accent/50 hover:text-accent/80 focus:border-accent focus:bg-accent/5 focus:text-accent"
                    }`}
                  title="Click aquí y presiona Ctrl+V para adjuntar un pantallazo — o click para abrir archivos"
                >
                  {subiendoFoto === i
                    ? <><span className="inline-block h-3 w-3 rounded-full border-2 border-current border-t-transparent animate-spin" /> Subiendo…</>
                    : <><span>📷</span> Ctrl+V — adjuntar pantallazo</>
                  }
                  <input
                    type="file"
                    accept="image/*"
                    className="sr-only"
                    onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) void subirFotoPaso(i, f);
                      e.target.value = "";
                    }}
                  />
                </label>
              </div>
            ))}
            <button
              type="button"
              onClick={() => setPasos((prev) => [...prev, { descripcion: "", fotos: [] }])}
              className="text-xs font-bold text-accent hover:underline"
            >
              + Agregar paso
            </button>
          </div>
          {error && <p className="text-xs text-danger">{error}</p>}
          <button
            type="button"
            disabled={!titulo.trim() || guardando}
            onClick={() => void crear()}
            className="w-full rounded-xl bg-accent py-3 text-sm font-extrabold text-white transition hover:brightness-110 disabled:opacity-40"
          >
            {guardando ? "Guardando…" : "Guardar procedimiento"}
          </button>
        </div>
      )}
    </div>
  );
}

// ── DelegarProcedimientoPanel ─────────────────────────────────────────────────

function DelegarProcedimientoPanel({
  protocolo,
  token,
  user,
  onCancel,
  onDelegado,
}: {
  protocolo: Protocolo;
  token: string;
  user: TicketsUser;
  onCancel: () => void;
  onDelegado: (cantidad: number) => void;
}) {
  const [usuarios, setUsuarios] = useState<UserInfo[]>([]);
  const [asignados, setAsignados] = useState<number[]>([]);
  const [nota, setNota] = useState(protocolo.descripcion?.trim() ?? "");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    tapi("/usuarios", token)
      .then((data) => setUsuarios(Array.isArray(data) ? data.filter((u: UserInfo) => u.activo && u.id !== user.id) : []))
      .catch(() => setUsuarios([]));
  }, [token, user.id]);

  function toggleAsignado(uid: number) {
    setAsignados((prev) =>
      prev.includes(uid) ? prev.filter((id) => id !== uid) : [...prev, uid],
    );
  }

  async function enviar() {
    if (asignados.length === 0) return;
    setLoading(true);
    setError("");
    try {
      const desc = nota.trim() || `Ejecutar procedimiento: ${protocolo.titulo}`;
      await Promise.all(
        asignados.map((uid) =>
          tapi("/", token, {
            method: "POST",
            body: JSON.stringify({
              titulo: protocolo.titulo,
              descripcion: desc,
              categoria: protocolo.categoria || "logistica",
              prioridad: "media",
              asignado_a: uid,
              tipo: "solicitud",
              protocolo_id: protocolo.id,
            }),
          }),
        ),
      );
      onDelegado(asignados.length);
    } catch (e) {
      setError(e instanceof Error ? e.message : "No se pudo delegar el procedimiento");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="rounded-xl border-2 border-accent/40 bg-accent/30  p-3 space-y-3">
      <div className="flex items-start justify-between gap-2">
        <div>
          <p className="text-xs font-extrabold text-ink">Delegar a un aliado</p>
          <p className="text-[10px] text-muted mt-0.5 truncate">{protocolo.titulo}</p>
        </div>
        <button type="button" onClick={onCancel} className="text-xs text-muted hover:text-ink shrink-0">✕</button>
      </div>
      <ProseTextarea
        className="quest-input w-full text-xs resize-none"
        rows={2}
        placeholder="Instrucciones para el aliado (opcional)…"
        value={nota}
        onChange={(e) => setNota(e.target.value)}
      />
      {usuarios.length === 0 ? (
        <p className="text-xs text-muted">No hay aliados disponibles para asignar.</p>
      ) : (
        <div className="flex flex-wrap gap-2">
          {usuarios.map((u) => (
            <button
              key={u.id}
              type="button"
              onClick={() => toggleAsignado(u.id)}
              className={`flex items-center gap-2 rounded-xl border-2 px-3 py-2 text-xs font-semibold transition ${
                asignados.includes(u.id)
                  ? "border-accent/50 bg-accent/10 text-accent"
                  : "border-border text-muted hover:border-accent/40 hover:text-accent"
              }`}
            >
              <span
                className="flex h-5 w-5 items-center justify-center rounded-full text-[10px] font-black text-white shrink-0"
                style={{ background: u.departamento?.color || "#0c6069" }}
              >
                {u.nombre.charAt(0).toUpperCase()}
              </span>
              {u.nombre.split(" ")[0]}
              {asignados.includes(u.id) && <Icon name="check" size={12} weight="bold" />}
            </button>
          ))}
        </div>
      )}
      {asignados.length > 1 && (
        <p className="text-[10px] text-muted">Se creará una solicitud por cada aliado seleccionado.</p>
      )}
      {error && <p className="text-xs text-danger">{error}</p>}
      <button
        type="button"
        disabled={loading || asignados.length === 0}
        onClick={() => void enviar()}
        className="w-full rounded-xl bg-accent py-2.5 text-xs font-bold text-white hover:bg-accent disabled:opacity-40 transition-colors"
      >
        {loading
          ? "Delegando…"
          : asignados.length > 1
            ? `Delegar a ${asignados.length} aliados`
            : "Delegar procedimiento"}
      </button>
    </div>
  );
}

// ── ProcedimientoCard ─────────────────────────────────────────────────────────

function ProcedimientoCard({
  p,
  token,
  user,
  onEjecutar,
  onActualizado,
}: {
  p: Protocolo;
  token: string;
  user: TicketsUser;
  onEjecutar: () => void;
  onActualizado: () => void;
}) {
  type PasoDraft = {
    descripcion: string;
    notas: string;
    adjuntos_ref: { nombre_archivo: string; mime: string }[];
  };

  const alcanceActual = (p.alcance ?? "personal") as "personal" | "global" | "seleccionado";
  const esGlobal = alcanceActual === "global";
  const [editando, setEditando] = useState(false);
  const [titulo, setTitulo] = useState(p.titulo);
  const [pasosDraft, setPasosDraft] = useState<PasoDraft[]>(
    () => (p.pasos || []).map((x) => ({
      descripcion: x.descripcion,
      notas: x.notas ?? "",
      adjuntos_ref: x.adjuntos_ref ?? [],
    }))
  );
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState("");
  const [subiendoFoto, setSubiendoFoto] = useState<number | null>(null);
  const [lbUrl, setLbUrl] = useState<string | null>(null);
  const [pasoPegarIdx, setPasoPegarIdx] = useState<number | null>(null);
  const editPasosRef = useRef<HTMLDivElement>(null);

  usePegarCapturaEnZona(editando, editPasosRef, (file) => {
    const idx = pasoPegarIdx ?? Math.max(0, pasosDraft.length - 1);
    if (pasosDraft.length > 0) void subirFotoPaso(idx, file);
  });

  // Picker de visibilidad
  const [showPicker, setShowPicker] = useState(false);
  const [showDelegar, setShowDelegar] = useState(false);
  const [delegarMsg, setDelegarMsg] = useState("");
  const [pickerAlcance, setPickerAlcance] = useState<"personal" | "global" | "seleccionado">(alcanceActual);
  const [pickerUserIds, setPickerUserIds] = useState<number[]>(
    () => (p.usuarios_compartidos ?? []).map((u) => u.id)
  );
  const [usuarios, setUsuarios] = useState<UserInfo[]>([]);
  const [loadingUsuarios, setLoadingUsuarios] = useState(false);
  const [savingPicker, setSavingPicker] = useState(false);
  const [eliminando, setEliminando] = useState(false);
  const puedeEliminar = puedeEliminarProtocolo(user, p);

  async function eliminarProcedimiento() {
    if (!confirm(`¿Eliminar el procedimiento "${p.titulo}"?\n\nLas solicitudes ya delegadas no se borran.`)) return;
    setEliminando(true);
    setMsg("");
    try {
      await tapi(`/protocolos/${p.id}`, token, { method: "DELETE" });
      onActualizado();
    } catch (e: any) {
      setMsg(e.message ?? "No se pudo eliminar");
      setTimeout(() => setMsg(""), 4000);
    } finally {
      setEliminando(false);
    }
  }

  async function subirFotoPaso(pasoIdx: number, file: File) {
    setSubiendoFoto(pasoIdx);
    try {
      const fd = new FormData();
      fd.append("archivo", file);
      const res = await fetch("/api/tickets/protocolos/upload-foto", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: fd,
      });
      if (!res.ok) {
        const d = await res.json().catch(() => ({}));
        throw new Error((d as any).error || `Error ${res.status}`);
      }
      const { nombre_archivo, mime } = await res.json();
      setPasosDraft((prev) =>
        prev.map((x, i) =>
          i === pasoIdx
            ? { ...x, adjuntos_ref: [...x.adjuntos_ref, { nombre_archivo, mime }] }
            : x
        )
      );
    } catch (e: any) {
      setMsg(e.message ?? "Error al subir foto");
      setTimeout(() => setMsg(""), 3000);
    } finally { setSubiendoFoto(null); }
  }

  async function guardarEdicion() {
    if (!titulo.trim()) { setMsg("El título no puede estar vacío."); return; }
    setSaving(true);
    setMsg("");
    try {
      await tapi(`/protocolos/${p.id}`, token, {
        method: "PUT",
        body: JSON.stringify({
          titulo: titulo.trim(),
          descripcion: p.descripcion ?? "",
          categoria: p.categoria ?? "",
          pasos: pasosDraft
            .filter((x) => x.descripcion.trim())
            .map((x) => ({
              descripcion: x.descripcion.trim(),
              notas: x.notas.trim() || null,
              adjuntos_ref: x.adjuntos_ref.length ? x.adjuntos_ref : undefined,
            })),
        }),
      });
      setEditando(false);
      onActualizado();
    } catch (e: any) {
      setMsg(e.message ?? "Error al guardar");
    } finally { setSaving(false); }
  }

  function abrirPicker() {
    setPickerAlcance(alcanceActual);
    setPickerUserIds((p.usuarios_compartidos ?? []).map((u) => u.id));
    setShowPicker(true);
    if (usuarios.length === 0) {
      setLoadingUsuarios(true);
      tapi("/usuarios", token)
        .then((d) => setUsuarios(Array.isArray(d) ? d as UserInfo[] : []))
        .catch(() => {})
        .finally(() => setLoadingUsuarios(false));
    }
  }

  async function guardarVisibilidad() {
    if (pickerAlcance === "seleccionado" && pickerUserIds.length === 0) {
      setMsg("Selecciona al menos un usuario.");
      return;
    }
    setSavingPicker(true);
    setMsg("");
    try {
      await tapi(`/protocolos/${p.id}/visibilidad`, token, {
        method: "POST",
        body: JSON.stringify({ alcance: pickerAlcance, usuario_ids: pickerUserIds }),
      });
      setShowPicker(false);
      onActualizado();
    } catch (e: any) {
      setMsg(e.message ?? "Error al guardar visibilidad");
    } finally { setSavingPicker(false); }
  }

  function cancelarEdicion() {
    setTitulo(p.titulo);
    setPasosDraft((p.pasos || []).map((x) => ({
      descripcion: x.descripcion,
      notas: x.notas ?? "",
      adjuntos_ref: x.adjuntos_ref ?? [],
    })));
    setEditando(false);
    setMsg("");
  }

  return (
    <div className={`rounded-xl border-2 bg-surface-panel p-3 space-y-2 transition-colors
      ${esGlobal ? "border-accent/40" : "border-border"}`}>

      {/* Cabecera: título + badge de privacidad (cliclable) */}
      {!editando ? (
        <div className="flex items-start gap-2">
          <div className="flex-1 min-w-0">
            <p className="font-semibold text-ink text-sm leading-snug">{p.titulo}</p>
            <p className="text-xs text-muted mt-0.5">
              {p.pasos?.length ?? 0} paso{(p.pasos?.length ?? 0) !== 1 ? "s" : ""}
              {(p.lista_compras?.length ?? 0) > 0 && ` · ${p.lista_compras!.length} ingrediente${p.lista_compras!.length !== 1 ? "s" : ""}`}
            </p>
            {alcanceActual === "seleccionado" && (p.usuarios_compartidos ?? []).length > 0 && (
              <p className="text-[10px] text-muted mt-0.5 truncate">
                👤 {(p.usuarios_compartidos ?? []).map((u) => u.nombre.split(" ")[0]).join(", ")}
              </p>
            )}
          </div>
          <div className="flex shrink-0 items-center gap-1">
            <button
              type="button"
              onClick={abrirPicker}
              title="Cambiar visibilidad"
              className={`text-[10px] font-bold rounded-full px-2 py-0.5 border transition-colors hover:opacity-80
                ${alcanceActual === "global"
                  ? "text-accent bg-accent/10 border-accent/25"
                  : alcanceActual === "seleccionado"
                    ? "text-accent  bg-accent/10 border-accent/25"
                    : "text-muted bg-surface-hover border-border"
                }`}>
              {alcanceActual === "global" ? "🌐 Equipo" : alcanceActual === "seleccionado" ? "👤 Específico" : "🔒 Privado"}
            </button>
            {puedeEliminar && (
              <button
                type="button"
                onClick={() => void eliminarProcedimiento()}
                disabled={eliminando}
                title="Eliminar procedimiento"
                className="flex h-6 w-6 items-center justify-center rounded-lg border border-border text-xs text-muted transition hover:border-danger hover:text-danger disabled:opacity-40"
              >
                ✕
              </button>
            )}
          </div>
        </div>
      ) : (
        /* Modo edición */
        <div className="space-y-3">
          <div>
            <label className="text-[10px] font-bold uppercase tracking-wide text-muted mb-1 block">Título</label>
            <ProseInput
              autoFocus
              className="quest-input w-full text-sm"
              value={titulo}
              onChange={(e) => setTitulo(e.target.value)}
              maxLength={120}
            />
          </div>

          <div ref={editPasosRef} className="space-y-2" onPaste={(e) => {
            const idx = pasoPegarIdx ?? 0;
            manejarPasteCaptura(e, (file) => void subirFotoPaso(idx, file));
          }}>
            <label className="text-[10px] font-bold uppercase tracking-wide text-muted block">
              Pasos {pasosDraft.length > 0 && <span className="font-normal">({pasosDraft.length})</span>}
              <span className="ml-2 normal-case font-normal text-muted/80">· Ctrl+V para pegar captura en el paso activo</span>
            </label>
            {pasosDraft.map((paso, i) => (
              <div
                key={i}
                className={`rounded-lg border bg-surface p-2.5 space-y-2 transition-colors ${
                  pasoPegarIdx === i ? "border-accent/60 ring-1 ring-accent/30" : "border-border"
                }`}
                onFocusCapture={() => setPasoPegarIdx(i)}
                onMouseEnter={() => setPasoPegarIdx(i)}
                onPaste={(e) => manejarPasteCaptura(e, (file) => void subirFotoPaso(i, file))}
              >
                <div className="flex items-start gap-2">
                  <span className="text-[10px] font-bold text-muted mt-2 shrink-0 w-4 text-center">{i + 1}</span>
                  <div className="flex-1 min-w-0 space-y-1.5">
                    <ProseInput
                      className="quest-input w-full text-xs"
                      placeholder="Nombre del paso…"
                      value={paso.descripcion}
                      onChange={(e) => setPasosDraft((prev) =>
                        prev.map((x, j) => j === i ? { ...x, descripcion: e.target.value } : x)
                      )}
                    />
                    <ProseTextarea
                      className="quest-input w-full text-xs resize-none"
                      rows={2}
                      placeholder="Notas / instrucciones (opcional)…"
                      value={paso.notas}
                      onChange={(e) => setPasosDraft((prev) =>
                        prev.map((x, j) => j === i ? { ...x, notas: e.target.value } : x)
                      )}
                    />
                  </div>
                  <button
                    type="button"
                    onClick={() => setPasosDraft((prev) => prev.filter((_, j) => j !== i))}
                    className="shrink-0 text-muted hover:text-red-500 p-1 transition-colors mt-0.5"
                    title="Eliminar paso"
                  >
                    <Icon name="trash" size={11} />
                  </button>
                </div>

                {/* Fotos de referencia del paso */}
                {lbUrl && <ImageLightbox url={lbUrl} onClose={() => setLbUrl(null)} />}
                <div className="ml-6 space-y-1.5">
                  {paso.adjuntos_ref.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {paso.adjuntos_ref.map((a, ai) => {
                        const esImagen = a.mime.startsWith("image/") || /\.(jpg|jpeg|png|gif|webp)$/i.test(a.nombre_archivo);
                        const url = ticketsUploadUrl(a.nombre_archivo, token);
                        return (
                          <div key={ai} className="relative group">
                            {esImagen
                              ? <button type="button" onClick={() => setLbUrl(url)} className="block" title="Ver imagen">
                                  <img src={url} alt="" className="h-16 w-16 rounded-lg object-cover border border-border group-hover:opacity-80 transition-opacity" />
                                  <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-sm font-bold transition-opacity pointer-events-none">🔍</span>
                                </button>
                              : <a href={url} target="_blank" rel="noreferrer"
                                  className="flex h-16 w-16 items-center justify-center rounded-lg border border-border bg-surface text-xl">📄</a>
                            }
                            <button
                              type="button"
                              onClick={() => setPasosDraft((prev) =>
                                prev.map((x, j) =>
                                  j === i
                                    ? { ...x, adjuntos_ref: x.adjuntos_ref.filter((_, k) => k !== ai) }
                                    : x
                                )
                              )}
                              className="absolute -top-1 -right-1 hidden group-hover:flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-white text-[9px] font-bold shadow"
                              title="Quitar foto"
                            >✕</button>
                          </div>
                        );
                      })}
                    </div>
                  )}

                  {/* Botón agregar foto */}
                  <label className={`inline-flex cursor-pointer items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-[11px] font-semibold transition-colors
                    ${subiendoFoto === i
                      ? "border-accent/40 text-accent/60"
                      : "border-dashed border-border text-muted hover:border-accent hover:text-accent"
                    }`}>
                    {subiendoFoto === i
                      ? <><span className="inline-block h-3 w-3 rounded-full border-2 border-current border-t-transparent animate-spin" /> Subiendo…</>
                      : <><span>📷</span> Foto o Ctrl+V</>
                    }
                    <input
                      type="file"
                      accept="image/*,.pdf,application/pdf"
                      className="sr-only"
                      disabled={subiendoFoto !== null}
                      onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) void subirFotoPaso(i, f);
                        e.target.value = "";
                      }}
                    />
                  </label>
                </div>
              </div>
            ))}
            <button
              type="button"
              onClick={() => setPasosDraft((prev) => [...prev, { descripcion: "", notas: "", adjuntos_ref: [] }])}
              className="flex items-center gap-1 text-xs text-accent hover:underline"
            >
              <Icon name="plus" size={11} weight="bold" /> Agregar paso
            </button>
          </div>

          {msg && <p className="text-xs text-red-400">{msg}</p>}

          <div className="flex gap-2 pt-1">
            <button type="button" disabled={saving} onClick={guardarEdicion}
              className="flex-1 rounded-xl bg-accent py-2 text-xs font-bold text-white disabled:opacity-40">
              {saving ? "Guardando…" : "Guardar cambios"}
            </button>
            <button type="button" onClick={cancelarEdicion}
              className="rounded-xl border border-border px-3 py-2 text-xs text-muted hover:text-ink">
              Cancelar
            </button>
          </div>
        </div>
      )}

      {msg && !editando && <p className="text-xs text-red-400">{msg}</p>}

      {/* Picker de visibilidad */}
      {showPicker && !editando && (
        <div className="rounded-xl border-2 border-accent/30 bg-accent/5 p-3 space-y-3">
          <p className="text-xs font-extrabold text-ink">¿Quién puede ver este procedimiento?</p>
          <div className="space-y-2">
            {([
              { value: "personal",    icon: "🔒", label: "Solo yo",              desc: "Solo tú puedes verlo y ejecutarlo" },
              { value: "global",      icon: "🌐", label: "Todo el equipo",       desc: "Cualquier persona del equipo puede ejecutarlo" },
              { value: "seleccionado",icon: "👤", label: "Personas específicas", desc: "Elige exactamente quién puede verlo" },
            ] as const).map((opt) => (
              <label key={opt.value} className="flex items-start gap-2.5 cursor-pointer group">
                <input
                  type="radio"
                  name={`vis-${p.id}`}
                  value={opt.value}
                  checked={pickerAlcance === opt.value}
                  onChange={() => setPickerAlcance(opt.value)}
                  className="mt-0.5 accent-accent shrink-0"
                />
                <div>
                  <p className="text-xs font-semibold text-ink">{opt.icon} {opt.label}</p>
                  <p className="text-[10px] text-muted">{opt.desc}</p>
                </div>
              </label>
            ))}
          </div>

          {/* Selector de usuarios cuando es "seleccionado" */}
          {pickerAlcance === "seleccionado" && (
            <div className="rounded-lg border border-border bg-surface overflow-hidden">
              {loadingUsuarios ? (
                <p className="px-3 py-2 text-xs text-muted">Cargando usuarios…</p>
              ) : usuarios.filter((u) => u.activo !== 0).length === 0 ? (
                <p className="px-3 py-2 text-xs text-muted">No hay otros usuarios.</p>
              ) : (
                <div className="max-h-40 overflow-y-auto divide-y divide-border/40">
                  {usuarios.filter((u) => u.activo !== 0).map((u) => (
                    <label key={u.id} className="flex items-center gap-2.5 px-3 py-2 cursor-pointer hover:bg-surface-hover transition-colors">
                      <input
                        type="checkbox"
                        checked={pickerUserIds.includes(u.id)}
                        onChange={(e) => setPickerUserIds((prev) =>
                          e.target.checked ? [...prev, u.id] : prev.filter((id) => id !== u.id)
                        )}
                        className="h-3.5 w-3.5 accent-accent rounded"
                      />
                      <span className="text-xs font-semibold text-ink">{u.nombre}</span>
                      {u.departamento && (
                        <span className="text-[10px] text-muted ml-auto shrink-0">{u.departamento.nombre}</span>
                      )}
                    </label>
                  ))}
                </div>
              )}
              {pickerAlcance === "seleccionado" && pickerUserIds.length > 0 && (
                <p className="px-3 py-1.5 text-[10px] text-accent font-semibold border-t border-border/40">
                  {pickerUserIds.length} persona{pickerUserIds.length !== 1 ? "s" : ""} seleccionada{pickerUserIds.length !== 1 ? "s" : ""}
                </p>
              )}
            </div>
          )}

          <div className="flex gap-2 pt-1">
            <button type="button" disabled={savingPicker} onClick={guardarVisibilidad}
              className="flex-1 rounded-xl bg-accent py-2 text-xs font-extrabold text-white disabled:opacity-40 hover:brightness-110 transition-all">
              {savingPicker ? "Guardando…" : "Guardar visibilidad"}
            </button>
            <button type="button" onClick={() => { setShowPicker(false); setMsg(""); }}
              className="rounded-xl border border-border px-3 py-2 text-xs text-muted hover:text-ink">
              Cancelar
            </button>
          </div>
        </div>
      )}

      {delegarMsg && !editando && (
        <p className="text-xs font-semibold text-accent">{delegarMsg}</p>
      )}

      {showDelegar && !editando && (
        <DelegarProcedimientoPanel
          protocolo={p}
          token={token}
          user={user}
          onCancel={() => setShowDelegar(false)}
          onDelegado={(n) => {
            setShowDelegar(false);
            setDelegarMsg(`✓ ${n} solicitud${n !== 1 ? "es" : ""} creada${n !== 1 ? "s" : ""} en Por resolver`);
            setTimeout(() => setDelegarMsg(""), 5000);
            onActualizado();
          }}
        />
      )}

      {/* Botones de acción */}
      {!editando && !showPicker && !showDelegar && (
        <div className="flex gap-1.5 flex-wrap">
          <button type="button" onClick={onEjecutar}
            className="flex-1 rounded-xl bg-accent py-2 text-xs font-bold text-white hover:brightness-110 transition-all min-w-[70px]">
            ↻ Ejecutar
          </button>
          <button
            type="button"
            onClick={() => { setShowDelegar(true); setDelegarMsg(""); }}
            className="rounded-xl border border-accent/50 bg-accent/10 px-2.5 py-2 text-xs font-bold text-accent  hover:bg-accent/20 transition-colors"
            title="Asignar este procedimiento a un aliado del equipo"
          >
            👥 Delegar
          </button>
          <button type="button" onClick={() => setEditando(true)}
            className="rounded-xl border border-border px-2.5 py-2 text-xs font-bold text-muted hover:border-accent hover:text-accent transition-colors"
            title="Editar nombre y pasos">
            ✏️ Editar
          </button>
          <button type="button" onClick={abrirPicker}
            className="rounded-xl border border-border px-2.5 py-2 text-xs font-bold text-muted hover:border-accent hover:text-accent transition-colors"
            title="Cambiar visibilidad">
            🔒 Visibilidad
          </button>
        </div>
      )}
    </div>
  );
}

// ── AdminSubhomePanel — métricas de equipo para admins ────────────────────────

interface AdminMetricaUsuario {
  uid: number;
  acciones_activas: number;
  acciones_pendientes: number;
  acciones_resueltas: number;
  solicitudes_activas: number;
  solicitudes_resueltas: number;
}

function AdminSubhomePanel({
  token, acciones, usuarios, onVerActivas,
}: {
  token: string;
  acciones: Ticket[];
  usuarios: UserInfo[];
  onVerActivas: () => void;
}) {
  const [metricas, setMetricas] = useState<AdminMetricaUsuario[]>([]);
  const [dias, setDias] = useState(7);
  const [loadingMetricas, setLoadingMetricas] = useState(true);

  // Live stats from already-fetched acciones
  const liveByUser = useMemo(() => {
    const m: Record<number, { activas: number; pendientes: number }> = {};
    for (const a of acciones) {
      const uid = a.asignado_a;
      if (!uid) continue;
      if (!m[uid]) m[uid] = { activas: 0, pendientes: 0 };
      if (a.estado === "en_proceso") m[uid].activas++;
      else if (a.estado === "pendiente") m[uid].pendientes++;
    }
    return m;
  }, [acciones]);

  useEffect(() => {
    setLoadingMetricas(true);
    tapi(`/admin/metricas-acciones?dias=${dias}`, token)
      .then((d: any) => { if (Array.isArray(d?.usuarios)) setMetricas(d.usuarios); })
      .catch(() => {})
      .finally(() => setLoadingMetricas(false));
  }, [token, dias]);

  const allUids = Array.from(new Set([
    ...Object.keys(liveByUser).map(Number),
    ...metricas.map((m) => m.uid),
  ]));

  const rows = allUids.map((uid) => {
    const u = usuarios.find((x) => x.id === uid);
    const live = liveByUser[uid] ?? { activas: 0, pendientes: 0 };
    const hist = metricas.find((m) => m.uid === uid);
    return {
      uid,
      nombre: u?.nombre ?? `Usuario #${uid}`,
      activas: live.activas,
      pendientes: live.pendientes,
      resueltas: hist?.acciones_resueltas ?? 0,
      solActivas: hist?.solicitudes_activas ?? 0,
      solResueltas: hist?.solicitudes_resueltas ?? 0,
    };
  }).sort((a, b) => b.activas - a.activas || b.pendientes - a.pendientes || a.nombre.localeCompare(b.nombre));

  const totalActivas = rows.reduce((s, r) => s + r.activas, 0);
  const totalPendientes = rows.reduce((s, r) => s + r.pendientes, 0);
  const totalResueltas = rows.reduce((s, r) => s + r.resueltas, 0);

  return (
    <div className="space-y-4">
      {/* Resumen global */}
      <div className="grid grid-cols-3 gap-3">
        <div className="rounded-2xl border border-accent/20  bg-accent/5  p-4 text-center">
          <p className="text-3xl font-black text-accent  tabular-nums leading-none">{totalActivas}</p>
          <p className="text-xs font-bold text-muted mt-1.5">En proceso</p>
        </div>
        <div className="rounded-2xl border border-accent/20  bg-accent/5  p-4 text-center">
          <p className="text-3xl font-black text-accent  tabular-nums leading-none">{totalPendientes}</p>
          <p className="text-xs font-bold text-muted mt-1.5">Pendientes</p>
        </div>
        <div className="rounded-2xl border border-border bg-surface p-4 text-center">
          <p className="text-3xl font-black text-ink dark:text-white tabular-nums leading-none">{totalResueltas}</p>
          <p className="text-xs font-bold text-muted mt-1.5">Resueltas</p>
        </div>
      </div>

      {/* Tabla por usuario */}
      <div className="rounded-2xl border border-border overflow-hidden">
        <div className="flex items-center justify-between gap-3 px-4 py-3 bg-surface border-b border-border">
          <p className="text-xs font-bold uppercase tracking-widest text-muted">Por operador</p>
          <div className="flex items-center gap-2">
            <p className="text-xs text-muted">Resueltas últimos</p>
            <select
              value={dias}
              onChange={(e) => setDias(Number(e.target.value))}
              className="quest-input py-0.5 px-2 text-xs"
            >
              {[1, 3, 7, 14, 30].map((d) => (
                <option key={d} value={d}>{d} días</option>
              ))}
            </select>
          </div>
        </div>
        {loadingMetricas && metricas.length === 0 ? (
          <p className="px-4 py-6 text-sm text-muted text-center">Cargando…</p>
        ) : rows.length === 0 ? (
          <p className="px-4 py-6 text-sm text-muted text-center">Sin actividad registrada.</p>
        ) : (
          <div className="divide-y divide-border/50">
            {rows.map((r) => (
              <div key={r.uid} className="flex items-center gap-3 px-4 py-3 hover:bg-surface-hover transition-colors">
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-semibold text-ink truncate">{r.nombre}</p>
                  {(r.solActivas + r.solResueltas) > 0 && (
                    <p className="text-[11px] text-muted">Solicitudes: {r.solActivas} activas · {r.solResueltas} resueltas</p>
                  )}
                </div>
                <div className="flex items-center gap-1.5 shrink-0 flex-wrap justify-end">
                  {r.activas > 0 && (
                    <span className="inline-flex items-center rounded-full bg-accent/10  px-2 py-0.5 text-xs font-bold text-accent">
                      ⚡ {r.activas}
                    </span>
                  )}
                  {r.pendientes > 0 && (
                    <span className="inline-flex items-center rounded-full bg-accent/10  px-2 py-0.5 text-xs font-bold text-accent">
                      🗓 {r.pendientes}
                    </span>
                  )}
                  {r.resueltas > 0 && (
                    <span className="inline-flex items-center rounded-full bg-surface border border-border px-2 py-0.5 text-xs font-bold text-muted">
                      ✓ {r.resueltas}
                    </span>
                  )}
                  {r.activas === 0 && r.pendientes === 0 && r.resueltas === 0 && (
                    <span className="text-xs text-muted italic">Sin actividad</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <button
        type="button"
        onClick={onVerActivas}
        className="w-full rounded-xl border-2 border-border py-3 text-sm font-bold text-ink hover:border-accent hover:text-accent transition"
      >
        Ver todas las acciones activas del equipo →
      </button>
    </div>
  );
}

