// ── NotasPensamientos ─────────────────────────────────────────────────────────

type NotaPensamiento = { id: number; contenido: string; creadaEn: string };

function NotasPensamientos({ crearSignal = 0 }: { crearSignal?: number }) {
  const { token } = useTicketsAuth();
  const [notas, setNotas] = useState<NotaPensamiento[]>([]);
  const [texto, setTexto] = useState("");
  const [expandida, setExpandida] = useState<number | null>(null);
  const [cargando, setCargando] = useState(true);
  const [errorCarga, setErrorCarga] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const cargar = useCallback(async () => {
    if (!token) return;
    setErrorCarga(false);
    try {
      const r = await fetch("/api/tickets/notas", {
        headers: { Authorization: `Bearer ${token}` },
        cache: "no-store",
      });
      if (r.ok) {
        const data = await r.json() as { id: number; contenido: string; creado_en: string }[];
        const serverNotas = data.map((n) => ({ id: n.id, contenido: n.contenido, creadaEn: n.creado_en }));
        // Migración única: notas guardadas en localStorage con la clave antigua
        if (serverNotas.length === 0) {
          try {
            const raw = localStorage.getItem("mck_notas_pensamientos");
            if (raw) {
              const legacy = JSON.parse(raw) as { id: number; contenido: string; creadaEn: string }[];
              if (Array.isArray(legacy) && legacy.length > 0) {
                const migradas: NotaPensamiento[] = [];
                for (const n of legacy) {
                  const pr = await fetch("/api/tickets/notas", {
                    method: "POST",
                    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
                    body: JSON.stringify({ contenido: n.contenido }),
                  });
                  if (pr.ok) {
                    const created = await pr.json() as { id: number; contenido: string; creado_en: string };
                    migradas.push({ id: created.id, contenido: created.contenido, creadaEn: created.creado_en });
                  }
                }
                if (migradas.length > 0) {
                  localStorage.removeItem("mck_notas_pensamientos");
                  setNotas(migradas);
                  return;
                }
              }
            }
          } catch { /* sin localStorage — ignorar */ }
        }
        setNotas(serverNotas);
      } else {
        setErrorCarga(true);
      }
    } catch { setErrorCarga(true); }
    finally { setCargando(false); }
  }, [token]);

  useEffect(() => { void cargar(); }, [cargar]);

  useEffect(() => {
    if (crearSignal > 0) textareaRef.current?.focus();
  }, [crearSignal]);

  const agregar = async () => {
    const t = texto.trim();
    if (!t || !token) return;
    setTexto("");
    try {
      const r = await fetch("/api/tickets/notas", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ contenido: t }),
      });
      if (r.ok) {
        const n = await r.json() as { id: number; contenido: string; creado_en: string };
        setNotas((prev) => [{ id: n.id, contenido: n.contenido, creadaEn: n.creado_en }, ...prev]);
      }
    } catch { /* revertir texto si falló */ setTexto(t); }
  };

  const eliminar = async (id: number) => {
    if (!token) return;
    setNotas((prev) => prev.filter((n) => n.id !== id));
    try {
      await fetch(`/api/tickets/notas/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
    } catch { void cargar(); }
  };

  const editarContenido = async (id: number, val: string) => {
    if (!token) return;
    setNotas((prev) => prev.map((n) => n.id === id ? { ...n, contenido: val } : n));
    try {
      await fetch(`/api/tickets/notas/${id}`, {
        method: "PUT",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ contenido: val }),
      });
    } catch { /* ignore — actualización optimista */ }
  };

  const formatFecha = (iso: string) => {
    try {
      const d = new Date(iso);
      const diff = Math.floor((Date.now() - d.getTime()) / 60000);
      if (diff < 1) return "ahora";
      if (diff < 60) return `hace ${diff}m`;
      if (diff < 1440) return `hace ${Math.floor(diff / 60)}h`;
      return d.toLocaleDateString("es-CO", { day: "numeric", month: "short" });
    } catch { return ""; }
  };

  return (
    <div className="space-y-3">
      {/* Lista de notas — primero para que sean visibles sin scroll */}
      {cargando ? (
        <p className="py-6 text-center text-sm text-muted">Cargando notas…</p>
      ) : errorCarga ? (
        <div className="py-4 text-center space-y-2">
          <p className="text-sm text-red-500">No se pudieron cargar las notas. Verifica tu conexión.</p>
          <button type="button" onClick={() => { setCargando(true); void cargar(); }}
            className="text-xs text-accent hover:underline">↻ Reintentar</button>
        </div>
      ) : notas.length === 0 ? (
        <p className="py-6 text-center text-sm text-muted">Aún no tienes notas. Escribe una abajo.</p>
      ) : (
        <div className="space-y-2">
          {notas.map((n) => (
            <div key={n.id} className="rounded-xl border border-border bg-surface-panel px-4 py-3 space-y-2">
              <div className="flex items-start justify-between gap-2">
                <span className="text-[10px] text-muted">{formatFecha(n.creadaEn)}</span>
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={() => setExpandida(expandida === n.id ? null : n.id)}
                    className="text-[10px] text-accent hover:underline"
                  >
                    {expandida === n.id ? "cerrar" : "editar"}
                  </button>
                  <button
                    type="button"
                    onClick={() => eliminar(n.id)}
                    className="text-[10px] text-muted hover:text-danger transition"
                    title="Eliminar"
                  >
                    ✕
                  </button>
                </div>
              </div>
              {expandida === n.id ? (
                <textarea
                  value={n.contenido}
                  onChange={(e) => editarContenido(n.id, e.target.value)}
                  rows={4}
                  className="w-full resize-none rounded-lg bg-surface-input border border-border px-3 py-2 text-sm text-ink outline-none focus:border-accent/60 focus:ring-1 focus:ring-accent/30 transition"
                  autoFocus
                />
              ) : (
                <p className="text-sm text-ink whitespace-pre-wrap leading-relaxed">{n.contenido}</p>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Input nueva nota — al fondo */}
      <div className="rounded-xl border border-border bg-surface-panel p-3 space-y-2">
        <textarea
          ref={textareaRef}
          value={texto}
          onChange={(e) => setTexto(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) { e.preventDefault(); agregar(); }
          }}
          placeholder="Escribe un pensamiento, idea o nota personal… (Ctrl+Enter para guardar)"
          rows={3}
          className="w-full resize-none rounded-lg bg-surface-input border border-border px-3 py-2 text-sm text-ink placeholder:text-muted outline-none focus:border-accent/60 focus:ring-1 focus:ring-accent/30 transition"
        />
        <div className="flex justify-end">
          <button
            type="button"
            onClick={agregar}
            disabled={!texto.trim()}
            className="rounded-lg bg-accent px-4 py-1.5 text-xs font-semibold text-white hover:opacity-90 disabled:opacity-40 transition"
          >
            Guardar nota
          </button>
        </div>
      </div>
    </div>
  );
}

// ── BolsilloSeguro ────────────────────────────────────────────────────────────

const BOLSILLO_CANARY = "McKBols2:";

type BolsilloNota = { id: number; titulo: string; contenido: string; editadaEn: string };

async function _bDerivKey(pin: string, salt: Uint8Array<ArrayBuffer>): Promise<CryptoKey> {
  const km = await crypto.subtle.importKey("raw", new TextEncoder().encode(pin), "PBKDF2", false, ["deriveKey"]);
  return crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations: 200_000, hash: "SHA-256" },
    km,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );
}

async function bolsilloEncriptar(notas: BolsilloNota[], pin: string): Promise<string> {
  const salt = crypto.getRandomValues(new Uint8Array(32)) as Uint8Array<ArrayBuffer>;
  const iv   = crypto.getRandomValues(new Uint8Array(12)) as Uint8Array<ArrayBuffer>;
  const key  = await _bDerivKey(pin, salt);
  const plain = new TextEncoder().encode(BOLSILLO_CANARY + JSON.stringify(notas));
  const ct   = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, plain);
  const buf  = new Uint8Array(32 + 12 + ct.byteLength);
  buf.set(salt, 0); buf.set(iv, 32); buf.set(new Uint8Array(ct), 44);
  return btoa(String.fromCharCode(...buf));
}

async function bolsilloDesencriptar(blob: string, pin: string): Promise<BolsilloNota[] | null> {
  try {
    const raw  = Uint8Array.from(atob(blob), (c) => c.charCodeAt(0)) as Uint8Array<ArrayBuffer>;
    const salt = raw.slice(0, 32)  as Uint8Array<ArrayBuffer>;
    const iv   = raw.slice(32, 44) as Uint8Array<ArrayBuffer>;
    const ct   = raw.slice(44)     as Uint8Array<ArrayBuffer>;
    const key  = await _bDerivKey(pin, salt);
    const plain = new TextDecoder().decode(await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ct));
    if (!plain.startsWith(BOLSILLO_CANARY)) return null;
    return JSON.parse(plain.slice(BOLSILLO_CANARY.length)) as BolsilloNota[];
  } catch { return null; }
}

function BolsilloSeguro({ token }: { token: string }) {
  type Vista = "cargando" | "locked" | "pin_setup" | "pin_unlock" | "lista" | "editar";
  const [vista, setVista]             = useState<Vista>("cargando");
  const [blob, setBlob]               = useState<string | null>(null);
  const [pin, setPin]                 = useState("");
  const [pinConfirm, setPinConfirm]   = useState("");
  const [pinError, setPinError]       = useState("");
  const [notas, setNotas]             = useState<BolsilloNota[]>([]);
  const [notaActiva, setNotaActiva]   = useState<BolsilloNota | null>(null);
  const [guardando, setGuardando]     = useState<"" | "saving" | "ok">("");
  const pinRef    = useRef<HTMLInputElement>(null);
  const debRef    = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pinActivo = useRef("");

  useEffect(() => {
    fetch("/api/tickets/auth/bolsillo", { headers: { Authorization: `Bearer ${token}` } })
      .then((r) => r.json())
      .then((d: { blob?: string | null }) => {
        const b = d.blob ?? null;
        setBlob(b);
        setVista(b ? "locked" : "pin_setup");
      })
      .catch(() => setVista("locked"));
  }, [token]);

  useEffect(() => {
    if (vista === "pin_unlock" || vista === "pin_setup") {
      setTimeout(() => pinRef.current?.focus(), 80);
    }
  }, [vista]);

  async function persistir(nuevasNotas: BolsilloNota[]) {
    if (!pinActivo.current) return;
    setGuardando("saving");
    try {
      const nuevoBlob = await bolsilloEncriptar(nuevasNotas, pinActivo.current);
      setBlob(nuevoBlob);
      await fetch("/api/tickets/auth/bolsillo", {
        method: "PUT",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ blob: nuevoBlob }),
      });
      setGuardando("ok");
      setTimeout(() => setGuardando(""), 2000);
    } catch { setGuardando(""); }
  }

  function persistirDebounce(nuevasNotas: BolsilloNota[]) {
    if (debRef.current) clearTimeout(debRef.current);
    debRef.current = setTimeout(() => void persistir(nuevasNotas), 900);
  }

  async function confirmarSetup() {
    if (pin.length < 4) { setPinError("Mínimo 4 dígitos"); return; }
    if (pin !== pinConfirm) { setPinError("Los PINes no coinciden"); return; }
    setPinError("");
    pinActivo.current = pin;
    const vacío: BolsilloNota[] = [];
    const nuevoBlob = await bolsilloEncriptar(vacío, pin);
    setBlob(nuevoBlob);
    setNotas(vacío);
    setVista("lista");
    void fetch("/api/tickets/auth/bolsillo", {
      method: "PUT",
      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ blob: nuevoBlob }),
    });
  }

  async function confirmarUnlock() {
    if (!blob) return;
    const resultado = await bolsilloDesencriptar(blob, pin);
    if (resultado === null) { setPinError("PIN incorrecto"); setPin(""); return; }
    setPinError("");
    pinActivo.current = pin;
    setNotas(resultado);
    setVista("lista");
  }

  function bloquear() {
    setNotas([]); setNotaActiva(null);
    setPin(""); setPinConfirm(""); setPinError("");
    pinActivo.current = "";
    setVista("locked");
  }

  function nuevaNota() {
    const nota: BolsilloNota = { id: Date.now(), titulo: "", contenido: "", editadaEn: new Date().toISOString() };
    setNotaActiva(nota);
    setVista("editar");
  }

  function abrirNota(n: BolsilloNota) { setNotaActiva({ ...n }); setVista("editar"); }

  function onCambioNota(campo: "titulo" | "contenido", val: string) {
    if (!notaActiva) return;
    const actualizada = { ...notaActiva, [campo]: val, editadaEn: new Date().toISOString() };
    setNotaActiva(actualizada);
    const nuevas = notas.some((n) => n.id === actualizada.id)
      ? notas.map((n) => n.id === actualizada.id ? actualizada : n)
      : [...notas, actualizada];
    setNotas(nuevas);
    persistirDebounce(nuevas);
  }

  function guardarYVolver() {
    if (notaActiva) {
      const nuevas = notas.some((n) => n.id === notaActiva.id)
        ? notas.map((n) => n.id === notaActiva.id ? notaActiva : n)
        : [...notas, notaActiva];
      setNotas(nuevas);
      void persistir(nuevas);
    }
    setNotaActiva(null);
    setVista("lista");
  }

  function eliminarNota(id: number) {
    const nuevas = notas.filter((n) => n.id !== id);
    setNotas(nuevas);
    void persistir(nuevas);
    setNotaActiva(null);
    setVista("lista");
  }

  if (vista === "cargando") return null;

  const em = "border-accent/60";
  const emBg = "bg-accent/40";

  return (
    <div className="border-t border-border/50 pt-6">
      <p className="mb-3 text-xs font-bold uppercase tracking-widest text-muted flex items-center gap-2">
        🔐 Bolsillo seguro
      </p>

      {/* Locked */}
      {vista === "locked" && (
        <button type="button"
          onClick={() => { setPin(""); setPinError(""); setVista("pin_unlock"); }}
          className="w-full flex items-center gap-3 rounded-2xl border-2 border-border bg-surface-panel px-4 py-4 text-left transition hover:border-accent/50 active:scale-[0.98]">
          <span className="text-2xl">🔒</span>
          <div>
            <p className="text-sm font-bold text-ink">Bolsillo cerrado</p>
            <p className="text-xs text-muted">Toca para ingresar el PIN</p>
          </div>
        </button>
      )}

      {/* Setup PIN */}
      {vista === "pin_setup" && (
        <div className="rounded-2xl border-2 border-accent/40 bg-accent/5 px-4 py-4 space-y-3">
          <p className="text-sm font-bold text-ink">Crear PIN del bolsillo</p>
          <p className="text-xs text-muted">El PIN nunca sale del dispositivo. Si lo perdés, el contenido no se puede recuperar.</p>
          <input ref={pinRef} type="password" inputMode="numeric" maxLength={12}
            placeholder="PIN (mín. 4 dígitos)" value={pin}
            onChange={(e) => setPin(e.target.value.replace(/\D/g, ""))}
            onKeyDown={(e) => e.key === "Enter" && pinRef.current?.blur()}
            className="w-full rounded-xl border-2 border-border bg-surface px-3 py-2 text-sm font-mono tracking-widest text-ink focus:border-accent focus:outline-none" />
          <input type="password" inputMode="numeric" maxLength={12}
            placeholder="Confirmar PIN" value={pinConfirm}
            onChange={(e) => setPinConfirm(e.target.value.replace(/\D/g, ""))}
            onKeyDown={(e) => e.key === "Enter" && void confirmarSetup()}
            className="w-full rounded-xl border-2 border-border bg-surface px-3 py-2 text-sm font-mono tracking-widest text-ink focus:border-accent focus:outline-none" />
          {pinError && <p className="text-xs text-red-500">{pinError}</p>}
          <button type="button" onClick={() => void confirmarSetup()}
            className="w-full rounded-xl bg-accent py-2 text-sm font-bold text-white hover:bg-accent/80 transition">
            Crear bolsillo
          </button>
        </div>
      )}

      {/* Unlock */}
      {vista === "pin_unlock" && (
        <div className="rounded-2xl border-2 border-border bg-surface-panel px-4 py-4 space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-sm font-bold text-ink">🔓 Ingresá el PIN</p>
            <button type="button" onClick={bloquear} className="text-xs text-muted hover:text-ink">✕ Cancelar</button>
          </div>
          <input ref={pinRef} type="password" inputMode="numeric" maxLength={12}
            placeholder="PIN" value={pin}
            onChange={(e) => { setPin(e.target.value.replace(/\D/g, "")); setPinError(""); }}
            onKeyDown={(e) => e.key === "Enter" && void confirmarUnlock()}
            className="w-full rounded-xl border-2 border-border bg-surface px-3 py-2 text-sm font-mono tracking-widest text-center text-ink focus:border-accent focus:outline-none" />
          {pinError && <p className="text-xs text-red-500 text-center">{pinError}</p>}
          <button type="button" onClick={() => void confirmarUnlock()}
            className="w-full rounded-xl bg-accent py-2 text-sm font-bold text-white hover:bg-accent/80 transition">
            Abrir
          </button>
        </div>
      )}

      {/* Lista de notas */}
      {vista === "lista" && (
        <div className={`rounded-2xl border-2 ${em} ${emBg} px-4 py-4 space-y-3`}>
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold text-accent  flex items-center gap-1.5">
              🔓 Abierto
              {guardando === "saving" && <span className="text-muted font-normal">Guardando…</span>}
              {guardando === "ok"     && <span className="font-normal">✓</span>}
            </p>
            <button type="button" onClick={bloquear}
              className="flex items-center gap-1 rounded-full bg-accent/10  px-3 py-1 text-xs font-bold text-accent  hover:bg-accent/20 transition">
              🔒 Bloquear
            </button>
          </div>

          {notas.length === 0 && (
            <p className="py-4 text-center text-xs text-muted">Sin notas aún. Crea la primera.</p>
          )}

          <div className="space-y-2">
            {notas.map((n) => (
              <button key={n.id} type="button" onClick={() => abrirNota(n)}
                className="w-full text-left rounded-xl border border-accent/20 bg-surface-input px-3 py-2.5 space-y-0.5 transition hover:border-accent/40 active:scale-[0.98]">
                <p className="text-sm font-bold text-ink truncate">{n.titulo || <span className="text-muted italic">Sin título</span>}</p>
                {n.contenido && (
                  <p className="text-xs text-muted line-clamp-2 font-mono">{n.contenido}</p>
                )}
              </button>
            ))}
          </div>

          <button type="button" onClick={nuevaNota}
            className="w-full rounded-xl border-2 border-dashed border-accent/30 dark:border-accent py-2.5 text-sm font-bold text-accent  hover:bg-accent/5  transition">
            + Nueva nota
          </button>
          <p className="text-[10px] text-muted text-center">AES-256-GCM · el servidor solo guarda el blob cifrado</p>
        </div>
      )}

      {/* Editor de nota */}
      {vista === "editar" && notaActiva && (
        <div className={`rounded-2xl border-2 ${em} ${emBg} px-4 py-4 space-y-3`}>
          <div className="flex items-center justify-between gap-2">
            <button type="button" onClick={guardarYVolver}
              className="text-xs font-bold text-accent  hover:underline">
              ‹ Volver
            </button>
            <span className="text-xs text-muted flex items-center gap-1">
              {guardando === "saving" && "Guardando…"}
              {guardando === "ok"     && "✓ Guardado"}
            </span>
            <button type="button" onClick={() => { if (confirm("¿Eliminar esta nota?")) eliminarNota(notaActiva.id); }}
              className="text-xs text-red-400 hover:text-red-600 transition">
              🗑 Eliminar
            </button>
          </div>
          <input
            autoFocus
            type="text"
            placeholder="Título de la nota"
            value={notaActiva.titulo}
            onChange={(e) => onCambioNota("titulo", e.target.value)}
            className="w-full rounded-xl border-2 border-accent/20 bg-surface-input px-3 py-2 text-sm font-bold text-ink focus:border-accent/40 focus:outline-none"
          />
          <textarea
            rows={10}
            placeholder="Contenido confidencial…"
            value={notaActiva.contenido}
            onChange={(e) => onCambioNota("contenido", e.target.value)}
            className="w-full resize-none rounded-xl border-2 border-accent/20 bg-surface-input px-3 py-2.5 text-sm text-ink focus:border-accent/40 focus:outline-none font-mono leading-relaxed"
          />
        </div>
      )}
    </div>
  );
}

// ── AccionesView ──────────────────────────────────────────────────────────────

function AccionesView({
  token, user, onSelect, onIrCompras, initialTab, onInicio,
  abrirFormPendientes = false,
  abrirFormProcedimiento = false,
}: {
  token: string; user: TicketsUser;
  onSelect: (id: number) => void;
  onIrCompras?: () => void;
  initialTab?: "subhome" | "activas" | "pendientes" | "procedimientos" | "historial" | "agenda" | "notas" | "bolsillo";
  onInicio?: () => void;
  abrirFormPendientes?: boolean;
  abrirFormProcedimiento?: boolean;
}) {
  const isAdmin = esAdminVistaEquipo(user);
  // apiToken = CHAT_API_TOKEN que usa /api/voz/transcribir (distinto del JWT de tickets)
  const { apiToken: chatApiToken } = useTicketsAuth();
  const [acciones, setAcciones] = useState<Ticket[]>([]);
  const [comprasDelegadas, setComprasDelegadas] = useState<Ticket[]>([]);
  const [usuarios, setUsuarios] = useState<UserInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [filtroEstado, setFiltroEstado] = useState<"" | "pendiente" | "en_proceso" | "resuelto" | "rechazado">(""); // "" = activas
  const [showWizard, setShowWizard] = useState(false);
  const [showIniciarMenu, setShowIniciarMenu] = useState(false);
  const [protocolosMenu, setProtocolosMenu] = useState<Protocolo[]>([]);
  const [loadingMenu, setLoadingMenu] = useState(false);
  const [wizardTituloInicial, setWizardTituloInicial] = useState("");
  const [plantillaWizard, setPlantillaWizard] = useState<PlantillaAccion | undefined>();
  const [reanudarWizard, setReanudarWizard] = useState<ResumeAccionState | null>(null);
  const [showRepetirWizard, setShowRepetirWizard] = useState(false);
  const [plantillaRepetir, setPlantillaRepetir] = useState<PlantillaAccion | undefined>();
  const [reanudarRepetir, setReanudarRepetir] = useState<ReanudarRepetirState | undefined>();
  /** Pantalla de ejecución (notas + cronómetro) al pulsar «Continuar donde quedé». */
  const [ejecutandoAccion, setEjecutandoAccion] = useState<{ id: number; titulo: string } | null>(null);
  const [tabAcciones, setTabAcciones] = useState<"subhome" | "activas" | "historial" | "procedimientos" | "pendientes" | "agenda" | "notas" | "bolsillo">(initialTab ?? "activas");
  const [appAbierta, setAppAbierta] = useState<"placas-concreto" | null>(null);
  const [historial, setHistorial] = useState<Ticket[]>([]);
  const [procedimientos, setProcedimientos] = useState<Protocolo[]>([]);
  const [pendientes, setPendientes] = useState<PendienteItem[]>([]);
  const [recordatorios, setRecordatorios] = useState<RecordatorioItem[]>([]);
  const [loadingPendientes, setLoadingPendientes] = useState(false);
  const [loadingRecordatorios, setLoadingRecordatorios] = useState(false);
  const [loadingExtra, setLoadingExtra] = useState(false);
  const [msg, setMsg] = useState("");
  const [crearPendienteSignal, setCrearPendienteSignal] = useState(0);
  const [crearRecordatorioSignal, setCrearRecordatorioSignal] = useState(0);
  const [crearProcedimientoSignal, setCrearProcedimientoSignal] = useState(0);
  const [crearNotaSignal, setCrearNotaSignal] = useState(0);
  const [registroExpandido, setRegistroExpandido] = useState<number | null>(null);
  const [registros, setRegistros] = useState<Record<number, { comentarios: any[]; adjuntos: any[] }>>({});
  const [histLbUrl, setHistLbUrl] = useState<string | null>(null);
  const nivel = user.rol?.nivel ?? 1;

  // ── STT (voz → título de acción) ─────────────────────────────────────────
  const stt = useStt(token, chatApiToken);

  // ── Alarma: voz periódica configurable ────────────────────────────────────
  const hayMiAccionEnProceso = useCallback(
    (lista: Ticket[]) => lista.some(
      (t) => t.estado === "en_proceso" && uidEq(t.asignado_a, user.id),
    ),
    [user.id],
  );
  const hayEnProceso = useMemo(() => hayMiAccionEnProceso(acciones), [acciones, hayMiAccionEnProceso]);
  const [alarmaActiva, setAlarmaActiva] = useState(true);
  const [alarmaMinutos, setAlarmaMinutos] = useState(15); // 1-60 min
  const [countdown, setCountdown]  = useState(0);        // segundos para próxima alarma
  const alarmaRef    = useRef(alarmaActiva);
  const minRef       = useRef(alarmaMinutos);
  const androidAlarmDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const accionesRef  = useRef(acciones);
  const solicitudesRef = useRef<Ticket[]>([]);
  const tokenRef     = useRef(chatApiToken ?? token);
  const ticketsTokenRef = useRef(token);
  const ultimaAlarmaRef = useRef(Date.now());
  const prevHayEnProcesoRef = useRef<boolean | null>(null);
  const alarmaSincronizadaRef = useRef(false);
  useEffect(() => { alarmaRef.current = alarmaActiva; }, [alarmaActiva]);
  useEffect(() => { minRef.current = alarmaMinutos; }, [alarmaMinutos]);
  useEffect(() => { accionesRef.current = acciones; }, [acciones]);
  useEffect(() => { tokenRef.current = chatApiToken ?? token; }, [chatApiToken, token]);
  useEffect(() => { ticketsTokenRef.current = token; }, [token]);

  // Polling de solicitudes asignadas para el mensaje de alarma
  useEffect(() => {
    const fetchSols = async () => {
      try {
        const data = await tapi("/?tipo=solicitud&activas=1", token) as any[];
        if (!Array.isArray(data)) return;
        solicitudesRef.current = data
          .map(normalizeTicketForList)
          .filter((t: Ticket) => uidEq(t.asignado_a, user.id) && t.estado !== "resuelto" && t.estado !== "rechazado");
      } catch { /* ignore */ }
    };
    void fetchSols();
    const iv = setInterval(() => void fetchSols(), 15_000);
    return () => clearInterval(iv);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token, user.id]);

  const ANDROID_PANEL_PKG = "co.mckennagroup.panel";

  const fireAndroidIntent = useCallback((path: string) => {
    if (isMcKennaAndroidApp() && mckennaAndroidBridge()) return;
    // intent:// solo en Android; en escritorio/Linux dispara diálogos "Abrir con…"
    if (!isAndroidMobileBrowser()) return;
    try {
      const url = `intent://${path}#Intent;scheme=mckennaapp;package=${ANDROID_PANEL_PKG};S.browser_fallback_url=about%3Ablank;end`;
      const a = document.createElement("a");
      a.href = url;
      a.style.display = "none";
      document.body.appendChild(a);
      a.click();
      setTimeout(() => a.remove(), 500);
    } catch { /* ignorar si no es APK Android */ }
  }, []);

  /** Guarda CHAT_API_TOKEN en la app para que descargue el WAV de Voicebox en nativo. */
  const sincronizarTokenAndroid = useCallback((apiToken: string) => {
    if (!apiToken) return;
    const bridge = mckennaAndroidBridge();
    if (bridge?.saveApiToken) {
      bridge.saveApiToken(apiToken);
      return;
    }
    fireAndroidIntent(`token?t=${encodeURIComponent(apiToken)}`);
  }, [fireAndroidIntent]);

  /** Configura AlarmManager nativo + opcional precache del WAV (precache=1). */
  const sincronizarAlarmaAndroid = useCallback((
    activa: boolean,
    minutos: number,
    hayTarea: boolean,
    precache = false,
  ) => {
    const bridge = mckennaAndroidBridge();
    if (bridge?.syncAlarma) {
      bridge.syncAlarma(activa, minutos, hayTarea, precache);
      return;
    }
    fireAndroidIntent(
      `alarma?activa=${activa}&intervalo=${minutos}&hay_tarea=${hayTarea}&precache=${precache ? "1" : "0"}`,
    );
  }, [fireAndroidIntent]);

  useEffect(() => {
    const tok = chatApiToken ?? token;
    if (!tok) return;
    // Esperar a que el TWA termine permisos + arranque de Chrome antes de lanzar intents
    const tid = setTimeout(() => sincronizarTokenAndroid(tok), 12_000);
    return () => clearTimeout(tid);
  }, [chatApiToken, token, sincronizarTokenAndroid]);

  // Al abrir: limpiar hay_tarea obsoleto en Android antes de cargar acciones del servidor
  useEffect(() => {
    sincronizarAlarmaAndroid(false, minRef.current, false, false);
  }, [sincronizarAlarmaAndroid]);

  useEffect(() => {
    if (loading) return;
    const tid = setTimeout(() => {
      sincronizarAlarmaAndroid(
        alarmaRef.current && hayEnProceso,
        minRef.current,
        hayEnProceso,
        false,
      );
      alarmaSincronizadaRef.current = true;
      prevHayEnProcesoRef.current = hayEnProceso;
    }, 300);
    return () => clearTimeout(tid);
  }, [loading, hayEnProceso, sincronizarAlarmaAndroid]);

  useEffect(() => {
    if (!alarmaSincronizadaRef.current) return;
    if (prevHayEnProcesoRef.current === hayEnProceso) return;
    prevHayEnProcesoRef.current = hayEnProceso;
    const tid = setTimeout(
      () => sincronizarAlarmaAndroid(alarmaRef.current && hayEnProceso, minRef.current, hayEnProceso, false),
      600,
    );
    return () => clearTimeout(tid);
  }, [hayEnProceso, sincronizarAlarmaAndroid]);

  // ── Service Worker + Web Push (pantalla bloqueada) ───────────────────────
  const pushSubRef = useRef<PushSubscription | null>(null);

  const registrarPush = useCallback(async (reg: ServiceWorkerRegistration, minutos: number, activa: boolean) => {
    if (!("PushManager" in window)) return;
    try {
      // Obtener clave VAPID pública del servidor
      const kr = await fetch("/api/voz/push/vapid-key");
      const { publicKey, disponible } = await kr.json() as { publicKey: string; disponible: boolean };
      if (!disponible || !publicKey) return;

      // Suscribir (reutiliza suscripción existente si ya existe)
      const sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(publicKey) as BufferSource,
      });
      pushSubRef.current = sub;

      // Registrar programación en el servidor
      await fetch("/api/voz/push/subscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${ticketsTokenRef.current}` },
        body: JSON.stringify({ subscription: sub.toJSON(), minutes: minutos, active: activa }),
      });
    } catch { /* push opcional — fallback al canal de SW message */ }
  }, []);

  useEffect(() => {
    if (isMcKennaAndroidApp() || !("serviceWorker" in navigator) || !webNotificationsAvailable()) return;
    const init = async () => {
      const NotificationApi = globalThis.Notification;
      let perm = NotificationApi.permission;
      if (perm === "default") {
        perm = await NotificationApi.requestPermission();
      }
      if (perm !== "granted") return;

      const reg = await navigator.serviceWorker.register("/app/sw-alarm.js", { scope: "/app/" });
      await navigator.serviceWorker.ready;
      await registrarPush(reg, alarmaMinutos, false);
    };
    init().catch(() => {});
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Re-registrar push cuando cambia intervalo, estado de alarma, o hay tareas activas.
  // El servidor solo envía pushes cuando active=true; desactivamos cuando no hay tareas.
  useEffect(() => {
    if (
      isMcKennaAndroidApp() ||
      !("serviceWorker" in navigator) ||
      !webNotificationsAvailable() ||
      globalThis.Notification.permission !== "granted"
    ) {
      return;
    }
    navigator.serviceWorker.ready.then((reg) => registrarPush(reg, alarmaMinutos, alarmaActiva && hayEnProceso)).catch(() => {});
  }, [alarmaMinutos, alarmaActiva, hayEnProceso, registrarPush]);

  // Pre-calentar caché web + nativo (WAV Voicebox) cuando hay acción propia en curso
  useEffect(() => {
    if (!alarmaActiva || !chatApiToken || !hayEnProceso) return;
    const tok = chatApiToken;
    const tid = setTimeout(() => {
      void (async () => {
        await warmAlarmCache(tok);
        sincronizarAlarmaAndroid(alarmaRef.current, minRef.current, true, true);
      })();
    }, 14_000);
    return () => clearTimeout(tid);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [alarmaActiva, chatApiToken, hayEnProceso, sincronizarAlarmaAndroid]);

  // Dispara la alarma: audio si foreground, notificación + push si background
  const dispararAlarma = useCallback(async (forzar = false) => {
    const hayTarea = hayMiAccionEnProceso(accionesRef.current);
    const solPendiente = solicitudesRef.current[0] ?? null;
    if (!forzar && (!alarmaRef.current || (!hayTarea && !solPendiente))) return;
    // Silencio nocturno 22:00–07:00 — solo el botón "Probar" puede saltarlo
    if (!forzar && esHorarioSilencio()) return;
    ultimaAlarmaRef.current = Date.now();
    if (!document.hidden) {
      if (solPendiente && !hayTarea) {
        const nombre = solPendiente.creado_por_nombre ?? solPendiente.creado_por_info?.nombre ?? "un compañero";
        await playSolicitudAudio(nombre, tokenRef.current ?? undefined);
      } else {
        await playAlarmAudio(tokenRef.current);
      }
    } else {
      // Background / pantalla bloqueada:
      // Canal A — SW message (app en background, pantalla encendida)
      const ctrl = navigator.serviceWorker?.controller;
      if (ctrl && webNotificationsAvailable() && globalThis.Notification.permission === "granted") {
        ctrl.postMessage({ type: "alarm-notification" });
      }
      // Canal B — push server-side (pantalla bloqueada) ya programado vía registrarPush.
      // El servidor dispara automáticamente al intervalo configurado.
    }
  }, [hayMiAccionEnProceso]);

  // Bucle principal: polling 10 s + visibilitychange para resistir throttling
  useEffect(() => {
    const check = () => {
      const ms = minRef.current * 60 * 1000;
      if (Date.now() - ultimaAlarmaRef.current >= ms) void dispararAlarma();
    };
    const iv = setInterval(check, 10_000);
    // Al abrir la app reiniciamos el contador para no disparar la alarma inmediatamente.
    // El usuario verá la alerta en el próximo intervalo normal, no al instante de entrar.
    const onVisible = () => {
      if (!document.hidden) ultimaAlarmaRef.current = Date.now();
    };
    document.addEventListener("visibilitychange", onVisible);
    return () => { clearInterval(iv); document.removeEventListener("visibilitychange", onVisible); };
  }, [dispararAlarma]);

  // Countdown: actualizar cada segundo para mostrar tiempo restante
  useEffect(() => {
    if (!alarmaActiva) { setCountdown(0); return; }
    const iv = setInterval(() => {
      const ms = minRef.current * 60 * 1000;
      const restante = Math.max(0, Math.ceil((ms - (Date.now() - ultimaAlarmaRef.current)) / 1000));
      setCountdown(restante);
    }, 1000);
    return () => clearInterval(iv);
  }, [alarmaActiva]);

  const load = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const paramsAccion = new URLSearchParams({ tipo: "accion", ...(isAdmin ? { vista_equipo: "1" } : {}) });
      const [data, usrs, compras] = await Promise.allSettled([
        tapi(`/?${paramsAccion}`, token),
        tapi("/usuarios", token),
        tapiSafe("/compras-delegadas", token),
      ]);
      const accRaw = data.status === "fulfilled" && Array.isArray(data.value) ? data.value : [];
      const comprasList = compras.status === "fulfilled" && Array.isArray(compras.value)
        ? compras.value.map(normalizeTicketForList)
        : [];
      setComprasDelegadas(comprasList);
      const padresCompra = new Set(
        comprasList.map((c) => c.ticket_padre_id).filter((id): id is number => id != null),
      );
      const accList: Ticket[] = accRaw.map(normalizeTicketForList);
      const list = accList.filter((t) => {
        const tipo = (t.tipo || "").toLowerCase();
        if (tipo !== "accion") return false;
        if (esSolicitudCompraDelegada(t)) return false;
        if (padresCompra.has(t.id)) return false;
        return true;
      });
      setAcciones((prev) => {
        const snap = (arr: Ticket[]) => JSON.stringify(arr.map((t) => `${t.id}:${t.estado}:${t.actualizado_en ?? ""}:${t.pasos_completados ?? 0}/${t.pasos_total ?? 0}`));
        return snap(list) === snap(prev) ? prev : list;
      });
      if (usrs.status === "fulfilled" && Array.isArray(usrs.value)) {
        setUsuarios(usrs.value);
      }
    } catch { /* ignore */ }
    finally { if (!silent) setLoading(false); }
  }, [token, isAdmin, user.id]);

  useEffect(() => {
    const iv = setInterval(() => { void load(true); }, 15000);
    return () => clearInterval(iv);
  }, [load]);
  useEffect(() => onPanelResume(() => { void load(true); }), [load]);

  function abrirWizard(tituloPrefill = "", plantilla?: PlantillaAccion) {
    setReanudarWizard(null);
    setWizardTituloInicial(tituloPrefill);
    setPlantillaWizard(plantilla);
    setShowWizard(true);
    setMsg("");
  }

  async function continuarAccion(t: Ticket) {
    const tipo = (t.tipo || "").toLowerCase();
    if (tipo !== "accion" || esTarjetaSoloCompras(t, user) || esSolicitudCompraDelegada(t)) {
      setMsg("Esta tarea es solo ir de compras — ábrela en Solicitudes.");
      onIrCompras?.();
      return;
    }
    if (comprasDelegadas.some((c) => c.ticket_padre_id === t.id)) {
      setMsg("Las compras de esta acción las llevas en Solicitudes → Ir de compras.");
      onIrCompras?.();
      return;
    }

    // Acción en_proceso sin bloqueo: abrir pantalla de ejecución (notas + cronómetro) en Hugo
    if (t.estado === "en_proceso" && !t.bloqueado_por && onInicio) {
      setLoadingExtra(true);
      setMsg("");
      try {
        const payload = { id: t.id, titulo: t.titulo };
        localStorage.setItem("mckenna-accion-activa", JSON.stringify(payload));
        // Boot en store: Hugo lo consume al montar/actualizar. localStorage solo no basta —
        // AgenteMandoView borraba mckenna-accion-activa al montar y nunca abría la acción.
        useAppStore.getState().setHugoAccionBoot(payload);
        onInicio();
        return;
      } catch {
        /* falló el handoff — continuar con el wizard como fallback */
      } finally {
        setLoadingExtra(false);
      }
    }

    setLoadingExtra(true);
    setMsg("");
    try {
      const resume = await cargarEstadoReanudacion(t.id, token);
      if (t.estado === "pendiente") {
        try {
          const segPrev = resume.ticket.corrida?.segundos_acumulados ?? resume.ticket.segundos_trabajo ?? 0;
          await tapi(`/${t.id}/corridas/iniciar`, token, {
            method: "POST",
            body: JSON.stringify({ segundos_previos: segPrev }),
          });
          await tapi(`/${t.id}/estado`, token, {
            method: "PUT",
            body: JSON.stringify({ estado: "en_proceso" }),
          });
          const det = await tapi(`/${t.id}`, token) as Ticket;
          resume.ticket = det;
        } catch { /* wizard sincroniza al abrir */ }
      }

      // Detectar si este ticket fue creado por RepetirAccionWizard:
      // Tiene pasos guardados, no hay compras pendientes y no hay bloqueos.
      // En ese caso, retomar con la UI Duolingo paso-a-paso.
      const esRepetir =
        resume.faseInicial === "cierre" &&
        resume.plantilla.pasos.length > 0 &&
        !resume.bloqueoCompras &&
        !resume.bloqueadoIntervencion &&
        resume.plantilla.listaCompras.length === 0;

      if (esRepetir) {
        // Cargar IDs de pasos del servidor para poder marcarlos completados
        let pasosIds: number[] = [];
        let startPasoIdx = 0;
        try {
          const pasosRaw = await tapi(`/${t.id}/pasos`, token) as Paso[];
          const reales = pasosRaw.filter((p) => p.descripcion !== "Ir de compras");
          pasosIds = reales.map((p) => p.id);
          const primerIncompleto = reales.findIndex((p) => !pasoEstaCompletado(p));
          startPasoIdx = primerIncompleto >= 0 ? primerIncompleto : reales.length;
        } catch { /* usamos idx 0 */ }

        const segundosBase = resume.ticket.corrida?.segundos_acumulados ?? resume.ticket.segundos_trabajo ?? 0;
        setPlantillaRepetir(resume.plantilla);
        setReanudarRepetir({
          ticketId: t.id,
          pasosIds,
          corridaId: resume.ticket.corrida?.id ?? null,
          segundosBase,
          startPasoIdx,
        });
        setShowRepetirWizard(true);
        return;
      }

      setReanudarWizard(resume);
      setPlantillaWizard(undefined);
      setWizardTituloInicial("");
      setShowWizard(true);
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "No se pudo abrir la acción");
    } finally {
      setLoadingExtra(false);
    }
  }

  const cargarHistorialYProcedimientos = useCallback(async (silent = false) => {
    if (!silent) setLoadingExtra(true);
    // Cargar independientemente para que un fallo en historial no bloquee procedimientos
    const [histRes, procRes] = await Promise.allSettled([
      tapi("/acciones/historial", token),
      tapi("/protocolos?alcance=mis", token),
    ]);
    if (histRes.status === "fulfilled") {
      setHistorial(Array.isArray(histRes.value) ? histRes.value.map(normalizeTicketForList) : []);
    }
    if (procRes.status === "fulfilled") {
      setProcedimientos(Array.isArray(procRes.value) ? procRes.value : []);
    }
    if (!silent) setLoadingExtra(false);
  }, [token]);

  const cargarPendientes = useCallback(async () => {
    setLoadingPendientes(true);
    try {
      const data = await tapi("/pendientes", token);
      setPendientes(Array.isArray(data) ? data : []);
    } catch { /* ignore */ } finally { setLoadingPendientes(false); }
  }, [token]);

  const cargarRecordatorios = useCallback(async () => {
    setLoadingRecordatorios(true);
    try {
      const data = await tapi("/recordatorios", token);
      const lista = Array.isArray(data) ? data : [];
      setRecordatorios(lista);
      const hoy = new Date().toISOString().slice(0, 10);
      const activos = lista.filter((r: RecordatorioItem) => r.proxima_fecha <= hoy);
      const sessionKey = `mck-rec-notif-${hoy}`;
      if (activos.length > 0 && !sessionStorage.getItem(sessionKey)) {
        sessionStorage.setItem(sessionKey, "1");
        // Notificación WhatsApp (voz Hugo García por WhatsApp)
        fetch("/api/tickets/recordatorios/notificar-hoy", {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
        }).catch(() => {});
        // Audio en el navegador (voz Hugo García)
        const apiTok = chatApiToken ?? token;
        if (apiTok) void playRecordatorioAlerta(apiTok, activos.length);
      }
    } catch { /* ignore */ } finally { setLoadingRecordatorios(false); }
  }, [token, chatApiToken]);

  useEffect(() => {
    void load(false);
    void cargarPendientes();
    void cargarRecordatorios();
  }, [load, cargarPendientes, cargarRecordatorios]);

  useEffect(() => {
    if (tabAcciones === "historial" || tabAcciones === "procedimientos") {
      void cargarHistorialYProcedimientos();
    }
    if (tabAcciones === "pendientes" || tabAcciones === "subhome" || tabAcciones === "agenda") void cargarPendientes();
    if (tabAcciones === "subhome" || tabAcciones === "agenda") void cargarRecordatorios();
  }, [tabAcciones, cargarHistorialYProcedimientos, cargarPendientes, cargarRecordatorios]);

  // Historial/procedimientos: refresco periódico y al volver a la app (móvil en background no recibe el poll de activas)
  useEffect(() => {
    if (tabAcciones !== "historial" && tabAcciones !== "procedimientos") return;
    const iv = setInterval(() => { void cargarHistorialYProcedimientos(true); }, 15000);
    return onPanelResume(() => { void cargarHistorialYProcedimientos(true); });
  }, [tabAcciones, cargarHistorialYProcedimientos]);

  async function repetirProcedimiento(protocoloId: number) {
    setLoadingExtra(true);
    try {
      const p = await tapi(`/protocolos/${protocoloId}`, token) as Protocolo;
      const plantilla = plantillaDesdeProtocolo(p);
      // Si el procedimiento tiene pasos o lista de compras → usar el wizard guía visual
      if (plantilla.pasos.length > 0 || plantilla.listaCompras.length > 0) {
        setPlantillaRepetir(plantilla);
        setShowRepetirWizard(true);
      } else {
        abrirWizard("", plantilla);
      }
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "No se pudo cargar el procedimiento");
    } finally {
      setLoadingExtra(false);
    }
  }

  async function repetirDesdeHistorial(accionId: number) {
    setLoadingExtra(true);
    try {
      let plantilla: PlantillaAccion;
      try {
        const data = await tapi(`/${accionId}/plantilla-accion`, token) as PlantillaAccionApi;
        plantilla = plantillaDesdeApi(data);
      } catch {
        const [det, pasosRaw] = await Promise.all([
          tapi(`/${accionId}`, token) as Promise<Ticket>,
          tapi(`/${accionId}/pasos`, token) as Promise<Paso[]>,
        ]);
        const pasosArr = Array.isArray(pasosRaw) ? pasosRaw : [];
        let listaCompras: ItemCompraAccion[] = [];
        const pasosEj: PasoAccionDraft[] = [];
        for (const p of pasosArr) {
          if (p.descripcion === "Ir de compras" && p.notas) {
            listaCompras = parseListaComprasDesdeNotas(p.notas as string);
          } else if (p.descripcion) {
            pasosEj.push({ nombre: p.descripcion, desc: (p.notas as string) || "" });
          }
        }
        plantilla = {
          titulo: det.titulo,
          protocoloId: det.protocolo_id ?? undefined,
          listaCompras,
          pasos: pasosEj,
        };
      }
      setPlantillaRepetir(plantilla);
      setShowRepetirWizard(true);
      setMsg("");
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "No se pudo cargar la acción");
    } finally {
      setLoadingExtra(false);
    }
  }

  async function guardarProcedimientoHistorial(accionId: number, alcance: "personal" | "global") {
    setLoadingExtra(true);
    try {
      await tapi(`/${accionId}/guardar-procedimiento`, token, {
        method: "POST",
        body: JSON.stringify({ alcance }),
      });
      setMsg(alcance === "global"
        ? "Procedimiento compartido con el equipo"
        : "Procedimiento guardado en «Mis procedimientos»");
      void cargarHistorialYProcedimientos();
      setTimeout(() => setMsg(""), 3000);
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "Error al guardar procedimiento");
    } finally {
      setLoadingExtra(false);
    }
  }

  async function promoverProtocolo(protocoloId: number) {
    try {
      await tapi(`/protocolos/${protocoloId}/promover`, token, { method: "POST" });
      setMsg("Procedimiento disponible para delegar en solicitudes");
      void cargarHistorialYProcedimientos();
      setTimeout(() => setMsg(""), 3000);
    } catch (e: unknown) {
      setMsg(e instanceof Error ? e.message : "Error al promover");
    }
  }

  async function onAccionCreada(_ticketId: number) {
    // Parar alarma Android inmediatamente antes de que el usuario pueda salir de la app.
    // load() es async; si el usuario cierra antes de que termine, la alarma quedaba activa.
    sincronizarAlarmaAndroid(alarmaRef.current, minRef.current, false, false);
    setShowWizard(false);
    setWizardTituloInicial("");
    setPlantillaWizard(undefined);
    setReanudarWizard(null);
    await load(false);
    // Re-sincronizar con estado real por si quedan otras acciones en_proceso
    sincronizarAlarmaAndroid(alarmaRef.current, minRef.current, hayMiAccionEnProceso(accionesRef.current), false);
    if (tabAcciones !== "activas") void cargarHistorialYProcedimientos();
    setMsg("Acción registrada");
    setTimeout(() => setMsg(""), 2500);
  }

  // Agrupar acciones por usuario asignado (las solicitudes van solo en pestaña Solicitudes)
  const porAsignado = useMemo(() => {
    const map = new Map<number, { nombre: string; acciones: Ticket[] }>();
    for (const t of acciones) {
      if ((t.tipo || "") !== "accion" || esSolicitudCompraDelegada(t)) continue;
      const uid = t.asignado_a ?? 0;
      if (!map.has(uid)) {
        map.set(uid, { nombre: t.asignado_a_nombre ?? "Sin asignar", acciones: [] });
      }
      map.get(uid)!.acciones.push(t);
    }
    return [...map.values()].sort((a, b) => a.nombre.localeCompare(b.nombre, "es"));
  }, [acciones]);

  const sinResolver = acciones.filter((t) => t.estado !== "resuelto" && t.estado !== "rechazado").length;

  if (showRepetirWizard && plantillaRepetir) {
    return (
      <RepetirAccionWizard
        token={token}
        user={user}
        chatApiToken={chatApiToken}
        plantilla={plantillaRepetir}
        reanudar={reanudarRepetir}
        onCancel={() => {
          setShowRepetirWizard(false);
          setPlantillaRepetir(undefined);
          setReanudarRepetir(undefined);
          void load(true);
        }}
        onCreated={(id) => {
          setShowRepetirWizard(false);
          setPlantillaRepetir(undefined);
          setReanudarRepetir(undefined);
          void onAccionCreada(id);
        }}
      />
    );
  }

  if (showWizard && !isAdmin) {
    return (
      <NuevaAccionWizard
        token={token}
        user={user}
        chatApiToken={chatApiToken}
        tituloInicial={wizardTituloInicial}
        plantilla={plantillaWizard}
        reanudar={reanudarWizard ?? undefined}
        onCancel={() => {
          setShowWizard(false);
          setWizardTituloInicial("");
          setPlantillaWizard(undefined);
          setReanudarWizard(null);
          void load(true);
        }}
        onCreated={(id) => void onAccionCreada(id)}
      />
    );
  }

  const tc = ACCIONES_TAB_CFG[tabAcciones as AccionesTab] ?? ACCIONES_TAB_CFG.subhome;
  const mostrarCta = tc.ctaBase && !isAdmin;
  const mostrarCtaCrear =
    tabAcciones === "pendientes"
    || (tabAcciones === "procedimientos" && puedeCrearProtocolos(user))
    || tabAcciones === "notas";
  const labelCtaCrear =
    tabAcciones === "pendientes" ? "+ Nueva acción futura"
    : tabAcciones === "agenda" ? "+ Nuevo recordatorio"
    : tabAcciones === "notas" ? "+ Nueva nota"
    : "+ Nuevo procedimiento";
  function abrirFormularioCrear() {
    if (tabAcciones === "pendientes") setCrearPendienteSignal((n) => n + 1);
    else if (tabAcciones === "agenda") setCrearRecordatorioSignal((n) => n + 1);
    else if (tabAcciones === "notas") setCrearNotaSignal((n) => n + 1);
    else if (tabAcciones === "procedimientos") setCrearProcedimientoSignal((n) => n + 1);
  }

  return (
    <div className="space-y-4">
      {/* Header — barra compacta adaptativa al subtab activo */}
      <div className={`rounded-xl border ${tc.card} px-3 py-2.5 space-y-2`}>
        {/* Fila principal: ícono + título + badge + CTAs */}
        <div className="flex items-center gap-2 flex-wrap">
          <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg border border-border/60 bg-surface/80 text-ink">
            <TopicIcon value={tc.emoji} size={15} weight="regular" />
          </span>
          <span className="text-sm font-bold text-ink flex items-center gap-1.5">
            {tc.titulo}
            {(tabAcciones === "subhome" || tabAcciones === "activas") && sinResolver > 0 && (
              <span className="rounded-full bg-accent px-1.5 py-px text-[10px] font-bold text-white">{sinResolver}</span>
            )}
          </span>
          <div className="ml-auto flex items-center gap-1.5 flex-wrap">
            {mostrarCta && (
              <button
                type="button"
                onClick={async () => {
                  setLoadingMenu(true);
                  setShowIniciarMenu(true);
                  try {
                    const data = await tapi("/protocolos", token);
                    setProtocolosMenu(Array.isArray(data) ? data : []);
                  } catch { setProtocolosMenu([]); } finally { setLoadingMenu(false); }
                }}
                className={`${CENTRO_MANDO_CTA_BTN} ${tc.btnCtaCls}`}
              >
                <Icon name="plus" size={16} weight="bold" />
                Iniciar acción
              </button>
            )}
            {mostrarCtaCrear && (
              <button
                type="button"
                onClick={abrirFormularioCrear}
                className={`${CENTRO_MANDO_CTA_BTN} ${tc.btnCtaCls}`}
              >
                <Icon name="plus" size={16} weight="bold" />
                {labelCtaCrear}
              </button>
            )}
            {tabAcciones === "subhome" && onInicio && (
              <button
                type="button"
                onClick={onInicio}
                className="flex items-center gap-1 rounded-lg border border-border/60 px-2.5 py-1 text-xs font-bold text-muted hover:border-accent hover:text-accent transition"
                title="Volver al inicio"
              >
                <TopicIcon value="🏠" size={13} className="shrink-0" /> Inicio
              </button>
            )}
          </div>
        </div>
      </div>

      {/* ── Menú de inicio: libre o desde procedimiento ── */}
      {showIniciarMenu && !isAdmin && (
        <div className="rounded-2xl border-2 border-accent/40 bg-accent/5 p-4 space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold uppercase tracking-widest text-accent">¿Cómo quieres empezar?</p>
            <button type="button" onClick={() => setShowIniciarMenu(false)} className="text-muted hover:text-ink text-sm">✕</button>
          </div>
          <div className="grid gap-2 sm:grid-cols-2">
            <button
              type="button"
              onClick={() => { setShowIniciarMenu(false); abrirWizard(); }}
              className="text-left rounded-2xl border-2 border-border bg-surface px-4 py-4 transition hover:border-accent hover:bg-accent/5 group"
            >
              <p className="text-sm font-extrabold text-ink group-hover:text-accent transition-colors">✍️ Acción libre</p>
              <p className="mt-1 text-xs text-muted">Describe con tus palabras qué vas a hacer.</p>
            </button>
            <div className="rounded-2xl border-2 border-border bg-surface px-4 py-4 space-y-2">
              <p className="text-sm font-extrabold text-ink">📋 Desde procedimiento</p>
              <p className="text-xs text-muted">Ejecuta un proceso ya definido del equipo.</p>
              {loadingMenu && <p className="text-xs text-muted">Cargando…</p>}
              {!loadingMenu && protocolosMenu.length === 0 && (
                <p className="text-xs text-muted italic">No hay procedimientos disponibles.</p>
              )}
              {!loadingMenu && protocolosMenu.length > 0 && (
                <div className="space-y-1 max-h-40 overflow-y-auto pr-1">
                  {protocolosMenu.map((p) => (
                    <button
                      key={p.id}
                      type="button"
                      onClick={() => {
                        setShowIniciarMenu(false);
                        const plantilla = plantillaDesdeProtocolo(p);
                        const tieneContenido = plantilla.listaCompras.length > 0 || plantilla.pasos.length > 0;
                        if (tieneContenido) {
                          setPlantillaRepetir(plantilla);
                          setReanudarRepetir(undefined);
                          setShowRepetirWizard(true);
                        } else {
                          abrirWizard("", plantilla);
                        }
                      }}
                      className="w-full text-left rounded-xl border border-border px-3 py-2 text-xs font-semibold text-ink hover:border-accent hover:bg-accent/5 transition"
                    >
                      <span className="block truncate">{p.titulo}</span>
                      {(p.pasos?.length ?? 0) > 0 && (
                        <span className="text-[10px] text-muted">{p.pasos.length} paso{p.pasos.length !== 1 ? "s" : ""}{(p.lista_compras?.length ?? 0) > 0 ? ` · ${p.lista_compras!.length} ingredientes` : ""}</span>
                      )}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {msg && !showWizard && (
        <p className="text-sm text-accent font-semibold">{msg}</p>
      )}


      {/* ── Sub-home de Acciones: métricas de equipo para admin ── */}
      {isAdmin && tabAcciones === "subhome" && (
        <AdminSubhomePanel
          token={token}
          acciones={acciones}
          usuarios={usuarios}
          onVerActivas={() => setTabAcciones("activas")}
        />
      )}

      {/* ── Sub-home de Acciones: cards por sección ── */}
      {!isAdmin && tabAcciones === "subhome" && (() => {
        const hoy = new Date().toISOString().slice(0, 10);
        const recHoy = recordatorios.filter((r) => r.proxima_fecha <= hoy).length;
        const pendHoy = pendientes.filter((p) => p.fecha_recordatorio && p.fecha_recordatorio <= hoy).length;
        const activas = acciones.filter((t) => t.estado === "en_proceso").length;
        const subCard = [
          "group flex flex-col gap-5 rounded-3xl border p-6 text-left w-full",
          "shadow-[0_2px_14px_rgba(0,0,0,0.06)] hover:shadow-[0_6px_22px_rgba(0,0,0,0.10)]",
          "transition-all duration-200 cursor-pointer active:scale-[0.97]",
        ].join(" ");
        return (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">

            <button type="button" onClick={() => setTabAcciones("activas")}
              className={`${subCard} bg-accent/5  border-accent/20`}>
              <div className="flex items-center justify-between gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="⚡" size={24} />
                </span>
                <span className="text-4xl font-black text-ink dark:text-white tabular-nums leading-none tracking-tight">{acciones.length}</span>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">En curso</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Las acciones que tienes activas ahorita mismo.</p>
            </button>

            {/* Agenda unificada: futuras + recordatorios en una sola card */}
            <button type="button" onClick={() => setTabAcciones("agenda")}
              className={`${subCard} bg-accent/5  border-accent/20`}>
              <div className="flex items-center justify-between gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="📅" size={24} />
                </span>
                <div className="text-right space-y-1">
                  <span className="text-4xl font-black text-ink dark:text-white tabular-nums leading-none tracking-tight">
                    {recordatorios.length}
                  </span>
                  {recHoy > 0 && (
                    <p className="text-xs font-bold text-accent">{recHoy} para hoy</p>
                  )}
                </div>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">Agenda</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Tu espacio personal. Recordatorios, notas y pensamientos solo tuyos.</p>
            </button>

            <button type="button" onClick={() => setTabAcciones("historial")}
              className={`${subCard} bg-stone-50 dark:bg-stone-900/60 border-stone-200 dark:border-stone-600/50`}>
              <div className="flex items-center gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="📜" size={24} />
                </span>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">Historial</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Todo lo que ya completaste. Pa' que no se pierda nada de lo que hiciste.</p>
            </button>

            <button type="button" onClick={() => setTabAcciones("procedimientos")}
              className={`${subCard} bg-accent/5  border-accent/20`}>
              <div className="flex items-center justify-between gap-3">
                <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-border bg-surface text-ink">
                  <TopicIcon value="🔒" size={24} />
                </span>
                <span className="text-4xl font-black text-ink dark:text-white tabular-nums leading-none tracking-tight">{procedimientos.length}</span>
              </div>
              <p className="text-2xl font-extrabold text-ink dark:text-white leading-snug tracking-tight">Procedimientos</p>
              <p className="text-base font-bold text-ink/80 dark:text-white/90 leading-snug">Pasos que ya guardaste listos pa' reutilizar. Sin tener que explicar todo de nuevo.</p>
            </button>

          </div>
        );
      })()}


      {tabAcciones === "pendientes" && (
        <PendientesPanel
          token={token}
          pendientes={pendientes}
          loading={loadingPendientes}
          abrirFormInicial={abrirFormPendientes}
          abrirFormSignal={crearPendienteSignal}
          onRecargar={() => void cargarPendientes()}
        />
      )}

      {tabAcciones === "agenda" && (
        <div className="space-y-6">
          <RecordatoriosPanel
            token={token}
            recordatorios={recordatorios}
            loading={loadingRecordatorios}
            abrirFormInicial={false}
            abrirFormSignal={crearRecordatorioSignal}
            onRecargar={() => void cargarRecordatorios()}
            usuarios={isAdmin ? usuarios : []}
            usuarioActualId={user.id}
          />
        </div>
      )}

      {tabAcciones === "notas" && (
        <NotasPensamientos crearSignal={crearNotaSignal} />
      )}

      {tabAcciones === "bolsillo" && (
        <BolsilloSeguro token={token} />
      )}

      {tabAcciones === "historial" && isAdmin && (
        <div className="space-y-3">
          <div className="flex items-center justify-between gap-2">
            <p className="text-xs text-muted flex items-center gap-2">
              {loadingExtra ? "Actualizando…" : (
                <>
                  <span className="font-semibold text-ink">{historial.length}</span>
                  {` acción${historial.length !== 1 ? "es" : ""} resueltas — todo el equipo`}
                </>
              )}
            </p>
            <button type="button" onClick={() => void cargarHistorialYProcedimientos()}
              disabled={loadingExtra}
              className="text-xs text-accent hover:underline disabled:opacity-50">
              ↻ Recargar
            </button>
          </div>
          {loadingExtra && historial.length === 0 && <p className="text-sm text-muted">Cargando historial…</p>}
          {!loadingExtra && historial.length === 0 && (
            <p className="py-8 text-center text-sm text-muted">No hay acciones resueltas aún.</p>
          )}
          {!loadingExtra && historial.length > 0 && (
            <div className="space-y-2">
              {historial.map((t) => {
                const seg = t.segundos_trabajo ?? 0;
                const total = t.pasos_total ?? 0;
                const ok = t.pasos_completados ?? 0;
                const tiempoStr = (() => {
                  if (seg < 60) return seg > 0 ? `${seg}s` : null;
                  const h = Math.floor(seg / 3600);
                  const m = Math.floor((seg % 3600) / 60);
                  return h > 0 ? `${h}h ${m}m` : `${m}m`;
                })();
                const fechaStr = (() => {
                  const raw = t.actualizado_en ?? t.creado_en;
                  if (!raw) return null;
                  try {
                    const d = new Date(raw.includes("T") || raw.includes("Z") ? raw : raw + "Z");
                    const diff = Math.floor((Date.now() - d.getTime()) / 86400000);
                    if (diff === 0) return "hoy";
                    if (diff === 1) return "ayer";
                    if (diff < 30) return `hace ${diff}d`;
                    return d.toLocaleDateString("es-CO", { day: "numeric", month: "short" });
                  } catch { return null; }
                })();
                const completa = total > 0 && ok === total;
                return (
                  <button key={t.id} type="button" onClick={() => onSelect(t.id)}
                    className="w-full text-left rounded-xl border-2 border-border bg-surface-panel px-4 py-3 space-y-1.5 hover:border-accent/50 transition active:scale-[0.99]">
                    <div className="flex items-start justify-between gap-2">
                      <p className="font-bold text-sm text-ink leading-snug flex-1 min-w-0 truncate">{t.titulo}</p>
                      {fechaStr && <span className="text-[10px] text-muted shrink-0">{fechaStr}</span>}
                    </div>
                    <div className="flex flex-wrap items-center gap-1.5">
                      {(t as any).responsable_nombre && (
                        <span className="inline-flex items-center gap-1 rounded-full border border-border bg-surface px-2 py-0.5 text-[10px] font-semibold text-ink">
                          👤 {(t as any).responsable_nombre}
                        </span>
                      )}
                      {total > 0 && (
                        <span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold border ${
                          completa ? "border-accent/40 text-accent" : "border-accent/40 text-accent"
                        }`}>
                          {completa ? `✓ ${total} paso${total !== 1 ? "s" : ""}` : `${ok}/${total} pasos`}
                        </span>
                      )}
                      {tiempoStr && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-surface border border-border px-2 py-0.5 text-[10px] text-muted">
                          ⏱ {tiempoStr}
                        </span>
                      )}
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </div>
      )}

      {tabAcciones === "historial" && !isAdmin && (
        <div className="space-y-3">
          <div className="flex items-center justify-between gap-2">
            <p className="text-xs text-muted">
              {loadingExtra ? "Actualizando…" : `${historial.length} acción${historial.length === 1 ? "" : "es"} en historial`}
            </p>
            <button
              type="button"
              onClick={() => void cargarHistorialYProcedimientos()}
              disabled={loadingExtra}
              className="text-xs text-accent hover:underline disabled:opacity-50"
            >
              ↻ Recargar historial
            </button>
          </div>
          {loadingExtra && historial.length === 0 && <p className="text-sm text-muted">Cargando historial…</p>}
          {!loadingExtra && historial.length === 0 && (
            <p className="py-8 text-center text-sm text-muted">Aún no hay acciones en tu historial.</p>
          )}
          {!loadingExtra && historial.length > 0 && (
            <div className="grid gap-3 sm:grid-cols-2">
              {historial.map((t) => {
                const total = t.pasos_total ?? 0;
                const ok = t.pasos_completados ?? 0;
                const seg = t.segundos_trabajo ?? 0;
                const tieneProcedimiento = !!(t.procedimiento_id ?? t.protocolo_id);

                const estado =
                  total === 0 ? "vacia"
                  : ok === total ? "completa"
                  : "incompleta";

                const borderClass =
                  estado === "completa" ? "border-accent/50"
                  : estado === "incompleta" ? "border-accent/50"
                  : "border-border";

                const badge =
                  estado === "completa"
                    ? <span className="inline-flex items-center gap-1 rounded-full bg-accent/10  px-2 py-0.5 text-[10px] font-bold text-accent">✓ Completa</span>
                  : estado === "incompleta"
                    ? <span className="inline-flex items-center gap-1 rounded-full bg-accent/10  px-2 py-0.5 text-[10px] font-bold text-accent">⚠ Incompleta</span>
                  : <span className="inline-flex items-center gap-1 rounded-full bg-surface border border-border px-2 py-0.5 text-[10px] font-bold text-muted">Sin pasos</span>;

                const tiempoStr = (() => {
                  if (seg < 60) return seg > 0 ? `${seg}s` : null;
                  const h = Math.floor(seg / 3600);
                  const m = Math.floor((seg % 3600) / 60);
                  return h > 0 ? `${h}h ${m}m` : `${m}m`;
                })();

                const fechaStr = (() => {
                  const raw = t.actualizado_en ?? t.creado_en;
                  if (!raw) return null;
                  try {
                    const d = new Date(raw.includes("T") || raw.includes("Z") ? raw : raw + "Z");
                    const diff = Math.floor((Date.now() - d.getTime()) / 86400000);
                    if (diff === 0) return "hoy";
                    if (diff === 1) return "ayer";
                    if (diff < 30) return `hace ${diff}d`;
                    return d.toLocaleDateString("es-CO", { day: "numeric", month: "short" });
                  } catch { return null; }
                })();

                return (
                  <div key={t.id} className={`rounded-xl border-2 ${borderClass} bg-surface-panel p-3 space-y-2.5`}>
                    {/* Header: badge + fecha */}
                    <div className="flex items-start justify-between gap-2">
                      {badge}
                      {fechaStr && <span className="text-[10px] text-muted shrink-0">{fechaStr}</span>}
                    </div>

                    {/* Título */}
                    <p className="font-bold text-sm text-ink leading-snug">{t.titulo}</p>
                    <p className="text-[10px] text-muted font-mono">{t.numero}</p>

                    {/* Stats */}
                    <div className="flex flex-wrap gap-1.5">
                      {total > 0 && (
                        <span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold border ${
                          estado === "completa"
                            ? "bg-accent/5  border-accent/40 text-accent"
                            : "bg-accent/5  border-accent/40 text-accent"
                        }`}>
                          {estado === "completa" ? "✓" : `${ok}/`}{estado !== "completa" && total} {total === 1 ? "paso" : "pasos"}
                        </span>
                      )}
                      {tiempoStr && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-surface border border-border px-2 py-0.5 text-[10px] font-semibold text-muted">
                          ⏱ {tiempoStr}
                        </span>
                      )}
                      {t.categoria && (
                        <span className="inline-flex items-center rounded-full bg-surface border border-border px-2 py-0.5 text-[10px] text-muted">
                          {t.categoria}
                        </span>
                      )}
                      {tieneProcedimiento && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-accent/10 border border-accent/30 px-2 py-0.5 text-[10px] font-bold text-accent">
                          📋 Procedimiento
                        </span>
                      )}
                    </div>

                    {/* Registro de actividad expandible */}
                    {registroExpandido === t.id && (
                      <div className="rounded-xl bg-surface border border-border p-3 space-y-2">
                        {!registros[t.id] ? (
                          <p className="text-xs text-muted text-center py-2">Cargando…</p>
                        ) : (() => {
                            const items = [
                              ...registros[t.id].comentarios.map((c: any) => ({ ...c, _tipo: "comentario" })),
                              ...registros[t.id].adjuntos.map((a: any) => ({ ...a, _tipo: "adjunto" })),
                            ].sort((a, b) => (a.creado_en ?? "").localeCompare(b.creado_en ?? ""));

                            if (items.length === 0) return (
                              <p className="text-xs text-muted text-center py-2">No hay notas ni fotos registradas.</p>
                            );

                            const fmt = (ts: string) => {
                              try { return new Date(ts.includes("T") || ts.includes("Z") ? ts : ts + "Z").toLocaleString("es-CO", { dateStyle: "short", timeStyle: "short" }); }
                              catch { return ts; }
                            };

                            return (
                              <div className="space-y-2">
                                {histLbUrl && <ImageLightbox url={histLbUrl} onClose={() => setHistLbUrl(null)} />}
                                {items.map((item: any, idx: number) => (
                                  <div key={idx}>
                                    {item._tipo === "adjunto" ? (
                                      <div>
                                        <button
                                          type="button"
                                          onClick={() => setHistLbUrl(`/api/tickets/uploads/${encodeURIComponent(item.nombre_archivo)}?token=${token}`)}
                                          className="group relative block w-full max-w-xs"
                                        >
                                          <img src={`/api/tickets/uploads/${encodeURIComponent(item.nombre_archivo)}?token=${token}`}
                                            alt={item.nombre_original ?? "foto"}
                                            className="rounded-xl w-full border border-border object-cover hover:opacity-80 transition"/>
                                          <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-2xl font-bold transition-opacity pointer-events-none">🔍</span>
                                        </button>
                                        <p className="text-[10px] text-muted mt-1">{fmt(item.creado_en)}</p>
                                      </div>
                                    ) : (
                                      <div className="rounded-lg bg-surface-hover px-3 py-2">
                                        <p className="text-xs text-ink leading-relaxed whitespace-pre-wrap">{item.texto}</p>
                                        <p className="text-[10px] text-muted mt-1">{fmt(item.creado_en)}</p>
                                      </div>
                                    )}
                                  </div>
                                ))}
                              </div>
                            );
                          })()
                        }
                      </div>
                    )}

                    {/* Acciones */}
                    <div className="flex flex-col gap-1.5 pt-0.5">
                      {/* Ver registro */}
                      <button
                        type="button"
                        onClick={async () => {
                          if (registroExpandido === t.id) { setRegistroExpandido(null); return; }
                          setRegistroExpandido(t.id);
                          if (!registros[t.id]) {
                            const [coms, adjs] = await Promise.allSettled([
                              tapi(`/${t.id}/comentarios`, token),
                              tapi(`/${t.id}/adjuntos`, token),
                            ]);
                            setRegistros(prev => ({
                              ...prev,
                              [t.id]: {
                                comentarios: coms.status === "fulfilled" && Array.isArray(coms.value) ? coms.value : [],
                                adjuntos: adjs.status === "fulfilled" && Array.isArray(adjs.value) ? adjs.value : [],
                              },
                            }));
                          }
                        }}
                        className="w-full rounded-xl border-2 border-border py-2 text-sm font-bold text-ink hover:border-accent hover:text-accent transition"
                      >
                        {registroExpandido === t.id ? "▲ Ocultar registro" : "📷 Ver fotos y notas"}
                      </button>
                      <button
                        type="button"
                        disabled={loadingExtra}
                        onClick={() => void repetirDesdeHistorial(t.id)}
                        className="w-full rounded-xl border-2 border-accent/50 py-2 text-sm font-bold text-accent hover:bg-accent/10 disabled:opacity-40 transition"
                      >
                        ↻ Ejecutar de nuevo
                      </button>
                      {!tieneProcedimiento && (
                        <div className="flex gap-1.5">
                          <button
                            type="button"
                            disabled={loadingExtra}
                            onClick={() => void guardarProcedimientoHistorial(t.id, "personal")}
                            className="flex-1 rounded-xl border border-border py-1.5 text-xs font-semibold text-muted hover:border-accent hover:text-accent disabled:opacity-40 transition"
                            title="Solo tú lo verás en Mis procedimientos"
                          >
                            🔒 Guardar personal
                          </button>
                          <button
                            type="button"
                            disabled={loadingExtra}
                            onClick={() => void guardarProcedimientoHistorial(t.id, "global")}
                            className="flex-1 rounded-xl border border-border py-1.5 text-xs font-semibold text-muted hover:border-accent hover:text-accent disabled:opacity-40 transition"
                            title="Todo el equipo podrá usarlo y delegarlo"
                          >
                            🌐 Compartir
                          </button>
                        </div>
                      )}
                      {tieneProcedimiento && (
                        <button
                          type="button"
                          disabled={loadingExtra}
                          onClick={() => { const pid = t.procedimiento_id ?? t.protocolo_id; if (pid) void repetirProcedimiento(pid); }}
                          className="w-full rounded-xl border border-border py-1.5 text-xs font-semibold text-muted hover:border-accent hover:text-accent transition"
                        >
                          ↻ Desde procedimiento guardado
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {tabAcciones === "procedimientos" && (
        <div className="space-y-4">
          <NuevoProcedimientoForm
            token={token}
            user={user}
            abrirFormInicial={abrirFormProcedimiento}
            abrirFormSignal={crearProcedimientoSignal}
            onCreado={() => void cargarHistorialYProcedimientos()}
          />

          {/* Aplicaciones — procedimientos interactivos (calculadoras, no checklist) */}
          <div className="space-y-2">
            <p className="text-xs font-bold uppercase tracking-wide text-muted flex items-center gap-1.5">
              🧩 Aplicaciones — disponibles para todo el equipo
            </p>
            <button
              type="button"
              onClick={() => setAppAbierta("placas-concreto")}
              className="flex w-full items-center gap-3 rounded-xl border-2 border-accent/30 bg-accent/5 p-3 text-left transition hover:border-accent/60 hover:bg-accent/10"
            >
              <TopicIcon value="🧱" size={20} className="shrink-0 text-accent" />
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold text-ink">Placas de Concreto Pulido</p>
                <p className="text-[11px] text-muted">Calculadora de taller — dosificación exacta por pieza</p>
              </div>
              <span className="shrink-0 rounded-full bg-accent/15 px-2 py-0.5 text-[10px] font-bold text-accent">Abrir</span>
            </button>
          </div>

          {loadingExtra && <p className="text-sm text-muted">Cargando…</p>}
          {!loadingExtra && procedimientos.length === 0 && !abrirFormProcedimiento && crearProcedimientoSignal === 0 && (
            <div className="space-y-3 py-8 text-center">
              <p className="text-sm text-muted">Aún no tienes procedimientos guardados.</p>
              {puedeCrearProtocolos(user) && (
                <button
                  type="button"
                  onClick={() => setCrearProcedimientoSignal((n) => n + 1)}
                  className={`mx-auto ${CENTRO_MANDO_CTA_BTN} bg-accent hover:bg-accent shadow-[0_2px_0_#0c4a6e]`}
                >
                  + Nuevo procedimiento
                </button>
              )}
            </div>
          )}

          {/* Privados */}
          {procedimientos.filter((p) => (p.alcance ?? "personal") === "personal").length > 0 && (
            <div className="space-y-2">
              <p className="text-xs font-bold uppercase tracking-wide text-muted flex items-center gap-1.5">
                🔒 Privados — solo tú los ves
              </p>
              <div className="grid gap-2 sm:grid-cols-2">
                {procedimientos.filter((p) => (p.alcance ?? "personal") === "personal").map((p) => (
                  <ProcedimientoCard
                    key={p.id}
                    p={p}
                    token={token}
                    user={user}
                    onEjecutar={() => {
                        const plantilla = plantillaDesdeProtocolo(p);
                        if (plantilla.pasos.length > 0 || plantilla.listaCompras.length > 0) {
                          setPlantillaRepetir(plantilla);
                          setShowRepetirWizard(true);
                        } else {
                          abrirWizard("", plantilla);
                        }
                      }}
                    onActualizado={() => void cargarHistorialYProcedimientos()}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Compartidos con personas específicas */}
          {procedimientos.filter((p) => p.alcance === "seleccionado").length > 0 && (
            <div className="space-y-2">
              <p className="text-xs font-bold uppercase tracking-wide text-muted flex items-center gap-1.5">
                👤 Compartido con personas específicas
              </p>
              <div className="grid gap-2 sm:grid-cols-2">
                {procedimientos.filter((p) => p.alcance === "seleccionado").map((p) => (
                  <ProcedimientoCard
                    key={p.id}
                    p={p}
                    token={token}
                    user={user}
                    onEjecutar={() => {
                        const plantilla = plantillaDesdeProtocolo(p);
                        if (plantilla.pasos.length > 0 || plantilla.listaCompras.length > 0) {
                          setPlantillaRepetir(plantilla);
                          setShowRepetirWizard(true);
                        } else {
                          abrirWizard("", plantilla);
                        }
                      }}
                    onActualizado={() => void cargarHistorialYProcedimientos()}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Compartidos con el equipo */}
          {procedimientos.filter((p) => (p.alcance ?? "personal") === "global").length > 0 && (
            <div className="space-y-2">
              <p className="text-xs font-bold uppercase tracking-wide text-muted flex items-center gap-1.5">
                🌐 Compartidos — todo el equipo puede ejecutarlos
              </p>
              <div className="grid gap-2 sm:grid-cols-2">
                {procedimientos.filter((p) => (p.alcance ?? "personal") === "global").map((p) => (
                  <ProcedimientoCard
                    key={p.id}
                    p={p}
                    token={token}
                    user={user}
                    onEjecutar={() => {
                        const plantilla = plantillaDesdeProtocolo(p);
                        if (plantilla.pasos.length > 0 || plantilla.listaCompras.length > 0) {
                          setPlantillaRepetir(plantilla);
                          setShowRepetirWizard(true);
                        } else {
                          abrirWizard("", plantilla);
                        }
                      }}
                    onActualizado={() => void cargarHistorialYProcedimientos()}
                  />
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {appAbierta === "placas-concreto" && (
        <PlacasConcretoModal onClose={() => setAppAbierta(null)} />
      )}

      {/* Secciones secundarias — visibles salvo cuando se está dentro de un subtab */}
      {!isAdmin && tabAcciones !== "pendientes" && tabAcciones !== "historial" && tabAcciones !== "procedimientos" && tabAcciones !== "notas" && tabAcciones !== "bolsillo" && tabAcciones !== "agenda" && (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
          {[
            { tab: "pendientes" as const,    emoji: "🗓️", label: "Futuras",        count: pendientes.length,      color: "border-accent/20  bg-accent/5  hover:border-accent/40" },
            { tab: "procedimientos" as const,emoji: "🔒", label: "Procedimientos", count: procedimientos.length,  color: "border-accent/20          bg-accent/5          hover:border-accent/40"     },
            { tab: "historial" as const,     emoji: "📜", label: "Historial",      count: null,                   color: "border-stone-200   dark:border-stone-600/50   bg-stone-50   dark:bg-stone-900/60   hover:border-stone-400"   },
          ].map(({ tab, emoji, label, count, color }) => (
            <button
              key={tab}
              type="button"
              onClick={() => setTabAcciones(tab)}
              className={`flex flex-col items-start gap-1 rounded-2xl border p-4 text-left transition-all active:scale-[0.97] cursor-pointer shadow-sm ${color}`}
            >
              <TopicIcon value={emoji} size={22} className="text-ink" />
              <span className="text-sm font-extrabold text-ink leading-tight">{label}</span>
              {count != null && (
                <span className="text-xs font-bold text-muted">{count} {count === 1 ? "ítem" : "ítems"}</span>
              )}
            </button>
          ))}
        </div>
      )}

      {!["pendientes","historial","procedimientos","notas","bolsillo","agenda"].includes(tabAcciones) && loading && (
        <div className="py-8 text-center text-sm text-muted">Cargando acciones…</div>
      )}

      {!["pendientes","historial","procedimientos","notas","bolsillo","agenda"].includes(tabAcciones) && !loading && acciones.length === 0 && (
        <div className="py-12 text-center space-y-2">
          <TopicIcon value="⚡" size={28} className="mx-auto text-muted" />
          <p className="text-sm text-muted">No hay acciones registradas.</p>
        </div>
      )}

      {/* Tarjetas agrupadas por estado */}
      {!["pendientes","historial","procedimientos","notas","bolsillo","agenda"].includes(tabAcciones) && !loading && (
        <>
          {(
            [
              { key: "pendiente",             emoji: "⏸", label: "Pendientes" },
              { key: "en_proceso",            emoji: "▶", label: "En proceso" },
              { key: "esperando_aprobacion",  emoji: "🕐", label: "Esperando aprobación" },
              { key: "resuelto",              emoji: "✓", label: "Resueltas" },
              { key: "rechazado",             emoji: "✕", label: "Canceladas" },
            ] as { key: string; emoji: string; label: string }[]
          ).map(({ key, emoji, label }) => {
            const grupo = acciones.filter((t) => t.estado === key && (t.tipo || "") === "accion" && !esSolicitudCompraDelegada(t));
            if (grupo.length === 0) return null;
            return (
              <div key={key} className="space-y-2">
                <div className="flex items-center gap-2">
                  <span className="text-sm">{emoji}</span>
                  <span className="text-xs font-bold uppercase tracking-wide text-muted">{label}</span>
                  <span className="rounded-full bg-surface border border-border px-1.5 py-0.5 text-[10px] text-muted">{grupo.length}</span>
                </div>
                <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
                  {grupo.map((t) => (
                    <AccionCard
                      key={t.id}
                      ticket={t}
                      token={token}
                      user={user}
                      onSelect={onSelect}
                      onChanged={() => void load(true)}
                      onContinuar={
                        !isAdmin && !comprasDelegadas.some((c) => c.ticket_padre_id === t.id)
                          ? (tk) => void continuarAccion(tk)
                          : undefined
                      }
                      isAdmin={isAdmin}
                      readOnly={isAdmin}
                    />
                  ))}
                </div>
              </div>
            );
          })}
        </>
      )}
    </div>
  );
}

// ── Modal de recorte de imagen ────────────────────────────────────────────────

function CropperModal({ file, onConfirmar, onCancelar }: {
  file: File;
  onConfirmar: (cropped: File) => void;
  onCancelar: () => void;
}) {
  const [imgSrc, setImgSrc] = useState("");
  const [crop, setCrop] = useState({ x: 0.05, y: 0.05, w: 0.90, h: 0.90 });
  const [imgRect, setImgRect] = useState<{ left: number; top: number; width: number; height: number } | null>(null);
  const [aplicando, setAplicando] = useState(false);
  const imgRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const dragging = useRef<{
    handle: string;
    startClientX: number; startClientY: number;
    startCrop: { x: number; y: number; w: number; h: number };
  } | null>(null);

  useEffect(() => {
    const url = URL.createObjectURL(file);
    setImgSrc(url);
    return () => URL.revokeObjectURL(url);
  }, [file]);

  const calcImgRect = useCallback(() => {
    const img = imgRef.current;
    const container = containerRef.current;
    if (!img || !container || !img.naturalWidth) return;
    const cW = container.clientWidth;
    const cH = container.clientHeight;
    const ia = img.naturalWidth / img.naturalHeight;
    const ca = cW / cH;
    let dW: number, dH: number, dX: number, dY: number;
    if (ia > ca) { dW = cW; dH = cW / ia; dX = 0; dY = (cH - dH) / 2; }
    else { dH = cH; dW = cH * ia; dX = (cW - dW) / 2; dY = 0; }
    setImgRect({ left: dX, top: dY, width: dW, height: dH });
  }, []);

  useEffect(() => {
    window.addEventListener("resize", calcImgRect);
    return () => window.removeEventListener("resize", calcImgRect);
  }, [calcImgRect]);

  function onPointerDown(handle: string, e: React.PointerEvent) {
    e.stopPropagation();
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    dragging.current = {
      handle,
      startClientX: e.clientX, startClientY: e.clientY,
      startCrop: { ...crop },
    };
  }

  function onPointerMove(e: React.PointerEvent) {
    if (!dragging.current || !imgRect) return;
    const ddx = (e.clientX - dragging.current.startClientX) / imgRect.width;
    const ddy = (e.clientY - dragging.current.startClientY) / imgRect.height;
    const { handle, startCrop: sc } = dragging.current;
    const MIN = 0.08;
    let { x, y, w, h } = sc;

    if (handle === "move") {
      x = Math.max(0, Math.min(1 - w, x + ddx));
      y = Math.max(0, Math.min(1 - h, y + ddy));
    } else if (handle === "tl") {
      const nx = Math.min(sc.x + sc.w - MIN, sc.x + ddx);
      const ny = Math.min(sc.y + sc.h - MIN, sc.y + ddy);
      w = sc.w + (sc.x - nx); h = sc.h + (sc.y - ny); x = nx; y = ny;
    } else if (handle === "tr") {
      const ny = Math.min(sc.y + sc.h - MIN, sc.y + ddy);
      w = Math.max(MIN, sc.w + ddx); h = sc.h + (sc.y - ny); y = ny;
    } else if (handle === "bl") {
      const nx = Math.min(sc.x + sc.w - MIN, sc.x + ddx);
      w = sc.w + (sc.x - nx); h = Math.max(MIN, sc.h + ddy); x = nx;
    } else if (handle === "br") {
      w = Math.max(MIN, sc.w + ddx); h = Math.max(MIN, sc.h + ddy);
    }

    x = Math.max(0, x); y = Math.max(0, y);
    w = Math.min(1 - x, w); h = Math.min(1 - y, h);
    setCrop({ x, y, w, h });
  }

  function onPointerUp() { dragging.current = null; }

  async function aplicarRecorte() {
    const img = imgRef.current;
    if (!img) return;
    setAplicando(true);
    try {
      const canvas = document.createElement("canvas");
      const sx = Math.round(crop.x * img.naturalWidth);
      const sy = Math.round(crop.y * img.naturalHeight);
      const sw = Math.round(crop.w * img.naturalWidth);
      const sh = Math.round(crop.h * img.naturalHeight);
      canvas.width = sw; canvas.height = sh;
      const ctx = canvas.getContext("2d")!;
      ctx.drawImage(img, sx, sy, sw, sh, 0, 0, sw, sh);
      await new Promise<void>(resolve => {
        canvas.toBlob(blob => {
          if (!blob) { resolve(); return; }
          const nombre = file.name.replace(/\.[^.]+$/, "") + "_recortada.jpg";
          onConfirmar(new File([blob], nombre, { type: "image/jpeg" }));
          resolve();
        }, "image/jpeg", 0.92);
      });
    } finally {
      setAplicando(false);
    }
  }

  const H = 36;

  return createPortal(
    <div className="fixed inset-0 z-[9999] bg-black flex flex-col">
      <div className="shrink-0 flex items-center justify-between px-4 py-3 bg-black/90 pt-safe">
        <button onClick={onCancelar}
          className="text-white/70 text-sm px-4 py-2 rounded-xl bg-white/10 active:bg-white/20">
          Cancelar
        </button>
        <span className="text-white text-sm font-semibold">Recortar imagen</span>
        <button onClick={aplicarRecorte} disabled={aplicando}
          className="text-white text-sm font-semibold px-4 py-2 rounded-xl bg-accent active:opacity-80 disabled:opacity-50">
          {aplicando ? "…" : "Listo"}
        </button>
      </div>

      <div
        ref={containerRef}
        className="flex-1 relative overflow-hidden select-none touch-none"
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerLeave={onPointerUp}
      >
        {imgSrc && (
          <img
            ref={imgRef}
            src={imgSrc}
            alt=""
            className="absolute inset-0 w-full h-full object-contain pointer-events-none"
            draggable={false}
            onLoad={calcImgRect}
          />
        )}

        {imgRect && (() => {
          const cx = imgRect.left + crop.x * imgRect.width;
          const cy = imgRect.top + crop.y * imgRect.height;
          const cw = crop.w * imgRect.width;
          const ch = crop.h * imgRect.height;
          return (
            <>
              {/* Oscurecer áreas fuera del recorte */}
              <div className="absolute bg-black/55 pointer-events-none" style={{ left: imgRect.left, top: imgRect.top, width: imgRect.width, height: cy - imgRect.top }} />
              <div className="absolute bg-black/55 pointer-events-none" style={{ left: imgRect.left, top: cy + ch, width: imgRect.width, height: imgRect.top + imgRect.height - cy - ch }} />
              <div className="absolute bg-black/55 pointer-events-none" style={{ left: imgRect.left, top: cy, width: cx - imgRect.left, height: ch }} />
              <div className="absolute bg-black/55 pointer-events-none" style={{ left: cx + cw, top: cy, width: imgRect.left + imgRect.width - cx - cw, height: ch }} />

              {/* Borde del recorte */}
              <div className="absolute border border-white/80 pointer-events-none box-border" style={{ left: cx, top: cy, width: cw, height: ch }} />

              {/* Líneas de tercios */}
              <div className="absolute pointer-events-none overflow-hidden" style={{ left: cx, top: cy, width: cw, height: ch }}>
                <div className="absolute bg-white/25 w-px inset-y-0" style={{ left: "33.33%" }} />
                <div className="absolute bg-white/25 w-px inset-y-0" style={{ left: "66.66%" }} />
                <div className="absolute bg-white/25 h-px inset-x-0" style={{ top: "33.33%" }} />
                <div className="absolute bg-white/25 h-px inset-x-0" style={{ top: "66.66%" }} />
              </div>

              {/* Área de arrastre (mover recorte) */}
              <div
                className="absolute cursor-move touch-none"
                style={{ left: cx, top: cy, width: cw, height: ch }}
                onPointerDown={e => onPointerDown("move", e)}
              />

              {/* Esquinas */}
              {([["tl", cx, cy], ["tr", cx + cw, cy], ["bl", cx, cy + ch], ["br", cx + cw, cy + ch]] as [string, number, number][]).map(([corner, hx, hy]) => (
                <div
                  key={corner}
                  className="absolute touch-none flex items-center justify-center"
                  style={{ left: hx - H / 2, top: hy - H / 2, width: H, height: H }}
                  onPointerDown={e => onPointerDown(corner, e)}
                >
                  <div className="w-5 h-5 rounded-full bg-white shadow-xl"
                    style={{ border: "2.5px solid var(--color-accent, #3b82f6)" }} />
                </div>
              ))}
            </>
          );
        })()}
      </div>

      <div className="shrink-0 py-2.5 text-center text-white/40 text-xs pb-safe">
        Arrastra las esquinas para ajustar el recorte
      </div>
    </div>,
    document.body,
  );
}

// ── Botón cámara (acción en ejecución) ───────────────────────────────────────

function BotonCamaraEjecucion({ onFile, title = "Tomar foto" }: { onFile: (file: File) => void; title?: string }) {
  const inputId = useId();
  return (
    <>
      <input
        id={inputId}
        type="file"
        accept="image/*"
        capture="environment"
        className="sr-only"
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) onFile(file);
          e.target.value = "";
        }}
      />
      <label
        htmlFor={inputId}
        className="h-11 w-11 shrink-0 rounded-full bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 flex items-center justify-center text-gray-500 dark:text-white/70 hover:text-gray-700 dark:hover:text-white transition cursor-pointer"
        title={title}
        aria-label={title}
      >
        <svg className="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M23 19a2 2 0 01-2 2H3a2 2 0 01-2-2V8a2 2 0 012-2h4l2-3h6l2 3h4a2 2 0 012 2z"/>
          <circle cx="12" cy="13" r="4"/>
        </svg>
      </label>
    </>
  );
}

// ── PanelComprasEjecucion ─────────────────────────────────────────────────────

type ItemCompraEjec = {
  id: number; nombre: string; cantidad: string; unidad: string;
  comprado: boolean; precio_estimado: number | null; notas: string | null;
};

function PanelComprasEjecucion({
  token, ticketId, ticketTitulo, onVolver,
}: {
  token: string; ticketId: number; ticketTitulo: string; onVolver: () => void;
}) {
  const [items, setItems] = useState<ItemCompraEjec[]>([]);
  const [loading, setLoading] = useState(true);
  const [inputNombre, setInputNombre] = useState("");
  const [inputCantidad, setInputCantidad] = useState("");
  const [inputUnidad, setInputUnidad] = useState<"u"|"g"|"kg"|"L"|"ml">("u");
  const [guardando, setGuardando] = useState(false);
  const [facturaFile, setFacturaFile] = useState<File | null>(null);
  const [subiendoFactura, setSubiendoFactura] = useState(false);
  const [msg, setMsg] = useState("");
  const facturaRef = useRef<HTMLInputElement>(null);

  async function cargar() {
    setLoading(true);
    try {
      const res = await fetch(`/api/tickets/${ticketId}/lista-compras`, { headers: { Authorization: `Bearer ${token}` } });
      const data = res.ok ? await res.json() as Array<Record<string,unknown>> : [];
      setItems(data.map(r => ({
        id: r.id as number,
        nombre: ((r.nombre || r.material_nombre || "") as string).trim(),
        cantidad: String(r.cantidad ?? "1"),
        unidad: (r.unidad as string) || "u",
        comprado: !!(r.comprado),
        precio_estimado: (r.precio_estimado as number | null) ?? null,
        notas: (r.notas as string | null) ?? null,
      })));
    } catch { /* silencioso */ }
    finally { setLoading(false); }
  }

  useEffect(() => { void cargar(); }, [ticketId]);

  async function agregar() {
    const nombre = inputNombre.trim();
    if (!nombre) return;
    setGuardando(true);
    setMsg("");
    try {
      const res = await fetch(`/api/tickets/${ticketId}/lista-compras`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ nombre, cantidad: inputCantidad || "1", unidad: inputUnidad }),
      });
      if (!res.ok) throw new Error("error");
      const data = await res.json() as Array<Record<string,unknown>>;
      setItems(data.map(r => ({
        id: r.id as number,
        nombre: ((r.nombre || r.material_nombre || "") as string).trim(),
        cantidad: String(r.cantidad ?? "1"),
        unidad: (r.unidad as string) || "u",
        comprado: !!(r.comprado),
        precio_estimado: (r.precio_estimado as number | null) ?? null,
        notas: (r.notas as string | null) ?? null,
      })));
      setInputNombre("");
      setInputCantidad("");
    } catch { setMsg("No se pudo agregar."); }
    finally { setGuardando(false); }
  }

  async function toggleComprado(item: ItemCompraEjec) {
    try {
      const res = await fetch(`/api/tickets/lista-compras/${item.id}`, {
        method: "PUT",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ comprado: item.comprado ? 0 : 1 }),
      });
      if (!res.ok) return;
      const data = await res.json() as Array<Record<string,unknown>>;
      setItems(data.map(r => ({
        id: r.id as number,
        nombre: ((r.nombre || r.material_nombre || "") as string).trim(),
        cantidad: String(r.cantidad ?? "1"),
        unidad: (r.unidad as string) || "u",
        comprado: !!(r.comprado),
        precio_estimado: (r.precio_estimado as number | null) ?? null,
        notas: (r.notas as string | null) ?? null,
      })));
    } catch { /* silencioso */ }
  }

  async function eliminar(id: number) {
    try {
      const res = await fetch(`/api/tickets/lista-compras/${id}`, { method: "DELETE", headers: { Authorization: `Bearer ${token}` } });
      if (!res.ok) return;
      const data = await res.json() as Array<Record<string,unknown>>;
      setItems(data.map(r => ({
        id: r.id as number,
        nombre: ((r.nombre || r.material_nombre || "") as string).trim(),
        cantidad: String(r.cantidad ?? "1"),
        unidad: (r.unidad as string) || "u",
        comprado: !!(r.comprado),
        precio_estimado: (r.precio_estimado as number | null) ?? null,
        notas: (r.notas as string | null) ?? null,
      })));
    } catch { /* silencioso */ }
  }

  async function subirFactura(file: File) {
    setSubiendoFactura(true);
    setMsg("");
    try {
      const fd = new FormData();
      fd.append("archivo", file);
      const res = await fetch(`/api/tickets/${ticketId}/adjuntos`, {
        method: "POST", headers: { Authorization: `Bearer ${token}` }, body: fd,
      });
      if (!res.ok) throw new Error("upload");
      setFacturaFile(file);
      await fetch(`/api/tickets/${ticketId}/comentarios`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ texto: "🧾 Factura de compras adjunta." }),
      });
      setMsg("✅ Factura adjunta correctamente.");
    } catch { setMsg("No se pudo subir la factura."); }
    finally { setSubiendoFactura(false); }
  }

  const activos = items.filter(i => i.nombre.trim());
  const comprados = activos.filter(i => i.comprado).length;

  return (
    <div className="hugo-chat flex flex-col h-full min-h-0 overflow-hidden bg-surface font-sans antialiased text-ink">
      {/* Header */}
      <div className="shrink-0 border-b-2 border-border bg-surface-panel pt-safe shadow-paper-sm">
        <div className="flex items-center gap-3 px-4 py-2.5">
          <button type="button" onClick={onVolver}
            className="flex items-center justify-center h-8 w-8 rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-white/10 dark:text-white/70 dark:hover:bg-white/20 transition shrink-0">‹</button>
          <div className="flex-1 min-w-0">
            <p className="text-xs font-extrabold uppercase tracking-widest text-muted">Lista de compras</p>
            <p className="text-base font-extrabold text-ink leading-snug truncate tracking-tight">{ticketTitulo}</p>
          </div>
          {activos.length > 0 && (
            <div className="shrink-0 flex items-center gap-1 bg-accent/10 rounded-full px-3 py-1">
              <span className="text-xs font-black tabular-nums text-accent">{comprados}/{activos.length}</span>
            </div>
          )}
        </div>
      </div>

      {/* Lista */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-2 bg-gray-50 dark:bg-gray-950">
        {loading && <p className="text-center text-sm text-muted py-8">Cargando…</p>}
        {!loading && activos.length === 0 && (
          <div className="text-center py-10 space-y-2">
            <TopicIcon value="🛒" size={36} className="mx-auto text-muted" />
            <p className="text-sm text-gray-400 dark:text-white/40">Agregue los productos<br/>que necesita conseguir.</p>
          </div>
        )}
        {activos.map(item => (
          <div key={item.id} className={`flex items-center gap-3 rounded-2xl border px-4 py-3 bg-surface-input transition ${item.comprado ? "border-accent/50  opacity-70" : "border-gray-200 dark:border-white/10"}`}>
            <button type="button" onClick={() => void toggleComprado(item)}
              className={`shrink-0 h-6 w-6 rounded-full border-2 flex items-center justify-center transition ${item.comprado ? "bg-accent/50 border-accent/50 text-white" : "border-gray-300 dark:border-white/20"}`}>
              {item.comprado && <svg className="h-3 w-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><polyline points="20 6 9 17 4 12"/></svg>}
            </button>
            <div className="flex-1 min-w-0">
              <p className={`text-sm font-semibold leading-snug ${item.comprado ? "line-through text-gray-400 dark:text-white/30" : "text-ink"}`}>{item.nombre}</p>
              {(item.cantidad !== "1" || item.unidad !== "u") && (
                <p className="text-xs text-muted">{item.cantidad} {item.unidad}</p>
              )}
            </div>
            <button type="button" onClick={() => void eliminar(item.id)}
              className="shrink-0 h-7 w-7 rounded-full flex items-center justify-center text-gray-400 hover:bg-red-50 hover:text-red-500 dark:hover:bg-red-900/20 transition text-xs">✕</button>
          </div>
        ))}
        {msg && <p className={`text-center text-xs px-4 py-2 font-semibold ${msg.startsWith("✅") ? "text-accent" : "text-red-500 dark:text-red-400"}`}>{msg}</p>}
      </div>

      {/* Formulario agregar + factura */}
      <div className="shrink-0 border-t border-gray-200 dark:border-white/10 bg-surface-panel pb-safe px-4 pt-3 pb-3 space-y-2">
        {/* Fila producto */}
        <div className="flex gap-2">
          <input value={inputNombre} onChange={e => setInputNombre(e.target.value)}
            onKeyDown={e => { if ((e.key === "Enter" || e.key === " ") && inputNombre.trim()) { e.preventDefault(); void agregar(); } }}
            placeholder="Producto…"
            className="flex-1 rounded-xl bg-gray-100 dark:bg-gray-800 border border-gray-200 dark:border-white/10 px-3 py-2.5 text-sm text-ink placeholder:text-gray-400 outline-none focus:border-accent/60 transition"/>
          <input value={inputCantidad} onChange={e => setInputCantidad(e.target.value)}
            placeholder="Cant."
            inputMode="decimal"
            className="w-16 rounded-xl bg-gray-100 dark:bg-gray-800 border border-gray-200 dark:border-white/10 px-3 py-2.5 text-sm text-ink placeholder:text-gray-400 outline-none focus:border-accent/60 transition"/>
          <select value={inputUnidad} onChange={e => setInputUnidad(e.target.value as "u"|"g"|"kg"|"L"|"ml")}
            className="w-16 rounded-xl bg-gray-100 dark:bg-gray-800 border border-gray-200 dark:border-white/10 px-2 py-2.5 text-sm font-bold text-ink outline-none focus:border-accent/60 transition">
            <option value="u">u</option>
            <option value="g">g</option>
            <option value="kg">kg</option>
            <option value="L">L</option>
            <option value="ml">ml</option>
          </select>
          <button type="button" onClick={() => void agregar()} disabled={guardando || !inputNombre.trim()}
            className="h-11 w-11 shrink-0 rounded-xl bg-accent disabled:opacity-40 text-white font-extrabold text-lg flex items-center justify-center transition">+</button>
        </div>
        {/* Adjuntar factura */}
        <input ref={facturaRef} type="file" accept="image/*,.pdf" className="hidden"
          onChange={e => { const f = e.target.files?.[0]; if (f) void subirFactura(f); e.target.value = ""; }}/>
        <button type="button" onClick={() => facturaRef.current?.click()} disabled={subiendoFactura}
          className={`w-full flex items-center justify-center gap-2 rounded-xl border-2 py-2.5 text-sm font-bold transition disabled:opacity-50 ${facturaFile ? "border-accent/40 text-accent  bg-accent/5" : "border-dashed border-gray-300 dark:border-white/20 text-muted hover:border-accent hover:text-accent"}`}>
          <span>🧾</span>
          <span>{subiendoFactura ? "Subiendo…" : facturaFile ? `Factura: ${facturaFile.name}` : "Adjuntar factura de compras"}</span>
        </button>
      </div>
    </div>
  );
}

// ── EjecucionAccionChat ───────────────────────────────────────────────────────

function EjecucionAccionChat({
  token, accion, stt, chatApiToken, onVolver, onTerminado,
}: {
  token: string;
  accion: { id: number; titulo: string };
  stt: ReturnType<typeof useStt>;
  chatApiToken: string | null | undefined;
  onVolver: () => void;
  onTerminado: () => void;
}) {
  type Nota = { id: number; texto: string; fotoUrl?: string; tipo: "texto" | "foto" | "sistema"; duracionSeg?: number; serverItemId?: number; guardando?: boolean; errorGuarda?: boolean; eliminando?: boolean };

  const { segundos, activo: cronometroActivo, pausar, syncDesdeServidor, fmt: fmtSeg } = useTicketCronometro(accion.id, token);
  const [notas, setNotas] = useState<Nota[]>([]);
  const [cargandoNotas, setCargandoNotas] = useState(true);
  const [inputNota, setInputNota] = useState("");
  const [terminando, setTerminando] = useState(false);
  const [error, setError] = useState("");
  const [modoCompras, setModoCompras] = useState(false);
  const [numCompras, setNumCompras] = useState(0);
  const [lbUrl, setLbUrl] = useState<string | null>(null);
  const pasoInicioRef = useRef(Date.now());
  const notaIdRef = useRef(0);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputNotaRef = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
    const el = inputNotaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 128)}px`;
  }, [inputNota]);

  useEffect(() => {
    pasoInicioRef.current = Date.now();
  }, [accion.id]);

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [notas]);

  // Carga historial existente del servidor al montar (sincronización entre dispositivos)
  useEffect(() => {
    let cancelled = false;
    async function cargarHistorial() {
      setCargandoNotas(true);
      try {
        const [resComs, resAdjs, resCompras] = await Promise.all([
          fetch(`/api/tickets/${accion.id}/comentarios`, { headers: { Authorization: `Bearer ${token}` } }),
          fetch(`/api/tickets/${accion.id}/adjuntos`,   { headers: { Authorization: `Bearer ${token}` } }),
          fetch(`/api/tickets/${accion.id}/lista-compras`, { headers: { Authorization: `Bearer ${token}` } }),
        ]);
        if (cancelled) return;

        type ComRow = { id: number; texto: string; creado_en: string };
        type AdjRow = { id: number; nombre_archivo: string; mime: string | null; nombre_original: string; creado_en: string };

        const coms: ComRow[]  = resComs.ok  ? await resComs.json()  : [];
        const adjs: AdjRow[]  = resAdjs.ok  ? await resAdjs.json()  : [];
        const compras: Array<{nombre:string}> = resCompras.ok ? await resCompras.json() : [];

        // Mezclar y ordenar por fecha
        const items: Array<{ creado_en: string; nota: Nota }> = [];
        let localId = 0;
        for (const c of coms) {
          items.push({ creado_en: c.creado_en, nota: { id: ++localId, texto: c.texto, tipo: "texto", serverItemId: c.id } });
        }
        for (const a of adjs) {
          const esImagen = (a.mime ?? "").startsWith("image/");
          if (esImagen) {
            items.push({ creado_en: a.creado_en, nota: {
              id: ++localId, texto: "", tipo: "foto",
              fotoUrl: ticketsUploadUrl(a.nombre_archivo, token),
              serverItemId: a.id,
            }});
          } else {
            items.push({ creado_en: a.creado_en, nota: {
              id: ++localId, texto: `📎 ${a.nombre_original}`, tipo: "texto", serverItemId: a.id,
            }});
          }
        }

        // Cargar hilos de sub-tickets (intervenciones resueltas)
        try {
          const resSubTkts = await fetch(`/api/tickets/${accion.id}/sub-tickets`, { headers: { Authorization: `Bearer ${token}` } });
          const subTkts: Array<{ id: number; numero: string; estado: string; asignado_a_nombre: string; resuelto_en: string }> =
            resSubTkts.ok ? await resSubTkts.json() : [];
          for (const sub of subTkts.filter(s => s.estado === "resuelto")) {
            const [rSubComs, rSubAdjs] = await Promise.all([
              fetch(`/api/tickets/${sub.id}/comentarios`, { headers: { Authorization: `Bearer ${token}` } }),
              fetch(`/api/tickets/${sub.id}/adjuntos`,   { headers: { Authorization: `Bearer ${token}` } }),
            ]);
            const subComs: ComRow[] = rSubComs.ok ? await rSubComs.json() : [];
            const subAdjs: AdjRow[] = rSubAdjs.ok ? await rSubAdjs.json() : [];
            const ts = sub.resuelto_en || "";
            items.push({ creado_en: ts, nota: {
              id: ++localId, texto: `🔧 ${sub.numero} — ${sub.asignado_a_nombre}`, tipo: "sistema",
            }});
            for (const c of subComs) {
              items.push({ creado_en: c.creado_en, nota: { id: ++localId, texto: c.texto, tipo: "texto" } });
            }
            for (const a of subAdjs) {
              if ((a.mime ?? "").startsWith("image/")) {
                items.push({ creado_en: a.creado_en, nota: {
                  id: ++localId, texto: "", tipo: "foto",
                  fotoUrl: ticketsUploadUrl(a.nombre_archivo, token),
                }});
              }
            }
          }
        } catch { /* silencioso */ }

        items.sort((a, b) => a.creado_en.localeCompare(b.creado_en));
        notaIdRef.current = localId;
        setNotas(items.map(i => i.nota));
        setNumCompras(compras.filter(i => i.nombre?.trim()).length);
      } catch { /* silencioso — el usuario puede seguir escribiendo */ }
      finally { if (!cancelled) setCargandoNotas(false); }
    }
    void cargarHistorial();
    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [accion.id]);

  // Guarda cada ítem inmediatamente para preservar el orden cronológico real
  async function agregarNota(texto: string, fotoFile?: File, fotoUrl?: string) {
    if (!texto.trim() && !fotoFile) return;
    const duracionSeg = Math.max(1, Math.floor((Date.now() - pasoInicioRef.current) / 1000));
    pasoInicioRef.current = Date.now();
    const nid = ++notaIdRef.current;
    const tipo: "texto" | "foto" = fotoFile ? "foto" : "texto";
    setNotas(prev => [...prev, { id: nid, texto: texto.trim(), fotoUrl, tipo, duracionSeg, guardando: true }]);
    setInputNota("");
    try {
      let serverItemId: number | undefined;
      if (fotoFile) {
        const fd = new FormData();
        fd.append("archivo", fotoFile);
        const res = await fetch(`/api/tickets/${accion.id}/adjuntos`, {
          method: "POST", headers: { Authorization: `Bearer ${token}` }, body: fd,
        });
        if (!res.ok) throw new Error("upload");
        const json = await res.json() as { id: number };
        serverItemId = json.id;
      } else if (texto.trim()) {
        const res = await fetch(`/api/tickets/${accion.id}/comentarios`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
          body: JSON.stringify({ texto: texto.trim() }),
        });
        if (!res.ok) throw new Error("comment");
        const json = await res.json() as { id: number };
        serverItemId = json.id;
      }
      setNotas(prev => prev.map(n => n.id === nid ? { ...n, guardando: false, serverItemId } : n));
    } catch {
      setNotas(prev => prev.map(n => n.id === nid ? { ...n, guardando: false, errorGuarda: true } : n));
    }
  }

  async function eliminarNota(nota: Nota) {
    if (!nota.serverItemId || nota.guardando || nota.eliminando) return;
    setNotas(prev => prev.map(n => n.id === nota.id ? { ...n, eliminando: true } : n));
    try {
      const url = nota.tipo === "foto"
        ? `/api/tickets/adjuntos/${nota.serverItemId}`
        : `/api/tickets/comentarios/${nota.serverItemId}`;
      const res = await fetch(url, { method: "DELETE", headers: { Authorization: `Bearer ${token}` } });
      if (!res.ok) throw new Error("delete");
      setNotas(prev => prev.filter(n => n.id !== nota.id));
    } catch {
      setNotas(prev => prev.map(n => n.id === nota.id ? { ...n, eliminando: false } : n));
    }
  }

  const [cropFile, setCropFile] = useState<File | null>(null);

  function onFotoSeleccionada(file: File) {
    setCropFile(file);
  }

  function handlePaste(e: React.ClipboardEvent) {
    const items = Array.from(e.clipboardData.items);
    const imgItem = items.find(it => it.type.startsWith("image/"));
    if (!imgItem) return;
    e.preventDefault();
    const file = imgItem.getAsFile();
    if (file) setCropFile(new File([file], `captura-${Date.now()}.png`, { type: file.type }));
  }

  async function terminar() {
    // Esperar que todo esté guardado antes de cerrar
    const pendientes = notas.filter(n => n.guardando).length;
    if (pendientes > 0) { setError(`Aún guardando ${pendientes} ítem(s)…`); return; }
    setTerminando(true);
    setError("");
    try {
      await fetch(`/api/tickets/${accion.id}/completar-accion`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ reporte: `Duración total: ${fmtSeg(segundos)}` }),
      });
      localStorage.removeItem(`mckenna-accion-alarma-${accion.id}`);
      localStorage.removeItem("mckenna-accion-activa");
      onTerminado();
    } catch { setError("No se pudo cerrar. Intenta de nuevo."); }
    finally { setTerminando(false); }
  }

  async function guardarYVolver() {
    await pausar();
    localStorage.setItem("mckenna-accion-activa", JSON.stringify({ id: accion.id, titulo: accion.titulo }));
    onVolver();
  }

  if (modoCompras) {
    return (
      <PanelComprasEjecucion
        token={token}
        ticketId={accion.id}
        ticketTitulo={accion.titulo}
        onVolver={() => {
          // Recargar conteo al volver
          fetch(`/api/tickets/${accion.id}/lista-compras`, { headers: { Authorization: `Bearer ${token}` } })
            .then(r => r.ok ? r.json() : [])
            .then((items: Array<{nombre:string}>) => setNumCompras(items.filter(i => i.nombre?.trim()).length))
            .catch(() => {});
          setModoCompras(false);
        }}
      />
    );
  }

  return (
    <>
      {cropFile && (
        <CropperModal
          file={cropFile}
          onConfirmar={croppedFile => {
            setCropFile(null);
            void agregarNota("", croppedFile, URL.createObjectURL(croppedFile));
          }}
          onCancelar={() => setCropFile(null)}
        />
      )}
    {/* onPaste en el contenedor: captura Ctrl+V con imagen desde cualquier lugar de la vista */}
    <div className="hugo-chat flex flex-col h-full min-h-0 overflow-hidden bg-surface font-sans antialiased text-ink" onPaste={handlePaste}>
      {/* Header con cronómetro */}
      <div className="shrink-0 border-b-2 border-border bg-surface-panel pt-safe shadow-paper-sm">
        <div className="flex items-center gap-3 px-4 py-2.5">
          <button type="button" onClick={guardarYVolver}
            className="flex items-center justify-center h-8 w-8 rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-white/10 dark:text-white/70 dark:hover:bg-white/20 transition shrink-0">‹</button>
          <div className="flex-1 min-w-0">
            <p className="text-xs font-extrabold uppercase tracking-widest text-muted">En ejecución</p>
            <p className="text-base font-extrabold text-ink leading-snug truncate tracking-tight">{accion.titulo}</p>
          </div>
          {/* Cronómetro + pausa */}
          <div className="shrink-0 flex items-center gap-2">
            <div className={`flex items-center gap-1.5 rounded-full px-3 py-1 ${cronometroActivo ? "bg-accent/10" : "bg-accent/10"}`}>
              <span className="text-xs">⏱</span>
              <span className={`text-sm font-black tabular-nums ${cronometroActivo ? "text-accent" : "text-accent"}`}>{fmtSeg(segundos)}</span>
              {cronometroActivo && <span className="h-1.5 w-1.5 rounded-full bg-accent animate-pulse" />}
            </div>
            {cronometroActivo ? (
              <button
                type="button"
                onClick={() => void pausar()}
                title="Pausar cronómetro"
                className="flex items-center justify-center h-8 w-8 rounded-full bg-accent/10 text-accent hover:bg-accent/20    transition shrink-0"
              >
                ⏸
              </button>
            ) : (
              <button
                type="button"
                onClick={() => void syncDesdeServidor(true)}
                title="Reanudar cronómetro"
                className="flex items-center justify-center h-8 w-8 rounded-full bg-accent text-white hover:bg-accent/80 transition shrink-0"
              >
                ▶
              </button>
            )}
          </div>
        </div>
        <AccionAlarmaRecordatorio
          ticketId={accion.id}
          tituloAccion={accion.titulo}
          cronometroActivo={cronometroActivo}
        />
      </div>

      {/* Área de actividad */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3 bg-gray-50 dark:bg-gray-950">
        {cargandoNotas && (
          <div className="flex items-center justify-center py-10 gap-2">
            {[0,1,2].map(i => <span key={i} className="block h-2.5 w-2.5 rounded-full bg-accent animate-bounce" style={{ animationDelay: `${i*150}ms` }}/>)}
          </div>
        )}
        {!cargandoNotas && notas.length === 0 && (
          <div className="text-center py-6 space-y-2">
            <p className="text-3xl">📋</p>
            <p className="text-sm text-gray-400 dark:text-white/40">
              Cuénteme qué va haciendo,<br/>tome fotos como evidencia.
            </p>
          </div>
        )}
        {(() => {
          let pasoNum = 0;
          return notas.map(nota => {
            if (nota.tipo === "sistema") {
              return (
                <div key={nota.id} className="flex items-center gap-2 py-1">
                  <div className="flex-1 h-px bg-border" />
                  <span className="text-[10px] font-bold text-muted uppercase tracking-wide px-2 shrink-0">{nota.texto}</span>
                  <div className="flex-1 h-px bg-border" />
                </div>
              );
            }
            if (nota.tipo === "texto") pasoNum++;
            const label = nota.tipo === "texto" ? `Paso ${pasoNum}` : null;
            const durLabel = nota.duracionSeg ? fmtSeg(nota.duracionSeg) : null;
            return (
              <div key={nota.id} className="flex justify-end">
                <div className="max-w-[88%] space-y-1">
                  {label && (
                    <p className="text-right text-[10px] font-bold text-accent/70 uppercase tracking-wide">
                      {label}{durLabel ? ` · ⏱ ${durLabel}` : ""}
                    </p>
                  )}
                  {nota.fotoUrl && (
                    <div className="relative group">
                      {lbUrl && <ImageLightbox url={lbUrl} onClose={() => setLbUrl(null)} />}
                      <button type="button" onClick={() => !(nota.guardando || nota.eliminando) && setLbUrl(nota.fotoUrl!)} className="block w-full max-w-xs text-left" title="Ver imagen">
                        <img src={nota.fotoUrl} alt="foto"
                          className={`rounded-xl w-full max-w-xs border object-cover transition group-hover:opacity-80 ${nota.guardando || nota.eliminando ? "opacity-60" : ""} border-gray-200 dark:border-white/10`}/>
                        {!(nota.guardando || nota.eliminando) && <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-2xl font-bold transition-opacity pointer-events-none">🔍</span>}
                      </button>
                      {!nota.guardando && nota.serverItemId && (
                        <button type="button" onClick={() => void eliminarNota(nota)}
                          disabled={!!nota.eliminando}
                          className="absolute top-1 right-1 hidden group-hover:flex items-center justify-center h-6 w-6 rounded-full bg-black/60 text-white text-xs hover:bg-red-600 transition">
                          {nota.eliminando ? "…" : "✕"}
                        </button>
                      )}
                    </div>
                  )}
                  {nota.texto && (
                    <div className={`relative group bg-accent rounded-2xl rounded-br-sm px-4 py-2.5 text-sm text-white leading-relaxed transition ${nota.guardando || nota.eliminando ? "opacity-60" : ""}`}>
                      {nota.texto}
                      {!nota.guardando && nota.serverItemId && (
                        <button type="button" onClick={() => void eliminarNota(nota)}
                          disabled={!!nota.eliminando}
                          className="absolute -top-1.5 -right-1.5 hidden group-hover:flex items-center justify-center h-5 w-5 rounded-full bg-red-500 text-white text-[10px] hover:bg-red-700 transition">
                          {nota.eliminando ? "…" : "✕"}
                        </button>
                      )}
                    </div>
                  )}
                  <p className="text-right text-[10px] text-gray-400 dark:text-white/30">
                    {nota.errorGuarda ? "⚠ No se guardó" : nota.eliminando ? "Eliminando…" : nota.guardando ? "Guardando…" : "✓"}
                  </p>
                </div>
              </div>
            );
          });
        })()}
        {error && <p className="text-center text-xs text-red-500 dark:text-red-400">{error}</p>}
        <div ref={bottomRef}/>
      </div>

      {/* Pie: terminar + input + micrófono */}
      <div className="shrink-0 border-t border-gray-200 dark:border-white/10 bg-surface-panel pb-safe">
      <div className="px-4 pt-3 pb-2">
        <button type="button" onClick={terminar} disabled={terminando || notas.some(n => n.guardando)}
          className="w-full rounded-2xl bg-accent/50 hover:bg-accent/40 disabled:opacity-50 py-3.5 text-base font-extrabold text-white transition active:scale-[0.98] shadow-lg">
          {terminando ? "Cerrando…" : notas.some(n => n.guardando) ? "Guardando…" : "✅ Terminé la actividad"}
        </button>
      </div>

      <div className="px-4 py-2.5 flex items-end gap-2">
        <BotonCamaraEjecucion onFile={onFotoSeleccionada} title="Tomar foto o pegar captura (Ctrl+V)" />
        <button type="button" onClick={() => setModoCompras(true)} title="Lista de compras"
          className="relative shrink-0 h-11 w-11 rounded-full bg-gray-100 text-gray-600 hover:bg-gray-200 dark:bg-gray-700 dark:text-white dark:hover:bg-gray-600 flex items-center justify-center transition text-lg">
          🛒
          {numCompras > 0 && <span className="absolute -top-0.5 -right-0.5 h-4 min-w-4 rounded-full bg-accent text-white text-[9px] font-black flex items-center justify-center px-0.5">{numCompras}</span>}
        </button>
        <ProseTextarea ref={inputNotaRef} value={inputNota} onChange={e => setInputNota(e.target.value)} prose={false}
          onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); agregarNota(inputNota); } }}
          onPaste={handlePaste}
          rows={1}
          placeholder="Cuénteme qué hizo… (Shift+Enter para nueva línea)"
          className="flex-1 rounded-2xl bg-gray-100 border border-gray-200 px-4 py-2.5 text-sm text-gray-900 placeholder:text-gray-400 outline-none focus:border-accent/60 transition resize-none overflow-y-auto min-h-[42px] max-h-32 dark:bg-gray-800 dark:border-white/15 dark:text-white dark:placeholder:text-white/40"/>
        {inputNota.trim() ? (
          <button type="button" onClick={() => agregarNota(inputNota)}
            className="h-11 w-11 shrink-0 rounded-full bg-accent flex items-center justify-center text-white shadow active:scale-95 transition">
            <svg className="h-5 w-5 rotate-90" viewBox="0 0 24 24" fill="currentColor"><path d="M2 21l21-9L2 3v7l15 2-15 2v7z"/></svg>
          </button>
        ) : (
          <button type="button" onClick={() => stt.grabando ? stt.detener() : stt.iniciar(txt => agregarNota(txt))}
            disabled={stt.transcribiendo}
            className={`h-11 w-11 shrink-0 rounded-full flex items-center justify-center shadow transition active:scale-95 disabled:opacity-50 ${
              stt.grabando ? "bg-red-500 animate-pulse text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200 dark:bg-gray-700 dark:text-white dark:hover:bg-gray-600"
            }`}>
            {stt.grabando
              ? <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="6" width="12" height="12" rx="2"/></svg>
              : <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor"><path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/><path d="M19 10v2a7 7 0 01-14 0v-2M12 19v4M8 23h8"/></svg>
            }
          </button>
        )}
      </div>
      {(stt.grabando || stt.transcribiendo) && (
        <p className="text-center text-xs text-accent px-4 pb-1">
          {stt.grabando ? `🎙️ ${stt.segundos}s` : "✨ Transcribiendo…"}
        </p>
      )}
      </div>
    </div>
    </>
  );
}

// ── RevisionSolicitudView ─────────────────────────────────────────────────────

function RevisionSolicitudView({
  token, solicitud, onVolver, onConfirmar, onPedirAjustes,
}: {
  token: string;
  solicitud: { id: number; titulo: string; numero: string; asignado_a_nombre: string };
  onVolver: () => void;
  onConfirmar: () => Promise<void>;
  onPedirAjustes: (motivo: string) => Promise<void>;
}) {
  type NotaRev = { id: number; texto: string; fotoUrl?: string; autorNombre?: string };
  const [notas, setNotas] = useState<NotaRev[]>([]);
  const [descripcion, setDescripcion] = useState("");
  const [cargando, setCargando] = useState(true);
  const [confirmando, setConfirmando] = useState(false);
  const [showRechazo, setShowRechazo] = useState(false);
  const [motivoRechazo, setMotivoRechazo] = useState("");
  const [rechazando, setRechazando] = useState(false);
  const [lbUrl, setLbUrl] = useState<string | null>(null);
  type ItemAjuste = { id: number; texto: string; fotos: { file: File; preview: string | null }[] };
  const itemIdRef = useRef(0);
  const [itemsAjuste, setItemsAjuste] = useState<ItemAjuste[]>([{ id: 0, texto: "", fotos: [] }]);
  const bottomRef = useRef<HTMLDivElement>(null);

  function agregarItemAjuste() {
    setItemsAjuste(prev => [...prev, { id: ++itemIdRef.current, texto: "", fotos: [] }]);
  }
  function eliminarItemAjuste(id: number) {
    setItemsAjuste(prev => prev.filter(it => it.id !== id));
  }
  function setTextoItem(id: number, texto: string) {
    setItemsAjuste(prev => prev.map(it => it.id === id ? { ...it, texto } : it));
  }
  function agregarFotoItem(id: number, file: File) {
    const preview = file.type.startsWith("image/") ? URL.createObjectURL(file) : null;
    setItemsAjuste(prev => prev.map(it => it.id === id ? { ...it, fotos: [...it.fotos, { file, preview }] } : it));
  }
  function quitarFotoItem(itemId: number, idx: number) {
    setItemsAjuste(prev => prev.map(it => it.id === itemId ? { ...it, fotos: it.fotos.filter((_, i) => i !== idx) } : it));
  }

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [notas]);

  useEffect(() => {
    let cancelled = false;
    async function cargar() {
      setCargando(true);
      try {
        const hdrs = { Authorization: `Bearer ${token}` };
        const [resTkt, resComs, resAdjs] = await Promise.all([
          fetch(`/api/tickets/${solicitud.id}`,             { headers: hdrs }),
          fetch(`/api/tickets/${solicitud.id}/comentarios`, { headers: hdrs }),
          fetch(`/api/tickets/${solicitud.id}/adjuntos`,    { headers: hdrs }),
        ]);
        if (cancelled) return;
        type ComRow = { id: number; texto: string; creado_en: string; autor_nombre?: string };
        type AdjRow = { id: number; nombre_archivo: string; mime: string | null; nombre_original: string; creado_en: string; creado_por_nombre?: string };
        const tkt: { descripcion?: string } = resTkt.ok ? await resTkt.json() : {};
        const coms: ComRow[] = resComs.ok ? await resComs.json() : [];
        const adjs: AdjRow[] = resAdjs.ok ? await resAdjs.json() : [];
        if (tkt.descripcion?.trim()) setDescripcion(tkt.descripcion.trim());
        const items: Array<{ creado_en: string; nota: NotaRev }> = [];
        let lid = 0;
        for (const c of coms) {
          items.push({ creado_en: c.creado_en, nota: { id: ++lid, texto: c.texto, autorNombre: c.autor_nombre } });
        }
        for (const a of adjs) {
          const esImg = (a.mime ?? "").startsWith("image/");
          if (esImg) {
            items.push({ creado_en: a.creado_en, nota: {
              id: ++lid, texto: "", autorNombre: a.creado_por_nombre,
              fotoUrl: ticketsUploadUrl(a.nombre_archivo, token),
            }});
          } else {
            items.push({ creado_en: a.creado_en, nota: {
              id: ++lid, texto: `📎 ${a.nombre_original}`, autorNombre: a.creado_por_nombre,
            }});
          }
        }
        items.sort((a, b) => a.creado_en.localeCompare(b.creado_en));
        setNotas(items.map(i => i.nota));
      } catch { /* silencioso */ }
      finally { if (!cancelled) setCargando(false); }
    }
    void cargar();
    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [solicitud.id]);

  return (
    <div className="hugo-chat flex flex-col h-full min-h-0 overflow-hidden bg-surface font-sans antialiased text-ink">
      {/* Header */}
      <div className="shrink-0 flex items-start gap-3 px-4 py-3 border-b-2 border-border bg-surface-panel pt-safe shadow-paper-sm">
        <button type="button" onClick={onVolver}
          className="mt-0.5 flex items-center justify-center h-8 w-8 rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-white/10 dark:text-white/70 dark:hover:bg-white/20 transition shrink-0">‹</button>
        <div className="min-w-0 flex-1">
          <p className="text-[10px] font-extrabold uppercase tracking-widest text-accent  mb-0.5">⏳ Revisar y confirmar</p>
          <p className="text-base font-extrabold text-ink leading-snug line-clamp-2 tracking-tight">{solicitud.titulo}</p>
          {solicitud.asignado_a_nombre && (
            <p className="text-sm font-bold text-muted mt-0.5">Resolvió: {solicitud.asignado_a_nombre}</p>
          )}
        </div>
      </div>

      {/* Hilo */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3 bg-gray-50 dark:bg-gray-950">
        {/* Tarjeta de contexto */}
        <div className="rounded-2xl border-2 border-accent/60  bg-accent/5  px-4 py-3 space-y-1">
          <div className="flex items-center gap-2">
            <span className="h-6 w-6 shrink-0 rounded-full bg-accent/50 text-white text-[11px] font-black flex items-center justify-center">
              {solicitud.asignado_a_nombre?.charAt(0)?.toUpperCase() ?? "?"}
            </span>
            <p className="text-[11px] font-extrabold text-accent  uppercase tracking-wide">
              {solicitud.asignado_a_nombre} · {shortNumero(solicitud.numero)}
            </p>
          </div>
          <p className="text-sm font-bold text-accent  leading-snug">{solicitud.titulo}</p>
          {descripcion && descripcion !== solicitud.titulo && (
            <p className="text-sm text-accent/80  leading-relaxed whitespace-pre-wrap">{descripcion}</p>
          )}
        </div>

        {cargando && (
          <div className="flex items-center justify-center py-10 gap-2">
            {[0,1,2].map(i => <span key={i} className="block h-2.5 w-2.5 rounded-full bg-accent animate-bounce" style={{ animationDelay: `${i*150}ms` }}/>)}
          </div>
        )}

        {!cargando && notas.length === 0 && (
          <p className="text-center py-8 text-sm text-gray-400 dark:text-white/40">
            No se registraron notas ni fotos durante la ejecución.
          </p>
        )}

        {notas.map(nota => (
          <div key={nota.id} className="flex justify-start">
            <div className="max-w-[88%] space-y-1">
              {nota.autorNombre && (
                <p className="text-[10px] font-extrabold text-accent uppercase tracking-wide px-1">{nota.autorNombre}</p>
              )}
              {nota.fotoUrl && (
                <>
                  {lbUrl && <ImageLightbox url={lbUrl} onClose={() => setLbUrl(null)} />}
                  <button type="button" onClick={() => setLbUrl(nota.fotoUrl!)} className="group relative block w-full max-w-xs text-left" title="Ver imagen">
                    <img src={nota.fotoUrl} alt="foto"
                      className="rounded-xl w-full max-w-xs border border-gray-200 dark:border-white/10 object-cover group-hover:opacity-80 transition-opacity" />
                    <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-2xl font-bold transition-opacity pointer-events-none">🔍</span>
                  </button>
                </>
              )}
              {nota.texto && (
                <div className="rounded-2xl rounded-bl-sm px-4 py-2.5 text-sm leading-relaxed bg-surface-panel border-2 border-border text-ink">
                  {nota.texto}
                </div>
              )}
            </div>
          </div>
        ))}

        <div ref={bottomRef} />
      </div>

      {/* Pie: confirmar / pedir ajustes */}
      <div className="shrink-0 border-t border-gray-200 dark:border-white/10 bg-surface-panel px-4 py-3 pb-safe space-y-2">
        {showRechazo ? (
          <div className="space-y-3">
            <p className="text-xs font-extrabold uppercase tracking-wide text-muted">¿Qué necesita ajustar?</p>

            {itemsAjuste.map((item, idx) => (
              <div key={item.id} className="rounded-xl border-2 border-border bg-surface p-2.5 space-y-2">
                {itemsAjuste.length > 1 && (
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-extrabold uppercase tracking-wide text-muted">Punto {idx + 1}</span>
                    <button type="button" onClick={() => eliminarItemAjuste(item.id)}
                      className="text-xs text-muted hover:text-red-500 leading-none">✕</button>
                  </div>
                )}
                <ProseTextarea
                  value={item.texto}
                  onChange={e => setTextoItem(item.id, e.target.value)}
                  placeholder={idx === 0 ? "Explica qué faltó o qué debe corregirse…" : "Describe este punto…"}
                  rows={2}
                  className="w-full rounded-xl border-2 border-border bg-surface px-3 py-2 text-sm text-ink placeholder:text-muted outline-none focus:border-accent transition resize-none"
                />
                {/* Fotos del item */}
                {item.fotos.length > 0 && (
                  <div className="flex flex-wrap gap-1.5">
                    {item.fotos.map((f, fi) => (
                      <div key={fi} className="relative">
                        {f.preview
                          ? <img src={f.preview} alt="" className="h-16 w-16 rounded-lg object-cover border-2 border-border" />
                          : <div className="h-16 w-16 rounded-lg border-2 border-border bg-surface-hover flex items-center justify-center text-xl">📎</div>
                        }
                        <button type="button" onClick={() => quitarFotoItem(item.id, fi)}
                          className="absolute -top-1 -right-1 h-4 w-4 rounded-full bg-red-500 text-white text-[9px] font-bold flex items-center justify-center leading-none">✕</button>
                      </div>
                    ))}
                  </div>
                )}
                <label className="flex items-center gap-1.5 cursor-pointer text-xs text-muted hover:text-accent transition-colors">
                  <span>📷</span>
                  <span>{item.fotos.length > 0 ? "Agregar otra imagen" : "Adjuntar imagen o PDF"}</span>
                  <input type="file" accept="image/*,.pdf,application/pdf" multiple className="sr-only"
                    onChange={e => {
                      Array.from(e.target.files ?? []).forEach(f => agregarFotoItem(item.id, f));
                      e.target.value = "";
                    }}
                  />
                </label>
              </div>
            ))}

            <button type="button" onClick={agregarItemAjuste}
              className="flex items-center gap-1.5 text-xs text-accent  hover:underline font-bold">
              + Agregar otro punto de ajuste
            </button>

            <div className="flex gap-2">
              <button type="button"
                onClick={() => { setShowRechazo(false); setMotivoRechazo(""); setItemsAjuste([{ id: 0, texto: "", fotos: [] }]); }}
                className="flex-1 rounded-2xl border-2 border-border py-2.5 text-sm font-bold text-muted transition hover:bg-surface-hover">
                Cancelar
              </button>
              <button type="button"
                disabled={rechazando || itemsAjuste.every(it => !it.texto.trim() && it.fotos.length === 0)}
                onClick={async () => {
                  setRechazando(true);
                  // Subir todas las fotos de todos los items
                  for (const item of itemsAjuste) {
                    for (const foto of item.fotos) {
                      const fd = new FormData();
                      fd.append("archivo", foto.file);
                      await fetch(`/api/tickets/${solicitud.id}/adjuntos`, {
                        method: "POST",
                        headers: { Authorization: `Bearer ${token}` },
                        body: fd,
                      }).catch(() => { /* no crítico */ });
                    }
                  }
                  // Motivo: unir todos los textos no vacíos
                  const motivo = itemsAjuste
                    .map((it, i) => it.texto.trim() ? (itemsAjuste.length > 1 ? `${i + 1}. ${it.texto.trim()}` : it.texto.trim()) : "")
                    .filter(Boolean)
                    .join("\n");
                  await onPedirAjustes(motivo);
                  setItemsAjuste([{ id: 0, texto: "", fotos: [] }]);
                  setRechazando(false);
                }}
                className="flex-1 rounded-2xl bg-accent/50 hover:bg-accent/40 py-2.5 text-sm font-extrabold text-white transition active:scale-[0.98] disabled:opacity-50">
                {rechazando ? "Enviando…" : "↩️ Devolver para ajustes"}
              </button>
            </div>
          </div>
        ) : (
          <div className="flex gap-2">
            <button type="button"
              onClick={() => setShowRechazo(true)}
              className="flex-1 rounded-2xl border-2 border-accent/40 py-3 text-sm font-extrabold text-accent transition hover:bg-accent/5  active:scale-[0.98]">
              ↩️ Pedir ajustes
            </button>
            <button type="button"
              disabled={confirmando}
              onClick={async () => {
                setConfirmando(true);
                await onConfirmar();
                setConfirmando(false);
              }}
              className="flex-2 flex-grow-[2] rounded-2xl bg-accent/50 hover:bg-accent/40 py-3 text-sm font-extrabold text-white transition active:scale-[0.98] shadow-lg disabled:opacity-50">
              {confirmando ? "Confirmando…" : "✅ Confirmar — todo listo"}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

// ── ResolverActividadChat ─────────────────────────────────────────────────────

function ResolverActividadChat({
  token, solicitud, stt, chatApiToken, onVolver, onTerminado,
}: {
  token: string;
  solicitud: { id: number; titulo: string; numero: string; creado_por_nombre: string };
  stt: ReturnType<typeof useStt>;
  chatApiToken: string | null | undefined;
  onVolver: () => void;
  onTerminado: () => void;
}) {
  type Nota = { id: number; texto: string; fotoUrl?: string; autorNombre?: string; esSolicitante?: boolean; tipo?: "texto" | "foto" | "sistema"; serverItemId?: number; guardando?: boolean; errorGuarda?: boolean; eliminando?: boolean };
  const { user: currentUser } = useTicketsAuth();
  const [notas, setNotas] = useState<Nota[]>([]);
  const [cargandoNotas, setCargandoNotas] = useState(true);
  const [descripcion, setDescripcion] = useState("");
  const [inputNota, setInputNota] = useState("");
  const [terminando, setTerminando] = useState(false);
  const [error, setError] = useState("");
  const [showIntervencion, setShowIntervencion] = useState(false);
  const [modoIntervencion, setModoIntervencion] = useState<"pausar" | "colaborar">("pausar");
  const [participantes, setParticipantes] = useState<{ usuario_id: number; usuario_nombre: string; rol: string }[]>([]);
  const [usuarios, setUsuarios] = useState<{ id: number; nombre: string }[]>([]);
  const [interUsuario, setInterUsuario] = useState("");
  const [interTitulo, setInterTitulo] = useState("");
  const [creandoInter, setCreandoInter] = useState(false);
  // Bloqueo por intervención pendiente
  const [bloqueadoPorNumero, setBloqueadoPorNumero] = useState<string | null>(null);
  const [bloqueadoPorNombre, setBloqueadoPorNombre] = useState<string | null>(null);
  // Contexto del ticket padre (cuando este es un sub-ticket de intervención)
  const [padreInfo, setPadreInfo] = useState<{ titulo: string; numero: string; notasPadre: Nota[] } | null>(null);
  const [showPadre, setShowPadre] = useState(false);
  const [lbUrl, setLbUrl] = useState<string | null>(null);
  const notaIdRef = useRef(0);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputNotaRef = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
    const el = inputNotaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 128)}px`;
  }, [inputNota]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [notas]);

  // Carga historial existente + descripción del ticket al montar
  useEffect(() => {
    let cancelled = false;
    async function cargarHistorial() {
      setCargandoNotas(true);
      try {
        const hdrs = { Authorization: `Bearer ${token}` };
        const [resTkt, resComs, resAdjs] = await Promise.all([
          fetch(`/api/tickets/${solicitud.id}`,            { headers: hdrs }),
          fetch(`/api/tickets/${solicitud.id}/comentarios`, { headers: hdrs }),
          fetch(`/api/tickets/${solicitud.id}/adjuntos`,    { headers: hdrs }),
        ]);
        if (cancelled) return;

        type ComRow = { id: number; texto: string; creado_en: string; autor_nombre?: string };
        type AdjRow = { id: number; nombre_archivo: string; mime: string | null; nombre_original: string; creado_en: string; creado_por_nombre?: string };
        type TktRow = {
          descripcion?: string;
          participantes?: { usuario_id: number; usuario_nombre: string; rol: string }[];
          bloqueado_por?: number | null;
          bloqueado_por_numero?: string | null;
          asignado_a_nombre?: string | null;
          ticket_padre_id?: number | null;
          ticket_padre_titulo?: string | null;
          ticket_padre_numero?: string | null;
        };

        const tkt: TktRow           = resTkt.ok  ? await resTkt.json()  : {};
        const coms: ComRow[]        = resComs.ok  ? await resComs.json() : [];
        const adjs: AdjRow[]        = resAdjs.ok  ? await resAdjs.json() : [];

        if (tkt.participantes) setParticipantes(tkt.participantes);

        // Detectar bloqueo por intervención pendiente
        if (tkt.bloqueado_por) {
          setBloqueadoPorNumero(tkt.bloqueado_por_numero ?? null);
          // Obtener el nombre del asignado del sub-ticket (bloqueador)
          try {
            const resBloq = await fetch(`/api/tickets/${tkt.bloqueado_por}`, { headers: hdrs });
            if (resBloq.ok) {
              const bloqTkt: { asignado_a_nombre?: string } = await resBloq.json();
              setBloqueadoPorNombre(bloqTkt.asignado_a_nombre ?? null);
            }
          } catch { /* silencioso */ }
        }

        // Si este ticket ES un sub-ticket (intervención), cargar el hilo del ticket padre
        if (tkt.ticket_padre_id) {
          try {
            const [resPadreComs, resPadreAdjs] = await Promise.all([
              fetch(`/api/tickets/${tkt.ticket_padre_id}/comentarios`, { headers: hdrs }),
              fetch(`/api/tickets/${tkt.ticket_padre_id}/adjuntos`, { headers: hdrs }),
            ]);
            const padreComs: ComRow[] = resPadreComs.ok ? await resPadreComs.json() : [];
            const padreAdjs: AdjRow[] = resPadreAdjs.ok ? await resPadreAdjs.json() : [];
            const nombreSolPadre = solicitud.creado_por_nombre?.trim().toLowerCase();
            const padreItems: Array<{ creado_en: string; nota: Nota }> = [];
            let pid = 0;
            for (const c of padreComs) {
              const autor = c.autor_nombre ?? "";
              padreItems.push({ creado_en: c.creado_en, nota: {
                id: --pid, texto: c.texto, autorNombre: autor,
                esSolicitante: !!nombreSolPadre && autor.trim().toLowerCase() === nombreSolPadre,
              }});
            }
            for (const a of padreAdjs) {
              const autor = a.creado_por_nombre ?? "";
              const esImg = (a.mime ?? "").startsWith("image/");
              if (esImg) {
                padreItems.push({ creado_en: a.creado_en, nota: {
                  id: --pid, texto: "", autorNombre: autor,
                  esSolicitante: !!nombreSolPadre && autor.trim().toLowerCase() === nombreSolPadre,
                  fotoUrl: ticketsUploadUrl(a.nombre_archivo, token),
                }});
              }
            }
            padreItems.sort((a, b) => a.creado_en.localeCompare(b.creado_en));
            if (padreItems.length > 0) {
              setPadreInfo({
                titulo: tkt.ticket_padre_titulo ?? "Hilo principal",
                numero: tkt.ticket_padre_numero ?? "",
                notasPadre: padreItems.map(i => i.nota),
              });
            }
          } catch { /* silencioso */ }
        }

        if (tkt.descripcion?.trim()) setDescripcion(tkt.descripcion.trim());

        // Nombre del solicitante para identificar sus aportes
        const nombreSol = solicitud.creado_por_nombre?.trim().toLowerCase();

        const items: Array<{ creado_en: string; nota: Nota }> = [];
        let localId = 0;
        for (const c of coms) {
          const autor = c.autor_nombre ?? "";
          const esSol = !!nombreSol && autor.trim().toLowerCase() === nombreSol;
          items.push({ creado_en: c.creado_en, nota: {
            id: ++localId, texto: c.texto, autorNombre: autor, esSolicitante: esSol,
            tipo: "texto", serverItemId: c.id,
          }});
        }
        for (const a of adjs) {
          const autor = a.creado_por_nombre ?? "";
          const esSol = !!nombreSol && autor.trim().toLowerCase() === nombreSol;
          const esImg = (a.mime ?? "").startsWith("image/");
          if (esImg) {
            items.push({ creado_en: a.creado_en, nota: {
              id: ++localId, texto: "", autorNombre: autor, esSolicitante: esSol,
              fotoUrl: ticketsUploadUrl(a.nombre_archivo, token),
              tipo: "foto", serverItemId: a.id,
            }});
          } else {
            items.push({ creado_en: a.creado_en, nota: {
              id: ++localId, texto: `📎 ${a.nombre_original}`, autorNombre: autor, esSolicitante: esSol,
              tipo: "texto", serverItemId: a.id,
            }});
          }
        }

        // Cargar hilos de sub-tickets (intervenciones resueltas por terceros)
        try {
          const resSubTkts = await fetch(`/api/tickets/${solicitud.id}/sub-tickets`, { headers: hdrs });
          const subTkts: Array<{ id: number; numero: string; estado: string; asignado_a_nombre: string; resuelto_en: string }> =
            resSubTkts.ok ? await resSubTkts.json() : [];
          for (const sub of subTkts.filter(s => s.estado === "resuelto")) {
            const [rSubComs, rSubAdjs] = await Promise.all([
              fetch(`/api/tickets/${sub.id}/comentarios`, { headers: hdrs }),
              fetch(`/api/tickets/${sub.id}/adjuntos`,   { headers: hdrs }),
            ]);
            const subComs: ComRow[] = rSubComs.ok ? await rSubComs.json() : [];
            const subAdjs: AdjRow[] = rSubAdjs.ok ? await rSubAdjs.json() : [];
            items.push({ creado_en: sub.resuelto_en || "", nota: {
              id: ++localId, texto: `🔧 ${sub.numero} — ${sub.asignado_a_nombre}`, tipo: "sistema",
            }});
            for (const c of subComs) {
              items.push({ creado_en: c.creado_en, nota: {
                id: ++localId, texto: c.texto, autorNombre: c.autor_nombre ?? sub.asignado_a_nombre,
                esSolicitante: false, tipo: "texto",
              }});
            }
            for (const a of subAdjs) {
              if ((a.mime ?? "").startsWith("image/")) {
                items.push({ creado_en: a.creado_en, nota: {
                  id: ++localId, texto: "", autorNombre: a.creado_por_nombre ?? sub.asignado_a_nombre,
                  esSolicitante: false, tipo: "foto",
                  fotoUrl: ticketsUploadUrl(a.nombre_archivo, token),
                }});
              }
            }
          }
        } catch { /* silencioso */ }

        items.sort((a, b) => a.creado_en.localeCompare(b.creado_en));
        notaIdRef.current = localId;
        setNotas(items.map(i => i.nota));
      } catch { /* silencioso */ }
      finally { if (!cancelled) setCargandoNotas(false); }
    }
    void cargarHistorial();
    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [solicitud.id]);

  async function agregarNota(texto: string, fotoFile?: File, fotoUrl?: string) {
    if (!texto.trim() && !fotoFile) return;
    const nid = ++notaIdRef.current;
    setNotas(prev => [...prev, { id: nid, texto: texto.trim(), fotoUrl, guardando: true }]);
    setInputNota("");
    try {
      let serverItemId: number | undefined;
      if (fotoFile) {
        const fd = new FormData();
        fd.append("archivo", fotoFile);
        const res = await fetch(`/api/tickets/${solicitud.id}/adjuntos`, {
          method: "POST", headers: { Authorization: `Bearer ${token}` }, body: fd,
        });
        if (!res.ok) throw new Error("upload");
        const json = await res.json();
        serverItemId = json.id;
        setNotas(prev => prev.map(n => n.id === nid ? { ...n, guardando: false, tipo: "foto", serverItemId } : n));
      } else if (texto.trim()) {
        const res = await fetch(`/api/tickets/${solicitud.id}/comentarios`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
          body: JSON.stringify({ texto: texto.trim() }),
        });
        if (!res.ok) throw new Error("comment");
        const json = await res.json();
        serverItemId = json.id;
        setNotas(prev => prev.map(n => n.id === nid ? { ...n, guardando: false, tipo: "texto", serverItemId } : n));
      }
    } catch {
      setNotas(prev => prev.map(n => n.id === nid ? { ...n, guardando: false, errorGuarda: true } : n));
    }
  }

  async function eliminarNota(nota: Nota) {
    if (!nota.serverItemId || nota.guardando || nota.eliminando) return;
    setNotas(prev => prev.map(n => n.id === nota.id ? { ...n, eliminando: true } : n));
    try {
      const url = nota.tipo === "foto"
        ? `/api/tickets/adjuntos/${nota.serverItemId}`
        : `/api/tickets/comentarios/${nota.serverItemId}`;
      const res = await fetch(url, { method: "DELETE", headers: { Authorization: `Bearer ${token}` } });
      if (!res.ok) throw new Error("delete");
      setNotas(prev => prev.filter(n => n.id !== nota.id));
    } catch {
      setNotas(prev => prev.map(n => n.id === nota.id ? { ...n, eliminando: false } : n));
    }
  }

  const [cropFile, setCropFile] = useState<File | null>(null);

  function onFotoSeleccionada(file: File) {
    setCropFile(file);
  }

  function handlePaste(e: React.ClipboardEvent) {
    const items = Array.from(e.clipboardData.items);
    const imgItem = items.find(it => it.type.startsWith("image/"));
    if (!imgItem) return;
    e.preventDefault();
    const file = imgItem.getAsFile();
    if (file) setCropFile(new File([file], `captura-${Date.now()}.png`, { type: file.type }));
  }

  async function cargarUsuarios() {
    try {
      const data = await tapi("/usuarios", token);
      setUsuarios(Array.isArray(data) ? data.filter((u: any) => u.activo) : []);
    } catch { /* ignore */ }
  }

  async function crearIntervencion() {
    if (!interUsuario) return;
    setCreandoInter(true);
    try {
      if (modoIntervencion === "colaborar") {
        // Agregar como participante/colaborador sin pausar
        await tapi(`/${solicitud.id}/participantes`, token, {
          method: "POST",
          body: JSON.stringify({ usuario_id: Number(interUsuario), rol: "colaborador" }),
        });
        const nombreInvitado = usuarios.find(u => String(u.id) === interUsuario)?.nombre ?? "Compañero";
        // Dejar nota en el hilo anunciando la colaboración
        await fetch(`/api/tickets/${solicitud.id}/comentarios`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
          body: JSON.stringify({ texto: `👥 ${nombreInvitado} fue invitado a colaborar en este hilo.${interTitulo.trim() ? ` (${interTitulo.trim()})` : ""}` }),
        });
        // Actualizar lista de participantes localmente
        setParticipantes(prev => [
          ...prev.filter(p => p.usuario_id !== Number(interUsuario)),
          { usuario_id: Number(interUsuario), usuario_nombre: nombreInvitado, rol: "colaborador" },
        ]);
        const newNota: Nota = {
          id: ++notaIdRef.current,
          texto: `👥 ${nombreInvitado} fue invitado a colaborar en este hilo.${interTitulo.trim() ? ` (${interTitulo.trim()})` : ""}`,
          autorNombre: "Sistema",
          esSolicitante: false,
        };
        setNotas(prev => [...prev, newNota]);
        setShowIntervencion(false);
        setInterTitulo("");
        setInterUsuario("");
      } else {
        if (!interTitulo.trim()) return;
        await tapi(`/${solicitud.id}/pedir-intervencion`, token, {
          method: "POST",
          body: JSON.stringify({
            titulo: interTitulo.trim(),
            descripcion: "",
            asignado_a: Number(interUsuario),
          }),
        });
        setShowIntervencion(false);
        setInterTitulo("");
        setInterUsuario("");
        setError("Intervención solicitada. La solicitud quedará pausada hasta que el compañero responda.");
      }
    } catch (e: any) {
      setError(e.message || "No se pudo crear la intervención.");
    } finally {
      setCreandoInter(false);
    }
  }

  async function terminar() {
    if (notas.some(n => n.guardando)) { setError("Aún guardando ítems…"); return; }
    setTerminando(true);
    setError("");
    try {
      const res = await fetch(`/api/tickets/${solicitud.id}/estado`, {
        method: "PUT",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        // Pasa a esperando_aprobacion: el solicitante debe confirmar que fue atendida
        body: JSON.stringify({ estado: "esperando_aprobacion" }),
      });
      if (!res.ok) throw new Error("No se pudo marcar la actividad");
      onTerminado();
    } catch (e: any) {
      setError(e.message || "Ocurrió un error. Intenta de nuevo.");
    } finally {
      setTerminando(false);
    }
  }

  const hayContenido = notas.length > 0;

  if (showIntervencion) {
    const canSubmit = modoIntervencion === "colaborar"
      ? !!interUsuario
      : !!interTitulo.trim() && !!interUsuario;
    return (
      <div className="hugo-chat flex flex-col h-full min-h-0 overflow-hidden bg-surface font-sans antialiased text-ink">
        <div className="shrink-0 flex items-center gap-3 px-4 py-3 border-b-2 border-border bg-surface-panel pt-safe shadow-paper-sm">
          <button type="button" onClick={() => setShowIntervencion(false)}
            className="flex items-center justify-center h-8 w-8 rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-white/10 dark:text-white/70 transition shrink-0">‹</button>
          <p className="text-base font-extrabold text-ink">Pedir intervención</p>
        </div>
        <div className="flex-1 overflow-y-auto px-4 py-5 space-y-5">
          {/* Selector de modo */}
          <div className="grid grid-cols-2 gap-2">
            <button type="button"
              onClick={() => setModoIntervencion("pausar")}
              className={`rounded-2xl border-2 px-4 py-3 text-left transition ${
                modoIntervencion === "pausar"
                  ? "border-accent/40 bg-accent/5"
                  : "border-border bg-surface hover:border-accent/50"
              }`}>
              <p className="text-sm font-extrabold text-ink">🛑 Pausar y delegar</p>
              <p className="mt-0.5 text-[11px] text-muted leading-snug">Crea un sub-ticket. La solicitud queda bloqueada hasta que el compañero responda.</p>
            </button>
            <button type="button"
              onClick={() => setModoIntervencion("colaborar")}
              className={`rounded-2xl border-2 px-4 py-3 text-left transition ${
                modoIntervencion === "colaborar"
                  ? "border-accent/40 bg-accent/5"
                  : "border-border bg-surface hover:border-accent/50"
              }`}>
              <p className="text-sm font-extrabold text-ink">👥 Invitar a colaborar</p>
              <p className="mt-0.5 text-[11px] text-muted leading-snug">Comparte el hilo. El compañero puede ver y escribir en la misma conversación sin pausar.</p>
            </button>
          </div>

          {/* Compañero */}
          <div className="space-y-2">
            <label className="text-xs font-extrabold uppercase tracking-wide text-muted">¿A quién?</label>
            {usuarios.length === 0
              ? <button type="button" onClick={cargarUsuarios} className="text-sm text-accent font-bold">Cargar compañeros…</button>
              : <select value={interUsuario} onChange={e => setInterUsuario(e.target.value)}
                  className="w-full rounded-xl border-2 border-border bg-surface px-4 py-3 text-sm text-ink outline-none focus:border-accent transition">
                  <option value="">Elegí un compañero</option>
                  {usuarios.filter(u => u.id !== currentUser?.id).map(u => (
                    <option key={u.id} value={u.id}>{u.nombre}</option>
                  ))}
                </select>
            }
          </div>

          {/* Título/motivo — solo en modo pausar, opcional en colaborar */}
          <div className="space-y-2">
            <label className="text-xs font-extrabold uppercase tracking-wide text-muted">
              {modoIntervencion === "pausar" ? "¿Qué necesitás que haga? *" : "Contexto para el compañero (opcional)"}
            </label>
            <input
              value={interTitulo}
              onChange={e => setInterTitulo(e.target.value)}
              placeholder={modoIntervencion === "pausar" ? "Ej: Preparar el informe de inventario" : "Ej: Revisá la sección de facturación"}
              className="w-full rounded-xl border-2 border-border bg-surface px-4 py-3 text-sm text-ink placeholder:text-muted outline-none focus:border-accent transition"
            />
          </div>

          {error && <p className="text-xs text-red-500">{error}</p>}
        </div>
        <div className="shrink-0 border-t border-gray-200 dark:border-white/10 bg-surface-panel px-4 py-3 pb-safe">
          <button type="button" onClick={crearIntervencion}
            disabled={creandoInter || !canSubmit}
            className={`w-full rounded-2xl py-3.5 text-base font-extrabold text-white disabled:opacity-50 transition active:scale-[0.98] ${
              modoIntervencion === "colaborar" ? "bg-accent hover:bg-accent/50" : "bg-accent hover:bg-accent-hover"
            }`}>
            {creandoInter
              ? "Enviando…"
              : modoIntervencion === "colaborar"
                ? "👥 Invitar a colaborar"
                : "🛑 Crear sub-ticket y pausar"}
          </button>
        </div>
      </div>
    );
  }

  return (
    <>
      {cropFile && (
        <CropperModal
          file={cropFile}
          onConfirmar={croppedFile => {
            setCropFile(null);
            void agregarNota("", croppedFile, URL.createObjectURL(croppedFile));
          }}
          onCancelar={() => setCropFile(null)}
        />
      )}
      {lbUrl && <ImageLightbox url={lbUrl} onClose={() => setLbUrl(null)} />}
    <div className="hugo-chat flex flex-col h-full min-h-0 overflow-hidden bg-surface font-sans antialiased text-ink" onPaste={handlePaste}>
      {/* Header */}
      <div className="shrink-0 flex items-start gap-3 px-4 py-3 border-b-2 border-border bg-surface-panel pt-safe shadow-paper-sm">
        <button type="button" onClick={onVolver}
          className="mt-0.5 flex items-center justify-center h-8 w-8 rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-white/10 dark:text-white/70 dark:hover:bg-white/20 transition shrink-0"
        >‹</button>
        <div className="min-w-0 flex-1">
          <p className="text-xs font-extrabold uppercase tracking-widest text-muted mb-0.5">Solicitud para atender</p>
          <p className="text-base font-extrabold text-ink leading-snug line-clamp-2 tracking-tight">{solicitud.titulo}</p>
          {solicitud.creado_por_nombre && (
            <p className="text-sm font-bold text-muted mt-0.5">De: {solicitud.creado_por_nombre}</p>
          )}
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {participantes.length > 0 && (
            <div className="flex items-center gap-1" title={participantes.map(p => p.usuario_nombre).join(", ")}>
              {participantes.slice(0, 3).map(p => (
                <span key={p.usuario_id}
                  className="flex h-7 w-7 items-center justify-center rounded-full bg-accent/50 text-white text-[10px] font-black shadow"
                  title={`${p.usuario_nombre} (${p.rol})`}>
                  {p.usuario_nombre.charAt(0).toUpperCase()}
                </span>
              ))}
              {participantes.length > 3 && (
                <span className="text-xs font-bold text-muted">+{participantes.length - 3}</span>
              )}
            </div>
          )}
          <button type="button"
            onClick={() => { setShowIntervencion(true); void cargarUsuarios(); }}
            className="shrink-0 rounded-xl border border-border bg-surface px-2.5 py-1.5 text-xs font-bold text-muted hover:border-accent hover:text-accent transition"
            title="Pedir intervención de un compañero">
            🤝 Intervenir
          </button>
        </div>
      </div>

      {/* Área de notas / actividad */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3 bg-gray-50 dark:bg-gray-950">

        {/* Banner: bloqueo por intervención pendiente */}
        {bloqueadoPorNumero && (
          <div className="rounded-2xl border-2 border-accent/70 bg-accent/5  px-4 py-3 flex items-start gap-3">
            <span className="text-xl shrink-0">⏳</span>
            <div>
              <p className="text-xs font-extrabold text-accent  uppercase tracking-wide">Esperando intervención</p>
              <p className="text-sm text-accent  leading-snug mt-0.5">
                Sub-ticket <strong>{bloqueadoPorNumero}</strong>{bloqueadoPorNombre ? ` asignado a ${bloqueadoPorNombre}` : ""} debe resolverse antes de poder marcar esta solicitud como terminada. Puedes seguir comunicándote en el hilo.
              </p>
            </div>
          </div>
        )}

        {/* Hilo del ticket padre (cuando este es un sub-ticket de intervención) */}
        {padreInfo && (
          <div className="rounded-2xl border-2 border-accent/60  bg-accent/5">
            <button type="button"
              onClick={() => setShowPadre(v => !v)}
              className="w-full flex items-center justify-between px-4 py-2.5 text-left">
              <div className="flex items-center gap-2">
                <span className="text-accent">👥</span>
                <span className="text-xs font-extrabold text-accent  uppercase tracking-wide">
                  Hilo principal · {padreInfo.numero}
                </span>
                <span className="text-xs text-accent/70  truncate max-w-[150px]">{padreInfo.titulo}</span>
              </div>
              <span className="text-xs font-bold text-accent/50 shrink-0 ml-2">{showPadre ? "▲ Ocultar" : `▼ Ver (${padreInfo.notasPadre.length})`}</span>
            </button>
            {showPadre && (
              <div className="border-t border-accent/20  px-4 py-3 space-y-2 max-h-72 overflow-y-auto">
                {padreInfo.notasPadre.map(nota => {
                  const esSol = !!nota.esSolicitante;
                  return (
                    <div key={nota.id} className={`flex ${esSol ? "justify-start" : "justify-end"}`}>
                      <div className="max-w-[88%] space-y-0.5">
                        {nota.autorNombre && (
                          <p className="text-[10px] font-extrabold text-accent  uppercase tracking-wide px-1">{nota.autorNombre}</p>
                        )}
                        {nota.fotoUrl && (
                          <>
                            {lbUrl && <ImageLightbox url={lbUrl} onClose={() => setLbUrl(null)} />}
                            <button type="button" onClick={() => setLbUrl(nota.fotoUrl!)} className="group relative block w-full max-w-xs text-left" title="Ver imagen">
                              <img src={nota.fotoUrl} alt="foto" className="rounded-xl w-full max-w-xs border border-accent/20  object-cover group-hover:opacity-80 transition-opacity" />
                              <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 text-white text-2xl font-bold transition-opacity pointer-events-none">🔍</span>
                            </button>
                          </>
                        )}
                        {nota.texto && (
                          <div className={`rounded-2xl px-3 py-2 text-xs leading-relaxed ${
                            esSol ? "bg-accent/10  text-accent  rounded-bl-sm"
                                  : "bg-accent/20  text-accent  rounded-br-sm"
                          }`}>{nota.texto}</div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* Tarjeta de contexto: descripción de la solicitud (siempre visible) */}
        {!cargandoNotas && (
          <div className="rounded-2xl border-2 border-accent/60  bg-accent/5  px-4 py-3 space-y-1">
            <div className="flex items-center gap-2">
              <span className="h-6 w-6 shrink-0 rounded-full bg-accent/50 text-white text-[11px] font-black flex items-center justify-center">
                {solicitud.creado_por_nombre?.charAt(0)?.toUpperCase() ?? "?"}
              </span>
              <p className="text-[11px] font-extrabold text-accent  uppercase tracking-wide">
                {solicitud.creado_por_nombre} · Solicitud {solicitud.numero}
              </p>
            </div>
            <p className="text-sm font-bold text-accent  leading-snug">{solicitud.titulo}</p>
            {descripcion && descripcion !== solicitud.titulo && (
              <p className="text-sm text-accent/80  leading-relaxed whitespace-pre-wrap">{descripcion}</p>
            )}
          </div>
        )}

        {cargandoNotas && (
          <div className="flex items-center justify-center py-10 gap-2">
            {[0,1,2].map(i => <span key={i} className="block h-2.5 w-2.5 rounded-full bg-accent animate-bounce" style={{ animationDelay: `${i*150}ms` }}/>)}
          </div>
        )}
        {!cargandoNotas && notas.length === 0 && (
          <div className="text-center py-8 space-y-2">
            <p className="text-sm text-gray-400 dark:text-white/40">
              Cuénteme qué va haciendo o tome fotos.<br />Cuando termine, toque el botón verde.
            </p>
          </div>
        )}

        {notas.map(nota => {
          if (nota.tipo === "sistema") {
            return (
              <div key={nota.id} className="flex items-center gap-2 py-1.5">
                <div className="flex-1 h-px bg-border" />
                <span className="text-[10px] font-bold text-muted uppercase tracking-wide px-2 shrink-0">{nota.texto}</span>
                <div className="flex-1 h-px bg-border" />
              </div>
            );
          }
          const esSol = !!nota.esSolicitante;
          // Nota mía: la escribió el usuario actual (o no tiene autor = recién agregada localmente)
          const esMia = !nota.autorNombre || nota.autorNombre === currentUser?.nombre;
          // Colaborador: tiene autor, no soy yo, no es el solicitante
          const esColab = !!nota.autorNombre && !esSol && !esMia;
          const posicion = esSol || esColab ? "justify-start" : "justify-end";
          const canDelete = esMia && !esSol && !esColab && !!nota.serverItemId && !nota.guardando;
          return (
            <div key={nota.id} className={`flex ${posicion} group`}>
              <div className="max-w-[88%] space-y-1">
                {/* Nombre del autor — para solicitante y colaboradores */}
                {(esSol || esColab) && nota.autorNombre && (
                  <p className={`text-[10px] font-extrabold uppercase tracking-wide px-1 ${
                    esColab ? "text-accent" : "text-accent"
                  }`}>
                    {nota.autorNombre}
                  </p>
                )}
                {nota.fotoUrl && (
                  <div className="relative group/img">
                    <button type="button" onClick={() => !(nota.guardando || nota.eliminando) && setLbUrl(nota.fotoUrl!)} className="block w-full max-w-xs text-left" title="Ver imagen">
                      <img src={nota.fotoUrl} alt="foto"
                        className={`rounded-xl w-full max-w-xs border object-cover transition group-hover/img:opacity-80 ${nota.guardando || nota.eliminando ? "opacity-60" : ""} ${
                          esSol ? "border-accent/20"
                          : esColab ? "border-accent/20"
                          : "border-gray-200 dark:border-white/10"
                        }`}/>
                      {!(nota.guardando || nota.eliminando) && <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover/img:opacity-100 text-white text-2xl font-bold transition-opacity pointer-events-none">🔍</span>}
                    </button>
                    {canDelete && (
                      <button
                        onClick={() => eliminarNota(nota)}
                        disabled={nota.eliminando}
                        className="absolute top-1 right-1 opacity-0 group-hover/img:opacity-100 bg-black/60 hover:bg-red-600 text-white rounded-full h-6 w-6 flex items-center justify-center text-xs transition"
                        title="Eliminar foto"
                      >✕</button>
                    )}
                  </div>
                )}
                {nota.texto && (
                  <div className="relative">
                    <div className={`rounded-2xl px-4 py-2.5 text-sm leading-relaxed transition ${nota.guardando || nota.eliminando ? "opacity-60" : ""} ${
                      esSol
                        ? "bg-accent/10  text-accent  rounded-bl-sm"
                        : esColab
                          ? "bg-accent/10  text-accent  rounded-bl-sm"
                          : "bg-accent text-white rounded-br-sm"
                    }`}>
                      {nota.texto}
                    </div>
                    {canDelete && (
                      <button
                        onClick={() => eliminarNota(nota)}
                        disabled={nota.eliminando}
                        className="absolute -top-2 -right-2 opacity-0 group-hover:opacity-100 bg-black/60 hover:bg-red-600 text-white rounded-full h-5 w-5 flex items-center justify-center text-[10px] transition"
                        title="Eliminar nota"
                      >✕</button>
                    )}
                  </div>
                )}
                <p className={`text-[10px] text-gray-400 dark:text-white/30 ${esSol || esColab ? "text-left" : "text-right"}`}>
                  {nota.eliminando ? "Eliminando…" : nota.errorGuarda ? "⚠ No se guardó" : nota.guardando ? "Guardando…" : "✓"}
                </p>
              </div>
            </div>
          );
        })}
        {error && <p className="text-center text-xs text-red-500 dark:text-red-400">{error}</p>}
        <div ref={bottomRef} />
      </div>

      {/* Pie: terminar + input + micrófono */}
      <div className="shrink-0 border-t border-gray-200 dark:border-white/10 bg-surface-panel pb-safe">
      <div className="px-4 pt-3 pb-2">
        <button type="button" onClick={terminar}
          disabled={terminando || notas.some(n => n.guardando) || !!bloqueadoPorNumero}
          className="w-full rounded-2xl bg-accent/50 hover:bg-accent/40 disabled:opacity-50 py-3.5 text-base font-extrabold text-white transition active:scale-[0.98] shadow-lg">
          {terminando ? "Enviando para revisión…"
            : notas.some(n => n.guardando) ? "Guardando…"
            : bloqueadoPorNumero ? `⏳ Esperando intervención ${bloqueadoPorNumero}`
            : "✅ Listo — enviar para confirmación"}
        </button>
        <p className="text-center text-[10px] text-gray-400 dark:text-white/30 mt-1.5">
          {bloqueadoPorNumero
            ? "Primero debe resolverse la intervención pendiente."
            : hayContenido ? "El solicitante recibirá aviso para confirmar."
            : "Podés marcar sin notas — el solicitante deberá confirmar."}
        </p>
      </div>

      <div className="px-4 py-2.5 flex items-end gap-2">
        <BotonCamaraEjecucion onFile={onFotoSeleccionada} title="Tomar foto o pegar captura (Ctrl+V)" />
        <ProseTextarea ref={inputNotaRef} value={inputNota} onChange={e => setInputNota(e.target.value)} prose={false}
          onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); agregarNota(inputNota); } }}
          onPaste={handlePaste}
          rows={1}
          placeholder="Cuénteme qué hizo… (Shift+Enter para nueva línea)"
          className="flex-1 rounded-2xl bg-gray-100 border border-gray-200 px-4 py-2.5 text-sm text-gray-900 placeholder:text-gray-400 outline-none focus:border-accent/60 transition resize-none overflow-y-auto min-h-[42px] max-h-32 dark:bg-gray-800 dark:border-white/15 dark:text-white dark:placeholder:text-white/40"
        />
        {inputNota.trim() ? (
          <button type="button" onClick={() => agregarNota(inputNota)}
            className="h-11 w-11 shrink-0 rounded-full bg-accent flex items-center justify-center text-white shadow active:scale-95 transition">
            <svg className="h-5 w-5 rotate-90" viewBox="0 0 24 24" fill="currentColor"><path d="M2 21l21-9L2 3v7l15 2-15 2v7z"/></svg>
          </button>
        ) : (
          <button type="button" onClick={() => stt.grabando ? stt.detener() : stt.iniciar(txt => agregarNota(txt))}
            disabled={stt.transcribiendo}
            className={`h-11 w-11 shrink-0 rounded-full flex items-center justify-center text-white shadow transition active:scale-95 disabled:opacity-50 ${
              stt.grabando ? "bg-red-500 animate-pulse" : "bg-gray-200 text-gray-600 hover:bg-gray-300 dark:bg-gray-700 dark:text-white dark:hover:bg-gray-600"
            }`}>
            {stt.grabando
              ? <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="6" width="12" height="12" rx="2"/></svg>
              : <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor"><path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/><path d="M19 10v2a7 7 0 01-14 0v-2M12 19v4M8 23h8"/></svg>
            }
          </button>
        )}
      </div>
      {(stt.grabando || stt.transcribiendo) && (
        <p className="text-center text-xs text-accent px-4 pb-1">
          {stt.grabando ? `🎙️ Grabando… ${stt.segundos}s` : "✨ Transcribiendo…"}
        </p>
      )}
      </div>
    </div>
    </>
  );
}

// ── AgenteMandoView ───────────────────────────────────────────────────────────

type AgenteBurbuja = {
  id: number;
  rol: "agente" | "usuario";
  texto: string;
  chips?: AgentChip[];
};

type AgentChip = {
  label: string;
  subtitulo?: string;
  tipo?: "solicitud_aprobar" | "solicitud_asignada" | "accion_activa" | "util" | "solicitud_esperando" | "colaboracion" | "recordatorio" | "labor_tablero" | "pendiente";
  cmd?: string;
  datos?: Record<string, unknown>;
  onTap?: () => void;
};

function AgenteMandoView({
  token, user, modoInicio = false, embedido = false, chatExpanded = true,
  onToggleChatExpanded, onExpandChat, onSalir, onAbrirMenu, onIrInicio,
  onGoSolicitudes, onGoAcciones, onGoTablero, onGoHistorialAcciones, onGoImpresora,
  onGoRecordatorios, onGoTableroLabores, onGoPendientes, clearSubViewKey = 0,
  isMobile = false,
}: {
  token: string;
  user: TicketsUser;
  /** Pantalla principal de la app: solo chat, sin panel de accesos. */
  modoInicio?: boolean;
  /** Chat anclado al pie del Agenda (no pantalla completa). */
  embedido?: boolean;
  chatExpanded?: boolean;
  onToggleChatExpanded?: () => void;
  onExpandChat?: () => void;
  onSalir: () => void;
  onAbrirMenu?: () => void;
  /** Volver a Hugo (pantalla principal de la app). */
  onIrInicio: () => void;
  onGoSolicitudes: () => void;
  onGoAcciones: () => void;
  onGoTablero: () => void;
  onGoHistorialAcciones: () => void;
  onGoImpresora?: () => void;
  onGoRecordatorios?: () => void;
  onGoTableroLabores?: () => void;
  onGoPendientes?: () => void;
  /** Incrementar este valor desde el padre limpia las sub-vistas activas (revisar, resolver, ejecución). */
  clearSubViewKey?: number;
  /** En móvil full-screen: ajusta el header y comportamiento del botón de acción. */
  isMobile?: boolean;
}) {
  const { apiToken: chatApiToken } = useTicketsAuth();
  const verImpresora = puedeVerSeccionPanel(user, "etiquetas");
  const stt = useStt(token, chatApiToken);
  const nombre = user.nombre.split(" ")[0];

  const [burbujas, setBurbujas] = useState<AgenteBurbuja[]>([]);
  const [protocolos, setProtocolos] = useState<{ id: number; titulo: string; pasos?: any[]; lista_compras?: any[] }[]>([]);
  const [accionActual, setAccionActual] = useState<{
    id: number; titulo: string; pasos: any[];
    pasos_total: number; pasos_completados: number;
  } | null>(null);
  const [solicitudResolviendo, setSolicitudResolviendo] = useState<{
    id: number; titulo: string; numero: string; creado_por_nombre: string;
  } | null>(null);
  const [solicitudesPorAprobar, setSolicitudesPorAprobar] = useState<{
    id: number; titulo: string; numero: string; asignado_a_nombre: string;
  }[]>([]);
  const [confirmandoSolicitud, setConfirmandoSolicitud] = useState<{
    id: number; titulo: string; asignado_a_nombre: string;
  } | null>(null);
  const [revisionSolicitud, setRevisionSolicitud] = useState<{
    id: number; titulo: string; numero: string; asignado_a_nombre: string;
  } | null>(null);
  const [modoEjecucion, setModoEjecucion] = useState<{ id: number; titulo: string } | null>(null);
  const [esperandoTituloAccion, setEsperandoTituloAccion] = useState(false);
  const hugoAccionBoot = useAppStore((s) => s.hugoAccionBoot);
  const setHugoAccionBoot = useAppStore((s) => s.setHugoAccionBoot);

  // «Continuar donde quedé» (Acciones) deja hugoAccionBoot y navega aquí
  useEffect(() => {
    if (!hugoAccionBoot?.id) return;
    const boot = { id: hugoAccionBoot.id, titulo: hugoAccionBoot.titulo || "" };
    setHugoAccionBoot(null);
    localStorage.setItem("mckenna-accion-activa", JSON.stringify(boot));
    setModoEjecucion(boot);
  }, [hugoAccionBoot, setHugoAccionBoot]);

  // Limpiar clave legacy al montar — evita que una sesión anterior abra la acción automáticamente
  // (salvo handoff fresco de Continuar, que ya consumió hugoAccionBoot arriba)
  useEffect(() => {
    if (useAppStore.getState().hugoAccionBoot?.id) return;
    localStorage.removeItem("mckenna-accion-activa");
  }, []);

  // Limpiar sub-vistas cuando el padre incrementa clearSubViewKey (botón "Agenda" en móvil)
  useEffect(() => {
    if (!clearSubViewKey) return;
    setSolicitudResolviendo(null);
    setRevisionSolicitud(null);
    setModoEjecucion(null);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [clearSubViewKey]);

  // Descartar acción guardada en localStorage si ya fue resuelta/rechazada o no es del usuario
  useEffect(() => {
    if (!modoEjecucion) return;
    let cancelled = false;
    void (async () => {
      try {
        const det = await tapi(`/${modoEjecucion.id}`, token) as Ticket;
        if (cancelled) return;
        const norm = normalizeTicketForList(det);
        const estadoActivo = norm.estado === "en_proceso" || norm.estado === "pendiente";
        if (!estadoActivo || !uidEq(norm.asignado_a, user.id)) {
          localStorage.removeItem("mckenna-accion-activa");
          setModoEjecucion(null);
        }
      } catch {
        // Error de red: conservar modoEjecucion para no bloquear al usuario
      }
    })();
    return () => { cancelled = true; };
  }, [modoEjecucion?.id, token, user.id]);

  const [solicitudesCount, setSolicitudesCount] = useState(0);
  const [accionesCount, setAccionesCount] = useState(0);
  const [pensando, setPensando] = useState(false);
  const [input, setInput] = useState("");
  const [ttsPlaying, setTtsPlaying] = useState<number | null>(null);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  useLayoutEffect(() => {
    const el = inputRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 128)}px`;
  }, [input]);
  const burbulaIdRef = useRef(0);
  const autoPlayedRef = useRef(false);

  function nextId() { return ++burbulaIdRef.current; }

  function agregarBurbuja(rol: "agente" | "usuario", texto: string, chips?: AgentChip[]) {
    setBurbujas(prev => [...prev, { id: nextId(), rol, texto, chips }]);
  }

  /** Reemplaza el historial por un único mensaje del agente (chat limpio). */
  function establecerBurbujaAgente(texto: string, chips?: AgentChip[]) {
    setBurbujas([{ id: nextId(), rol: "agente", texto, chips }]);
  }

  function truncarTituloChip(t: string, max = 28) {
    const s = t.trim();
    return s.length > max ? `${s.slice(0, max - 1)}…` : s;
  }

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [burbujas, pensando]);

  // Auto-reproducir el saludo al abrir el dashboard, máximo una vez cada 6 horas
  useEffect(() => {
    if (autoPlayedRef.current || pensando) return;
    const primerAgente = burbujas.find(b => b.rol === "agente");
    if (!primerAgente) return;
    autoPlayedRef.current = true;
    const SEIS_HORAS = 6 * 60 * 60 * 1000;
    const KEY = "mckenna-hugo-tts-ultimo";
    const ultimo = parseInt(localStorage.getItem(KEY) ?? "0");
    if (Date.now() - ultimo < SEIS_HORAS) return;
    localStorage.setItem(KEY, String(Date.now()));
    const ttsToken = chatApiToken ?? token;
    if (!ttsToken) return;
    hablarHugoTts(ttsToken, primerAgente.texto).catch(() => {});
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [burbujas, pensando]);

  // Cargar contexto inicial
  useEffect(() => {
    void cargarContextoInicial();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  async function aplicarContextoAgente(
    res: {
      respuesta?: string;
      contexto?: {
        protocolos?: { id: number; titulo: string }[];
        acciones_activas?: any[];
        solicitudes_asignadas?: any[];
        solicitudes_por_aprobar?: any[];
        solicitudes_esperando_confirmacion?: any[];
        solicitudes_creadas_activas?: any[];
        colaboraciones?: any[];
        recordatorios_hoy?: { id: number; titulo: string; proxima_fecha?: string }[];
        pendientes?: { id: number; titulo: string; fecha_recordatorio?: string | null }[];
        labores_tablero?: { id: number; titulo: string; mision_titulo?: string; pasos_total?: number; pasos_completados?: number }[];
      };
    },
    opts?: { trasActividad?: boolean },
  ) {
    const prots: { id: number; titulo: string }[] = res.contexto?.protocolos ?? [];
    const accActivas: any[] = res.contexto?.acciones_activas ?? [];
    const solAsignadas: any[] = res.contexto?.solicitudes_asignadas ?? [];
    const solPorAprobar: any[] = res.contexto?.solicitudes_por_aprobar ?? [];
    const solEsperando: any[] = res.contexto?.solicitudes_esperando_confirmacion ?? [];
    const solCreadasActivas: any[] = res.contexto?.solicitudes_creadas_activas ?? [];
    const colabs: any[] = res.contexto?.colaboraciones ?? [];
    const recordatoriosHoy = res.contexto?.recordatorios_hoy ?? [];
    const pendientes = res.contexto?.pendientes ?? [];
    const laboresTablero = res.contexto?.labores_tablero ?? [];
    setProtocolos(prots);
    setSolicitudesCount(solAsignadas.length);
    setAccionesCount(accActivas.length);
    setSolicitudesPorAprobar(solPorAprobar);

    if (modoEjecucion && !accActivas.some((a: { id: number }) => a.id === modoEjecucion.id)) {
      localStorage.removeItem("mckenna-accion-activa");
      setModoEjecucion(null);
    }

    const { texto: textoLocal, chips } = construirMensajeContexto(
      solAsignadas, accActivas, solPorAprobar, solEsperando, solCreadasActivas, colabs,
      recordatoriosHoy, pendientes, laboresTablero, opts,
    );
    const texto = opts?.trasActividad
      ? textoLocal
      : (res.respuesta?.trim() || textoLocal);
    establecerBurbujaAgente(texto, chips);
  }

  async function cargarContextoInicial() {
    setPensando(true);
    try {
      const res = await tapi("/agente-chat", token, {
        method: "POST",
        body: JSON.stringify({ mensaje: "", historial: [] }),
      });
      await aplicarContextoAgente(res);
    } catch {
      establecerBurbujaAgente(`¡Hola ${nombre}! ¿Qué va a hacer hoy? Cuénteme y lo registramos.`, [
        { label: "⚡ Registrar acción", onTap: mostrarProcedimientos },
        { label: "📋 Crear solicitud", onTap: onGoSolicitudes },
      ]);
    } finally {
      setPensando(false);
    }
  }

  async function reiniciarTrasActividad() {
    setPensando(true);
    setConfirmandoSolicitud(null);
    try {
      const res = await tapi("/agente-chat", token, {
        method: "POST",
        body: JSON.stringify({ mensaje: "", historial: [] }),
      });
      await aplicarContextoAgente(res, { trasActividad: true });
    } catch {
      establecerBurbujaAgente("¡Listo! ¿Con qué labor sigue?", [
        { label: "⚡ Registrar acción", onTap: mostrarProcedimientos },
        { label: "📋 Crear solicitud", onTap: onGoSolicitudes },
      ]);
    } finally {
      setPensando(false);
    }
  }

  function buildMainChips(_prots: { id: number; titulo: string }[], accActivas: any[]): AgentChip[] {
    const chips: AgentChip[] = [];
    if (accActivas.length > 0) {
      chips.push({ tipo: "util", label: `📊 Ver mis ${accActivas.length} activa${accActivas.length > 1 ? "s" : ""}`, onTap: mostrarActivas });
    }
    chips.push({ tipo: "util", label: "⚡ Registrar acción", onTap: mostrarProcedimientos });
    chips.push({ tipo: "util", label: "📋 Crear solicitud", onTap: onGoSolicitudes });
    return chips;
  }

  /** Un solo mensaje de saludo / post-actividad + chips unificados (sin burbujas apiladas). */
  function construirMensajeContexto(
    solAsignadas: any[],
    accActivas: any[],
    solPorAprobar: any[],
    solEsperando: any[],
    solCreadasActivas: any[],
    colabs: any[],
    recordatoriosHoy: { id: number; titulo: string }[],
    pendientes: { id: number; titulo: string; fecha_recordatorio?: string | null }[],
    laboresTablero: { id: number; titulo: string; mision_titulo?: string; pasos_total?: number; pasos_completados?: number }[],
    opts?: { trasActividad?: boolean },
  ): { texto: string; chips: AgentChip[] } {
    const chips: AgentChip[] = [];
    const hoy = new Date().toISOString().slice(0, 10);

    // Recordatorios vencidos o para hoy
    for (const r of recordatoriosHoy.slice(0, 3)) {
      chips.push({
        tipo: "recordatorio",
        label: `🔔 ${truncarTituloChip(r.titulo)}`,
        onTap: onGoRecordatorios,
      });
    }

    // Labores del tablero asignadas al usuario
    for (const l of laboresTablero.slice(0, 3)) {
      const prog = l.pasos_total
        ? `${l.pasos_completados ?? 0}/${l.pasos_total} pasos`
        : undefined;
      chips.push({
        tipo: "labor_tablero",
        label: `🎯 ${truncarTituloChip(l.titulo)}`,
        subtitulo: l.mision_titulo ? `${l.mision_titulo}${prog ? ` · ${prog}` : ""}` : prog,
        onTap: onGoAcciones,
      });
    }

    // Pendientes anotados (acciones futuras)
    const pendientesHoy = pendientes.filter(
      (p) => p.fecha_recordatorio && String(p.fecha_recordatorio).slice(0, 10) <= hoy,
    );
    for (const p of pendientesHoy.slice(0, 2)) {
      chips.push({
        tipo: "pendiente",
        label: `🗓️ ${truncarTituloChip(p.titulo)}`,
        subtitulo: "Pendiente para hoy",
        onTap: onGoPendientes,
      });
    }

    // Solicitudes que esperan mi aprobación (las creé yo, estado esperando_aprobacion)
    for (const s of solPorAprobar.slice(0, 3)) {
      chips.push({
        tipo: "solicitud_aprobar",
        label: `🔔 ${truncarTituloChip(s.titulo)}`,
        subtitulo: s.asignado_a_nombre,
        onTap: () => {
          setRevisionSolicitud({ id: s.id, titulo: s.titulo, numero: s.numero, asignado_a_nombre: s.asignado_a_nombre });
        },
      });
    }

    // Solicitudes que yo creé y siguen activas (en_proceso / pendiente — ejecutor trabajando)
    for (const s of solCreadasActivas.slice(0, 3)) {
      chips.push({
        tipo: "solicitud_esperando",
        label: `🔄 ${truncarTituloChip(s.titulo)}`,
        subtitulo: s.asignado_a_nombre ? `En proceso: ${s.asignado_a_nombre}` : "En proceso",
        onTap: onGoSolicitudes,
      });
    }

    // Solicitudes asignadas a mí que debo atender
    for (const s of solAsignadas.slice(0, 3)) {
      chips.push({
        tipo: "solicitud_asignada",
        label: `📝 ${truncarTituloChip(s.titulo)}`,
        subtitulo: s.creado_por_nombre,
        onTap: () => setSolicitudResolviendo({
          id: s.id, titulo: s.titulo, numero: s.numero, creado_por_nombre: s.creado_por_nombre,
        }),
      });
    }

    // Solicitudes que yo ejecuté y están esperando que el solicitante confirme
    for (const s of solEsperando.slice(0, 3)) {
      chips.push({
        tipo: "solicitud_esperando",
        label: `⏳ ${truncarTituloChip(s.titulo)}`,
        subtitulo: s.creado_por_nombre,
      });
    }

    // Tickets en los que fui invitado a colaborar
    for (const c of colabs.slice(0, 3)) {
      chips.push({
        tipo: "colaboracion",
        label: `👥 ${truncarTituloChip(c.titulo)}`,
        subtitulo: c.asignado_a_nombre ? `Ejecuta: ${c.asignado_a_nombre}` : c.creado_por_nombre,
        onTap: () => setSolicitudResolviendo({
          id: c.id, titulo: c.titulo, numero: c.numero, creado_por_nombre: c.creado_por_nombre,
        }),
      });
    }

    // Acciones activas en curso
    for (const a of accActivas.slice(0, 3)) {
      chips.push({
        tipo: "accion_activa",
        label: `⚡ ${truncarTituloChip(a.titulo)}`,
        onTap: () => void continuarAccion(a),
      });
    }
    chips.push({ tipo: "util", label: "⚡ Registrar acción", onTap: mostrarProcedimientos });
    chips.push({ tipo: "util", label: "📋 Crear solicitud", onTap: onGoSolicitudes });

    if (opts?.trasActividad) {
      const preguntas: string[] = [];
      if (recordatoriosHoy.length > 0) {
        preguntas.push(
          recordatoriosHoy.length === 1
            ? `¿Ya atendió «${recordatoriosHoy[0].titulo}»?`
            : `¿Le quedan ${recordatoriosHoy.length} recordatorios por hoy?`,
        );
      }
      if (solAsignadas.length > 0 && preguntas.length < 2) {
        preguntas.push(
          solAsignadas.length === 1
            ? `¿Sigue con la solicitud «${solAsignadas[0].titulo}»?`
            : `¿Atiende alguna de las ${solAsignadas.length} solicitudes pendientes?`,
        );
      }
      if (accActivas.length > 0 && preguntas.length < 2) {
        preguntas.push("¿Retoma una acción en curso o registra otra?");
      }
      const seguimiento = preguntas.length > 0
        ? preguntas.join(" ")
        : "¿Con qué labor sigue?";
      return { texto: `¡Listo! Actividad registrada. ${seguimiento}`, chips };
    }

    // Texto local de respaldo si el API no devuelve saludo
    const preguntas: string[] = [];
    if (recordatoriosHoy.length > 0) {
      preguntas.push(
        recordatoriosHoy.length === 1
          ? `¿Ya atendió el recordatorio «${recordatoriosHoy[0].titulo}»?`
          : `¿Por cuál recordatorio empezamos? (${recordatoriosHoy.length} para hoy)`,
      );
    }
    if (laboresTablero.length > 0 && preguntas.length < 2) {
      preguntas.push(`¿Avanzó con «${laboresTablero[0].titulo}» en el tablero?`);
    }
    if (solAsignadas.length > 0 && preguntas.length < 2) {
      preguntas.push(
        solAsignadas.length === 1
          ? `¿Atendió la solicitud «${solAsignadas[0].titulo}»?`
          : `¿Con cuál solicitud arranca? (${solAsignadas.length} le esperan)`,
      );
    }
    if (accActivas.length > 0 && preguntas.length < 2) {
      preguntas.push(
        accActivas.length === 1
          ? `¿Sigue con «${accActivas[0].titulo}» o registra otra acción?`
          : "¿Retoma alguna acción en curso o empieza una nueva?",
      );
    }
    if (pendientesHoy.length > 0 && preguntas.length < 2) {
      preguntas.push("¿Convierte en acción algún pendiente anotado para hoy?");
    }
    if (solPorAprobar.length > 0 && preguntas.length < 2) {
      preguntas.push("¿Revisa las solicitudes que esperan su confirmación?");
    }

    let texto = `¡Hola ${nombre}!`;
    if (preguntas.length > 0) {
      texto += ` ${preguntas.slice(0, 2).join(" ")}`;
    } else {
      const totalPendiente = accActivas.length + solAsignadas.length + solPorAprobar.length
        + solCreadasActivas.length + laboresTablero.length;
      texto += totalPendiente === 0
        ? " ¿Qué va a hacer hoy? Cuénteme y lo registramos."
        : " ¿En qué labor del día le ayudo?";
    }
    return { texto, chips };
  }

  function mostrarProcedimientos(_procsOverride?: typeof protocolos) {
    agregarBurbuja("agente", "¿Es algo nuevo o algo que ya ha hecho antes?", [
      { label: "🆕 Acción nueva",       onTap: pedirTituloLibre },
      { label: "🔄 Acción recurrente",  onTap: mostrarListaProcedimientos },
    ]);
  }

  function mostrarListaProcedimientos() {
    const prots = protocolos;
    if (prots.length === 0) {
      agregarBurbuja("agente", "No tiene procedimientos guardados por ahora. ¿Cómo se llama la acción?");
      inputRef.current?.focus();
      return;
    }
    const chips: AgentChip[] = prots.slice(0, 6).map(p => ({
      label: p.titulo,
      cmd: "crear_accion",
      datos: { protocolo_id: p.id, titulo: p.titulo, lista_compras: p.lista_compras ?? [] },
    }));
    agregarBurbuja("agente", "Elegí el que corresponde:", chips);
  }

  function pedirTituloLibre() {
    setEsperandoTituloAccion(true);
    agregarBurbuja("agente", "¿Cómo se llama la acción?");
    inputRef.current?.focus();
  }

  function mostrarActivas() {
    agregarBurbuja("agente", "Acá están sus acciones en curso. Tóquele a una para continuar.");
  }

  async function continuarAccion(a: any) {
    setPensando(true);
    try {
      localStorage.setItem("mckenna-accion-activa", JSON.stringify({ id: a.id, titulo: a.titulo }));
      setModoEjecucion({ id: a.id, titulo: a.titulo });
    } catch {
      localStorage.setItem("mckenna-accion-activa", JSON.stringify({ id: a.id, titulo: a.titulo }));
      setModoEjecucion({ id: a.id, titulo: a.titulo });
    } finally {
      setPensando(false);
    }
  }

  async function cargarPasosAccion(id: number, titulo: string) {
    setPensando(true);
    try {
      const t = await tapi(`/${id}`, token) as any;
      const pasosRaw: any[] = t.pasos ?? [];
      // normalizar: usar descripcion como campo principal
      const pasos = pasosRaw.map((p: any) => ({
        ...p,
        descripcion: (p.descripcion || p.nombre || "").trim(),
      })).filter((p: any) => p.descripcion);
      const completados = pasos.filter((p: any) => p.completado).length;
      const total = pasos.length;
      setAccionActual({ id, titulo, pasos, pasos_total: total, pasos_completados: completados });

      if (total === 0) {
        agregarBurbuja("agente", `"${titulo}" lista para trabajar. Dígame cuando termine.`, [
          { label: "🏁 Cerrar acción", onTap: () => pedirCierre(id) },
        ]);
        return;
      }

      const pendientes = pasos.filter((p: any) => !p.completado);
      if (pendientes.length === 0) {
        agregarBurbuja("agente", `¡Todos los pasos listos! ¿Cerramos "${titulo}"?`, [
          { label: "🏁 Sí, cerrar", onTap: () => pedirCierre(id) },
        ]);
        return;
      }

      mostrarPasoActual(id, titulo, pasos, completados, total);
    } catch {
      agregarBurbuja("agente", "No pude cargar los pasos. Intenta de nuevo.");
    } finally {
      setPensando(false);
    }
  }

  function mostrarPasoActual(ticketId: number, titulo: string, pasos: any[], completados: number, total: number) {
    const pendientes = pasos.filter((p: any) => !p.completado);
    if (pendientes.length === 0) {
      agregarBurbuja("agente", `¡Todos los pasos de "${titulo}" listos!`, [
        { label: "🏁 Cerrar acción", onTap: () => pedirCierre(ticketId) },
      ]);
      return;
    }
    const sig = pendientes[0];
    const notas = (sig.notas || "").trim();
    const msgPaso = `Paso ${completados + 1}/${total}: ${sig.descripcion}${notas ? `\n📝 ${notas}` : ""}`;
    agregarBurbuja(
      "agente",
      msgPaso,
      [
        { label: `✓ Listo`, cmd: "marcar_paso", datos: { ticket_id: ticketId, paso_id: sig.id } },
        { label: "🏁 Cerrar acción", onTap: () => pedirCierre(ticketId) },
      ],
    );
  }

  function pedirCierre(id: number) {
    agregarBurbuja("agente", "¿Quiere dejar un reporte de cierre? (opcional, puede omitir)");
    setAccionActual(prev => prev ? { ...prev, id } : prev);
    inputRef.current?.focus();
  }

  async function enviar(texto: string, cmd?: string, datos?: Record<string, unknown>) {
    if (pensando || (!texto.trim() && !cmd)) return;
    if (embedido && !chatExpanded) onExpandChat?.();

    // Interceptar cuando el bot esperaba el nombre de la acción
    if (esperandoTituloAccion && texto.trim() && !cmd) {
      setEsperandoTituloAccion(false);
      cmd = "crear_accion";
      datos = { titulo: texto.trim() };
    }

    if (texto.trim()) agregarBurbuja("usuario", texto.trim());
    setInput("");
    setPensando(true);

    try {
      const historialEnvio = burbujas.slice(-10).map(b => ({ rol: b.rol, texto: b.texto }));
      const res = await tapi("/agente-chat", token, {
        method: "POST",
        body: JSON.stringify({
          mensaje: texto.trim(),
          historial: historialEnvio,
          accion_cmd: cmd ?? null,
          accion_datos: datos ?? null,
        }),
      });

      const protsActualizados = res.contexto?.protocolos ?? protocolos;
      if (res.contexto?.protocolos) setProtocolos(res.contexto.protocolos);
      const accActivas: any[] = res.contexto?.acciones_activas ?? [];
      if (res.contexto?.solicitudes_por_aprobar) setSolicitudesPorAprobar(res.contexto.solicitudes_por_aprobar);

      // ── Comando ejecutado ────────────────────────────────────────────────────
      const resultado = res.accion_resultado as any;
      if (resultado && !resultado.error) {

        if (cmd === "crear_accion" && resultado.ticket_id) {
          const titulo = resultado.titulo ?? texto;
          // Guardar en localStorage para persistencia
          localStorage.setItem("mckenna-accion-activa", JSON.stringify({ id: resultado.ticket_id, titulo }));
          // Entrar directamente al modo de ejecución libre
          setModoEjecucion({ id: resultado.ticket_id, titulo });
          return;
        }

        if (cmd === "marcar_paso") {
          const pasosAct: any[] = (resultado.pasos ?? []).map((p: any) => ({
            ...p,
            descripcion: (p.descripcion || p.nombre || "").trim(),
          })).filter((p: any) => p.descripcion);
          const total = resultado.pasos_total ?? pasosAct.length;
          const completados = resultado.pasos_completados ?? 0;
          setAccionActual(prev => prev ? { ...prev, pasos: pasosAct, pasos_total: total, pasos_completados: completados } : prev);
          const ticketId = datos?.ticket_id as number;
          const tituloActual = accionActual?.titulo ?? "";
          mostrarPasoActual(ticketId, tituloActual, pasosAct, completados, total);
          return;
        }

        if (cmd === "completar_accion") {
          setAccionActual(null);
          void reiniciarTrasActividad();
          return;
        }

        if (cmd === "crear_solicitud") {
          agregarBurbuja("agente", res.respuesta, [
            { label: "📋 Ver mis solicitudes", onTap: onGoSolicitudes },
            { label: "🏠 Inicio", onTap: onIrInicio },
          ]);
          return;
        }
      }

      // ── Comandos de aprobación/rechazo de solicitudes (manejados localmente) ──
      if (cmd === "aprobar_solicitud") {
        const sid = datos?.id as number;
        const stitulo = datos?.titulo as string;
        setPensando(true);
        try {
          await tapi(`/${sid}/estado`, token, {
            method: "PUT",
            body: JSON.stringify({ estado: "resuelto" }),
          });
          setConfirmandoSolicitud(null);
          setSolicitudesPorAprobar(prev => prev.filter(s => s.id !== sid));
          agregarBurbuja("agente", `✅ Solicitud "${stitulo}" cerrada correctamente.`);
          void reiniciarTrasActividad();
        } catch {
          agregarBurbuja("agente", "No pude cerrar la solicitud. Intentá desde Agenda.");
        } finally {
          setPensando(false);
        }
        return;
      }

      if (cmd === "rechazar_solicitud") {
        const sid = datos?.id as number;
        const stitulo = datos?.titulo as string;
        setPensando(true);
        try {
          await tapi(`/${sid}/estado`, token, {
            method: "PUT",
            body: JSON.stringify({ estado: "en_proceso" }),
          });
          setConfirmandoSolicitud(null);
          setSolicitudesPorAprobar(prev => prev.filter(s => s.id !== sid));
          agregarBurbuja("agente", `↩️ Solicitud "${stitulo}" devuelta. ${datos?.asignado_a_nombre ? `Le avisaré a ${String(datos.asignado_a_nombre)} que necesita ajustes.` : "Quedó de nuevo en proceso."}`);
          void reiniciarTrasActividad();
        } catch {
          agregarBurbuja("agente", "No pude actualizar la solicitud. Intentá desde Agenda.");
        } finally {
          setPensando(false);
        }
        return;
      }

      if (resultado?.error) {
        agregarBurbuja("agente", `No pude hacerlo: ${resultado.error}`, buildMainChips(protsActualizados, accActivas));
        return;
      }

      // ── Texto libre: detectar intención ──────────────────────────────────────
      const procsRel: any[] = res.procs_relevantes ?? [];
      const esIntent: boolean = res.es_intent ?? false;
      const solCtx = res.solicitud_ctx ?? {};

      // Mostrar respuesta del LLM (o fallback del servidor)
      if (res.respuesta) agregarBurbuja("agente", res.respuesta);

      if (solCtx.es_solicitud) {
        // ── SOLICITUD A OTRA PERSONA ────────────────────────────────────────
        const u = solCtx.usuario as { id: number; nombre: string } | null;
        const tituloSol: string = solCtx.titulo_sugerido ?? texto.trim();
        if (u && tituloSol) {
          // Tenemos persona + título → ofrecer crear directamente
          agregarBurbuja("agente", `¿Creo la solicitud para ${u.nombre}?`, [
            {
              label: `📋 Sí, crear solicitud`,
              cmd: "crear_solicitud",
              datos: { titulo: tituloSol, asignado_a: u.id, asignado_a_nombre: u.nombre },
            },
            { label: "✏️ Cambiar texto", onTap: () => inputRef.current?.focus() },
          ]);
        } else if (u && !tituloSol) {
          // Tenemos persona pero no título → el bot ya preguntó, no agregar más chips
        } else if (!u && solCtx.persona_nombre) {
          // Persona no encontrada → ya el servidor respondió el error, sin chips extra
        }
        // Si es solicitud genérica sin persona, el servidor ya preguntó
      } else if (procsRel.length > 0 || esIntent) {
        // Intención de acción detectada → pregunta simple, sin listar procedimientos
        agregarBurbuja("agente", "¿La registramos?", [
          { label: "🆕 Acción nueva",      cmd: "crear_accion", datos: { titulo: texto.trim() } },
          { label: "🔄 Acción recurrente", onTap: mostrarListaProcedimientos },
        ]);
      } else {
        // Respuesta genérica: pegar chips contextuales a la última burbuja del agente
        const chips = buildChipsContextuales(accActivas);
        if (chips.length > 0) setBurbujas(prev => {
          const last = prev[prev.length - 1];
          if (last?.rol === "agente" && !last.chips) {
            return [...prev.slice(0, -1), { ...last, chips }];
          }
          return prev;
        });
      }
    } catch {
      agregarBurbuja("agente", "Sin conexión con el servidor. Intenta de nuevo.", [
        { label: "🔄 Reintentar", onTap: () => void enviar(texto, cmd, datos) },
      ]);
    } finally {
      setPensando(false);
    }
  }

  function buildChipsContextuales(accActivas: any[]): AgentChip[] {
    if (accionActual) {
      const pendientes = accionActual.pasos.filter((p: any) => !p.completado);
      if (pendientes.length > 0) {
        return [
          { label: "✓ Listo el paso", cmd: "marcar_paso", datos: { ticket_id: accionActual.id, paso_id: pendientes[0].id } },
          { label: "🏁 Cerrar acción", onTap: () => pedirCierre(accionActual.id) },
        ];
      }
      return [{ label: "🏁 Cerrar acción", onTap: () => pedirCierre(accionActual.id) }];
    }
    return buildMainChips(protocolos, accActivas);
  }

  async function hablar(texto: string, burbulaId: number) {
    if (ttsPlaying === burbulaId) {
      window.speechSynthesis?.cancel();
      setTtsPlaying(null);
      return;
    }
    const ttsToken = chatApiToken ?? token;
    if (!ttsToken) return;
    setTtsPlaying(burbulaId);
    try {
      await hablarHugoTts(ttsToken, texto);
    } finally {
      setTtsPlaying(null);
    }
  }

  function onChipTap(chip: AgentChip) {
    if (chip.onTap) { chip.onTap(); return; }
    if (chip.cmd) {
      void enviar(chip.label, chip.cmd, chip.datos as Record<string, unknown>);
    } else {
      void enviar(chip.label);
    }
  }

  const lastChips = burbujas.length > 0 ? burbujas[burbujas.length - 1].chips : undefined;
  const ultimaBurbujaAgenteId = useMemo(() => {
    for (let i = burbujas.length - 1; i >= 0; i--) {
      if (burbujas[i].rol === "agente") return burbujas[i].id;
    }
    return null;
  }, [burbujas]);
  const ultimaBurbujaAgente = useMemo(() => {
    for (let i = burbujas.length - 1; i >= 0; i--) {
      if (burbujas[i].rol === "agente") return burbujas[i];
    }
    return null;
  }, [burbujas]);
  const previewAgente = ultimaBurbujaAgente?.texto ?? "¿Qué hacemos hoy, veci?";
  const dockExpandido = !embedido || chatExpanded;

  // ── Modo revisión de solicitud para confirmar ────────────────────────────────
  if (revisionSolicitud) {
    return (
      <RevisionSolicitudView
        token={token}
        solicitud={revisionSolicitud}
        onVolver={() => setRevisionSolicitud(null)}
        onConfirmar={async () => {
          setPensando(true);
          try {
            await tapi(`/${revisionSolicitud.id}/estado`, token, {
              method: "PUT",
              body: JSON.stringify({ estado: "resuelto" }),
            });
            setRevisionSolicitud(null);
            setConfirmandoSolicitud(null);
            setSolicitudesPorAprobar(prev => prev.filter(s => s.id !== revisionSolicitud.id));
            void reiniciarTrasActividad();
          } catch {
            agregarBurbuja("agente", "No pude cerrar la solicitud. Intentá desde Agenda.");
            setRevisionSolicitud(null);
          } finally { setPensando(false); }
        }}
        onPedirAjustes={async (motivo) => {
          setPensando(true);
          try {
            await tapi(`/${revisionSolicitud.id}/estado`, token, {
              method: "PUT",
              body: JSON.stringify({ estado: "en_proceso" }),
            });
            if (motivo.trim()) {
              await fetch(`/api/tickets/${revisionSolicitud.id}/comentarios`, {
                method: "POST",
                headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
                body: JSON.stringify({ texto: `↩️ Ajustes solicitados: ${motivo.trim()}` }),
              });
            }
            setRevisionSolicitud(null);
            setConfirmandoSolicitud(null);
            setSolicitudesPorAprobar(prev => prev.filter(s => s.id !== revisionSolicitud.id));
            void reiniciarTrasActividad();
          } catch {
            agregarBurbuja("agente", "No pude actualizar la solicitud. Intentá desde Agenda.");
            setRevisionSolicitud(null);
          } finally { setPensando(false); }
        }}
      />
    );
  }

  // ── Modo ejecución de acción propia ─────────────────────────────────────────
  if (modoEjecucion) {
    return (
      <EjecucionAccionChat
        token={token}
        accion={modoEjecucion}
        stt={stt}
        chatApiToken={chatApiToken}
        onVolver={() => setModoEjecucion(null)}
        onTerminado={() => {
          setModoEjecucion(null);
          void reiniciarTrasActividad();
        }}
      />
    );
  }

  // ── Modo resolver solicitud ──────────────────────────────────────────────────
  if (solicitudResolviendo) {
    return (
      <ResolverActividadChat
        token={token}
        solicitud={solicitudResolviendo}
        stt={stt}
        chatApiToken={chatApiToken}
        onVolver={() => setSolicitudResolviendo(null)}
        onTerminado={() => {
          setSolicitudResolviendo(null);
          void reiniciarTrasActividad();
        }}
      />
    );
  }

  if (embedido && !dockExpandido) {
    const hayActividad = solicitudesCount > 0 || !!accionActual || solicitudesPorAprobar.length > 0;
    return (
      <button
        type="button"
        onClick={() => onExpandChat?.()}
        className="hugo-dock-fab group"
        aria-label="Iniciar conversación con Hugo García"
        title="Hablar con Hugo García"
      >
        <span className="flex h-14 w-14 items-center justify-center rounded-full bg-accent text-xl font-black text-white shadow-[0_4px_14px_rgba(12,96,105,0.45)] transition group-hover:scale-105 group-active:scale-95">
          H
        </span>
        {hayActividad && (
          <span className="absolute -right-0.5 -top-0.5 flex h-5 min-w-5 items-center justify-center rounded-full border-2 border-surface-panel bg-accent/50 px-1 text-[10px] font-extrabold text-white">
            {solicitudesCount > 0 ? solicitudesCount : "!"}
          </span>
        )}
        <span className="pointer-events-none absolute bottom-full right-0 mb-2 hidden whitespace-nowrap rounded-xl border-2 border-border bg-surface-panel px-3 py-1.5 text-xs font-extrabold text-ink shadow-paper-md sm:group-hover:block">
          Hugo García
        </span>
      </button>
    );
  }

  return (
    <div
      className={`hugo-chat flex flex-col min-h-0 overflow-hidden bg-surface font-sans antialiased text-ink ${
        embedido ? "hugo-dock-panel" : "h-full"
      }`}
    >

      {/* ── Header ───────────────────────────────────────────────────────────── */}
      {embedido ? (
        <div className="flex shrink-0 items-center gap-3 border-b border-border/60 bg-surface-panel px-4 py-2">
          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-accent text-xs font-black text-white">H</div>
          <p className="flex-1 text-sm font-bold text-ink leading-tight">Hugo García</p>
          {accionActual && (
            <span className="shrink-0 rounded-full border border-accent/30 bg-accent/10 px-2 py-0.5 text-[10px] font-extrabold text-accent">
              En curso
            </span>
          )}
          <div className="flex shrink-0 items-center gap-1">
            <button
              type="button"
              onClick={() => onToggleChatExpanded?.()}
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-border text-muted transition hover:border-accent hover:text-accent"
              aria-label="Minimizar chat"
              title="Minimizar"
            >
              <svg className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" aria-hidden>
                <path d="M6 9l6 6 6-6" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
            {isMobile && onAbrirMenu && (
              <button
                type="button"
                onClick={() => { onToggleChatExpanded?.(); onAbrirMenu(); }}
                className="flex h-7 w-7 items-center justify-center rounded-lg border border-border text-muted transition hover:border-accent hover:text-accent text-sm"
                aria-label="Menú"
                title="Menú"
              >
                ☰
              </button>
            )}
          </div>
        </div>
      ) : (
        <div className="flex shrink-0 items-center gap-3 border-b-2 border-border bg-surface-panel px-4 py-3 pt-safe shadow-paper-sm">
          {modoInicio ? (
            <button type="button" onClick={onAbrirMenu}
              className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl border-2 border-border bg-surface text-lg font-extrabold text-ink transition hover:bg-surface-hover"
              aria-label="Menú">☰</button>
          ) : (
            <button type="button" onClick={onSalir}
              className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl border-2 border-border bg-surface text-xl font-extrabold text-muted transition hover:bg-surface-hover hover:text-ink"
              aria-label="Volver">‹</button>
          )}
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-accent text-lg font-black text-white shadow">H</div>
          <div className="min-w-0 flex-1">
            <p className="text-lg font-extrabold leading-tight tracking-tight text-ink">Hugo García</p>
            <p className="text-sm font-bold leading-snug text-muted">
              {modoInicio ? "¿Qué hacemos hoy?" : "Asistente de Operaciones"}
            </p>
          </div>
          {modoInicio && (
            <>
              {verImpresora && onGoImpresora && (
                <button type="button" onClick={onGoImpresora}
                  className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl border-2 border-border bg-surface text-muted transition hover:border-accent hover:text-accent"
                  title="Impresora · Etiquetas"
                  aria-label="Impresora">
                  <Icon name="etiquetas" size={20} weight="regular" />
                </button>
              )}
              <button type="button" onClick={onGoTablero}
                className="shrink-0 rounded-full border border-border bg-surface px-2.5 py-1 text-xs font-extrabold text-ink transition hover:border-accent hover:text-accent"
                title="Agenda">
                🎯 Agenda
              </button>
            </>
          )}
          {accionActual && !modoInicio && (
            <span className="shrink-0 rounded-full border border-accent/30 bg-accent/10 px-2.5 py-1 text-xs font-extrabold text-accent">En curso</span>
          )}
        </div>
      )}

      {/* ── Chat (área flexible) ───────────────────────────────────────────── */}
      {dockExpandido && (
      <div className="flex-1 min-h-0 overflow-y-auto overscroll-contain bg-surface px-4 py-4 space-y-3">
        {burbujas
          .filter(b => {
            // En modo embebido (móvil full-screen), ocultar el saludo inicial cuando
            // hay chips — el listado ya describe el contexto sin necesidad del texto.
            if (embedido && modoInicio && lastChips && lastChips.length > 0) {
              const hayMensajesUsuario = burbujas.some(x => x.rol === "usuario");
              if (!hayMensajesUsuario && b.rol === "agente") return false;
            }
            return true;
          })
          .map((b) => (
          <div key={b.id} className={`flex flex-col ${b.rol === "usuario" ? "items-end" : "items-start"} gap-1.5`}>
            <div className={`hugo-bubble max-w-[90%] rounded-2xl px-4 py-3 whitespace-pre-wrap shadow-paper-sm ${
              b.rol === "usuario"
                ? "hugo-bubble--user bg-accent text-white rounded-br-md"
                : "bg-surface-panel border-2 border-border text-ink rounded-bl-md"
            }`}>
              <p>{b.texto}</p>
              {b.rol === "agente" && b.id === ultimaBurbujaAgenteId && (
                <button type="button" onClick={() => void hablar(b.texto, b.id)}
                  className={`mt-2 flex items-center gap-1.5 text-xs font-extrabold transition ${
                    ttsPlaying === b.id ? "text-accent animate-pulse" : "text-muted hover:text-ink"
                  }`}>
                  <svg className="h-4 w-4" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02z"/>
                  </svg>
                  {ttsPlaying === b.id ? "Escuchando…" : "Escuchar"}
                </button>
              )}
            </div>
          </div>
        ))}
        {lastChips && lastChips.length > 0 && !pensando && (
          <div className="rounded-xl overflow-hidden mt-2 border border-border/40 divide-y divide-border/30">
            {([] as typeof lastChips).concat(
              lastChips.filter(c => c.tipo === "accion_activa"),
              lastChips.filter(c => c.tipo === "solicitud_asignada"),
              lastChips.filter(c => c.tipo === "solicitud_aprobar"),
              lastChips.filter(c => c.tipo === "recordatorio"),
              lastChips.filter(c => c.tipo === "pendiente"),
              lastChips.filter(c => c.tipo === "colaboracion"),
              lastChips.filter(c => c.tipo === "labor_tablero"),
              lastChips.filter(c => c.tipo === "solicitud_esperando"),
              lastChips.filter(c => !c.tipo || c.tipo === "util"),
            ).map((chip, i) => {
              const meta: Record<string, { icon: string; dot: string; bg: string; label: string }> = {
                accion_activa:        { icon: "⚡", dot: "bg-accent/50",   bg: "bg-accent/70",   label: "text-accent" },
                solicitud_asignada:   { icon: "📋", dot: "bg-accent/40",   bg: "bg-accent/60",   label: "text-accent" },
                solicitud_aprobar:    { icon: "⏳", dot: "bg-accent/40",  bg: "bg-accent/60", label: "text-accent" },
                recordatorio:         { icon: "🔔", dot: "bg-accent/40", bg: "bg-accent/50", label: "text-accent" },
                pendiente:            { icon: "🗓️", dot: "bg-accent/40", bg: "bg-accent/50", label: "text-accent" },
                colaboracion:         { icon: "👥", dot: "bg-accent/30", bg: "bg-accent/50", label: "text-accent" },
                labor_tablero:        { icon: "🎯", dot: "bg-stone-400",  bg: "bg-stone-50/60 dark:bg-stone-900/20",  label: "text-stone-700 dark:text-stone-300" },
                solicitud_esperando:  { icon: "·",  dot: "bg-slate-300",  bg: "bg-slate-50/40 dark:bg-slate-900/10",  label: "text-slate-500 dark:text-slate-400" },
                util:                 { icon: "→",  dot: "bg-border",     bg: "bg-surface",                            label: "text-ink" },
              };
              const t = chip.tipo ?? "util";
              const m = meta[t] ?? meta.util;
              const clickable = t !== "solicitud_esperando";
              const Tag = clickable ? "button" : "div";
              return (
                <Tag
                  key={i}
                  {...(clickable ? { type: "button" as const, onClick: () => onChipTap(chip) } : {})}
                  className={`flex w-full items-center gap-3 px-3 py-2.5 text-left transition ${m.bg} ${clickable ? "hover:brightness-95 dark:hover:brightness-110 active:scale-[0.99] cursor-pointer" : "opacity-50 cursor-default"}`}
                >
                  <span className={`h-2 w-2 shrink-0 rounded-full ${m.dot}`} />
                  <span className="min-w-0 flex-1">
                    <span className={`block truncate text-sm font-semibold ${m.label}`}>{chip.label}</span>
                    {chip.subtitulo && (
                      <span className="block truncate text-xs text-muted/70">{chip.subtitulo}</span>
                    )}
                  </span>
                  {clickable && (
                    <svg className="h-3.5 w-3.5 shrink-0 text-muted/30" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                      <path d="M9 18l6-6-6-6"/>
                    </svg>
                  )}
                </Tag>
              );
            })}
          </div>
        )}
        {pensando && (
          <div className="flex items-start">
            <div className="bg-surface-panel border-2 border-border rounded-2xl rounded-bl-md px-5 py-3.5 flex gap-1.5 shadow-paper-sm">
              {[0,1,2].map(i => <span key={i} className="block h-2.5 w-2.5 rounded-full bg-muted animate-bounce" style={{ animationDelay: `${i*150}ms` }}/>)}
            </div>
          </div>
        )}
        {(stt.grabando || stt.transcribiendo) && (
          <div className="flex justify-end">
            <div className="bg-accent/15 border-2 border-accent/40 rounded-2xl px-4 py-2 text-sm font-extrabold text-accent">
              {stt.grabando ? `🎙️ ${stt.segundos}s` : "✨ Transcribiendo…"}
            </div>
          </div>
        )}
        {stt.error && <p className="text-center text-sm font-bold text-danger">{stt.error}</p>}
        <div ref={bottomRef} />
      </div>
      )}

      {/* ── Pie: progreso (si aplica) + input ───────────────────────────────── */}
      <div className="shrink-0 border-t-2 border-border bg-surface-panel pb-safe shadow-paper-sm">

        {accionActual && accionActual.pasos_total > 0 && dockExpandido && (
          <div className="px-4 pt-3 pb-1 shrink-0">
            <div className="flex justify-between text-xs font-extrabold text-muted mb-1.5">
              <span className="truncate">{accionActual.titulo}</span>
              <span className="text-accent shrink-0 ml-2">{accionActual.pasos_completados}/{accionActual.pasos_total}</span>
            </div>
            <div className="h-1 rounded-full bg-gray-200 dark:bg-white/10 overflow-hidden">
              <div className="h-full rounded-full bg-accent transition-all duration-500"
                style={{ width: `${Math.round((accionActual.pasos_completados / accionActual.pasos_total) * 100)}%` }}/>
            </div>
          </div>
        )}

        {!embedido && (
        <div className="shrink-0 flex flex-wrap gap-1.5 px-4 pt-2 pb-1">
          {modoInicio && (
            <button type="button" onClick={onGoTablero}
              className="inline-flex items-center gap-1.5 rounded-lg border border-stone-200 bg-stone-50 px-2.5 py-1 text-xs font-semibold text-stone-700 transition active:scale-[0.97] dark:border-stone-600/50 dark:bg-stone-900/50 dark:text-stone-300">
              <TopicIcon value="🎯" size={12} weight="regular" />
              Agenda
            </button>
          )}
          <button type="button" onClick={onGoSolicitudes}
            className={`inline-flex items-center gap-1.5 rounded-lg border px-2.5 py-1 text-xs font-semibold transition active:scale-[0.97] ${
              solicitudesCount > 0
                ? "border-accent/20 bg-accent/5 text-accent"
                : "border-border bg-surface text-muted"
            }`}>
            <TopicIcon value="📋" size={12} weight="regular" />
            {solicitudesCount} solicitud{solicitudesCount === 1 ? "" : "es"}
          </button>
        </div>
        )}

        <div className={`flex shrink-0 items-end gap-3 px-4 ${embedido && !dockExpandido ? "py-2" : "py-3"}`}>
          <ProseTextarea
            ref={inputRef}
            rows={1}
            value={input}
            onChange={e => setInput(e.target.value)}
            prose={false}
            onFocus={() => { if (embedido && !chatExpanded) onExpandChat?.(); }}
            onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); void enviar(input); } }}
            placeholder="Escriba o dicte…"
            disabled={pensando}
            className="hugo-input flex-1 rounded-2xl border-2 border-border bg-surface-input px-5 py-3.5 text-ink placeholder:text-muted placeholder:font-semibold outline-none focus:border-accent transition disabled:opacity-50 shadow-paper-sm resize-none overflow-y-auto min-h-[42px] max-h-32"
          />
          {input.trim() ? (
            <button type="button" onClick={() => void enviar(input)} disabled={pensando}
              className="h-12 w-12 shrink-0 rounded-2xl bg-accent flex items-center justify-center text-white shadow-paper disabled:opacity-50 active:scale-95 transition">
              <svg className="h-5 w-5 rotate-90" viewBox="0 0 24 24" fill="currentColor"><path d="M2 21l21-9L2 3v7l15 2-15 2v7z"/></svg>
            </button>
          ) : (
            <button type="button"
              onClick={() => stt.grabando ? stt.detener() : stt.iniciar(txt => void enviar(txt))}
              disabled={pensando || stt.transcribiendo}
              className={`h-12 w-12 shrink-0 rounded-2xl flex items-center justify-center text-white shadow-paper transition active:scale-95 disabled:opacity-50 ${
                stt.grabando ? "bg-danger animate-pulse" : "bg-accent hover:brightness-110"
              }`}
              aria-label={stt.grabando ? "Detener" : "Grabar voz"}>
              {stt.grabando
                ? <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="6" width="12" height="12" rx="2"/></svg>
                : <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/>
                    <path d="M19 10v2a7 7 0 01-14 0v-2M12 19v4M8 23h8"/>
                  </svg>
              }
            </button>
          )}
        </div>

      </div>
    </div>
  );
}

function useIsMobile() {
  const [mobile, setMobile] = useState(() =>
    typeof window !== "undefined" && window.matchMedia("(max-width: 639px)").matches
  );
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 639px)");
    const handler = (e: MediaQueryListEvent) => setMobile(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);
  return mobile;
}

// ── Main panel ────────────────────────────────────────────────────────────────

export default function TicketsPanel() {
  const { token, user, setAuth, clear } = useTicketsAuth();
  const toggleSidebar = useAppStore((s) => s.toggleSidebar);
  const setPanel = useAppStore((s) => s.setPanel);
  const setCentroMandoView = useAppStore((s) => s.setCentroMandoView);
  const hasHydrated = useAppStore((s) => s._hasHydrated);
  const savedCentroView = useAppStore((s) => s.centroMandoView);
  const savedTicketId = useAppStore((s) => s.ticketsSelectedId);
  const savedMisionId = useAppStore((s) => s.ticketsSelectedMisionId);
  const setTicketsSelectedId = useAppStore((s) => s.setTicketsSelectedId);
  const setTicketsSelectedMisionId = useAppStore((s) => s.setTicketsSelectedMisionId);
  const ticketsBootView = useAppStore((s) => s.ticketsBootView);
  const setTicketsBootView = useAppStore((s) => s.setTicketsBootView);
  const solicitudBoot = useAppStore((s) => s.solicitudBoot);
  const setSolicitudBoot = useAppStore((s) => s.setSolicitudBoot);
  const accionesBootTab = useAppStore((s) => s.accionesBootTab);
  const setAccionesBootTab = useAppStore((s) => s.setAccionesBootTab);
  // questDark vive en html.dark vía panelTheme; no re-aplicar class dark en quest-canvas.
  // Inicializar desde el store para que el botón atrás del mouse no caiga en "home"
  // al remontar Hugo (el bridge aún no existe en el popstate).
  const [view, setView] = useState<View>(() => (useAppStore.getState().centroMandoView as View) || "home");
  const [navRestored, setNavRestored] = useState(false);
  const [hugoChatExpanded, setHugoChatExpanded] = useState(false);
  const [abrirFormPendientes, setAbrirFormPendientes] = useState(false);
  const [abrirFormProcedimiento, setAbrirFormProcedimiento] = useState(false);
  const [accionesInitialTab, setAccionesInitialTab] = useState<"subhome" | "activas" | "pendientes" | "procedimientos" | "historial" | "agenda" | "notas" | "bolsillo">("activas");
  const [selectedId, setSelectedId] = useState<number | null>(() => useAppStore.getState().ticketsSelectedId);
  const [selectedMisionId, setSelectedMisionId] = useState<number | null>(() => useAppStore.getState().ticketsSelectedMisionId);
  const [categorias, setCategorias] = useState<Categoria[]>([]);
  const [bajoStockCount, setBajoStockCount] = useState(0);
  const [navScope, setNavScope] = useState<NavScope>({ kind: "all" });
  const [boardRefreshKey, setBoardRefreshKey] = useState(0);
  const [accionesKey, setAccionesKey] = useState(0);
  const [createCategoriaFija, setCreateCategoriaFija] = useState<string | undefined>();
  const [agenteClearKey, setAgenteClearKey] = useState(0);
  const isMobile = useIsMobile();
  const carritoOpen = useInventarioCarrito((s) => s.modalOpen);
  const openCarrito = useInventarioCarrito((s) => s.setModalOpen);
  const panel = useAppStore((s) => s.panel);
  const viewRef = useRef(view);
  const selectedIdRef = useRef(selectedId);
  const selectedMisionIdRef = useRef(selectedMisionId);
  viewRef.current = view;
  selectedIdRef.current = selectedId;
  selectedMisionIdRef.current = selectedMisionId;

  useEffect(() => {
    registerTicketsNavBridge({
      getView: () => viewRef.current,
      getSelectedId: () => selectedIdRef.current,
      getSelectedMisionId: () => selectedMisionIdRef.current,
      apply: (partial) => {
        if (partial.view !== undefined) setView(partial.view as View);
        if (partial.selectedId !== undefined) setSelectedId(partial.selectedId);
        if (partial.selectedMisionId !== undefined) setSelectedMisionId(partial.selectedMisionId);
      },
    });
    return () => registerTicketsNavBridge(null);
  }, []);

  useEffect(() => {
    setCentroMandoView(view);
  }, [view, setCentroMandoView]);

  useEffect(() => {
    setTicketsSelectedId(selectedId);
  }, [selectedId, setTicketsSelectedId]);

  useEffect(() => {
    setTicketsSelectedMisionId(selectedMisionId);
  }, [selectedMisionId, setTicketsSelectedMisionId]);

  // Restaurar sub-vista tras refrescar (localStorage + hash)
  useEffect(() => {
    if (!hasHydrated || navRestored || ticketsBootView) return;
    if (savedCentroView) setView(savedCentroView as View);
    if (savedTicketId != null) setSelectedId(savedTicketId);
    if (savedMisionId != null) setSelectedMisionId(savedMisionId);
    setNavRestored(true);
  }, [
    hasHydrated,
    navRestored,
    ticketsBootView,
    savedCentroView,
    savedTicketId,
    savedMisionId,
  ]);

  useEffect(() => {
    if (!token || !user) return;
    notifyNavChange();
  }, [token, user, panel, view, selectedId, selectedMisionId]);

  const reloadCats = useCallback(() => {
    if (!token) return;
    tapi("/categorias/", token).then((d) => setCategorias(Array.isArray(d) ? d : [])).catch(() => {});
  }, [token]);

  useEffect(() => { reloadCats(); }, [reloadCats]);

  // Sincronizar alarma nativa Android al abrir el panel (aunque no entren a Acciones)
  useEffect(() => {
    if (!token || !user) return;
    const bridge = mckennaAndroidBridge();
    bridge?.syncAlarma?.(false, 15, false, false);
    let cancelled = false;
    void (async () => {
      try {
        const data = await tapi("/?tipo=accion", token) as Ticket[];
        if (cancelled) return;
        const list = Array.isArray(data) ? data.map(normalizeTicketForList) : [];
        const hay = list.some(
          (t) => t.estado === "en_proceso" && uidEq(t.asignado_a, user.id),
        );
        bridge?.syncAlarma?.(hay, 15, hay, false);
      } catch { /* ignore */ }
    })();
    return () => { cancelled = true; };
  }, [token, user?.id]);

  useEffect(() => {
    return registerNestedBackHandler(() => {
      if (view === "home" && hugoChatExpanded) {
        setHugoChatExpanded(false);
        return true;
      }
      return false;
    });
  }, [view, hugoChatExpanded]);

  useEffect(() => {
    if (!ticketsBootView) return;
    const bootNivel = user?.rol?.nivel ?? 1;
    if (ticketsBootView === "acciones" && accionesBootTab) {
      setAccionesInitialTab(accionesBootTab);
      setAccionesKey((k) => k + 1);
      setAccionesBootTab(null);
    }
    if (ticketsBootView === "agente") {
      setView("home");
      setHugoChatExpanded(true);
    } else if (ticketsBootView === "contratos") {
      if (bootNivel >= 3) {
        setView("contratos");
        setHugoChatExpanded(false);
      } else {
        setView("home");
      }
    } else {
      setView(ticketsBootView as View);
      if (ticketsBootView === "home") setHugoChatExpanded(false);
    }
    setTicketsBootView(null);
  }, [ticketsBootView, accionesBootTab, setTicketsBootView, setAccionesBootTab, user?.rol?.nivel]);

  useEffect(() => {
    if (!solicitudBoot?.abrirTicketId) return;
    setView("solicitudes");
  }, [solicitudBoot]);

  useEffect(() => {
    if (!token) return;
    tapi("/materiales", token)
      .then((mats) => {
        if (Array.isArray(mats)) setBajoStockCount(mats.filter((m) => m.stock_minimo > 0 && m.stock_actual < m.stock_minimo).length);
      })
      .catch(() => {});
  }, [token, view]);

  // Auth is handled at App level; if somehow null here, bail early
  if (!token || !user) return null;

  const nivel = user.rol?.nivel ?? 1;
  const permisos = user.permisos_secciones;


  function goDetail(id: number) { setSelectedId(id); setView("detail"); }
  function goBack() {
    setBoardRefreshKey((k) => k + 1);
    setCreateCategoriaFija(undefined);
    setView("home");
    setSelectedId(null);
    setSelectedMisionId(null);
  }
  function goMisionDetail(id: number) { setSelectedMisionId(id); setView("mision_detail"); }
  function goInicio() {
    setTicketsBootView(null);
    setAccionesBootTab(null);
    setPanel("hugo");
    setCentroMandoView("home");
    setView("home");
    setHugoChatExpanded(true);
  }

  function goCentroMando() {
    setTicketsBootView(null);
    setAccionesBootTab(null);
    setCentroMandoView("home");
    setView("home");
    setHugoChatExpanded(false);
    setAgenteClearKey((k) => k + 1);
  }

  function goTablero() {
    setNavScope({ kind: "all" });
    setBoardRefreshKey((k) => k + 1);
    setView("home");
    setSelectedId(null);
    setSelectedMisionId(null);
  }

  function irATickets(destino: Exclude<TicketsBootView, null>) {
    setView(destino);
  }

  function salirDeAgente() {
    setCentroMandoView("home");
    setView("home");
    setHugoChatExpanded(false);
  }

  function goAcciones(tab: "subhome" | "activas" | "pendientes" | "procedimientos" | "historial" | "agenda" | "notas" | "bolsillo" = "activas") {
    setAccionesInitialTab(tab);
    setAbrirFormPendientes(tab === "pendientes");
    setAbrirFormProcedimiento(tab === "procedimientos");
    setAccionesKey((k) => k + 1);
    setView("acciones");
  }
  function goSolicitudes() { irATickets("solicitudes"); }
  function goVerSolicitud(id: number) {
    setSolicitudBoot({ abrirTicketId: id });
    irATickets("solicitudes");
  }
  function goContratos() {
    if (nivel < 3) return;
    setPanel("hugo");
    setCentroMandoView("contratos");
    setHugoChatExpanded(false);
    setView("contratos");
  }
  function goImpresora() {
    if (!puedeVerSeccionPanel(user, "etiquetas")) return;
    setPanel("etiquetas");
  }
  function goStock() {
    if (!puedeVerSeccionPanel(user, "stock")) return;
    setPanel("stock");
  }
  function goEmpaque() {
    if (!puedeVerSeccionPanel(user, "empaque")) return;
    setPanel("empaque");
  }
  function goCreateContrato() {
    if (nivel < 3) return;
    setPanel("hugo");
    setCentroMandoView("contratos");
    setCreateCategoriaFija("contratos");
    setView("create");
  }
  function goInventario() { setView("inventario"); }
  function goReinos() { setView("reinos"); }
  function goWorkload() { setView("workload"); }
  function goRecetas() { setView("recetas"); }
  function goCreateMision() { setView("crear_mision"); }
  function handleNavScope(scope: NavScope) { setNavScope(scope); }
  function goIrTableroConFiltro() {
    setBoardRefreshKey((k) => k + 1);
    setView("list");
  }
  function goIrInventarioConFiltro() { setView("inventario"); }

  return (
    <CategoriasCtx.Provider value={{ cats: categorias, reload: reloadCats }}>
    <div className="quest-canvas relative flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
        <InventarioCarritoModal
          token={token}
          nivel={nivel}
          onMisionCreated={(id) => {
            setBoardRefreshKey((k) => k + 1);
            goMisionDetail(id);
          }}
        />
        {view === "reinos" && (
          <ReinosView
            token={token}
            user={user}
            navScope={navScope}
            onNavScope={handleNavScope}
            onIrTablero={goIrTableroConFiltro}
            onIrInventario={goIrInventarioConFiltro}
          />
        )}
        {view === "home" && (
          <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain pb-6">
            <CentroMandoHome
              token={token}
              user={user}
              nivel={nivel}
              permisos={permisos}
              onAcciones={() => goAcciones("activas")}
              onSolicitudes={goSolicitudes}
              onVerSolicitud={goVerSolicitud}
              onContratos={goContratos}
              onTablero={() => goAcciones("activas")}
              onAccionesFuturas={() => goAcciones("agenda")}
              onRecordatorios={() => goAcciones("agenda")}
              onProcedimientos={() => goAcciones("procedimientos")}
              onImpresora={goImpresora}
              onStock={goStock}
              onEmpaque={goEmpaque}
              onNotas={() => goAcciones("notas")}
              onBolsillo={() => goAcciones("bolsillo")}
            />
          </div>
        )}
        {view === "list" && (
          <TicketListView
            token={token} user={user}
            onSelect={goDetail}
            onEditMision={goMisionDetail}
            navScope={navScope}
            refreshKey={boardRefreshKey}
          />
        )}
        {view === "acciones" && (
          <AccionesView
            key={accionesKey}
            token={token}
            user={user}
            onSelect={goDetail}
            onIrCompras={goSolicitudes}
            initialTab={accionesInitialTab}
            abrirFormPendientes={abrirFormPendientes}
            abrirFormProcedimiento={abrirFormProcedimiento}
            onInicio={goInicio}
          />
        )}
        {view === "solicitudes" && (
          <SolicitudesView
            token={token}
            user={user}
            onInicio={goInicio}
            boot={solicitudBoot}
            onBootConsumed={() => setSolicitudBoot(null)}
          />
        )}
        {view === "contratos" && nivel >= 3 && (
          <ContratosView
            token={token}
            user={user}
            onBack={goCentroMando}
            onSelect={goDetail}
            onCreate={goCreateContrato}
          />
        )}
        {view === "create" && (!createCategoriaFija || createCategoriaFija !== "contratos" || nivel >= 3) && (
          <CreateTicketView
            token={token} user={user}
            categoriaFija={createCategoriaFija}
            onBack={() => {
              const volverAContratos = createCategoriaFija === "contratos";
              setCreateCategoriaFija(undefined);
              if (volverAContratos) {
                goContratos();
              } else {
                setPanel("hugo");
                goCentroMando();
              }
            }}
            onCreated={(id) => {
              setCreateCategoriaFija(undefined);
              goDetail(id);
            }}
          />
        )}
        {view === "detail" && selectedId != null && (
          <TicketDetailView
            token={token} user={user}
            ticketId={selectedId}
            onBack={() => {
              if (selectedMisionId) { setView("mision_detail"); }
              else { goBack(); }
            }}
          />
        )}
        {view === "recetas" && (
          <RecetasPanel token={token} user={user} onBack={goBack} />
        )}
        {view === "workload" && nivel >= 2 && (
          <WorkloadView
            token={token}
            user={user}
            onBack={goBack}
            onAdministracion={nivel >= 3 ? () => setView("administracion") : undefined}
          />
        )}
        {view === "administracion" && nivel >= 3 && (
          <AdminView token={token} onBack={goBack} />
        )}
        {view === "crear_mision" && (
          <CreateMisionView
            token={token}
            user={user}
            onBack={goBack}
            onCreated={(id) => goMisionDetail(id)}
          />
        )}
        {view === "mision_detail" && selectedMisionId != null && (
          <MisionDetailView
            token={token} user={user}
            misionId={selectedMisionId}
            onBack={goBack}
            onTicket={(id) => { setSelectedId(id); setView("detail"); }}
          />
        )}
        {view === "inventario" && (
          <InventarioView
            token={token} user={user}
            navScope={navScope}
            onBack={goBack}
          />
        )}
    </div>
    </CategoriasCtx.Provider>
  );
}
